def create_agent_suite_plan(
    vault_dir: Path,
    config_data: Mapping[str, object],
    suite_data: Mapping[str, object],
    *,
    subject_prefix: str,
    lanes: tuple[str, ...] | None = None,
    replicas: int | None = None,
    mode: str = "matrix",
    variant_ids: tuple[str, ...] | None = None,
    curriculum_context: Mapping[str, object] | None = None,
) -> AgentSuiteResult:
    spec = ExperimentSpec.from_mapping(config_data)
    vault = ensure_vault(vault_dir)
    suite_name = _suite_name(suite_data)
    suite_slug = slugify(suite_name, fallback="agent-suite")
    cases = _suite_cases(suite_data)
    lane_specs = _parallel_lanes(config_data, lanes=lanes)
    replica_count = _parallel_replicas(config_data, replicas=replicas)
    suite_mode = _suite_mode(mode)
    matrix_variants = (
        _matrix_variant_choices(spec, variant_ids)
        if suite_mode == "matrix"
        else ()
    )
    matrix_variant_ids = tuple(variant.id for variant in matrix_variants) if matrix_variants else None
    variant_multiplier = len(matrix_variants) if suite_mode == "matrix" else 1
    runs_per_case = len(lane_specs) * replica_count * variant_multiplier
    total_runs = len(cases) * runs_per_case
    if total_runs > MAX_SUITE_RUNS:
        raise ValueError(f"agent suite exceeds {MAX_SUITE_RUNS} run limit")

    generated_at = _now()
    subject_hash = _hash_text(f"subject\0{subject_prefix}")
    suite_hash = _hash_json([case.manifest_dict() for case in cases])
    suite_id = _suite_id(
        generated_at=generated_at,
        experiment_slug=spec.slug,
        suite_slug=suite_slug,
        subject_hash=subject_hash,
        suite_hash=suite_hash,
    )
    strategy = "variant-matrix" if suite_mode == "matrix" else "lane-fanout"
    plans: list[AgentPlanResult] = []
    case_records: list[dict[str, object]] = []
    plan_records: list[dict[str, object]] = []
    for case in cases:
        suite_context = {
            "suite_id": suite_id,
            "suite_slug": suite_slug,
            "case_id": case.id,
            "case_hash": case.case_hash,
            "mode": suite_mode,
        }
        if curriculum_context:
            suite_context["curriculum_id"] = curriculum_context.get("curriculum_id")
            suite_context["curriculum_case_rank"] = _curriculum_case_rank(
                curriculum_context,
                case_id=case.id,
                case_hash=case.case_hash,
            )
        plan = _create_parallel_agent_plan(
            vault,
            config_data,
            subject_key=f"{subject_prefix}\0{suite_id}\0{case.id}",
            prompt_text=case.prompt,
            prompt_source_name=f"{case.id}.prompt.md",
            lanes=lanes,
            replicas=replicas,
            strategy=strategy,
            suite_context=suite_context,
            matrix_variant_ids=matrix_variant_ids,
        )
        plans.append(plan)
        case_record = case.manifest_dict()
        case_record.update(
            {
                "plan_id": plan.plan_id,
                "run_count": len(plan.runs),
                "plan_path": _relative_vault_path(vault, plan.path),
            }
        )
        case_records.append(case_record)
        plan_records.append(
            {
                "case_id": case.id,
                "case_hash": case.case_hash,
                "plan_id": plan.plan_id,
                "path": _relative_vault_path(vault, plan.path),
                "report_path": _relative_vault_path(vault, plan.report_path),
                "run_count": len(plan.runs),
                "runs": [
                    {
                        "run_id": run.run_id,
                        "variant_id": run.variant_id,
                        "path": _relative_vault_path(vault, run.path),
                    }
                    for run in plan.runs
                ],
            }
        )

    payload: dict[str, object] = {
        "schema": AGENT_SUITE_SCHEMA,
        "suite_id": suite_id,
        "generated_at": generated_at,
        "experiment": {
            "name": spec.name,
            "slug": spec.slug,
            "config_hash": _hash_json(spec.as_dict()),
            "description": spec.description,
            "primary_metric": spec.primary_metric.as_dict(),
            "rubric": spec.rubric.as_dict(),
            "traffic_salt": spec.traffic_salt,
            "guardrails": list(spec.guardrails),
            "min_trials_per_variant": spec.min_trials_per_variant,
        },
        "suite": {
            "name": suite_name,
            "slug": suite_slug,
            "suite_hash": suite_hash,
            "subject_hash": subject_hash,
            "mode": suite_mode,
        },
        "case_count": len(cases),
        "plan_count": len(plans),
        "run_count": total_runs,
        "runs_per_case": runs_per_case,
        "cases": case_records,
        "plans": plan_records,
        "variants": [item.as_dict() for item in spec.variants],
        "parallel": {
            "strategy": strategy,
            "replicas": replica_count,
            "lane_count": len(lane_specs),
            "variant_count": len(matrix_variants) if suite_mode == "matrix" else None,
            "matrix_variant_ids": [variant.id for variant in matrix_variants],
            "lanes": [item.as_dict() for item in lane_specs],
        },
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": [
                "subject_prefix",
                "prompt_text",
                "raw_transcript",
                "raw_output",
                "expected_answer",
            ],
        },
    }
    if curriculum_context:
        payload["curriculum"] = dict(curriculum_context)
    suite_path = safe_child(vault, "agent-runs", spec.slug, "suites", f"{suite_id}.json")
    report_path = safe_child(vault, "agent-runs", spec.slug, "suites", f"{suite_id}.md")
    suite_path.parent.mkdir(parents=True, exist_ok=True)
    written_json = write_unique_text(suite_path, json.dumps(payload, indent=2, sort_keys=True) + "\n")
    written_report = write_unique_text(report_path, _render_suite_report(payload))
    return AgentSuiteResult(
        experiment=spec.slug,
        suite_id=suite_id,
        path=written_json,
        report_path=written_report,
        plans=tuple(plans),
        payload=payload,
    )


def create_agent_curriculum_plan(
    vault_dir: Path,
    config_data: Mapping[str, object],
    suite_data: Mapping[str, object],
    *,
    subject_prefix: str,
    curriculum_id: str | None = None,
    baseline_variant_id: str | None = None,
    variant_ids: tuple[str, ...] | None = None,
    lanes: tuple[str, ...] | None = None,
    replicas: int | None = None,
    max_cases: int | None = None,
) -> AgentSuiteResult:
    spec = ExperimentSpec.from_mapping(config_data)
    vault = ensure_vault(vault_dir)
    root = safe_child(vault, "agent-runs", spec.slug)
    if not root.exists():
        raise FileNotFoundError(f"Agent experiment does not exist: {spec.slug}")
    curriculum = _load_curriculum_record(root, curriculum_id=curriculum_id)
    hard_cases = curriculum.get("hard_cases") if isinstance(curriculum.get("hard_cases"), list) else []
    if not hard_cases:
        raise ValueError("curriculum has no hard cases to plan")
    selected_cases = _curriculum_suite_data(
        suite_data,
        hard_cases=hard_cases,
        max_cases=max_cases,
    )
    selected_variant_ids = _curriculum_plan_variant_ids(
        spec,
        curriculum,
        explicit_variant_ids=variant_ids,
        baseline_variant_id=baseline_variant_id,
    )
    selected_lanes = _curriculum_plan_lanes(curriculum, explicit_lanes=lanes)
    context = _curriculum_plan_context(
        curriculum,
        selected_cases,
        selected_variant_ids=selected_variant_ids,
        selected_lanes=selected_lanes,
    )
    return create_agent_suite_plan(
        vault,
        config_data,
        selected_cases,
        subject_prefix=subject_prefix,
        lanes=selected_lanes,
        replicas=replicas,
        mode="matrix",
        variant_ids=selected_variant_ids,
        curriculum_context=context,
    )


def report_agent_suite(
    vault_dir: Path,
    *,
    suite_id: str,
    baseline_variant_id: str | None = None,
    min_completed_ratio: float = 1.0,
) -> AgentSuiteReportResult:
    _safe_run_id(suite_id)
    completion_floor = _ratio(min_completed_ratio, field="min_completed_ratio")
    vault = ensure_vault(vault_dir)
    suite_path, suite = _load_suite_record(vault, suite_id)
    spec = _spec_from_suite(suite)
    root = suite_path.parent.parent
    outcomes_by_run = _latest_outcomes_by_run(_load_outcome_records(root))
    baseline = _safe_variant_id(
        baseline_variant_id,
        spec=spec,
        fallback=_current_champion_variant_id(spec),
    )
    case_summaries = _suite_case_summaries(
        suite,
        outcomes_by_run=outcomes_by_run,
        metric=spec.primary_metric,
        variants=spec.variants,
    )
    variant_summaries = _suite_report_variant_summaries(
        spec,
        suite,
        outcomes_by_run=outcomes_by_run,
        case_summaries=case_summaries,
    )
    pairwise = _suite_pairwise_comparisons(
        spec,
        case_summaries,
        baseline_variant_id=baseline,
    )
    frontier = _efficiency_frontier(
        variant_summaries,
        metric=spec.primary_metric,
        metric_key="case_metric_mean",
    )
    winner = _suite_report_winner(spec, variant_summaries)
    summary = _suite_report_summary(
        case_summaries,
        pairwise,
        min_completed_ratio=completion_floor,
    )
    recommendations = _suite_report_recommendations(
        summary,
        pairwise,
        baseline_variant_id=baseline,
        winner_variant_id=winner,
        metric=spec.primary_metric,
    )
    recommendations.extend(_efficiency_recommendations(frontier, metric=spec.primary_metric))
    generated_at = _now()
    report_id = _suite_report_id(generated_at, suite_id, baseline, case_summaries)
    payload: dict[str, object] = {
        "schema": AGENT_SUITE_REPORT_SCHEMA,
        "report_id": report_id,
        "suite_id": suite_id,
        "generated_at": generated_at,
        "experiment": spec.as_dict(),
        "suite": suite.get("suite") if isinstance(suite.get("suite"), dict) else {},
        "suite_path": _relative_vault_path(vault, suite_path),
        "primary_metric": spec.primary_metric.as_dict(),
        "baseline_variant_id": baseline,
        "winner_variant_id": winner,
        "policy": {
            "min_completed_ratio": completion_floor,
            "comparison": "paired-by-suite-case",
            "confidence_interval": "normal-approx-95",
        },
        "summary": summary,
        "variant_summaries": variant_summaries,
        "efficiency_frontier": frontier,
        "case_summaries": case_summaries,
        "pairwise": pairwise,
        "recommendations": recommendations,
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": [
                "subject_prefix",
                "prompt_text",
                "raw_transcript",
                "raw_output",
                "expected_answer",
                "error_message",
            ],
        },
    }
    report_path = safe_child(root, "suite-reports", f"{report_id}.json")
    markdown_path = safe_child(root, "suite-reports", f"{report_id}.md")
    report_path.parent.mkdir(parents=True, exist_ok=True)
    written_json = write_unique_text(report_path, json.dumps(payload, indent=2, sort_keys=True) + "\n")
    written_report = write_unique_text(markdown_path, _render_suite_report_report(payload))
    return AgentSuiteReportResult(
        experiment=spec.slug,
        suite_id=suite_id,
        report_id=report_id,
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def create_agent_pipeline(
    vault_dir: Path,
    config_data: Mapping[str, object],
    pipeline_data: Mapping[str, object],
    *,
    subject_prefix: str,
    prompt_text: str | None = None,
    prompt_source_name: str | None = None,
    schedule_initial: bool = True,
) -> AgentPipelineResult:
    if not subject_prefix.strip():
        raise ValueError("subject_prefix is required")
    spec = ExperimentSpec.from_mapping(config_data)
    stages = _pipeline_stages(pipeline_data, config_data)
    vault = ensure_vault(vault_dir)
    generated_at = _now()
    pipeline_name = _pipeline_name(pipeline_data)
    pipeline_slug = slugify(pipeline_name, fallback="agent-pipeline")
    subject_hash = _hash_text(f"pipeline-subject\0{subject_prefix}")
    prompt = _content_fingerprint(prompt_text, source_name=prompt_source_name)
    pipeline_id = _pipeline_id(
        generated_at,
        spec.slug,
        pipeline_slug,
        subject_hash,
        [stage.as_dict() for stage in stages],
    )
    plans: list[AgentPlanResult] = []
    if schedule_initial:
        for index, stage in enumerate(stages, start=1):
            if stage.depends_on:
                continue
            plans.append(
                _create_pipeline_stage_plan(
                    vault,
                    spec,
                    stage,
                    pipeline_id=pipeline_id,
                    pipeline_slug=pipeline_slug,
                    stage_order=index,
                    subject_key=f"{subject_prefix}\0{pipeline_id}\0{stage.id}",
                    prompt_fingerprint=prompt,
                )
            )
    root = safe_child(vault, "agent-runs", spec.slug)
    stage_statuses = _pipeline_stage_statuses(root, pipeline_id, stages)
    summary = _pipeline_summary(stage_statuses, scheduled_count=len(plans))
    pipeline_status = _pipeline_status(summary)
    payload: dict[str, object] = {
        "schema": AGENT_PIPELINE_SCHEMA,
        "pipeline_id": pipeline_id,
        "generated_at": generated_at,
        "experiment": spec.as_dict(),
        "pipeline_status": pipeline_status,
        "pipeline": {
            "name": pipeline_name,
            "slug": pipeline_slug,
            "subject_hash": subject_hash,
            "stage_count": len(stages),
        },
        "prompt": prompt,
        "stages": [stage.as_dict() for stage in stages],
        "stage_statuses": stage_statuses,
        "plans": [_pipeline_plan_record(vault, plan) for plan in plans],
        "summary": summary,
        "recommendations": _pipeline_recommendations(pipeline_status, summary),
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["subject_prefix", "subject_key", "prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    pipeline_path = safe_child(root, "pipelines", f"{pipeline_id}.json")
    report_path = safe_child(root, "pipelines", f"{pipeline_id}.md")
    pipeline_path.parent.mkdir(parents=True, exist_ok=True)
    written_json = write_unique_text(pipeline_path, json.dumps(payload, indent=2, sort_keys=True) + "\n")
    written_report = write_unique_text(report_path, _render_pipeline_report(payload))
    return AgentPipelineResult(
        experiment=spec.slug,
        pipeline_id=pipeline_id,
        path=written_json,
        report_path=written_report,
        plans=tuple(plans),
        payload=payload,
    )


def advance_agent_pipeline(
    vault_dir: Path,
    *,
    pipeline_id: str,
    max_stages: int | None = None,
) -> AgentPipelineAdvanceResult:
    safe_pipeline_id = _safe_run_id(pipeline_id)
    stage_limit = _optional_positive_int(max_stages, field="max_stages")
    vault = ensure_vault(vault_dir)
    pipeline_path, pipeline = _load_pipeline_record(vault, safe_pipeline_id)
    spec = ExperimentSpec.from_mapping(pipeline.get("experiment"))
    stages = _pipeline_stages_from_record(pipeline)
    root = pipeline_path.parent.parent
    prompt = (
        _safe_prompt_fingerprint(pipeline["prompt"])
        if isinstance(pipeline.get("prompt"), Mapping)
        else _content_fingerprint(None, source_name=None)
    )
    pipeline_meta = pipeline.get("pipeline") if isinstance(pipeline.get("pipeline"), dict) else {}
    pipeline_slug = slugify(str(pipeline_meta.get("slug") or pipeline_meta.get("name") or "agent-pipeline"), fallback="agent-pipeline")
    before_statuses = _pipeline_stage_statuses(root, safe_pipeline_id, stages)
    eligible = [
        stage
        for stage, status in zip(stages, before_statuses)
        if status.get("stage_status") == "ready"
    ]
    if stage_limit is not None:
        eligible = eligible[:stage_limit]
    plans: list[AgentPlanResult] = []
    stage_order = {stage.id: index for index, stage in enumerate(stages, start=1)}
    for stage in eligible:
        plans.append(
            _create_pipeline_stage_plan(
                vault,
                spec,
                stage,
                pipeline_id=safe_pipeline_id,
                pipeline_slug=pipeline_slug,
                stage_order=stage_order[stage.id],
                subject_key=f"pipeline\0{safe_pipeline_id}\0{stage.id}",
                prompt_fingerprint=prompt,
            )
        )
    stage_statuses = _pipeline_stage_statuses(root, safe_pipeline_id, stages)
    summary = _pipeline_summary(stage_statuses, scheduled_count=len(plans))
    advance_status = _pipeline_advance_status(summary, scheduled_count=len(plans))
    generated_at = _now()
    advance_id = _pipeline_advance_id(generated_at, safe_pipeline_id, summary, plans)
    payload: dict[str, object] = {
        "schema": AGENT_PIPELINE_ADVANCE_SCHEMA,
        "advance_id": advance_id,
        "pipeline_id": safe_pipeline_id,
        "generated_at": generated_at,
        "experiment": spec.as_dict(),
        "pipeline_path": _relative_vault_path(vault, pipeline_path),
        "advance_status": advance_status,
        "plans": [_pipeline_plan_record(vault, plan) for plan in plans],
        "stage_statuses": stage_statuses,
        "summary": summary,
        "recommendations": _pipeline_recommendations(advance_status, summary),
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["subject_prefix", "subject_key", "prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    advance_path = safe_child(root, "pipeline-advances", f"{advance_id}.json")
    report_path = safe_child(root, "pipeline-advances", f"{advance_id}.md")
    advance_path.parent.mkdir(parents=True, exist_ok=True)
    written_json = write_unique_text(advance_path, json.dumps(payload, indent=2, sort_keys=True) + "\n")
    written_report = write_unique_text(report_path, _render_pipeline_advance_report(payload))
    return AgentPipelineAdvanceResult(
        experiment=spec.slug,
        pipeline_id=safe_pipeline_id,
        advance_id=advance_id,
        path=written_json,
        report_path=written_report,
        plans=tuple(plans),
        payload=payload,
    )


def create_agent_arena(
    vault_dir: Path,
    config_data: Mapping[str, object],
    *,
    subject_key: str,
    prompt_text: str | None = None,
    prompt_source_name: str | None = None,
    lanes: tuple[str, ...] | None = None,
    replicas: int | None = None,
    max_runs: int = MAX_ARENA_RUNS,
) -> AgentArenaResult:
    if not subject_key.strip():
        raise ValueError("subject_key is required")
    spec = ExperimentSpec.from_mapping(config_data)
    if len(spec.variants) < 2:
        raise ValueError("agent arena requires at least two variants")
    run_limit = _positive_int(max_runs, field="max_runs")
    if run_limit > MAX_ARENA_RUNS:
        raise ValueError(f"max_runs must be {MAX_ARENA_RUNS} or fewer")
    vault = ensure_vault(vault_dir)
    lane_specs = _parallel_lanes(config_data, lanes=lanes)
    replica_count = _parallel_replicas(config_data, replicas=replicas)
    pairs = _arena_variant_pairs(spec)
    requested_matches = len(pairs) * len(lane_specs) * replica_count
    requested_runs = requested_matches * 2
    generated_at = _now()
    subject_hash = _hash_text(f"subject\0{subject_key}")
    prompt = _content_fingerprint(prompt_text, source_name=prompt_source_name)
    arena_id = _arena_id(
        generated_at=generated_at,
        experiment_slug=spec.slug,
        subject_hash=subject_hash,
        variant_ids=[variant.id for variant in spec.variants],
        lane_ids=[lane.id for lane in lane_specs],
        replicas=replica_count,
    )
    plan_id = _plan_id(
        generated_at=generated_at,
        experiment_slug=spec.slug,
        subject_hash=_hash_text(f"arena\0{subject_key}\0{arena_id}"),
        prompt_sha256=prompt.get("sha256"),
    )
    runs: list[AgentRunResult] = []
    run_records: list[dict[str, object]] = []
    match_records: list[dict[str, object]] = []
    for pair_index, (variant_a, variant_b) in enumerate(pairs, start=1):
        for lane in lane_specs:
            for replica in range(1, replica_count + 1):
                if len(runs) + 2 > run_limit:
                    continue
                pair_id = _arena_pair_id(variant_a.id, variant_b.id)
                match_id = _arena_match_id(pair_id, lane.id, replica)
                block_id = match_id
                first, second = (
                    (variant_b, variant_a)
                    if (pair_index + replica) % 2 == 0
                    else (variant_a, variant_b)
                )
                match_runs: list[dict[str, object]] = []
                for arena_role, variant, opponent in (
                    ("a", first, second),
                    ("b", second, first),
                ):
                    child_subject = (
                        f"{subject_key}\0{arena_id}\0{plan_id}\0{match_id}\0"
                        f"{lane.id}\0{replica}\0{arena_role}\0{variant.id}"
                    )
                    context = {
                        "plan_id": plan_id,
                        "arena_id": arena_id,
                        "match_id": match_id,
                        "pair_id": pair_id,
                        "block_id": block_id,
                        "lane_id": lane.id,
                        "role": lane.role,
                        "replica": replica,
                        "merge_strategy": "arena-head-to-head",
                        "strategy": "arena-round-robin",
                        "arena_role": arena_role,
                        "opponent_variant_id": opponent.id,
                    }
                    if lane.objective:
                        context["objective"] = lane.objective
                    run = _write_agent_run(
                        vault,
                        spec,
                        selected=variant,
                        bucket=_matrix_assignment_bucket(spec, variant),
                        subject_key=child_subject,
                        prompt_text=None,
                        prompt_source_name=None,
                        prompt_fingerprint=prompt,
                        parallel_context=context,
                        assignment_strategy="arena-round-robin",
                    )
                    runs.append(run)
                    record = {
                        "run_id": run.run_id,
                        "lane_id": lane.id,
                        "role": lane.role,
                        "replica": replica,
                        "variant_id": run.variant_id,
                        "path": _relative_vault_path(vault, run.path),
                        "arena_id": arena_id,
                        "match_id": match_id,
                        "pair_id": pair_id,
                        "block_id": block_id,
                        "arena_role": arena_role,
                        "opponent_variant_id": opponent.id,
                    }
                    run_records.append(record)
                    match_runs.append(
                        {
                            "run_id": run.run_id,
                            "variant_id": run.variant_id,
                            "arena_role": arena_role,
                        }
                    )
                match_records.append(
                    {
                        "match_id": match_id,
                        "pair_id": pair_id,
                        "block_id": block_id,
                        "lane_id": lane.id,
                        "replica": replica,
                        "variant_a_id": first.id,
                        "variant_b_id": second.id,
                        "runs": match_runs,
                    }
                )
    scheduled_matches = len(match_records)
    scheduled_runs = len(runs)
    truncated = scheduled_runs < requested_runs
    arena_status = (
        "scheduled-partial"
        if truncated and scheduled_runs
        else "scheduled"
        if scheduled_runs
        else "no-runs"
    )
    root = safe_child(vault, "agent-runs", spec.slug)
    plan_path: Path | None = None
    plan_report_path: Path | None = None
    if scheduled_runs:
        plan_payload = _arena_plan_payload(
            spec,
            generated_at=generated_at,
            plan_id=plan_id,
            arena_id=arena_id,
            subject_hash=subject_hash,
            prompt=prompt,
            lanes=lane_specs,
            run_records=run_records,
            match_records=match_records,
        )
        plan_path = safe_child(root, "plans", f"{plan_id}.json")
        plan_report_path = safe_child(root, "plans", f"{plan_id}.md")
        plan_path.parent.mkdir(parents=True, exist_ok=True)
        plan_path = write_unique_text(
            plan_path,
            json.dumps(plan_payload, indent=2, sort_keys=True) + "\n",
        )
        plan_report_path = write_unique_text(plan_report_path, _render_plan_report(plan_payload))
    summary = {
        "variant_count": len(spec.variants),
        "pair_count": len(pairs),
        "lane_count": len(lane_specs),
        "replicas": replica_count,
        "requested_matches": requested_matches,
        "scheduled_matches": scheduled_matches,
        "requested_runs": requested_runs,
        "scheduled_runs": scheduled_runs,
        "max_runs": run_limit,
        "truncated": truncated,
    }
    payload: dict[str, object] = {
        "schema": AGENT_ARENA_SCHEMA,
        "arena_id": arena_id,
        "generated_at": generated_at,
        "experiment": spec.as_dict(),
        "arena_status": arena_status,
        "plan_id": plan_id if scheduled_runs else None,
        "plan_path": _relative_vault_path(vault, plan_path) if plan_path else None,
        "plan_report_path": (
            _relative_vault_path(vault, plan_report_path) if plan_report_path else None
        ),
        "primary_metric": spec.primary_metric.as_dict(),
        "summary": summary,
        "policy": {
            "strategy": "round-robin-head-to-head",
            "replicas": replica_count,
            "max_runs": run_limit,
            "balanced_order": True,
        },
        "parallel": {
            "lanes": [lane.as_dict() for lane in lane_specs],
        },
        "variants": [variant.as_dict() for variant in spec.variants],
        "prompt": prompt,
        "matches": match_records,
        "runs": run_records,
        "recommendations": _arena_recommendations(arena_status, summary),
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["subject_key", "prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    arena_path = safe_child(root, "arenas", f"{arena_id}.json")
    report_path = safe_child(root, "arenas", f"{arena_id}.md")
    arena_path.parent.mkdir(parents=True, exist_ok=True)
    written_json = write_unique_text(arena_path, json.dumps(payload, indent=2, sort_keys=True) + "\n")
    written_report = write_unique_text(report_path, _render_arena_report(payload))
    return AgentArenaResult(
        experiment=spec.slug,
        arena_id=arena_id,
        plan_id=plan_id if scheduled_runs else None,
        path=written_json,
        report_path=written_report,
        plan_path=plan_path,
        plan_report_path=plan_report_path,
        runs=tuple(runs),
        payload=payload,
    )


def report_agent_arena(
    vault_dir: Path,
    *,
    arena_id: str,
    min_completed_ratio: float = 1.0,
) -> AgentArenaReportResult:
    safe_arena_id = _safe_run_id(arena_id)
    completion_floor = _ratio(min_completed_ratio, field="min_completed_ratio")
    vault = ensure_vault(vault_dir)
    arena_path, arena = _load_arena_record(vault, safe_arena_id)
    spec = ExperimentSpec.from_mapping(arena.get("experiment"))
    root = arena_path.parent.parent
    outcomes_by_run = _latest_outcomes_by_run(_load_outcome_records(root))
    metric = spec.primary_metric
    match_results = _arena_report_matches(
        arena,
        outcomes_by_run=outcomes_by_run,
        metric=metric,
    )
    pairwise = _arena_report_pairwise(spec, match_results)
    variant_summaries = _arena_report_variant_summaries(
        spec,
        match_results,
        outcomes_by_run=outcomes_by_run,
        metric=metric,
    )
    winner = _arena_report_winner(spec, variant_summaries)
    summary = _arena_report_summary(
        arena,
        match_results,
        min_completed_ratio=completion_floor,
    )
    report_status = _arena_report_status(summary)
    recommendations = _arena_report_recommendations(
        summary,
        variant_summaries,
        winner_variant_id=winner,
    )
    generated_at = _now()
    report_id = _arena_report_id(generated_at, safe_arena_id, summary, variant_summaries)
    payload: dict[str, object] = {
        "schema": AGENT_ARENA_REPORT_SCHEMA,
        "report_id": report_id,
        "arena_id": safe_arena_id,
        "generated_at": generated_at,
        "experiment": spec.as_dict(),
        "arena_path": _relative_vault_path(vault, arena_path),
        "plan_id": arena.get("plan_id"),
        "report_status": report_status,
        "primary_metric": metric.as_dict(),
        "winner_variant_id": winner,
        "policy": {
            "min_completed_ratio": completion_floor,
            "comparison": "round-robin-head-to-head",
        },
        "summary": summary,
        "variant_summaries": variant_summaries,
        "pairwise": pairwise,
        "matches": match_results,
        "recommendations": recommendations,
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["subject_key", "prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    report_path = safe_child(root, "arena-reports", f"{report_id}.json")
    markdown_path = safe_child(root, "arena-reports", f"{report_id}.md")
    report_path.parent.mkdir(parents=True, exist_ok=True)
    written_json = write_unique_text(report_path, json.dumps(payload, indent=2, sort_keys=True) + "\n")
    written_report = write_unique_text(markdown_path, _render_arena_report_report(payload))
    return AgentArenaReportResult(
        experiment=spec.slug,
        arena_id=safe_arena_id,
        report_id=report_id,
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def create_agent_judge_panel(
    vault_dir: Path,
    config_data: Mapping[str, object],
    *,
    plan_id: str,
    metric_name: str = "judge_score",
    metric_direction: str = "maximize",
    judge_variants: tuple[str, ...] | None = None,
    replicas: int | None = None,
    include_pending_targets: bool = False,
    include_self_judges: bool = False,
    max_runs: int = MAX_JUDGE_PANEL_RUNS,
) -> AgentJudgePanelResult:
    _safe_plan_id(plan_id)
    spec = ExperimentSpec.from_mapping(config_data)
    metric = MetricSpec(
        name=_safe_label(metric_name),
        direction=_normalize_direction(metric_direction),
    )
    run_limit = _positive_int(max_runs, field="max_runs")
    if run_limit > MAX_JUDGE_PANEL_RUNS:
        raise ValueError(f"max_runs must be {MAX_JUDGE_PANEL_RUNS} or fewer")
    replica_count = _parallel_replicas(config_data, replicas=replicas)
    vault = ensure_vault(vault_dir)
    source_plan_path, source_plan = _load_plan_record(vault, plan_id)
    source_experiment = _plan_experiment(source_plan)
    if str(source_experiment["slug"]) != spec.slug:
        raise ValueError("judge panel config experiment must match the source plan")
    root = safe_child(vault, "agent-runs", spec.slug)
    outcomes_by_run = _latest_outcomes_by_run(_load_outcome_records(root))
    target_runs = _judge_panel_targets(
        root,
        source_plan,
        outcomes_by_run=outcomes_by_run,
        include_pending=include_pending_targets,
    )
    judges = _judge_panel_variants(spec, judge_variants)
    prompt = (
        source_plan.get("prompt")
        if isinstance(source_plan.get("prompt"), dict)
        else _content_fingerprint(None, source_name=None)
    )
    generated_at = _now()
    panel_id = _judge_panel_id(
        generated_at,
        spec.slug,
        plan_id,
        [str(item["run_id"]) for item in target_runs],
        [variant.id for variant in judges],
        metric.as_dict(),
    )
    judge_plan_id = _plan_id(
        generated_at=generated_at,
        experiment_slug=spec.slug,
        subject_hash=_hash_text(f"judge-panel\0{plan_id}\0{panel_id}"),
        prompt_sha256=prompt.get("sha256"),
    )
    runs: list[AgentRunResult] = []
    run_records: list[dict[str, object]] = []
    target_records: list[dict[str, object]] = []
    for target in target_runs:
        target_variant_id = str(target["variant_id"])
        target_outcome = outcomes_by_run.get(str(target["run_id"]))
        target_record = {
            "target_run_id": target["run_id"],
            "target_variant_id": target_variant_id,
            "source_lane_id": target.get("lane_id"),
            "source_role": target.get("role"),
            "source_replica": target.get("replica"),
            "outcome_id": target_outcome.get("outcome_id") if target_outcome else None,
            "outcome_status": target_outcome.get("status") if target_outcome else "pending",
            "output": (
                target_outcome.get("output")
                if isinstance(target_outcome, dict) and isinstance(target_outcome.get("output"), dict)
                else None
            ),
            "judge_runs": [],
        }
        for judge_variant in judges:
            if not include_self_judges and judge_variant.id == target_variant_id:
                continue
            for replica in range(1, replica_count + 1):
                if len(runs) >= run_limit:
                    continue
                child_subject = (
                    f"judge-panel\0{panel_id}\0{judge_plan_id}\0"
                    f"{target['run_id']}\0{judge_variant.id}\0{replica}"
                )
                context = {
                    "plan_id": judge_plan_id,
                    "judge_panel_id": panel_id,
                    "source_plan_id": plan_id,
                    "target_run_id": target["run_id"],
                    "target_variant_id": target_variant_id,
                    "judge_variant_id": judge_variant.id,
                    "lane_id": "judge",
                    "role": "judge",
                    "replica": replica,
                    "merge_strategy": "judge-panel",
                    "strategy": "judge-panel",
                    "metric": metric.as_dict(),
                }
                if target_record.get("outcome_id"):
                    context["target_outcome_id"] = target_record["outcome_id"]
                run = _write_agent_run(
                    vault,
                    spec,
                    selected=judge_variant,
                    bucket=_matrix_assignment_bucket(spec, judge_variant),
                    subject_key=child_subject,
                    prompt_text=None,
                    prompt_source_name=None,
                    prompt_fingerprint=prompt,
                    parallel_context=context,
                    assignment_strategy="judge-panel",
                )
                runs.append(run)
                record = {
                    "run_id": run.run_id,
                    "lane_id": "judge",
                    "role": "judge",
                    "replica": replica,
                    "variant_id": run.variant_id,
                    "path": _relative_vault_path(vault, run.path),
                    "judge_panel_id": panel_id,
                    "source_plan_id": plan_id,
                    "target_run_id": target["run_id"],
                    "target_variant_id": target_variant_id,
                    "judge_variant_id": judge_variant.id,
                }
                run_records.append(record)
                judge_runs = target_record.get("judge_runs")
                if isinstance(judge_runs, list):
                    judge_runs.append(
                        {
                            "run_id": run.run_id,
                            "judge_variant_id": judge_variant.id,
                            "replica": replica,
                        }
                    )
        target_records.append(target_record)
    scheduled_runs = len(runs)
    requested_runs = _judge_panel_requested_runs(
        target_runs,
        judges=judges,
        replicas=replica_count,
        include_self_judges=include_self_judges,
    )
    panel_status = (
        "scheduled-partial"
        if scheduled_runs < requested_runs and scheduled_runs
        else "scheduled"
        if scheduled_runs
        else "no-runs"
    )
    plan_path: Path | None = None
    plan_report_path: Path | None = None
    if scheduled_runs:
        plan_payload = _judge_panel_plan_payload(
            spec,
            generated_at=generated_at,
            plan_id=judge_plan_id,
            panel_id=panel_id,
            source_plan_id=plan_id,
            source_plan_path=_relative_vault_path(vault, source_plan_path),
            prompt=prompt,
            metric=metric,
            run_records=run_records,
        )
        plan_path = safe_child(root, "plans", f"{judge_plan_id}.json")
        plan_report_path = safe_child(root, "plans", f"{judge_plan_id}.md")
        plan_path.parent.mkdir(parents=True, exist_ok=True)
        plan_path = write_unique_text(
            plan_path,
            json.dumps(plan_payload, indent=2, sort_keys=True) + "\n",
        )
        plan_report_path = write_unique_text(plan_report_path, _render_plan_report(plan_payload))
    summary = {
        "target_count": len(target_runs),
        "judge_variant_count": len(judges),
        "replicas": replica_count,
        "requested_runs": requested_runs,
        "scheduled_runs": scheduled_runs,
        "max_runs": run_limit,
        "include_pending_targets": bool(include_pending_targets),
        "include_self_judges": bool(include_self_judges),
        "truncated": scheduled_runs < requested_runs,
    }
    payload: dict[str, object] = {
        "schema": AGENT_JUDGE_PANEL_SCHEMA,
        "panel_id": panel_id,
        "generated_at": generated_at,
        "experiment": spec.as_dict(),
        "panel_status": panel_status,
        "source_plan_id": plan_id,
        "source_plan_path": _relative_vault_path(vault, source_plan_path),
        "plan_id": judge_plan_id if scheduled_runs else None,
        "plan_path": _relative_vault_path(vault, plan_path) if plan_path else None,
        "plan_report_path": (
            _relative_vault_path(vault, plan_report_path) if plan_report_path else None
        ),
        "judge_metric": metric.as_dict(),
        "summary": summary,
        "policy": {
            "strategy": "multi-judge-panel",
            "replicas": replica_count,
            "max_runs": run_limit,
            "include_pending_targets": bool(include_pending_targets),
            "include_self_judges": bool(include_self_judges),
        },
        "judge_variants": [variant.as_dict() for variant in judges],
        "targets": target_records,
        "runs": run_records,
        "recommendations": _judge_panel_recommendations(panel_status, summary),
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["subject_key", "prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    panel_path = safe_child(root, "judge-panels", f"{panel_id}.json")
    report_path = safe_child(root, "judge-panels", f"{panel_id}.md")
    panel_path.parent.mkdir(parents=True, exist_ok=True)
    written_json = write_unique_text(panel_path, json.dumps(payload, indent=2, sort_keys=True) + "\n")
    written_report = write_unique_text(report_path, _render_judge_panel_report(payload))
    return AgentJudgePanelResult(
        experiment=spec.slug,
        panel_id=panel_id,
        plan_id=judge_plan_id if scheduled_runs else None,
        path=written_json,
        report_path=written_report,
        plan_path=plan_path,
        plan_report_path=plan_report_path,
        runs=tuple(runs),
        payload=payload,
    )


def report_agent_judge_panel(
    vault_dir: Path,
    *,
    panel_id: str,
    min_completed_ratio: float = 1.0,
) -> AgentJudgePanelReportResult:
    safe_panel_id = _safe_run_id(panel_id)
    completion_floor = _ratio(min_completed_ratio, field="min_completed_ratio")
    vault = ensure_vault(vault_dir)
    panel_path, panel = _load_judge_panel_record(vault, safe_panel_id)
    spec = ExperimentSpec.from_mapping(panel.get("experiment"))
    root = panel_path.parent.parent
    outcomes_by_run = _latest_outcomes_by_run(_load_outcome_records(root))
    metric = MetricSpec.from_value(panel.get("judge_metric"))
    target_summaries = _judge_panel_target_summaries(
        panel,
        outcomes_by_run=outcomes_by_run,
        metric=metric,
    )
    variant_summaries = _judge_panel_variant_summaries(
        spec,
        target_summaries,
        metric=metric,
    )
    judge_summaries = _judge_panel_judge_summaries(panel, outcomes_by_run=outcomes_by_run, metric=metric)
    winner_target = _judge_panel_winner_target(target_summaries, metric=metric)
    winner_variant = _judge_panel_winner_variant(variant_summaries, metric=metric)
    summary = _judge_panel_report_summary(
        panel,
        target_summaries,
        min_completed_ratio=completion_floor,
    )
    report_status = _judge_panel_report_status(summary)
    recommendations = _judge_panel_report_recommendations(
        summary,
        winner_variant_id=winner_variant,
    )
    generated_at = _now()
    report_id = _judge_panel_report_id(generated_at, safe_panel_id, summary, variant_summaries)
    payload: dict[str, object] = {
        "schema": AGENT_JUDGE_PANEL_REPORT_SCHEMA,
        "report_id": report_id,
        "panel_id": safe_panel_id,
        "generated_at": generated_at,
        "experiment": spec.as_dict(),
        "panel_path": _relative_vault_path(vault, panel_path),
        "source_plan_id": panel.get("source_plan_id"),
        "plan_id": panel.get("plan_id"),
        "report_status": report_status,
        "judge_metric": metric.as_dict(),
        "winner_target_run_id": winner_target.get("target_run_id") if winner_target else None,
        "winner_variant_id": winner_variant,
        "summary": summary,
        "target_summaries": target_summaries,
        "variant_summaries": variant_summaries,
        "judge_summaries": judge_summaries,
        "recommendations": recommendations,
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["subject_key", "prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    report_path = safe_child(root, "judge-panel-reports", f"{report_id}.json")
    markdown_path = safe_child(root, "judge-panel-reports", f"{report_id}.md")
    report_path.parent.mkdir(parents=True, exist_ok=True)
    written_json = write_unique_text(report_path, json.dumps(payload, indent=2, sort_keys=True) + "\n")
    written_report = write_unique_text(markdown_path, _render_judge_panel_report_report(payload))
    return AgentJudgePanelReportResult(
        experiment=spec.slug,
        panel_id=safe_panel_id,
        report_id=report_id,
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def _create_parallel_agent_plan(
    vault_dir: Path,
    config_data: Mapping[str, object],
    *,
    subject_key: str,
    prompt_text: str | None,
    prompt_source_name: str | None,
    lanes: tuple[str, ...] | None,
    replicas: int | None,
    strategy: str,
    prompt_fingerprint: Mapping[str, object] | None = None,
    suite_context: Mapping[str, object] | None = None,
    pipeline_context: Mapping[str, object] | None = None,
    matrix_variant_ids: tuple[str, ...] | None = None,
) -> AgentPlanResult:
    spec = ExperimentSpec.from_mapping(config_data)
    vault = ensure_vault(vault_dir)
    lane_specs = _parallel_lanes(config_data, lanes=lanes)
    replica_count = _parallel_replicas(config_data, replicas=replicas)
    matrix_mode = strategy == "variant-matrix"
    variant_choices: tuple[ModelVariant | None, ...] = (
        _matrix_variant_choices(spec, matrix_variant_ids)
        if matrix_mode
        else (None,)
    )
    run_count = len(lane_specs) * replica_count * len(variant_choices)
    if run_count > MAX_PARALLEL_RUNS:
        raise ValueError(f"parallel plan exceeds {MAX_PARALLEL_RUNS} run limit")

    generated_at = _now()
    subject_hash = _hash_text(f"subject\0{subject_key}")
    prompt = (
        _safe_prompt_fingerprint(prompt_fingerprint)
        if prompt_fingerprint is not None
        else _content_fingerprint(prompt_text, source_name=prompt_source_name)
    )
    config_hash = _hash_json(spec.as_dict())
    merge_strategy = _parallel_merge_strategy(config_data)
    plan_id = _plan_id(
        generated_at=generated_at,
        experiment_slug=spec.slug,
        subject_hash=subject_hash,
        prompt_sha256=prompt.get("sha256"),
    )
    runs: list[AgentRunResult] = []
    run_records: list[dict[str, object]] = []
    for lane in lane_specs:
        for replica in range(1, replica_count + 1):
            for forced_variant in variant_choices:
                variant_suffix = f"\0{forced_variant.id}" if forced_variant else ""
                child_subject = f"{subject_key}\0{plan_id}\0{lane.id}{variant_suffix}\0{replica}"
                if forced_variant is None:
                    selected, bucket = assign_variant(spec, child_subject)
                    assignment_strategy = "weighted-sha256"
                else:
                    selected = forced_variant
                    bucket = _matrix_assignment_bucket(spec, forced_variant)
                    assignment_strategy = "variant-matrix"
                context = {
                    "plan_id": plan_id,
                    "lane_id": lane.id,
                    "role": lane.role,
                    "replica": replica,
                    "merge_strategy": merge_strategy,
                    "strategy": strategy,
                }
                if forced_variant is not None:
                    context["matrix_cell"] = f"{lane.id}:{forced_variant.id}:{replica}"
                    context["forced_variant_id"] = forced_variant.id
                if lane.objective:
                    context["objective"] = lane.objective
                if suite_context:
                    context["suite_id"] = suite_context["suite_id"]
                    context["suite_slug"] = suite_context["suite_slug"]
                    context["case_id"] = suite_context["case_id"]
                    context["case_hash"] = suite_context["case_hash"]
                    if suite_context.get("curriculum_id"):
                        context["curriculum_id"] = suite_context["curriculum_id"]
                    if suite_context.get("curriculum_case_rank"):
                        context["curriculum_case_rank"] = suite_context["curriculum_case_rank"]
                if pipeline_context:
                    context["pipeline_id"] = pipeline_context["pipeline_id"]
                    context["pipeline_slug"] = pipeline_context["pipeline_slug"]
                    context["stage_id"] = pipeline_context["stage_id"]
                    context["stage_order"] = pipeline_context["stage_order"]
                run = _write_agent_run(
                    vault,
                    spec,
                    selected=selected,
                    bucket=bucket,
                    subject_key=child_subject,
                    prompt_text=prompt_text,
                    prompt_source_name=prompt_source_name,
                    prompt_fingerprint=prompt if prompt_fingerprint is not None else None,
                    parallel_context=context,
                    assignment_strategy=assignment_strategy,
                )
                runs.append(run)
                record = {
                    "run_id": run.run_id,
                    "lane_id": lane.id,
                    "role": lane.role,
                    "replica": replica,
                    "variant_id": run.variant_id,
                    "path": _relative_vault_path(vault, run.path),
                }
                if forced_variant is not None:
                    record["matrix_cell"] = context["matrix_cell"]
                run_records.append(record)
    payload: dict[str, object] = {
        "schema": AGENT_PLAN_SCHEMA,
        "plan_id": plan_id,
        "generated_at": generated_at,
        "experiment": {
            "name": spec.name,
            "slug": spec.slug,
            "config_hash": config_hash,
            "description": spec.description,
            "primary_metric": spec.primary_metric.as_dict(),
            "rubric": spec.rubric.as_dict(),
            "traffic_salt": spec.traffic_salt,
            "guardrails": list(spec.guardrails),
            "min_trials_per_variant": spec.min_trials_per_variant,
        },
        "parallel": {
            "strategy": strategy,
            "merge_strategy": merge_strategy,
            "replicas": replica_count,
            "lane_count": len(lane_specs),
            "variant_count": len(variant_choices) if matrix_mode else None,
            "matrix_variant_ids": [
                variant.id
                for variant in variant_choices
                if isinstance(variant, ModelVariant)
            ],
            "run_count": len(runs),
            "lanes": [item.as_dict() for item in lane_specs],
            "subject_hash": subject_hash,
        },
        "variants": [item.as_dict() for item in spec.variants],
        "prompt": prompt,
        "runs": run_records,
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["subject_key", "prompt_text", "raw_transcript", "raw_output"],
        },
    }
    if suite_context:
        payload["suite"] = dict(suite_context)
    if pipeline_context:
        payload["pipeline"] = dict(pipeline_context)
    if not matrix_mode:
        parallel_payload = payload["parallel"]
        if isinstance(parallel_payload, dict):
            parallel_payload.pop("variant_count", None)
    plan_path = safe_child(vault, "agent-runs", spec.slug, "plans", f"{plan_id}.json")
    report_path = safe_child(vault, "agent-runs", spec.slug, "plans", f"{plan_id}.md")
    plan_path.parent.mkdir(parents=True, exist_ok=True)
    written_json = write_unique_text(plan_path, json.dumps(payload, indent=2, sort_keys=True) + "\n")
    written_report = write_unique_text(report_path, _render_plan_report(payload))
    return AgentPlanResult(
        experiment=spec.slug,
        plan_id=plan_id,
        path=written_json,
        report_path=written_report,
        runs=tuple(runs),
        payload=payload,
    )


def merge_agent_plan(vault_dir: Path, *, plan_id: str) -> AgentMergeResult:
    _safe_plan_id(plan_id)
    vault = ensure_vault(vault_dir)
    plan_path, plan = _load_plan_record(vault, plan_id)
    experiment = _plan_experiment(plan)
    experiment_slug = str(experiment["slug"])
    root = safe_child(vault, "agent-runs", experiment_slug)
    outcomes_by_run = _latest_outcomes_by_run(_load_outcome_records(root))
    metric = MetricSpec.from_value(experiment.get("primary_metric"))
    expected_runs = _effective_plan_runs(root, plan)
    lane_summaries = _plan_lane_summaries(
        plan,
        outcomes_by_run,
        primary_metric=metric,
        plan_runs=expected_runs,
    )
    recommended = _recommended_plan_run(lane_summaries, primary_metric=metric)
    generated_at = _now()
    merge_id = _merge_id(generated_at, plan_id, lane_summaries)
    completed = sum(1 for item in expected_runs if item["run_id"] in outcomes_by_run)
    if completed == 0:
        merge_status = "no-outcomes"
    elif completed == len(expected_runs):
        merge_status = "complete"
    else:
        merge_status = "partial"
    payload: dict[str, object] = {
        "schema": AGENT_MERGE_SCHEMA,
        "merge_id": merge_id,
        "plan_id": plan_id,
        "generated_at": generated_at,
        "experiment": experiment,
        "plan_path": _relative_vault_path(vault, plan_path),
        "merge_status": merge_status,
        "expected_runs": len(expected_runs),
        "completed_runs": completed,
        "primary_metric": metric.as_dict(),
        "lane_summaries": lane_summaries,
        "recommended_run_id": recommended["run_id"] if recommended else None,
        "recommended_variant_id": recommended["variant_id"] if recommended else None,
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    merge_path = safe_child(root, "merges", f"{merge_id}.json")
    report_path = safe_child(root, "merges", f"{merge_id}.md")
    merge_path.parent.mkdir(parents=True, exist_ok=True)
    written_json = write_unique_text(merge_path, json.dumps(payload, indent=2, sort_keys=True) + "\n")
    written_report = write_unique_text(report_path, _render_merge_report(payload))
    return AgentMergeResult(
        experiment=experiment_slug,
        merge_id=merge_id,
        plan_id=plan_id,
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def claim_agent_run(
    vault_dir: Path,
    *,
    plan_id: str,
    client_id: str,
    lane_id: str | None = None,
    ttl_seconds: int = DEFAULT_CLAIM_TTL_SECONDS,
    claim_strategy: str = DEFAULT_CLAIM_STRATEGY,
) -> AgentClaimResult:
    _safe_plan_id(plan_id)
    client = _safe_text_label(client_id, field="client_id", max_length=120)
    ttl = _bounded_ttl(ttl_seconds)
    requested_lane = slugify(lane_id, fallback="lane") if lane_id else None
    strategy = _claim_strategy(claim_strategy)
    vault = ensure_vault(vault_dir)
    plan_path, plan = _load_plan_record(vault, plan_id)
    experiment = _plan_experiment(plan)
    experiment_slug = str(experiment["slug"])
    root = safe_child(vault, "agent-runs", experiment_slug)
    with _agent_claim_lock(root, plan_id):
        _raise_for_active_holds(root, scopes=("dispatch",))
        outcomes_by_run = _latest_outcomes_by_run(_load_outcome_records(root))
        run_records_by_id = {
            str(item.get("run_id")): item
            for item in _load_run_records(root)
            if isinstance(item.get("run_id"), str)
        }
        claims = _load_schema_records(root, "claims", AGENT_CLAIM_SCHEMA)
        heartbeats = _load_schema_records(root, "heartbeats", AGENT_HEARTBEAT_SCHEMA)
        now = _utc_now()
        active_claims = _active_claims_by_run(claims, heartbeats=heartbeats, now=now)
        active_quarantines = _active_agent_quarantines(root, now=now)
        plan_runs = _effective_plan_runs(root, plan)
        candidate_pool = _claim_candidates(
            plan_runs,
            requested_lane=requested_lane,
            outcomes_by_run=outcomes_by_run,
            active_claims=active_claims,
            active_quarantines=[],
            run_records_by_id=run_records_by_id,
        )
        candidates = _claim_candidates(
            plan_runs,
            requested_lane=requested_lane,
            outcomes_by_run=outcomes_by_run,
            active_claims=active_claims,
            active_quarantines=active_quarantines,
            run_records_by_id=run_records_by_id,
        )
        candidate = _select_claim_candidate(
            plan_runs,
            candidates,
            requested_lane=requested_lane,
            outcomes_by_run=outcomes_by_run,
            active_claims=active_claims,
            strategy=strategy,
        )
        if candidate is None:
            raise FileNotFoundError("No unclaimed pending agent run is available for this plan")

        claimed_at_dt = _utc_now()
        expires_at_dt = claimed_at_dt + timedelta(seconds=ttl)
        claim_id = _claim_id(claimed_at_dt.isoformat(), plan_id, str(candidate["run_id"]), client)
        payload: dict[str, object] = {
            "schema": AGENT_CLAIM_SCHEMA,
            "claim_id": claim_id,
            "generated_at": claimed_at_dt.isoformat(),
            "plan_id": plan_id,
            "experiment": experiment,
            "plan_path": _relative_vault_path(vault, plan_path),
            "run": candidate,
            "claim": {
                "client_id": client,
                "claimed_at": claimed_at_dt.isoformat(),
                "expires_at": expires_at_dt.isoformat(),
                "ttl_seconds": ttl,
                "status": "active",
            },
            "scheduler": {
                "strategy": strategy,
                "lane_id": requested_lane,
                "candidate_count": len(candidates),
                "quarantined_candidate_count": len(candidate_pool) - len(candidates),
                "active_quarantine_count": len(active_quarantines),
            },
            "privacy": {
                "mode": "metadata-only",
                "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
            },
        }
        claim_path = safe_child(root, "claims", f"{claim_id}.json")
        claim_path.parent.mkdir(parents=True, exist_ok=True)
        written = write_unique_text(claim_path, json.dumps(payload, indent=2, sort_keys=True) + "\n")
    return AgentClaimResult(
        experiment=experiment_slug,
        plan_id=plan_id,
        run_id=str(candidate["run_id"]),
        claim_id=claim_id,
        path=written,
        payload=payload,
    )


def dispatch_agent_plan(
    vault_dir: Path,
    *,
    plan_id: str,
    client_prefix: str,
    count: int,
    lane_id: str | None = None,
    ttl_seconds: int = DEFAULT_CLAIM_TTL_SECONDS,
    claim_strategy: str = DEFAULT_CLAIM_STRATEGY,
) -> AgentDispatchResult:
    _safe_plan_id(plan_id)
    requested_count = _positive_int(count, field="dispatch count")
    if requested_count > MAX_PARALLEL_RUNS:
        raise ValueError(f"dispatch count must be {MAX_PARALLEL_RUNS} or fewer")
    client = _safe_text_label(client_prefix, field="client_prefix", max_length=100)
    ttl = _bounded_ttl(ttl_seconds)
    requested_lane = slugify(lane_id, fallback="lane") if lane_id else None
    strategy = _claim_strategy(claim_strategy)
    vault = ensure_vault(vault_dir)
    plan_path, plan = _load_plan_record(vault, plan_id)
    experiment = _plan_experiment(plan)
    experiment_slug = str(experiment["slug"])
    root = safe_child(vault, "agent-runs", experiment_slug)
    claims: list[AgentClaimResult] = []
    packets: list[AgentWorkPacketResult] = []
    entries: list[dict[str, object]] = []
    for index in range(requested_count):
        worker_id = f"{client}-{index + 1:03d}"
        try:
            claim = claim_agent_run(
                vault,
                plan_id=plan_id,
                client_id=worker_id,
                lane_id=requested_lane,
                ttl_seconds=ttl,
                claim_strategy=strategy,
            )
        except FileNotFoundError:
            break
        packet = write_agent_work_packet(vault, claim_id=claim.claim_id)
        claims.append(claim)
        packets.append(packet)
        entries.append(_dispatch_entry(vault, claim, packet, worker_id=worker_id))
    if not entries:
        raise FileNotFoundError("No unclaimed pending agent runs are available for dispatch")

    generated_at = _now()
    dispatch_id = _dispatch_id(generated_at, plan_id, client, entries)
    dispatch_status = "complete" if len(entries) == requested_count else "partial"
    payload: dict[str, object] = {
        "schema": AGENT_DISPATCH_SCHEMA,
        "dispatch_id": dispatch_id,
        "generated_at": generated_at,
        "plan_id": plan_id,
        "experiment": experiment,
        "plan_path": _relative_vault_path(vault, plan_path),
        "dispatch_status": dispatch_status,
        "client_prefix": client,
        "lane_id": requested_lane,
        "ttl_seconds": ttl,
        "claim_strategy": strategy,
        "requested_count": requested_count,
        "claimed_count": len(claims),
        "work_packet_count": len(packets),
        "entries": entries,
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    dispatch_path = safe_child(root, "dispatches", f"{dispatch_id}.json")
    report_path = safe_child(root, "dispatches", f"{dispatch_id}.md")
    dispatch_path.parent.mkdir(parents=True, exist_ok=True)
    written_json = write_unique_text(
        dispatch_path,
        json.dumps(payload, indent=2, sort_keys=True) + "\n",
    )
    written_report = write_unique_text(report_path, _render_dispatch_report(payload))
    return AgentDispatchResult(
        experiment=experiment_slug,
        plan_id=plan_id,
        dispatch_id=dispatch_id,
        path=written_json,
        report_path=written_report,
        claims=tuple(claims),
        work_packets=tuple(packets),
        payload=payload,
    )


def hold_agent_experiment(
    vault_dir: Path,
    *,
    experiment: str,
    reason: str,
    scopes: tuple[str, ...] | None = None,
    ttl_seconds: int | None = None,
    operator: str | None = None,
) -> AgentHoldResult:
    vault = ensure_vault(vault_dir)
    experiment_slug = slugify(experiment, fallback="agent-experiment")
    root = safe_child(vault, "agent-runs", experiment_slug)
    root.mkdir(parents=True, exist_ok=True)
    scope_list = _hold_scopes(scopes)
    reason_text = _safe_text_label(reason, field="hold reason", max_length=220)
    ttl = _hold_ttl(ttl_seconds)
    generated_at_dt = _utc_now()
    generated_at = generated_at_dt.isoformat()
    expires_at = (generated_at_dt + timedelta(seconds=ttl)).isoformat() if ttl else None
    hold_id = _hold_id(generated_at, experiment_slug, "hold", scope_list, reason_text)
    payload: dict[str, object] = {
        "schema": AGENT_HOLD_SCHEMA,
        "hold_id": hold_id,
        "generated_at": generated_at,
        "experiment": _hold_experiment_payload(root),
        "action": "hold",
        "hold_status": "active",
        "scopes": list(scope_list),
        "reason": reason_text,
        "expires_at": expires_at,
        "operator": _optional_safe_text(operator, field="operator", max_length=120),
        "released_hold_ids": [],
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    active_before = _active_agent_holds(root, scopes=scope_list, now=generated_at_dt)
    payload["active_holds"] = active_before + [_agent_hold_summary(payload, experiment=experiment_slug)]
    hold_path = safe_child(root, "holds", f"{hold_id}.json")
    report_path = safe_child(root, "holds", f"{hold_id}.md")
    hold_path.parent.mkdir(parents=True, exist_ok=True)
    written_json = write_unique_text(hold_path, json.dumps(payload, indent=2, sort_keys=True) + "\n")
    written_report = write_unique_text(report_path, _render_hold_report(payload))
    return AgentHoldResult(
        experiment=experiment_slug,
        hold_id=hold_id,
        active=True,
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def release_agent_hold(
    vault_dir: Path,
    *,
    experiment: str,
    reason: str = "operator release",
    hold_id: str | None = None,
    scopes: tuple[str, ...] | None = None,
    operator: str | None = None,
) -> AgentHoldResult:
    vault = ensure_vault(vault_dir)
    experiment_slug = slugify(experiment, fallback="agent-experiment")
    root = safe_child(vault, "agent-runs", experiment_slug)
    if not root.exists():
        raise FileNotFoundError(f"Agent experiment does not exist: {experiment_slug}")
    scope_list = _hold_scopes(scopes)
    reason_text = _safe_text_label(reason, field="release reason", max_length=220)
    safe_hold_id = _safe_run_id(hold_id) if hold_id else None
    generated_at_dt = _utc_now()
    generated_at = generated_at_dt.isoformat()
    active_before = _active_agent_holds(root, scopes=scope_list, now=generated_at_dt)
    if safe_hold_id:
        if not any(str(item.get("hold_id") or "") == safe_hold_id for item in active_before):
            raise FileNotFoundError(f"Active agent hold not found: {safe_hold_id}")
        released_hold_ids = [safe_hold_id]
    else:
        released_hold_ids = [str(item["hold_id"]) for item in active_before if item.get("hold_id")]
    release_id = _hold_id(generated_at, experiment_slug, "release", scope_list, reason_text)
    hold_status = "released" if released_hold_ids else "no-active-hold"
    payload: dict[str, object] = {
        "schema": AGENT_HOLD_SCHEMA,
        "hold_id": release_id,
        "generated_at": generated_at,
        "experiment": _hold_experiment_payload(root),
        "action": "release",
        "hold_status": hold_status,
        "scopes": list(scope_list),
        "reason": reason_text,
        "expires_at": None,
        "operator": _optional_safe_text(operator, field="operator", max_length=120),
        "released_hold_ids": released_hold_ids,
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    payload["active_holds"] = [
        item for item in active_before if str(item.get("hold_id") or "") not in set(released_hold_ids)
    ]
    hold_path = safe_child(root, "holds", f"{release_id}.json")
    report_path = safe_child(root, "holds", f"{release_id}.md")
    hold_path.parent.mkdir(parents=True, exist_ok=True)
    written_json = write_unique_text(hold_path, json.dumps(payload, indent=2, sort_keys=True) + "\n")
    written_report = write_unique_text(report_path, _render_hold_report(payload))
    return AgentHoldResult(
        experiment=experiment_slug,
        hold_id=release_id,
        active=bool(payload["active_holds"]),
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def quarantine_agent_slice(
    vault_dir: Path,
    *,
    experiment: str,
    reason: str,
    variant_ids: tuple[str, ...] | None = None,
    providers: tuple[str, ...] | None = None,
    lanes: tuple[str, ...] | None = None,
    ttl_seconds: int | None = None,
    operator: str | None = None,
) -> AgentQuarantineResult:
    vault = ensure_vault(vault_dir)
    experiment_slug = slugify(experiment, fallback="agent-experiment")
    root = safe_child(vault, "agent-runs", experiment_slug)
    if not root.exists():
        raise FileNotFoundError(f"Agent experiment does not exist: {experiment_slug}")
    target = _quarantine_target(
        variant_ids=variant_ids,
        providers=providers,
        lanes=lanes,
    )
    quarantine_reason = _safe_text_label(reason, field="quarantine reason", max_length=240)
    ttl = _quarantine_ttl(ttl_seconds)
    operator_label = _optional_safe_text(operator, field="operator", max_length=120)
    generated_at_dt = _utc_now()
    expires_at = (
        (generated_at_dt + timedelta(seconds=ttl)).isoformat()
        if ttl is not None
        else None
    )
    quarantine_id = _quarantine_id(
        generated_at_dt.isoformat(),
        experiment_slug,
        "quarantine",
        target,
        quarantine_reason,
    )
    payload: dict[str, object] = {
        "schema": AGENT_QUARANTINE_SCHEMA,
        "quarantine_id": quarantine_id,
        "generated_at": generated_at_dt.isoformat(),
        "experiment": _hold_experiment_payload(root),
        "action": "quarantine",
        "quarantine_status": "active",
        "target": target,
        "reason": quarantine_reason,
        "operator": operator_label,
        "expires_at": expires_at,
        "ttl_seconds": ttl,
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    active_before = _active_agent_quarantines(root, now=generated_at_dt)
    payload["active_quarantines"] = active_before + [
        _agent_quarantine_summary(payload, experiment=experiment_slug)
    ]
    quarantine_path = safe_child(root, "quarantines", f"{quarantine_id}.json")
    report_path = safe_child(root, "quarantines", f"{quarantine_id}.md")
    quarantine_path.parent.mkdir(parents=True, exist_ok=True)
    written_json = write_unique_text(quarantine_path, json.dumps(payload, indent=2, sort_keys=True) + "\n")
    written_report = write_unique_text(report_path, _render_quarantine_report(payload))
    return AgentQuarantineResult(
        experiment=experiment_slug,
        quarantine_id=quarantine_id,
        active=True,
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def release_agent_quarantine(
    vault_dir: Path,
    *,
    experiment: str,
    reason: str = "operator release",
    quarantine_id: str | None = None,
    variant_ids: tuple[str, ...] | None = None,
    providers: tuple[str, ...] | None = None,
    lanes: tuple[str, ...] | None = None,
    operator: str | None = None,
) -> AgentQuarantineResult:
    vault = ensure_vault(vault_dir)
    experiment_slug = slugify(experiment, fallback="agent-experiment")
    root = safe_child(vault, "agent-runs", experiment_slug)
    if not root.exists():
        raise FileNotFoundError(f"Agent experiment does not exist: {experiment_slug}")
    safe_quarantine_id = _safe_run_id(quarantine_id) if quarantine_id else None
    target = _quarantine_target(
        variant_ids=variant_ids,
        providers=providers,
        lanes=lanes,
        require_non_empty=safe_quarantine_id is None,
    )
    release_reason = _safe_text_label(reason, field="quarantine release reason", max_length=240)
    operator_label = _optional_safe_text(operator, field="operator", max_length=120)
    generated_at_dt = _utc_now()
    active_before = _active_agent_quarantines(root, now=generated_at_dt)
    if safe_quarantine_id:
        released_ids = [
            str(item.get("quarantine_id"))
            for item in active_before
            if item.get("quarantine_id") == safe_quarantine_id
        ]
        if not released_ids:
            raise FileNotFoundError(f"Active agent quarantine not found: {safe_quarantine_id}")
    else:
        released_ids = [
            str(item.get("quarantine_id"))
            for item in active_before
            if _quarantine_targets_overlap(
                _quarantine_record_target(item),
                target,
            )
        ]
    release_id = _quarantine_id(
        generated_at_dt.isoformat(),
        experiment_slug,
        "release",
        target,
        release_reason,
    )
    payload: dict[str, object] = {
        "schema": AGENT_QUARANTINE_SCHEMA,
        "quarantine_id": release_id,
        "generated_at": generated_at_dt.isoformat(),
        "experiment": _hold_experiment_payload(root),
        "action": "release",
        "quarantine_status": "released",
        "target": target,
        "reason": release_reason,
        "operator": operator_label,
        "released_quarantine_ids": released_ids,
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    payload["active_quarantines"] = [
        item
        for item in active_before
        if str(item.get("quarantine_id") or "") not in set(released_ids)
    ]
    quarantine_path = safe_child(root, "quarantines", f"{release_id}.json")
    report_path = safe_child(root, "quarantines", f"{release_id}.md")
    quarantine_path.parent.mkdir(parents=True, exist_ok=True)
    written_json = write_unique_text(quarantine_path, json.dumps(payload, indent=2, sort_keys=True) + "\n")
    written_report = write_unique_text(report_path, _render_quarantine_report(payload))
    return AgentQuarantineResult(
        experiment=experiment_slug,
        quarantine_id=release_id,
        active=bool(payload["active_quarantines"]),
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def evaluate_agent_circuit(
    vault_dir: Path,
    *,
    experiment: str,
    group_by: str = "provider",
    min_outcomes: int = 3,
    recent_limit: int | None = None,
    max_failure_rate: float = 0.5,
    max_mean_latency_ms: float | None = None,
    max_mean_cost_usd: float | None = None,
    min_primary_metric: float | None = None,
    quarantine_on_trip: bool = False,
    quarantine_ttl_seconds: int | None = None,
    operator: str | None = None,
) -> AgentCircuitResult:
    group = _circuit_group(group_by)
    min_count = _positive_int(min_outcomes, field="min_outcomes")
    limit = _optional_positive_int(recent_limit, field="recent_limit")
    failure_ceiling = _ratio(max_failure_rate, field="max_failure_rate")
    latency_ceiling = _optional_non_negative_number(max_mean_latency_ms, field="max_mean_latency_ms")
    cost_ceiling = _optional_non_negative_number(max_mean_cost_usd, field="max_mean_cost_usd")
    metric_floor = _optional_finite(min_primary_metric, field="min_primary_metric")
    ttl = _quarantine_ttl(quarantine_ttl_seconds)
    operator_label = _optional_safe_text(operator, field="operator", max_length=120)
    vault = ensure_vault(vault_dir)
    experiment_slug = slugify(experiment, fallback="agent-experiment")
    root = safe_child(vault, "agent-runs", experiment_slug)
    if not root.exists():
        raise FileNotFoundError(f"Agent experiment does not exist: {experiment_slug}")
    runs = _load_run_records(root)
    if not runs:
        raise FileNotFoundError(f"Agent experiment has no run records: {experiment_slug}")
    spec = _spec_from_run(runs[-1])
    runs_by_id = {
        str(item.get("run_id")): item
        for item in runs
        if isinstance(item.get("run_id"), str)
    }
    latest_outcomes = list(_latest_outcomes_by_run(_load_outcome_records(root)).values())
    latest_outcomes.sort(key=lambda item: str(item.get("logged_at") or ""))
    scoped_outcomes = latest_outcomes[-limit:] if limit is not None else latest_outcomes
    rows = _circuit_group_rows(
        spec,
        scoped_outcomes,
        runs_by_id=runs_by_id,
        group_by=group,
        min_outcomes=min_count,
        max_failure_rate=failure_ceiling,
        max_mean_latency_ms=latency_ceiling,
        max_mean_cost_usd=cost_ceiling,
        min_primary_metric=metric_floor,
    )
    findings = _circuit_findings(rows)
    tripped_rows = [row for row in rows if row.get("circuit_state") == "tripped"]
    actions: list[dict[str, object]] = []
    if quarantine_on_trip:
        for row in tripped_rows:
            group_value = str(row.get("group") or "")
            if not group_value:
                continue
            try:
                quarantine = quarantine_agent_slice(
                    vault,
                    experiment=experiment_slug,
                    reason=f"circuit breaker tripped for {group} {group_value}",
                    variant_ids=(group_value,) if group == "variant" else None,
                    providers=(group_value,) if group == "provider" else None,
                    lanes=(group_value,) if group == "lane" else None,
                    ttl_seconds=ttl,
                    operator=operator_label,
                )
            except Exception as exc:
                actions.append(
                    {
                        "action": "quarantine",
                        "status": "failed",
                        "group_by": group,
                        "group": group_value,
                        "error": _safe_text_label(str(exc), field="circuit action error", max_length=220),
                    }
                )
                continue
            actions.append(
                {
                    "action": "quarantine",
                    "status": "written",
                    "group_by": group,
                    "group": group_value,
                    "quarantine_id": quarantine.quarantine_id,
                    "path": _relative_vault_path(vault, quarantine.path),
                    "report_path": _relative_vault_path(vault, quarantine.report_path),
                }
            )
    fail_count = sum(1 for item in findings if item.get("severity") == "fail")
    warn_count = sum(1 for item in findings if item.get("severity") == "warn")
    circuit_status = (
        "tripped"
        if fail_count
        else "watch"
        if warn_count
        else "healthy"
    )
    generated_at = _now()
    summary = {
        "outcome_count": len(scoped_outcomes),
        "group_count": len(rows),
        "tripped_groups": len(tripped_rows),
        "action_count": len(actions),
        "fail": fail_count,
        "warn": warn_count,
        "pass": sum(1 for item in findings if item.get("severity") == "pass"),
        "findings": len(findings),
    }
    circuit_id = _circuit_id(generated_at, experiment_slug, group, summary, rows)
    payload: dict[str, object] = {
        "schema": AGENT_CIRCUIT_SCHEMA,
        "circuit_id": circuit_id,
        "generated_at": generated_at,
        "experiment": spec.as_dict(),
        "circuit_status": circuit_status,
        "tripped": bool(fail_count),
        "primary_metric": spec.primary_metric.as_dict(),
        "policy": {
            "group_by": group,
            "min_outcomes": min_count,
            "recent_limit": limit,
            "max_failure_rate": failure_ceiling,
            "max_mean_latency_ms": latency_ceiling,
            "max_mean_cost_usd": cost_ceiling,
            "min_primary_metric": metric_floor,
            "quarantine_on_trip": bool(quarantine_on_trip),
            "quarantine_ttl_seconds": ttl,
        },
        "summary": summary,
        "groups": rows,
        "findings": findings,
        "actions": actions,
        "recommendations": _circuit_recommendations(circuit_status, findings, actions),
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    circuit_path = safe_child(root, "circuits", f"{circuit_id}.json")
    report_path = safe_child(root, "circuits", f"{circuit_id}.md")
    circuit_path.parent.mkdir(parents=True, exist_ok=True)
    written_json = write_unique_text(circuit_path, json.dumps(payload, indent=2, sort_keys=True) + "\n")
    written_report = write_unique_text(report_path, _render_circuit_report(payload))
    return AgentCircuitResult(
        experiment=experiment_slug,
        circuit_id=circuit_id,
        tripped=bool(fail_count),
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def orchestrate_agent_dispatch(
    vault_dir: Path,
    *,
    plan_id: str | None = None,
    suite_id: str | None = None,
    client_prefix: str,
    max_concurrency: int,
    batch_size: int | None = None,
    lane_id: str | None = None,
    ttl_seconds: int = DEFAULT_CLAIM_TTL_SECONDS,
    stale_after_seconds: int = 1800,
    claim_strategy: str = DEFAULT_CLAIM_STRATEGY,
) -> AgentOrchestrationResult:
    if bool(plan_id) == bool(suite_id):
        raise ValueError("provide exactly one of plan_id or suite_id")
    max_active = _positive_int(max_concurrency, field="max_concurrency")
    if max_active > MAX_PARALLEL_RUNS:
        raise ValueError(f"max_concurrency must be {MAX_PARALLEL_RUNS} or fewer")
    batch_limit = (
        _positive_int(batch_size, field="batch_size")
        if batch_size is not None
        else max_active
    )
    if batch_limit > MAX_PARALLEL_RUNS:
        raise ValueError(f"batch_size must be {MAX_PARALLEL_RUNS} or fewer")
    client = _safe_text_label(client_prefix, field="client_prefix", max_length=100)
    ttl = _bounded_ttl(ttl_seconds)
    stale_after = _positive_int(stale_after_seconds, field="stale_after_seconds")
    requested_lane = slugify(lane_id, fallback="lane") if lane_id else None
    strategy = _claim_strategy(claim_strategy)

    vault = ensure_vault(vault_dir)
    plan_refs = _orchestration_plan_refs(vault, plan_id=plan_id, suite_id=suite_id)
    generated_at = _now()
    now = _parse_datetime(generated_at) or _utc_now()
    before_plans = [
        _orchestration_plan_summary(
            vault,
            ref,
            lane_id=requested_lane,
            now=now,
            stale_after_seconds=stale_after,
        )
        for ref in plan_refs
    ]
    before_summary = _orchestration_totals(before_plans)
    active_holds = _active_holds_for_plan_refs(plan_refs, scopes=("dispatch",), now=now)
    capacity = 0 if active_holds else max(0, max_active - int(before_summary["active_claims"]))
    dispatches: list[AgentDispatchResult] = []

    for ref, summary in zip(plan_refs, before_plans):
        if capacity <= 0:
            break
        pending = int(summary.get("pending_runs") or 0)
        if pending <= 0:
            continue
        requested_count = min(batch_limit, capacity, pending)
        if requested_count <= 0:
            continue
        dispatch = dispatch_agent_plan(
            vault,
            plan_id=str(ref["plan_id"]),
            client_prefix=f"{client}-{len(dispatches) + 1:03d}",
            count=requested_count,
            lane_id=requested_lane,
            ttl_seconds=ttl,
            claim_strategy=strategy,
        )
        dispatches.append(dispatch)
        claimed = int(dispatch.payload.get("claimed_count") or 0)
        capacity = max(0, capacity - claimed)

    after_now = _utc_now()
    after_plans = [
        _orchestration_plan_summary(
            vault,
            ref,
            lane_id=requested_lane,
            now=after_now,
            stale_after_seconds=stale_after,
        )
        for ref in plan_refs
    ]
    after_summary = _orchestration_totals(after_plans)
    dispatch_records = [
        {
            "dispatch_id": item.dispatch_id,
            "experiment": item.experiment,
            "plan_id": item.plan_id,
            "path": _relative_vault_path(vault, item.path),
            "report_path": _relative_vault_path(vault, item.report_path),
            "dispatch_status": item.payload["dispatch_status"],
            "requested_count": item.payload["requested_count"],
            "claimed_count": item.payload["claimed_count"],
            "work_packet_count": item.payload["work_packet_count"],
        }
        for item in dispatches
    ]
    scope = _orchestration_scope(plan_id=plan_id, suite_id=suite_id, plan_refs=plan_refs)
    status = _orchestration_status(
        before_summary=before_summary,
        after_summary=after_summary,
        dispatch_count=len(dispatches),
        max_concurrency=max_active,
        active_holds=active_holds,
    )
    summary = dict(after_summary)
    summary.update(
        {
            "dispatch_count": len(dispatches),
            "claimed_count": sum(int(item.payload.get("claimed_count") or 0) for item in dispatches),
            "work_packet_count": sum(
                int(item.payload.get("work_packet_count") or 0) for item in dispatches
            ),
            "active_before": before_summary["active_claims"],
            "pending_before": before_summary["pending_runs"],
            "capacity_before": 0 if active_holds else max(0, max_active - int(before_summary["active_claims"])),
            "remaining_capacity": max(0, max_active - int(after_summary["active_claims"])),
            "active_holds": len(active_holds),
        }
    )
    recommendations = _orchestration_recommendations(status, summary)
    orchestration_id = _orchestration_id(
        generated_at,
        scope=scope,
        plan_ids=[str(item["plan_id"]) for item in plan_refs],
        summary=summary,
        dispatches=dispatch_records,
    )
    payload: dict[str, object] = {
        "schema": AGENT_ORCHESTRATION_SCHEMA,
        "orchestration_id": orchestration_id,
        "generated_at": generated_at,
        "scope": scope,
        "orchestration_status": status,
        "policy": {
            "scheduler": "oldest-plan-first",
            "max_concurrency": max_active,
            "batch_size": batch_limit,
            "lane_id": requested_lane,
            "ttl_seconds": ttl,
            "stale_after_seconds": stale_after,
            "client_prefix": client,
            "claim_strategy": strategy,
        },
        "summary": summary,
        "plans_before": before_plans,
        "plans": after_plans,
        "dispatches": dispatch_records,
        "active_holds": active_holds,
        "recommendations": recommendations,
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    report_root = safe_child(vault, "agent-runs", "_reports")
    report_root.mkdir(parents=True, exist_ok=True)
    orchestration_path = report_root / f"{orchestration_id}.json"
    report_path = report_root / f"{orchestration_id}.md"
    written_json = write_unique_text(
        orchestration_path,
        json.dumps(payload, indent=2, sort_keys=True) + "\n",
    )
    written_report = write_unique_text(report_path, _render_orchestration_report(payload))
    return AgentOrchestrationResult(
        orchestration_id=orchestration_id,
        path=written_json,
        report_path=written_report,
        dispatches=tuple(dispatches),
        payload=payload,
    )


def heartbeat_agent_claim(
    vault_dir: Path,
    *,
    claim_id: str,
    client_id: str,
    ttl_seconds: int = DEFAULT_CLAIM_TTL_SECONDS,
) -> AgentHeartbeatResult:
    _safe_run_id(claim_id)
    client = _safe_text_label(client_id, field="client_id", max_length=120)
    ttl = _bounded_ttl(ttl_seconds)
    vault = ensure_vault(vault_dir)
    claim_path, claim = _load_claim_record(vault, claim_id)
    experiment = claim.get("experiment") if isinstance(claim.get("experiment"), dict) else {}
    experiment_slug = str(experiment.get("slug") or "")
    if not experiment_slug:
        raise ValueError("agent claim record is missing experiment slug")
    claim_body = claim.get("claim") if isinstance(claim.get("claim"), dict) else {}
    if claim_body.get("client_id") != client:
        raise ValueError("claim client_id does not match heartbeat client_id")
    run = claim.get("run") if isinstance(claim.get("run"), dict) else {}
    run_id = str(run.get("run_id") or "")
    _safe_run_id(run_id)
    generated_at_dt = _utc_now()
    expires_at_dt = generated_at_dt + timedelta(seconds=ttl)
    heartbeat_id = _heartbeat_id(generated_at_dt.isoformat(), claim_id, client)
    payload: dict[str, object] = {
        "schema": AGENT_HEARTBEAT_SCHEMA,
        "heartbeat_id": heartbeat_id,
        "generated_at": generated_at_dt.isoformat(),
        "experiment": experiment,
        "plan_id": claim.get("plan_id"),
        "claim_id": claim_id,
        "claim_path": _relative_vault_path(vault, claim_path),
        "run_id": run_id,
        "heartbeat": {
            "client_id": client,
            "heartbeat_at": generated_at_dt.isoformat(),
            "expires_at": expires_at_dt.isoformat(),
            "ttl_seconds": ttl,
            "status": "active",
        },
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    heartbeat_path = safe_child(
        vault,
        "agent-runs",
        experiment_slug,
        "heartbeats",
        f"{heartbeat_id}.json",
    )
    heartbeat_path.parent.mkdir(parents=True, exist_ok=True)
    written = write_unique_text(
        heartbeat_path,
        json.dumps(payload, indent=2, sort_keys=True) + "\n",
    )
    return AgentHeartbeatResult(
        experiment=experiment_slug,
        claim_id=claim_id,
        run_id=run_id,
        heartbeat_id=heartbeat_id,
        path=written,
        payload=payload,
    )


def retry_agent_run(
    vault_dir: Path,
    *,
    run_id: str,
    reason: str = "manual",
    variant_id: str | None = None,
) -> AgentRetryResult:
    _safe_run_id(run_id)
    vault = ensure_vault(vault_dir)
    run_path, original = _load_run_record(vault, run_id)
    experiment = _run_experiment(original)
    experiment_slug = str(experiment["slug"])
    spec = _spec_from_run(original)
    selected = _retry_variant(original, spec=spec, variant_id=variant_id)
    parallel = original.get("parallel") if isinstance(original.get("parallel"), dict) else {}
    plan_id = parallel.get("plan_id") if isinstance(parallel.get("plan_id"), str) else None
    generated_at = _now()
    retry_reason = _safe_text_label(reason, field="retry reason", max_length=160)
    parallel_context = dict(parallel)
    parallel_context["retry_of_run_id"] = run_id
    parallel_context["retry_reason"] = retry_reason
    replacement = _write_agent_run(
        vault,
        spec,
        selected=selected,
        bucket=_retry_assignment_bucket(spec, selected),
        subject_key=f"retry\0{run_id}\0{generated_at}",
        prompt_text=None,
        prompt_source_name=None,
        prompt_fingerprint=original.get("prompt") if isinstance(original.get("prompt"), dict) else None,
        parallel_context=parallel_context,
        assignment_strategy="retry",
    )
    retry_id = _retry_id(generated_at, run_id, replacement.run_id)
    payload: dict[str, object] = {
        "schema": AGENT_RETRY_SCHEMA,
        "retry_id": retry_id,
        "generated_at": generated_at,
        "experiment": experiment,
        "plan_id": plan_id,
        "reason": retry_reason,
        "replacement_policy": "supersede-original",
        "original_run_id": run_id,
        "original_run_path": _relative_vault_path(vault, run_path),
        "replacement_run": {
            "run_id": replacement.run_id,
            "lane_id": parallel.get("lane_id"),
            "role": parallel.get("role"),
            "replica": parallel.get("replica", 1),
            "variant_id": replacement.variant_id,
            "path": _relative_vault_path(vault, replacement.path),
            "retry_of_run_id": run_id,
        },
        "variant": selected.as_dict(),
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["subject_key", "prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    root = safe_child(vault, "agent-runs", experiment_slug)
    retry_path = safe_child(root, "retries", f"{retry_id}.json")
    report_path = safe_child(root, "retries", f"{retry_id}.md")
    retry_path.parent.mkdir(parents=True, exist_ok=True)
    written_json = write_unique_text(retry_path, json.dumps(payload, indent=2, sort_keys=True) + "\n")
    written_report = write_unique_text(report_path, _render_retry_report(payload))
    return AgentRetryResult(
        experiment=experiment_slug,
        retry_id=retry_id,
        original_run_id=run_id,
        replacement_run_id=replacement.run_id,
        path=written_json,
        report_path=written_report,
        run=replacement,
        payload=payload,
    )


def recover_agent_harness(
    vault_dir: Path,
    *,
    experiment: str | None = None,
    max_retries: int = 8,
    stale_after_seconds: int = 1800,
    include_failed: bool = True,
    include_stale: bool = True,
    include_expired: bool = True,
    variant_id: str | None = None,
) -> AgentRecoveryResult:
    limit = _non_negative_int(max_retries, field="max_retries")
    stale_after = _positive_int(stale_after_seconds, field="stale_after_seconds")
    if not (include_failed or include_stale or include_expired):
        raise ValueError("at least one recovery source must be enabled")
    vault = ensure_vault(vault_dir)
    roots = _experiment_roots(vault, experiment=experiment)
    generated_at = _now()
    now = _parse_datetime(generated_at) or _utc_now()
    candidates: list[dict[str, object]] = []
    for root in roots:
        candidates.extend(
            _recovery_candidates(
                root,
                now=now,
                stale_after_seconds=stale_after,
                include_failed=include_failed,
                include_stale=include_stale,
                include_expired=include_expired,
            )
        )
    selected = candidates[:limit] if limit else []
    retries: list[AgentRetryResult] = []
    entries: list[dict[str, object]] = []
    errors: list[dict[str, object]] = []
    for candidate in selected:
        run_id = str(candidate.get("run_id") or "")
        reason = str(candidate.get("reason") or "recovery")
        try:
            retry = retry_agent_run(
                vault,
                run_id=run_id,
                reason=reason,
                variant_id=variant_id,
            )
        except (FileExistsError, FileNotFoundError, ValueError) as exc:
            errors.append(_recovery_error(candidate, exc))
            continue
        retries.append(retry)
        entries.append(_recovery_entry(vault, candidate, retry))
    scope = slugify(experiment, fallback="all") if experiment else "all"
    status = _recovery_status(
        candidates=len(candidates),
        selected=len(selected),
        retries=len(retries),
        errors=len(errors),
    )
    payload: dict[str, object] = {
        "schema": AGENT_RECOVERY_SCHEMA,
        "recovery_id": _recovery_id(generated_at, scope, selected, entries, errors),
        "generated_at": generated_at,
        "scope": scope,
        "recovery_status": status,
        "policy": {
            "max_retries": limit,
            "stale_after_seconds": stale_after,
            "include_failed": include_failed,
            "include_stale": include_stale,
            "include_expired": include_expired,
            "variant_id": slugify(variant_id, fallback="") if variant_id else None,
        },
        "summary": {
            "experiments": len(roots),
            "candidate_count": len(candidates),
            "selected_count": len(selected),
            "retry_count": len(retries),
            "error_count": len(errors),
            "remaining_candidates": max(0, len(candidates) - len(selected)),
        },
        "candidates": candidates,
        "entries": entries,
        "errors": errors,
        "recommendations": _recovery_recommendations(status, len(candidates), len(selected), len(retries)),
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    report_root = safe_child(vault, "agent-runs", "_reports")
    report_root.mkdir(parents=True, exist_ok=True)
    recovery_path = report_root / f"{payload['recovery_id']}.json"
    report_path = report_root / f"{payload['recovery_id']}.md"
    written_json = write_unique_text(
        recovery_path,
        json.dumps(payload, indent=2, sort_keys=True) + "\n",
    )
    written_report = write_unique_text(report_path, _render_recovery_report(payload))
    return AgentRecoveryResult(
        recovery_id=str(payload["recovery_id"]),
        recovered=bool(retries),
        path=written_json,
        report_path=written_report,
        retries=tuple(retries),
        payload=payload,
    )


def cycle_agent_harness(
    vault_dir: Path,
    *,
    experiment: str | None = None,
    plan_id: str | None = None,
    suite_id: str | None = None,
    client_prefix: str = "cycle-worker",
    max_concurrency: int = 8,
    batch_size: int | None = None,
    lane_id: str | None = None,
    ttl_seconds: int = DEFAULT_CLAIM_TTL_SECONDS,
    stale_after_seconds: int = 1800,
    claim_strategy: str = DEFAULT_CLAIM_STRATEGY,
    max_retries: int = 8,
    skip_recovery: bool = False,
    skip_orchestration: bool = False,
    dashboard_limit: int | None = 80,
) -> AgentCycleResult:
    if bool(plan_id) and bool(suite_id):
        raise ValueError("provide at most one of plan_id or suite_id")
    vault = ensure_vault(vault_dir)
    scope = _cycle_scope(experiment=experiment, plan_id=plan_id, suite_id=suite_id)
    generated_at = _now()
    strategy = _claim_strategy(claim_strategy)
    artifacts: dict[str, object] = {}
    recovery = None
    orchestration = None
    if not skip_recovery:
        recovery = recover_agent_harness(
            vault,
            experiment=experiment,
            max_retries=max_retries,
            stale_after_seconds=stale_after_seconds,
        )
        artifacts["recovery"] = _cycle_artifact_ref(
            vault,
            "recovery",
            recovery.recovery_id,
            recovery.path,
            recovery.report_path,
            status=str(recovery.payload["recovery_status"]),
            summary=recovery.payload["summary"],
        )
    if not skip_orchestration and (plan_id or suite_id):
        try:
            orchestration = orchestrate_agent_dispatch(
                vault,
                plan_id=plan_id,
                suite_id=suite_id,
                client_prefix=client_prefix,
                max_concurrency=max_concurrency,
                batch_size=batch_size,
                lane_id=lane_id,
                ttl_seconds=ttl_seconds,
                stale_after_seconds=stale_after_seconds,
                claim_strategy=strategy,
            )
        except FileNotFoundError as exc:
            artifacts["orchestration"] = {
                "artifact": "orchestration",
                "status": "no-dispatch",
                "message": _safe_text_label(str(exc), field="cycle orchestration", max_length=220),
            }
        else:
            artifacts["orchestration"] = _cycle_artifact_ref(
                vault,
                "orchestration",
                orchestration.orchestration_id,
                orchestration.path,
                orchestration.report_path,
                status=str(orchestration.payload["orchestration_status"]),
                summary=orchestration.payload["summary"],
            )
    watchdog = watchdog_agent_harness(
        vault,
        experiment=experiment,
        stale_after_seconds=stale_after_seconds,
    )
    artifacts["watchdog"] = _cycle_artifact_ref(
        vault,
        "watchdog",
        watchdog.watchdog_id,
        watchdog.path,
        watchdog.report_path,
        status="attention" if watchdog.needs_attention else "ok",
        summary=watchdog.payload["summary"],
    )
    status = summarize_agent_harness(vault, experiment=experiment)
    artifacts["status"] = _cycle_artifact_ref(
        vault,
        "status",
        status.status_id,
        status.path,
        status.report_path,
        summary=status.payload["summary"],
    )
    timeline = timeline_agent_harness(vault, experiment=experiment, limit=dashboard_limit)
    artifacts["timeline"] = _cycle_artifact_ref(
        vault,
        "timeline",
        timeline.timeline_id,
        timeline.path,
        timeline.report_path,
        summary=timeline.payload["summary"],
    )
    dashboard = write_agent_dashboard(vault, experiment=experiment, limit=dashboard_limit)
    artifacts["dashboard"] = _cycle_artifact_ref(
        vault,
        "dashboard",
        dashboard.dashboard_id,
        dashboard.path,
        dashboard.report_path,
        summary=dashboard.payload["summary"],
    )
    summary = _cycle_summary(
        recovery=recovery,
        orchestration=orchestration,
        watchdog=watchdog,
        status=status,
    )
    cycle_status = _cycle_status(summary)
    cycle_id = _cycle_id(generated_at, scope, summary, artifacts)
    payload: dict[str, object] = {
        "schema": AGENT_CYCLE_SCHEMA,
        "cycle_id": cycle_id,
        "generated_at": generated_at,
        "scope": scope,
        "cycle_status": cycle_status,
        "policy": {
            "client_prefix": _safe_text_label(client_prefix, field="client_prefix", max_length=100),
            "max_concurrency": _positive_int(max_concurrency, field="max_concurrency"),
            "batch_size": _optional_positive_int(batch_size, field="batch_size"),
            "lane_id": slugify(lane_id, fallback="lane") if lane_id else None,
            "ttl_seconds": _bounded_ttl(ttl_seconds),
            "stale_after_seconds": _positive_int(stale_after_seconds, field="stale_after_seconds"),
            "claim_strategy": strategy,
            "max_retries": _non_negative_int(max_retries, field="max_retries"),
            "skip_recovery": skip_recovery,
            "skip_orchestration": skip_orchestration,
            "dashboard_limit": _optional_positive_int(dashboard_limit, field="dashboard_limit"),
        },
        "summary": summary,
        "artifacts": artifacts,
        "recommendations": _cycle_recommendations(cycle_status, summary, bool(plan_id or suite_id)),
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    report_root = safe_child(vault, "agent-runs", "_reports")
    report_root.mkdir(parents=True, exist_ok=True)
    cycle_path = report_root / f"{cycle_id}.json"
    report_path = report_root / f"{cycle_id}.md"
    written_json = write_unique_text(cycle_path, json.dumps(payload, indent=2, sort_keys=True) + "\n")
    written_report = write_unique_text(report_path, _render_cycle_report(payload))
    return AgentCycleResult(
        cycle_id=cycle_id,
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def loop_agent_harness(
    vault_dir: Path,
    *,
    experiment: str | None = None,
    plan_id: str | None = None,
    suite_id: str | None = None,
    client_prefix: str = "loop-worker",
    max_concurrency: int = 8,
    batch_size: int | None = None,
    lane_id: str | None = None,
    ttl_seconds: int = DEFAULT_CLAIM_TTL_SECONDS,
    stale_after_seconds: int = 1800,
    claim_strategy: str = DEFAULT_CLAIM_STRATEGY,
    max_retries: int = 8,
    max_cycles: int = 3,
    stop_after_idle_cycles: int = 1,
    skip_recovery: bool = False,
    skip_orchestration: bool = False,
    dashboard_limit: int | None = 80,
) -> AgentLoopResult:
    if bool(plan_id) and bool(suite_id):
        raise ValueError("provide at most one of plan_id or suite_id")
    cycle_limit = _bounded_loop_cycles(max_cycles)
    idle_limit = _non_negative_int(
        stop_after_idle_cycles,
        field="stop_after_idle_cycles",
    )
    client = _safe_text_label(client_prefix, field="client_prefix", max_length=88)
    vault = ensure_vault(vault_dir)
    generated_at = _now()
    strategy = _claim_strategy(claim_strategy)
    scope = _cycle_scope(experiment=experiment, plan_id=plan_id, suite_id=suite_id)
    cycles: list[dict[str, object]] = []
    idle_streak = 0
    stop_reason = "max-cycles"
    for index in range(1, cycle_limit + 1):
        cycle = cycle_agent_harness(
            vault,
            experiment=experiment,
            plan_id=plan_id,
            suite_id=suite_id,
            client_prefix=f"{client}-{index:03d}",
            max_concurrency=max_concurrency,
            batch_size=batch_size,
            lane_id=lane_id,
            ttl_seconds=ttl_seconds,
            stale_after_seconds=stale_after_seconds,
            claim_strategy=strategy,
            max_retries=max_retries,
            skip_recovery=skip_recovery,
            skip_orchestration=skip_orchestration,
            dashboard_limit=dashboard_limit,
        )
        cycles.append(_loop_cycle_ref(vault, index, cycle))
        if cycle.payload["cycle_status"] == "acted":
            idle_streak = 0
        else:
            idle_streak += 1
        if idle_limit and idle_streak >= idle_limit:
            stop_reason = "idle-threshold"
            break

    summary = _loop_summary(cycles, requested_cycles=cycle_limit, stop_reason=stop_reason)
    loop_status = _loop_status(summary)
    loop_id = _agent_loop_id(generated_at, scope, summary, cycles)
    payload: dict[str, object] = {
        "schema": AGENT_LOOP_SCHEMA,
        "loop_id": loop_id,
        "generated_at": generated_at,
        "scope": scope,
        "loop_status": loop_status,
        "policy": {
            "client_prefix": client,
            "max_concurrency": _positive_int(max_concurrency, field="max_concurrency"),
            "batch_size": _optional_positive_int(batch_size, field="batch_size"),
            "lane_id": slugify(lane_id, fallback="lane") if lane_id else None,
            "ttl_seconds": _bounded_ttl(ttl_seconds),
            "stale_after_seconds": _positive_int(stale_after_seconds, field="stale_after_seconds"),
            "claim_strategy": strategy,
            "max_retries": _non_negative_int(max_retries, field="max_retries"),
            "max_cycles": cycle_limit,
            "stop_after_idle_cycles": idle_limit,
            "skip_recovery": skip_recovery,
            "skip_orchestration": skip_orchestration,
            "dashboard_limit": _optional_positive_int(dashboard_limit, field="dashboard_limit"),
        },
        "summary": summary,
        "cycles": cycles,
        "recommendations": _loop_recommendations(loop_status, summary, bool(plan_id or suite_id)),
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    report_root = safe_child(vault, "agent-runs", "_reports")
    report_root.mkdir(parents=True, exist_ok=True)
    loop_path = report_root / f"{loop_id}.json"
    report_path = report_root / f"{loop_id}.md"
    written_json = write_unique_text(loop_path, json.dumps(payload, indent=2, sort_keys=True) + "\n")
    written_report = write_unique_text(report_path, _render_loop_report(payload))
    return AgentLoopResult(
        loop_id=loop_id,
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def gate_agent_plan(
    vault_dir: Path,
    *,
    plan_id: str,
    min_completed_ratio: float = 1.0,
    max_failures: int = 0,
    metric_threshold: float | None = None,
    required_lanes: tuple[str, ...] = (),
) -> AgentGateResult:
    _safe_plan_id(plan_id)
    completion_floor = _ratio(min_completed_ratio, field="min_completed_ratio")
    failure_ceiling = _non_negative_int(max_failures, field="max_failures")
    threshold = _optional_finite(metric_threshold, field="metric_threshold")
    lane_requirements = tuple(slugify(item, fallback="lane") for item in required_lanes)

    vault = ensure_vault(vault_dir)
    plan_path, plan = _load_plan_record(vault, plan_id)
    experiment = _plan_experiment(plan)
    experiment_slug = str(experiment["slug"])
    root = safe_child(vault, "agent-runs", experiment_slug)
    outcomes = _load_outcome_records(root)
    outcomes_by_run = _latest_outcomes_by_run(outcomes)
    claims = _load_schema_records(root, "claims", AGENT_CLAIM_SCHEMA)
    heartbeats = _load_schema_records(root, "heartbeats", AGENT_HEARTBEAT_SCHEMA)
    now = _utc_now()
    active_claims = _active_claims_by_run(claims, heartbeats=heartbeats, now=now)
    metric = MetricSpec.from_value(experiment.get("primary_metric"))
    runs = _effective_plan_runs(root, plan)
    lane_summaries = _plan_lane_summaries(
        plan,
        outcomes_by_run,
        primary_metric=metric,
        plan_runs=runs,
    )
    recommended = _recommended_plan_run(lane_summaries, primary_metric=metric)
    completed = sum(1 for item in runs if item["run_id"] in outcomes_by_run)
    failed = sum(
        1
        for item in runs
        if item["run_id"] in outcomes_by_run
        and outcomes_by_run[str(item["run_id"])].get("status") == "failed"
    )
    claimed = sum(
        1
        for item in runs
        if item["run_id"] not in outcomes_by_run and item["run_id"] in active_claims
    )
    pending = len(runs) - completed - claimed
    heartbeats_by_claim = _latest_heartbeats_by_claim(heartbeats)
    expired_claims = sum(
        1 for item in claims if _claim_is_expired(item, heartbeats_by_claim=heartbeats_by_claim, now=now)
    )
    completed_ratio = completed / len(runs) if runs else 0.0
    findings = _gate_findings(
        lane_summaries=lane_summaries,
        metric=metric,
        recommended=recommended,
        completed_ratio=completed_ratio,
        min_completed_ratio=completion_floor,
        failed=failed,
        max_failures=failure_ceiling,
        metric_threshold=threshold,
        required_lanes=lane_requirements,
        pending=pending,
        claimed=claimed,
        expired_claims=expired_claims,
    )
    passed = not any(item["severity"] == "fail" for item in findings)
    generated_at = _now()
    gate_id = _gate_id(generated_at, plan_id, findings)
    payload: dict[str, object] = {
        "schema": AGENT_GATE_SCHEMA,
        "gate_id": gate_id,
        "generated_at": generated_at,
        "plan_id": plan_id,
        "experiment": experiment,
        "plan_path": _relative_vault_path(vault, plan_path),
        "gate_status": "pass" if passed else "fail",
        "policy": {
            "min_completed_ratio": completion_floor,
            "max_failures": failure_ceiling,
            "metric_threshold": threshold,
            "required_lanes": list(lane_requirements),
        },
        "summary": {
            "expected_runs": len(runs),
            "completed_runs": completed,
            "completed_ratio": round(completed_ratio, 6),
            "failed_runs": failed,
            "claimed_runs": claimed,
            "pending_runs": pending,
            "expired_claims": expired_claims,
        },
        "primary_metric": metric.as_dict(),
        "recommended_run_id": recommended["run_id"] if recommended else None,
        "recommended_variant_id": recommended["variant_id"] if recommended else None,
        "recommended_metric": recommended["metric"] if recommended else None,
        "lane_summaries": lane_summaries,
        "findings": findings,
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    gate_path = safe_child(root, "gates", f"{gate_id}.json")
    report_path = safe_child(root, "gates", f"{gate_id}.md")
    gate_path.parent.mkdir(parents=True, exist_ok=True)
    written_json = write_unique_text(gate_path, json.dumps(payload, indent=2, sort_keys=True) + "\n")
    written_report = write_unique_text(report_path, _render_gate_report(payload))
    return AgentGateResult(
        experiment=experiment_slug,
        plan_id=plan_id,
        gate_id=gate_id,
        passed=passed,
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def adjudicate_agent_plan(
    vault_dir: Path,
    *,
    plan_id: str,
    min_completed_ratio: float = 1.0,
    min_consensus_ratio: float = 0.5,
) -> AgentAdjudicationResult:
    _safe_plan_id(plan_id)
    completion_floor = _ratio(min_completed_ratio, field="min_completed_ratio")
    consensus_floor = _ratio(min_consensus_ratio, field="min_consensus_ratio")
    vault = ensure_vault(vault_dir)
    plan_path, plan = _load_plan_record(vault, plan_id)
    experiment = _plan_experiment(plan)
    experiment_slug = str(experiment["slug"])
    root = safe_child(vault, "agent-runs", experiment_slug)
    outcomes = _load_outcome_records(root)
    outcomes_by_run = _latest_outcomes_by_run(outcomes)
    metric = MetricSpec.from_value(experiment.get("primary_metric"))
    runs = _effective_plan_runs(root, plan)
    lane_summaries = _plan_lane_summaries(
        plan,
        outcomes_by_run,
        primary_metric=metric,
        plan_runs=runs,
    )
    recommended = _recommended_plan_run(lane_summaries, primary_metric=metric)
    lane_decisions = _adjudication_lane_decisions(lane_summaries)
    completed = sum(1 for item in runs if item["run_id"] in outcomes_by_run)
    completed_ratio = completed / len(runs) if runs else 0.0
    consensus = _adjudication_consensus(lane_decisions, recommended)
    latest_merge = _latest_schema_record(root, "merges", AGENT_MERGE_SCHEMA)
    latest_gate = _latest_schema_record(root, "gates", AGENT_GATE_SCHEMA)
    findings = _adjudication_findings(
        recommended=recommended,
        completed_ratio=completed_ratio,
        min_completed_ratio=completion_floor,
        consensus=consensus,
        min_consensus_ratio=consensus_floor,
        latest_gate=latest_gate,
    )
    accepted = not any(item["severity"] == "fail" for item in findings)
    generated_at = _now()
    adjudication_id = _adjudication_id(generated_at, plan_id, findings)
    payload: dict[str, object] = {
        "schema": AGENT_ADJUDICATION_SCHEMA,
        "adjudication_id": adjudication_id,
        "generated_at": generated_at,
        "plan_id": plan_id,
        "experiment": experiment,
        "plan_path": _relative_vault_path(vault, plan_path),
        "decision_status": "accepted" if accepted else "needs-review",
        "accepted": accepted,
        "policy": {
            "min_completed_ratio": completion_floor,
            "min_consensus_ratio": consensus_floor,
        },
        "summary": {
            "expected_runs": len(runs),
            "completed_runs": completed,
            "completed_ratio": round(completed_ratio, 6),
            "lane_count": len(lane_decisions),
            "decided_lanes": consensus["decided_lanes"],
        },
        "primary_metric": metric.as_dict(),
        "recommended_run_id": recommended["run_id"] if recommended else None,
        "recommended_variant_id": recommended["variant_id"] if recommended else None,
        "recommended_metric": recommended["metric"] if recommended else None,
        "consensus": consensus,
        "lane_decisions": lane_decisions,
        "latest_merge": _adjudication_reference(latest_merge, "merge_id", "merge_status"),
        "latest_gate": _adjudication_reference(latest_gate, "gate_id", "gate_status"),
        "findings": findings,
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    adjudication_path = safe_child(
        root,
        "adjudications",
        f"{adjudication_id}.json",
    )
    report_path = safe_child(root, "adjudications", f"{adjudication_id}.md")
    adjudication_path.parent.mkdir(parents=True, exist_ok=True)
    written_json = write_unique_text(
        adjudication_path,
        json.dumps(payload, indent=2, sort_keys=True) + "\n",
    )
    written_report = write_unique_text(report_path, _render_adjudication_report(payload))
    return AgentAdjudicationResult(
        experiment=experiment_slug,
        plan_id=plan_id,
        adjudication_id=adjudication_id,
        accepted=accepted,
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def quorum_agent_plan(
    vault_dir: Path,
    *,
    plan_id: str,
    min_completed_ratio: float = 1.0,
    min_agreement_ratio: float = 0.5,
) -> AgentQuorumResult:
    _safe_plan_id(plan_id)
    completion_floor = _ratio(min_completed_ratio, field="min_completed_ratio")
    agreement_floor = _ratio(min_agreement_ratio, field="min_agreement_ratio")
    vault = ensure_vault(vault_dir)
    plan_path, plan = _load_plan_record(vault, plan_id)
    experiment = _plan_experiment(plan)
    experiment_slug = str(experiment["slug"])
    root = safe_child(vault, "agent-runs", experiment_slug)
    outcomes_by_run = _latest_outcomes_by_run(_load_outcome_records(root))
    metric = MetricSpec.from_value(experiment.get("primary_metric"))
    runs = _effective_plan_runs(root, plan)
    lane_summaries = _plan_lane_summaries(
        plan,
        outcomes_by_run,
        primary_metric=metric,
        plan_runs=runs,
    )
    recommended = _recommended_plan_run(lane_summaries, primary_metric=metric)
    lane_votes = _quorum_lane_votes(lane_summaries)
    consensus = _quorum_consensus(lane_votes, recommended)
    completed = sum(1 for item in runs if item["run_id"] in outcomes_by_run)
    completed_ratio = completed / len(runs) if runs else 0.0
    findings = _quorum_findings(
        completed_ratio=completed_ratio,
        min_completed_ratio=completion_floor,
        consensus=consensus,
        min_agreement_ratio=agreement_floor,
    )
    passed = not any(item["severity"] == "fail" for item in findings)
    quorum_status = _quorum_status(passed, completed_ratio, completion_floor, consensus)
    generated_at = _now()
    quorum_id = _quorum_id(generated_at, plan_id, consensus, findings)
    payload: dict[str, object] = {
        "schema": AGENT_QUORUM_SCHEMA,
        "quorum_id": quorum_id,
        "generated_at": generated_at,
        "plan_id": plan_id,
        "experiment": experiment,
        "plan_path": _relative_vault_path(vault, plan_path),
        "quorum_status": quorum_status,
        "passed": passed,
        "policy": {
            "min_completed_ratio": completion_floor,
            "min_agreement_ratio": agreement_floor,
            "vote_basis": "best-primary-metric-per-lane",
        },
        "summary": {
            "expected_runs": len(runs),
            "completed_runs": completed,
            "completed_ratio": round(completed_ratio, 6),
            "lane_count": len(lane_votes),
            "decided_lanes": consensus["decided_lanes"],
            "agreement_ratio": consensus["agreement_ratio"],
            "split_brain": consensus["split_brain"],
        },
        "primary_metric": metric.as_dict(),
        "recommended_run_id": recommended["run_id"] if recommended else None,
        "recommended_variant_id": recommended["variant_id"] if recommended else None,
        "recommended_metric": recommended["metric"] if recommended else None,
        "consensus": consensus,
        "lane_votes": lane_votes,
        "findings": findings,
        "recommendations": _quorum_recommendations(quorum_status, consensus),
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    quorum_path = safe_child(root, "quorums", f"{quorum_id}.json")
    report_path = safe_child(root, "quorums", f"{quorum_id}.md")
    quorum_path.parent.mkdir(parents=True, exist_ok=True)
    written_json = write_unique_text(
        quorum_path,
        json.dumps(payload, indent=2, sort_keys=True) + "\n",
    )
    written_report = write_unique_text(report_path, _render_quorum_report(payload))
    return AgentQuorumResult(
        experiment=experiment_slug,
        plan_id=plan_id,
        quorum_id=quorum_id,
        passed=passed,
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


