def write_agent_dashboard(
    vault_dir: Path,
    *,
    experiment: str | None = None,
    limit: int | None = 80,
) -> AgentDashboardResult:
    vault = ensure_vault(vault_dir)
    roots = _experiment_roots(vault, experiment=experiment)
    event_limit = _optional_positive_int(limit, field="dashboard event limit")
    generated_at = _now()
    scope = slugify(experiment, fallback="all") if experiment else "all"
    dashboard_id = _dashboard_id(generated_at, scope)
    experiments = [_experiment_status(vault, root) for root in roots]
    recommendations = _status_recommendations(experiments)
    budget_reports = _status_budget_reports(vault, scope)
    capacity_reports = _status_capacity_reports(vault, scope)
    slo_reports = _status_slo_reports(vault, scope)
    dashboard_reports = _status_dashboard_reports(vault, scope)
    ingest_reports = _status_ingest_reports(vault, scope)
    orchestration_reports = _status_orchestration_reports(vault, scope)
    recovery_reports = _status_recovery_reports(vault, scope)
    cycle_reports = _status_cycle_reports(vault, scope)
    loop_reports = _status_loop_reports(vault, scope)
    events = [
        event
        for root in roots
        for event in _timeline_experiment(vault, root)
    ]
    events.extend(_timeline_report_events(vault, roots=roots, experiment=experiment))
    events.sort(key=lambda item: (str(item.get("timestamp") or ""), str(item.get("event_id") or "")))
    recent_events = events[-event_limit:] if event_limit is not None else events
    payload: dict[str, object] = {
        "schema": AGENT_DASHBOARD_SCHEMA,
        "dashboard_id": dashboard_id,
        "generated_at": generated_at,
        "scope": scope,
        "summary": _agent_scope_summary(
            experiments,
            budget_report_count=len(budget_reports),
            capacity_report_count=len(capacity_reports),
            slo_report_count=len(slo_reports),
            dashboard_report_count=len(dashboard_reports),
            ingest_report_count=len(ingest_reports),
            orchestration_report_count=len(orchestration_reports),
            recovery_report_count=len(recovery_reports),
            cycle_report_count=len(cycle_reports),
            loop_report_count=len(loop_reports),
        ),
        "experiments": experiments,
        "recommendations": recommendations,
        "events": recent_events,
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    report_root = safe_child(vault, "agent-runs", "_reports")
    report_root.mkdir(parents=True, exist_ok=True)
    report_path = report_root / f"{dashboard_id}.json"
    dashboard_path = safe_child(vault, "dashboards", f"{dashboard_id}.html")
    written_report = write_unique_text(
        report_path,
        json.dumps(payload, indent=2, sort_keys=True) + "\n",
    )
    written_dashboard = write_unique_text(dashboard_path, _render_agent_dashboard_html(payload))
    return AgentDashboardResult(
        dashboard_id=dashboard_id,
        path=written_dashboard,
        report_path=written_report,
        payload=payload,
    )


def audit_agent_harness(
    vault_dir: Path,
    *,
    experiment: str | None = None,
) -> AgentAuditResult:
    vault = ensure_vault(vault_dir)
    roots = _experiment_roots(vault, experiment=experiment)
    generated_at = _now()
    audit_id = _audit_id(generated_at, experiment or "all")
    experiment_reports = [_audit_experiment(vault, root) for root in roots]
    findings = [
        finding
        for report in experiment_reports
        for finding in report["findings"]
        if isinstance(finding, dict)
    ]
    summary = {
        "experiments": len(experiment_reports),
        "pass": sum(1 for item in findings if item.get("severity") == "pass"),
        "warn": sum(1 for item in findings if item.get("severity") == "warn"),
        "fail": sum(1 for item in findings if item.get("severity") == "fail"),
        "findings": len(findings),
    }
    if not experiment_reports:
        findings.append(
            _audit_finding(
                "warn",
                "no-experiments",
                "all",
                "No agent experiments were found.",
            )
        )
        summary["warn"] = int(summary["warn"]) + 1
        summary["findings"] = int(summary["findings"]) + 1
    failed = int(summary["fail"]) > 0
    payload: dict[str, object] = {
        "schema": AGENT_AUDIT_SCHEMA,
        "audit_id": audit_id,
        "generated_at": generated_at,
        "scope": slugify(experiment, fallback="all") if experiment else "all",
        "summary": summary,
        "experiments": experiment_reports,
        "findings": findings,
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    report_root = safe_child(vault, "agent-runs", "_reports")
    report_root.mkdir(parents=True, exist_ok=True)
    audit_path = report_root / f"{audit_id}.json"
    report_path = report_root / f"{audit_id}.md"
    written_json = write_unique_text(audit_path, json.dumps(payload, indent=2, sort_keys=True) + "\n")
    written_report = write_unique_text(report_path, _render_audit_report(payload))
    return AgentAuditResult(
        audit_id=audit_id,
        failed=failed,
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def write_agent_manifest(
    vault_dir: Path,
    *,
    experiment: str | None = None,
    include_reports: bool = False,
    max_artifacts: int = MAX_AGENT_MANIFEST_ARTIFACTS,
) -> AgentManifestResult:
    artifact_limit = _positive_int(max_artifacts, field="max_artifacts")
    vault = ensure_vault(vault_dir)
    scope_slug = slugify(experiment, fallback="all") if experiment else "all"
    files = _agent_manifest_files(vault, experiment=experiment, include_reports=include_reports)
    if len(files) > artifact_limit:
        raise ValueError(f"agent manifest exceeds {artifact_limit} artifact limit")
    artifacts = [_agent_manifest_artifact(vault, path) for path in files]
    artifacts.sort(key=lambda item: str(item.get("path") or ""))
    schema_counts: dict[str, int] = {}
    type_counts: dict[str, int] = {}
    total_bytes = 0
    for artifact in artifacts:
        schema = str(artifact.get("schema") or "unknown")
        artifact_type = str(artifact.get("artifact_type") or "unknown")
        schema_counts[schema] = schema_counts.get(schema, 0) + 1
        type_counts[artifact_type] = type_counts.get(artifact_type, 0) + 1
        total_bytes += int(artifact.get("bytes") or 0)
    scope = {
        "experiment": scope_slug,
        "include_reports": bool(include_reports),
    }
    content_sha256 = _hash_json(
        {
            "schema": AGENT_MANIFEST_SCHEMA,
            "scope": scope,
            "artifacts": artifacts,
        }
    )
    generated_at = _now()
    manifest_id = _agent_manifest_id(generated_at, scope_slug, content_sha256)
    payload: dict[str, object] = {
        "schema": AGENT_MANIFEST_SCHEMA,
        "manifest_id": manifest_id,
        "generated_at": generated_at,
        "scope": scope,
        "content_sha256": content_sha256,
        "summary": {
            "artifact_count": len(artifacts),
            "total_bytes": total_bytes,
            "schema_counts": schema_counts,
            "artifact_type_counts": type_counts,
        },
        "artifacts": artifacts,
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    report_root = safe_child(vault, "agent-runs", "_reports")
    report_root.mkdir(parents=True, exist_ok=True)
    manifest_path = report_root / f"{manifest_id}.json"
    report_path = report_root / f"{manifest_id}.md"
    written_json = write_unique_text(
        manifest_path,
        json.dumps(payload, indent=2, sort_keys=True) + "\n",
    )
    written_report = write_unique_text(report_path, _render_manifest_report(payload))
    return AgentManifestResult(
        manifest_id=manifest_id,
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def verify_agent_manifest(
    vault_dir: Path,
    *,
    manifest_id: str | None = None,
    fail_on_extra: bool = False,
) -> AgentManifestVerificationResult:
    vault = ensure_vault(vault_dir)
    manifest_path, manifest = _load_agent_manifest(vault, manifest_id=manifest_id)
    safe_manifest_id = str(manifest.get("manifest_id") or manifest_path.stem)
    scope = manifest.get("scope") if isinstance(manifest.get("scope"), dict) else {}
    experiment = str(scope.get("experiment") or "all")
    include_reports = bool(scope.get("include_reports"))
    artifacts = manifest.get("artifacts") if isinstance(manifest.get("artifacts"), list) else []
    expected_by_path = {
        str(item.get("path")): item
        for item in artifacts
        if isinstance(item, dict) and isinstance(item.get("path"), str)
    }
    findings: list[dict[str, object]] = []
    checked = 0
    missing = 0
    changed = 0
    for path_value, artifact in sorted(expected_by_path.items()):
        checked += 1
        try:
            target = _agent_manifest_target(vault, path_value)
        except ValueError as exc:
            changed += 1
            findings.append(
                _manifest_finding(
                    "fail",
                    "artifact-path",
                    path_value,
                    str(exc),
                )
            )
            continue
        if target.is_symlink():
            changed += 1
            findings.append(
                _manifest_finding(
                    "fail",
                    "artifact-symlink",
                    path_value,
                    "Manifest artifact path is a symlink.",
                )
            )
            continue
        if not target.exists():
            missing += 1
            findings.append(
                _manifest_finding(
                    "fail",
                    "artifact-missing",
                    path_value,
                    "Manifest artifact is missing.",
                )
            )
            continue
        if not target.is_file():
            changed += 1
            findings.append(
                _manifest_finding(
                    "fail",
                    "artifact-not-file",
                    path_value,
                    "Manifest artifact path is not a regular file.",
                )
            )
            continue
        actual_size = target.stat().st_size
        actual_hash = _sha256_file(target)
        if int(artifact.get("bytes") or -1) != actual_size:
            changed += 1
            findings.append(
                _manifest_finding(
                    "fail",
                    "artifact-size",
                    path_value,
                    "Manifest artifact byte count changed.",
                )
            )
        if str(artifact.get("sha256") or "") != actual_hash:
            changed += 1
            findings.append(
                _manifest_finding(
                    "fail",
                    "artifact-sha256",
                    path_value,
                    "Manifest artifact SHA-256 changed.",
                )
            )
    current_experiment = None if experiment == "all" else experiment
    current_paths = {
        _relative_vault_path(vault, path)
        for path in _agent_manifest_files(
            vault,
            experiment=current_experiment,
            include_reports=include_reports,
        )
    }
    extra_paths = sorted(path for path in current_paths if path not in expected_by_path)
    extra_severity = "fail" if fail_on_extra else "warn"
    for path in extra_paths:
        findings.append(
            _manifest_finding(
                extra_severity,
                "artifact-extra",
                path,
                "Artifact was created after the manifest snapshot.",
            )
        )
    fail_count = sum(1 for item in findings if item.get("severity") == "fail")
    warn_count = sum(1 for item in findings if item.get("severity") == "warn")
    verified = fail_count == 0
    if not findings:
        findings.append(
            _manifest_finding(
                "pass",
                "manifest-verified",
                _relative_vault_path(vault, manifest_path),
                "All manifest artifacts match the recorded hashes.",
            )
        )
    generated_at = _now()
    verification_id = _agent_manifest_verification_id(generated_at, safe_manifest_id, findings)
    payload: dict[str, object] = {
        "schema": AGENT_MANIFEST_VERIFICATION_SCHEMA,
        "verification_id": verification_id,
        "manifest_id": safe_manifest_id,
        "generated_at": generated_at,
        "manifest_path": _relative_vault_path(vault, manifest_path),
        "verification_status": "verified" if verified else "failed",
        "verified": verified,
        "policy": {
            "fail_on_extra": bool(fail_on_extra),
        },
        "scope": scope,
        "summary": {
            "checked_artifacts": checked,
            "missing_artifacts": missing,
            "changed_artifacts": changed,
            "extra_artifacts": len(extra_paths),
            "fail": fail_count,
            "warn": warn_count,
            "pass": sum(1 for item in findings if item.get("severity") == "pass"),
            "findings": len(findings),
        },
        "findings": findings,
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    report_root = safe_child(vault, "agent-runs", "_reports")
    report_root.mkdir(parents=True, exist_ok=True)
    verification_path = report_root / f"{verification_id}.json"
    report_path = report_root / f"{verification_id}.md"
    written_json = write_unique_text(
        verification_path,
        json.dumps(payload, indent=2, sort_keys=True) + "\n",
    )
    written_report = write_unique_text(report_path, _render_manifest_verification_report(payload))
    return AgentManifestVerificationResult(
        verification_id=verification_id,
        manifest_id=safe_manifest_id,
        verified=verified,
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def preflight_agent_harness(
    vault_dir: Path,
    *,
    experiment: str | None = None,
    plan_id: str | None = None,
    suite_id: str | None = None,
    min_pending_runs: int = 1,
    max_active_claims: int | None = None,
    stale_after_seconds: int = 1800,
    require_cross_model: bool = False,
    require_lane_coverage: bool = False,
    require_variant_coverage: bool = False,
    max_pending_skew: int | None = None,
    block_failed_outcomes: bool = False,
) -> AgentPreflightResult:
    if bool(plan_id) and bool(suite_id):
        raise ValueError("provide at most one of plan_id or suite_id")
    min_pending = _non_negative_int(min_pending_runs, field="min_pending_runs")
    max_active = (
        _non_negative_int(max_active_claims, field="max_active_claims")
        if max_active_claims is not None
        else None
    )
    stale_after = _positive_int(stale_after_seconds, field="stale_after_seconds")
    skew_limit = (
        _non_negative_int(max_pending_skew, field="max_pending_skew")
        if max_pending_skew is not None
        else None
    )
    vault = ensure_vault(vault_dir)
    generated_at = _now()
    now = _parse_datetime(generated_at) or _utc_now()
    scope, scoped_plans = _preflight_scope(
        vault,
        experiment=experiment,
        plan_id=plan_id,
        suite_id=suite_id,
    )
    policy = {
        "min_pending_runs": min_pending,
        "max_active_claims": max_active,
        "stale_after_seconds": stale_after,
        "require_cross_model": bool(require_cross_model),
        "require_lane_coverage": bool(require_lane_coverage),
        "require_variant_coverage": bool(require_variant_coverage),
        "max_pending_skew": skew_limit,
        "block_failed_outcomes": bool(block_failed_outcomes),
    }
    experiment_reports = [
        _preflight_experiment(
            vault,
            root,
            plans,
            now=now,
            policy=policy,
        )
        for root, plans in scoped_plans
    ]
    findings = [
        finding
        for report in experiment_reports
        for finding in report["findings"]
        if isinstance(finding, dict)
    ]
    if not experiment_reports:
        findings.append(
            _preflight_finding(
                "fail",
                "no-experiments",
                "all",
                "No agent experiments were found for this preflight scope.",
            )
        )
    summary = _preflight_summary(experiment_reports, findings)
    ready = int(summary["fail"]) == 0
    preflight_status = "ready" if ready and int(summary["warn"]) == 0 else "ready-with-warnings" if ready else "blocked"
    preflight_id = _preflight_id(generated_at, scope, policy, summary)
    coverage = _preflight_scope_coverage(experiment_reports)
    payload: dict[str, object] = {
        "schema": AGENT_PREFLIGHT_SCHEMA,
        "preflight_id": preflight_id,
        "generated_at": generated_at,
        "scope": scope,
        "preflight_status": preflight_status,
        "ready": ready,
        "policy": policy,
        "summary": summary,
        "coverage": coverage,
        "experiments": experiment_reports,
        "findings": findings,
        "recommendations": _preflight_recommendations(findings, summary),
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    report_root = safe_child(vault, "agent-runs", "_reports")
    report_root.mkdir(parents=True, exist_ok=True)
    preflight_path = report_root / f"{preflight_id}.json"
    report_path = report_root / f"{preflight_id}.md"
    written_json = write_unique_text(preflight_path, json.dumps(payload, indent=2, sort_keys=True) + "\n")
    written_report = write_unique_text(report_path, _render_preflight_report(payload))
    return AgentPreflightResult(
        preflight_id=preflight_id,
        ready=ready,
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def timeline_agent_harness(
    vault_dir: Path,
    *,
    experiment: str | None = None,
    limit: int | None = None,
) -> AgentTimelineResult:
    vault = ensure_vault(vault_dir)
    roots = _experiment_roots(vault, experiment=experiment)
    event_limit = _optional_positive_int(limit, field="timeline limit")
    generated_at = _now()
    timeline_id = _timeline_id(generated_at, experiment or "all")
    all_events = [
        event
        for root in roots
        for event in _timeline_experiment(vault, root)
    ]
    all_events.extend(_timeline_report_events(vault, roots=roots, experiment=experiment))
    all_events.sort(key=lambda item: (str(item.get("timestamp") or ""), str(item.get("event_id") or "")))
    events = all_events[-event_limit:] if event_limit is not None else all_events
    event_types: dict[str, int] = {}
    for event in events:
        event_type = str(event.get("event_type") or "unknown")
        event_types[event_type] = event_types.get(event_type, 0) + 1
    payload: dict[str, object] = {
        "schema": AGENT_TIMELINE_SCHEMA,
        "timeline_id": timeline_id,
        "generated_at": generated_at,
        "scope": slugify(experiment, fallback="all") if experiment else "all",
        "summary": {
            "experiments": len(roots),
            "events": len(events),
            "total_events": len(all_events),
            "limit": event_limit,
            "event_types": event_types,
        },
        "events": events,
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    report_root = safe_child(vault, "agent-runs", "_reports")
    report_root.mkdir(parents=True, exist_ok=True)
    timeline_path = report_root / f"{timeline_id}.json"
    report_path = report_root / f"{timeline_id}.md"
    written_json = write_unique_text(timeline_path, json.dumps(payload, indent=2, sort_keys=True) + "\n")
    written_report = write_unique_text(report_path, _render_timeline_report(payload))
    return AgentTimelineResult(
        timeline_id=timeline_id,
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def watchdog_agent_harness(
    vault_dir: Path,
    *,
    experiment: str | None = None,
    stale_after_seconds: int = 1800,
) -> AgentWatchdogResult:
    stale_after = _positive_int(stale_after_seconds, field="stale_after_seconds")
    vault = ensure_vault(vault_dir)
    roots = _experiment_roots(vault, experiment=experiment)
    generated_at = _now()
    now = _parse_datetime(generated_at) or _utc_now()
    watchdog_id = _watchdog_id(generated_at, experiment or "all")
    experiment_reports = [
        _watchdog_experiment(vault, root, now=now, stale_after_seconds=stale_after)
        for root in roots
    ]
    findings = [
        finding
        for report in experiment_reports
        for finding in report["findings"]
        if isinstance(finding, dict)
    ]
    if not experiment_reports:
        findings.append(
            _watchdog_finding(
                "warn",
                "no-experiments",
                "all",
                "No agent experiments were found.",
            )
        )
    needs_attention = any(item.get("severity") in {"warn", "fail"} for item in findings)
    payload: dict[str, object] = {
        "schema": AGENT_WATCHDOG_SCHEMA,
        "watchdog_id": watchdog_id,
        "generated_at": generated_at,
        "scope": slugify(experiment, fallback="all") if experiment else "all",
        "policy": {"stale_after_seconds": stale_after},
        "summary": {
            "experiments": len(experiment_reports),
            "plans": sum(int(item["counts"]["plans"]) for item in experiment_reports),
            "pending_runs": sum(int(item["counts"]["pending_runs"]) for item in experiment_reports),
            "active_claims": sum(int(item["counts"]["active_claims"]) for item in experiment_reports),
            "stale_claims": sum(int(item["counts"]["stale_claims"]) for item in experiment_reports),
            "expired_claims": sum(int(item["counts"]["expired_claims"]) for item in experiment_reports),
            "failed_outcomes": sum(int(item["counts"]["failed_outcomes"]) for item in experiment_reports),
            "findings": len(findings),
            "needs_attention": needs_attention,
        },
        "experiments": experiment_reports,
        "findings": findings,
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    report_root = safe_child(vault, "agent-runs", "_reports")
    report_root.mkdir(parents=True, exist_ok=True)
    watchdog_path = report_root / f"{watchdog_id}.json"
    report_path = report_root / f"{watchdog_id}.md"
    written_json = write_unique_text(
        watchdog_path,
        json.dumps(payload, indent=2, sort_keys=True) + "\n",
    )
    written_report = write_unique_text(report_path, _render_watchdog_report(payload))
    return AgentWatchdogResult(
        watchdog_id=watchdog_id,
        needs_attention=needs_attention,
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def plan_agent_capacity(
    vault_dir: Path,
    *,
    experiment: str | None = None,
    plan_id: str | None = None,
    suite_id: str | None = None,
    max_concurrency: int = 8,
    batch_size: int | None = None,
    target_utilization: float = 0.85,
    min_batch_size: int = 1,
    stale_after_seconds: int = 1800,
    latency_window: int = 20,
) -> AgentCapacityResult:
    concurrency_limit = _positive_int(max_concurrency, field="max_concurrency")
    requested_batch = _optional_positive_int(batch_size, field="batch_size")
    min_batch = _positive_int(min_batch_size, field="min_batch_size")
    if min_batch > concurrency_limit:
        raise ValueError("min_batch_size must be less than or equal to max_concurrency")
    utilization = _ratio(target_utilization, field="target_utilization")
    if utilization <= 0:
        raise ValueError("target_utilization must be greater than 0")
    stale_after = _positive_int(stale_after_seconds, field="stale_after_seconds")
    window = _positive_int(latency_window, field="latency_window")
    vault = ensure_vault(vault_dir)
    scope, scoped = _preflight_scope(vault, experiment=experiment, plan_id=plan_id, suite_id=suite_id)
    generated_at = _now()
    now = _parse_datetime(generated_at) or _utc_now()
    preflight_policy = {
        "min_pending_runs": 0,
        "max_active_claims": None,
        "stale_after_seconds": stale_after,
        "require_cross_model": False,
        "require_lane_coverage": False,
        "require_variant_coverage": False,
        "max_pending_skew": None,
        "block_failed_outcomes": False,
    }
    policy = {
        "max_concurrency": concurrency_limit,
        "batch_size": requested_batch,
        "target_utilization": utilization,
        "min_batch_size": min_batch,
        "stale_after_seconds": stale_after,
        "latency_window": window,
    }
    experiment_reports = [
        _capacity_experiment(
            vault,
            root,
            _preflight_experiment(vault, root, plans, now=now, policy=preflight_policy),
            max_concurrency=concurrency_limit,
            batch_size=requested_batch,
            target_utilization=utilization,
            min_batch_size=min_batch,
            latency_window=window,
        )
        for root, plans in scoped
    ]
    summary = _capacity_scope_summary(experiment_reports)
    capacity_status = _capacity_scope_status(summary)
    recommendations = _capacity_scope_recommendations(capacity_status, summary, experiment_reports)
    capacity_id = _capacity_id(generated_at, scope, policy, summary)
    payload: dict[str, object] = {
        "schema": AGENT_CAPACITY_SCHEMA,
        "capacity_id": capacity_id,
        "generated_at": generated_at,
        "scope": scope,
        "capacity_status": capacity_status,
        "policy": policy,
        "summary": summary,
        "experiments": experiment_reports,
        "recommendations": recommendations,
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    report_root = safe_child(vault, "agent-runs", "_reports")
    report_root.mkdir(parents=True, exist_ok=True)
    capacity_path = report_root / f"{capacity_id}.json"
    report_path = report_root / f"{capacity_id}.md"
    written_json = write_unique_text(
        capacity_path,
        json.dumps(payload, indent=2, sort_keys=True) + "\n",
    )
    written_report = write_unique_text(report_path, _render_capacity_report(payload))
    return AgentCapacityResult(
        capacity_id=capacity_id,
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def evaluate_agent_slo(
    vault_dir: Path,
    *,
    experiment: str | None = None,
    plan_id: str | None = None,
    suite_id: str | None = None,
    min_completion_rate: float = 0.0,
    max_failure_rate: float = 0.1,
    max_stale_claims: int = 0,
    max_expired_claims: int = 0,
    max_active_claims: int | None = None,
    max_quarantined_pending_runs: int | None = None,
    max_mean_latency_ms: float | None = None,
    require_no_active_holds: bool = True,
    require_no_active_quarantines: bool = False,
    stale_after_seconds: int = 1800,
) -> AgentSloResult:
    completion_floor = _ratio(min_completion_rate, field="min_completion_rate")
    failure_ceiling = _ratio(max_failure_rate, field="max_failure_rate")
    stale_ceiling = _non_negative_int(max_stale_claims, field="max_stale_claims")
    expired_ceiling = _non_negative_int(max_expired_claims, field="max_expired_claims")
    active_ceiling = _optional_non_negative_int(max_active_claims, field="max_active_claims")
    quarantined_ceiling = _optional_non_negative_int(
        max_quarantined_pending_runs,
        field="max_quarantined_pending_runs",
    )
    latency_ceiling = _optional_non_negative_number(max_mean_latency_ms, field="max_mean_latency_ms")
    stale_after = _positive_int(stale_after_seconds, field="stale_after_seconds")
    vault = ensure_vault(vault_dir)
    scope, scoped = _preflight_scope(vault, experiment=experiment, plan_id=plan_id, suite_id=suite_id)
    generated_at = _now()
    now = _parse_datetime(generated_at) or _utc_now()
    preflight_policy = {
        "min_pending_runs": 0,
        "max_active_claims": None,
        "stale_after_seconds": stale_after,
        "require_cross_model": False,
        "require_lane_coverage": False,
        "require_variant_coverage": False,
        "max_pending_skew": None,
        "block_failed_outcomes": False,
    }
    policy = {
        "min_completion_rate": completion_floor,
        "max_failure_rate": failure_ceiling,
        "max_stale_claims": stale_ceiling,
        "max_expired_claims": expired_ceiling,
        "max_active_claims": active_ceiling,
        "max_quarantined_pending_runs": quarantined_ceiling,
        "max_mean_latency_ms": latency_ceiling,
        "require_no_active_holds": bool(require_no_active_holds),
        "require_no_active_quarantines": bool(require_no_active_quarantines),
        "stale_after_seconds": stale_after,
    }
    experiment_reports = [
        _slo_experiment(
            vault,
            root,
            plans,
            _preflight_experiment(vault, root, plans, now=now, policy=preflight_policy),
            policy=policy,
        )
        for root, plans in scoped
    ]
    findings = [
        finding
        for report in experiment_reports
        for finding in report.get("findings", [])
        if isinstance(finding, dict)
    ]
    if not experiment_reports:
        findings.append(
            _slo_finding(
                "fail",
                "no-experiments",
                "all",
                "No agent experiments were found for this SLO scope.",
            )
        )
    summary = _slo_scope_summary(experiment_reports, findings)
    slo_status = _slo_status(summary)
    recommendations = _slo_recommendations(slo_status, summary, findings)
    slo_id = _slo_id(generated_at, scope, policy, summary)
    payload: dict[str, object] = {
        "schema": AGENT_SLO_SCHEMA,
        "slo_id": slo_id,
        "generated_at": generated_at,
        "scope": scope,
        "slo_status": slo_status,
        "passed": slo_status in {"pass", "pass-with-warnings"},
        "policy": policy,
        "summary": summary,
        "experiments": experiment_reports,
        "findings": findings,
        "recommendations": recommendations,
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    report_root = safe_child(vault, "agent-runs", "_reports")
    report_root.mkdir(parents=True, exist_ok=True)
    slo_path = report_root / f"{slo_id}.json"
    report_path = report_root / f"{slo_id}.md"
    written_json = write_unique_text(
        slo_path,
        json.dumps(payload, indent=2, sort_keys=True) + "\n",
    )
    written_report = write_unique_text(report_path, _render_slo_report(payload))
    return AgentSloResult(
        slo_id=slo_id,
        passed=bool(payload["passed"]),
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def evaluate_agent_mix(
    vault_dir: Path,
    *,
    experiment: str,
    min_provider_count: int = 2,
    min_variant_count: int = 2,
    max_provider_weight_share: float = 0.8,
    max_scheduled_provider_share: float = 0.85,
    max_completed_provider_share: float = 0.9,
    require_local_provider: bool = False,
) -> AgentMixResult:
    provider_floor = _positive_int(min_provider_count, field="min_provider_count")
    variant_floor = _positive_int(min_variant_count, field="min_variant_count")
    weight_share_ceiling = _ratio(max_provider_weight_share, field="max_provider_weight_share")
    scheduled_share_ceiling = _ratio(max_scheduled_provider_share, field="max_scheduled_provider_share")
    completed_share_ceiling = _ratio(max_completed_provider_share, field="max_completed_provider_share")
    vault = ensure_vault(vault_dir)
    experiment_slug = slugify(experiment, fallback="agent-experiment")
    root = safe_child(vault, "agent-runs", experiment_slug)
    if not root.exists():
        raise FileNotFoundError(f"Agent experiment does not exist: {experiment_slug}")
    runs = _load_run_records(root)
    if not runs:
        raise FileNotFoundError(f"Agent experiment has no run records: {experiment_slug}")
    spec = _spec_from_run(runs[-1])
    outcomes = _load_outcome_records(root)
    provider_mix = _provider_mix_summary(spec, runs, outcomes)
    lane_mix = _lane_provider_mix(runs, outcomes)
    policy = {
        "min_provider_count": provider_floor,
        "min_variant_count": variant_floor,
        "max_provider_weight_share": weight_share_ceiling,
        "max_scheduled_provider_share": scheduled_share_ceiling,
        "max_completed_provider_share": completed_share_ceiling,
        "require_local_provider": bool(require_local_provider),
    }
    findings = _mix_findings(
        experiment_slug,
        provider_mix,
        policy=policy,
    )
    passed = not any(item.get("severity") == "fail" for item in findings)
    mix_status = "pass" if passed and not any(item.get("severity") == "warn" for item in findings) else "warn" if passed else "fail"
    summary = _mix_summary(provider_mix, lane_mix, findings)
    recommendations = _mix_recommendations(
        provider_mix,
        lane_mix,
        findings,
        policy=policy,
    )
    generated_at = _now()
    mix_id = _mix_id(generated_at, experiment_slug, policy, summary)
    payload: dict[str, object] = {
        "schema": AGENT_MIX_SCHEMA,
        "mix_id": mix_id,
        "generated_at": generated_at,
        "experiment": spec.as_dict(),
        "mix_status": mix_status,
        "passed": passed,
        "policy": policy,
        "summary": summary,
        "providers": provider_mix,
        "lanes": lane_mix,
        "findings": findings,
        "recommendations": recommendations,
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["subject_key", "prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    mix_dir = safe_child(root, "mix")
    mix_dir.mkdir(parents=True, exist_ok=True)
    mix_path = mix_dir / f"{mix_id}.json"
    report_path = mix_dir / f"{mix_id}.md"
    written_json = write_unique_text(mix_path, json.dumps(payload, indent=2, sort_keys=True) + "\n")
    written_report = write_unique_text(report_path, _render_mix_report(payload))
    return AgentMixResult(
        mix_id=mix_id,
        passed=passed,
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def write_agent_snapshot(
    vault_dir: Path,
    *,
    experiment: str,
    baseline_snapshot_id: str | None = None,
) -> AgentSnapshotResult:
    vault = ensure_vault(vault_dir)
    experiment_slug = slugify(experiment, fallback="agent-experiment")
    root = safe_child(vault, "agent-runs", experiment_slug)
    if not root.exists():
        raise FileNotFoundError(f"Agent experiment does not exist: {experiment_slug}")
    baseline_record: dict[str, object] | None = None
    if baseline_snapshot_id:
        baseline_record = _load_agent_snapshot(root, baseline_snapshot_id)
    else:
        baseline_record = _latest_agent_snapshot(root)
    state = _experiment_snapshot_state(vault, root)
    section_hashes = _snapshot_section_hashes(state)
    content_sha256 = _hash_json(
        {
            "schema": AGENT_SNAPSHOT_SCHEMA,
            "experiment": experiment_slug,
            "section_hashes": section_hashes,
        }
    )
    baseline_state = (
        baseline_record.get("state")
        if isinstance(baseline_record, Mapping) and isinstance(baseline_record.get("state"), Mapping)
        else None
    )
    baseline_hashes = (
        baseline_record.get("section_hashes")
        if isinstance(baseline_record, Mapping) and isinstance(baseline_record.get("section_hashes"), Mapping)
        else _snapshot_section_hashes(baseline_state) if isinstance(baseline_state, Mapping) else None
    )
    changes = _snapshot_changes(section_hashes, baseline_hashes) if baseline_hashes is not None else []
    changed = bool(changes)
    generated_at = _now()
    snapshot_id = _snapshot_id(generated_at, experiment_slug, content_sha256)
    summary = _snapshot_summary(state, changes, baseline_record)
    payload: dict[str, object] = {
        "schema": AGENT_SNAPSHOT_SCHEMA,
        "snapshot_id": snapshot_id,
        "generated_at": generated_at,
        "experiment": {
            "slug": experiment_slug,
            "path": _relative_vault_path(vault, root),
        },
        "snapshot_status": "baseline" if baseline_record is None else "changed" if changed else "unchanged",
        "changed": changed,
        "baseline_snapshot_id": (
            baseline_record.get("snapshot_id")
            if isinstance(baseline_record, Mapping)
            else None
        ),
        "baseline_content_sha256": (
            baseline_record.get("content_sha256")
            if isinstance(baseline_record, Mapping)
            else None
        ),
        "content_sha256": content_sha256,
        "section_hashes": section_hashes,
        "summary": summary,
        "changes": changes,
        "state": state,
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": [
                "subject_key",
                "prompt_text",
                "raw_transcript",
                "raw_output",
                "error_message",
                "lane_objective",
                "guardrail_text",
            ],
        },
    }
    snapshot_dir = safe_child(root, "snapshots")
    snapshot_dir.mkdir(parents=True, exist_ok=True)
    snapshot_path = snapshot_dir / f"{snapshot_id}.json"
    report_path = snapshot_dir / f"{snapshot_id}.md"
    written_json = write_unique_text(
        snapshot_path,
        json.dumps(payload, indent=2, sort_keys=True) + "\n",
    )
    written_report = write_unique_text(report_path, _render_snapshot_report(payload))
    return AgentSnapshotResult(
        snapshot_id=snapshot_id,
        changed=changed,
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def budget_agent_harness(
    vault_dir: Path,
    *,
    experiment: str | None = None,
    max_cost_usd: float | None = None,
    max_total_tokens: int | None = None,
    max_mean_latency_ms: float | None = None,
    max_run_cost_usd: float | None = None,
    max_run_tokens: int | None = None,
    max_run_latency_ms: float | None = None,
) -> AgentBudgetResult:
    policy = _budget_policy(
        max_cost_usd=max_cost_usd,
        max_total_tokens=max_total_tokens,
        max_mean_latency_ms=max_mean_latency_ms,
        max_run_cost_usd=max_run_cost_usd,
        max_run_tokens=max_run_tokens,
        max_run_latency_ms=max_run_latency_ms,
    )
    vault = ensure_vault(vault_dir)
    roots = _experiment_roots(vault, experiment=experiment)
    generated_at = _now()
    budget_id = _budget_id(generated_at, experiment or "all", policy)
    experiment_reports = [
        _budget_experiment(root, policy=policy)
        for root in roots
    ]
    summary = _budget_scope_summary(experiment_reports)
    findings = _budget_scope_findings(
        scope=slugify(experiment, fallback="all") if experiment else "all",
        summary=summary,
        policy=policy,
    )
    for report in experiment_reports:
        report_findings = report.get("findings")
        if isinstance(report_findings, list):
            findings.extend(item for item in report_findings if isinstance(item, dict))
    if not experiment_reports:
        findings.append(
            _budget_finding(
                "warn",
                "no-experiments",
                "all",
                "No agent experiments were found.",
            )
        )
    fail_count = sum(1 for item in findings if item.get("severity") == "fail")
    warn_count = sum(1 for item in findings if item.get("severity") == "warn")
    over_budget = fail_count > 0
    summary["findings"] = len(findings)
    summary["fail"] = fail_count
    summary["warn"] = warn_count
    summary["over_budget"] = over_budget
    payload: dict[str, object] = {
        "schema": AGENT_BUDGET_SCHEMA,
        "budget_id": budget_id,
        "generated_at": generated_at,
        "scope": slugify(experiment, fallback="all") if experiment else "all",
        "budget_status": "over-budget" if over_budget else "within-budget",
        "over_budget": over_budget,
        "policy": policy,
        "summary": summary,
        "experiments": experiment_reports,
        "findings": findings,
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    report_root = safe_child(vault, "agent-runs", "_reports")
    report_root.mkdir(parents=True, exist_ok=True)
    budget_path = report_root / f"{budget_id}.json"
    report_path = report_root / f"{budget_id}.md"
    written_json = write_unique_text(
        budget_path,
        json.dumps(payload, indent=2, sort_keys=True) + "\n",
    )
    written_report = write_unique_text(report_path, _render_budget_report(payload))
    return AgentBudgetResult(
        budget_id=budget_id,
        over_budget=over_budget,
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def detect_agent_drift(
    vault_dir: Path,
    *,
    experiment: str,
    metric_name: str | None = None,
    baseline_window: int = 5,
    recent_window: int = 5,
    min_samples: int = 2,
    max_metric_drop: float = 0.05,
    max_cost_increase_ratio: float | None = None,
    max_latency_increase_ratio: float | None = None,
) -> AgentDriftResult:
    baseline_count = _positive_int(baseline_window, field="baseline_window")
    recent_count = _positive_int(recent_window, field="recent_window")
    sample_floor = _positive_int(min_samples, field="min_samples")
    metric_drop = _non_negative_number(max_metric_drop, field="max_metric_drop")
    cost_ratio = (
        _non_negative_number(max_cost_increase_ratio, field="max_cost_increase_ratio")
        if max_cost_increase_ratio is not None
        else None
    )
    latency_ratio = (
        _non_negative_number(max_latency_increase_ratio, field="max_latency_increase_ratio")
        if max_latency_increase_ratio is not None
        else None
    )
    vault = ensure_vault(vault_dir)
    experiment_slug = slugify(experiment, fallback="agent-experiment")
    root = safe_child(vault, "agent-runs", experiment_slug)
    if not root.exists():
        raise FileNotFoundError(f"Agent experiment does not exist: {experiment_slug}")
    runs = _load_run_records(root)
    if not runs:
        raise FileNotFoundError(f"Agent experiment has no run records: {experiment_slug}")
    spec = _spec_from_run(runs[-1])
    metric = _safe_label(metric_name or spec.primary_metric.name)
    outcomes = _load_outcome_records(root)
    windows = _drift_windows(
        spec,
        outcomes,
        runs_by_id={
            str(run.get("run_id")): run
            for run in runs
            if isinstance(run.get("run_id"), str)
        },
        metric_name=metric,
        baseline_window=baseline_count,
        recent_window=recent_count,
        min_samples=sample_floor,
        max_metric_drop=metric_drop,
        max_cost_increase_ratio=cost_ratio,
        max_latency_increase_ratio=latency_ratio,
    )
    findings = _drift_findings(windows)
    if not findings:
        findings.append(
            _drift_finding(
                "pass",
                "drift-stable",
                "all",
                "No metric, cost, or latency drift exceeded the configured thresholds.",
            )
        )
    fail_count = sum(1 for item in findings if item.get("severity") == "fail")
    warn_count = sum(1 for item in findings if item.get("severity") == "warn")
    drift_detected = fail_count > 0
    drift_status = (
        "drift-detected"
        if drift_detected
        else "stable-with-warnings"
        if warn_count
        else "stable"
    )
    summary = {
        "outcome_count": len(outcomes),
        "window_count": len(windows),
        "fail": fail_count,
        "warn": warn_count,
        "pass": sum(1 for item in findings if item.get("severity") == "pass"),
        "findings": len(findings),
        "drift_detected": drift_detected,
    }
    policy = {
        "metric_name": metric,
        "baseline_window": baseline_count,
        "recent_window": recent_count,
        "min_samples": sample_floor,
        "max_metric_drop": metric_drop,
        "max_cost_increase_ratio": cost_ratio,
        "max_latency_increase_ratio": latency_ratio,
    }
    generated_at = _now()
    drift_id = _drift_id(generated_at, experiment_slug, policy, summary)
    payload: dict[str, object] = {
        "schema": AGENT_DRIFT_SCHEMA,
        "drift_id": drift_id,
        "generated_at": generated_at,
        "experiment": spec.as_dict(),
        "drift_status": drift_status,
        "drift_detected": drift_detected,
        "primary_metric": spec.primary_metric.as_dict(),
        "policy": policy,
        "summary": summary,
        "windows": windows,
        "findings": findings,
        "recommendations": _drift_recommendations(findings, drift_status),
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    drift_path = safe_child(root, "drift", f"{drift_id}.json")
    report_path = safe_child(root, "drift", f"{drift_id}.md")
    drift_path.parent.mkdir(parents=True, exist_ok=True)
    written_json = write_unique_text(drift_path, json.dumps(payload, indent=2, sort_keys=True) + "\n")
    written_report = write_unique_text(report_path, _render_drift_report(payload))
    return AgentDriftResult(
        experiment=experiment_slug,
        drift_id=drift_id,
        drift_detected=drift_detected,
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def assess_agent_readiness(
    vault_dir: Path,
    *,
    experiment: str,
    min_outcomes: int = 1,
    max_failed_outcomes: int = 0,
    require_comparison: bool = False,
    require_budget: bool = False,
    require_route: bool = False,
    require_memory: bool = False,
    require_quorum: bool = False,
    require_promotion: bool = False,
    require_balance: bool = False,
    require_drift: bool = False,
) -> AgentReadinessResult:
    min_count = _non_negative_int(min_outcomes, field="min_outcomes")
    failed_ceiling = _non_negative_int(max_failed_outcomes, field="max_failed_outcomes")
    vault = ensure_vault(vault_dir)
    experiment_slug = slugify(experiment, fallback="agent-experiment")
    root = safe_child(vault, "agent-runs", experiment_slug)
    if not root.exists():
        raise FileNotFoundError(f"Agent experiment does not exist: {experiment_slug}")

    runs = _load_run_records(root)
    outcomes = _load_outcome_records(root)
    plans = _load_schema_records(root, "plans", AGENT_PLAN_SCHEMA)
    claims = _load_schema_records(root, "claims", AGENT_CLAIM_SCHEMA)
    heartbeats = _load_schema_records(root, "heartbeats", AGENT_HEARTBEAT_SCHEMA)
    comparisons = _load_schema_records(root, "comparisons", AGENT_COMPARISON_SCHEMA)
    allocations = _load_schema_records(root, "allocations", AGENT_ALLOCATION_SCHEMA)
    routes = _load_schema_records(root, "routes", AGENT_ROUTE_SCHEMA)
    memories = _load_schema_records(root, "memories", AGENT_MEMORY_SCHEMA)
    quorums = _load_schema_records(root, "quorums", AGENT_QUORUM_SCHEMA)
    gates = _load_schema_records(root, "gates", AGENT_GATE_SCHEMA)
    promotions = _load_schema_records(root, "promotions", AGENT_PROMOTION_SCHEMA)
    suite_reports = _load_schema_records(root, "suite-reports", AGENT_SUITE_REPORT_SCHEMA)
    balances = _load_schema_records(root, "balances", AGENT_BALANCE_SCHEMA)
    drift_reports = _load_schema_records(root, "drift", AGENT_DRIFT_SCHEMA)
    budget_reports = _budget_reports_for_experiment(vault, experiment_slug)
    spec = _spec_from_run(runs[-1]) if runs else None
    variant_summaries = _variant_summaries(spec, outcomes) if spec else []
    plan_summary = _readiness_plan_summary(root, plans, claims, heartbeats, outcomes)
    policy = {
        "min_outcomes": min_count,
        "max_failed_outcomes": failed_ceiling,
        "require_comparison": bool(require_comparison),
        "require_budget": bool(require_budget),
        "require_route": bool(require_route),
        "require_memory": bool(require_memory),
        "require_quorum": bool(require_quorum),
        "require_promotion": bool(require_promotion),
        "require_balance": bool(require_balance),
        "require_drift": bool(require_drift),
    }
    latest_comparison = comparisons[-1] if comparisons else None
    latest_budget = budget_reports[-1] if budget_reports else None
    latest_route = routes[-1] if routes else None
    latest_memory = memories[-1] if memories else None
    latest_quorum = quorums[-1] if quorums else None
    latest_gate = gates[-1] if gates else None
    latest_promotion = promotions[-1] if promotions else None
    latest_suite_report = suite_reports[-1] if suite_reports else None
    latest_allocation = allocations[-1] if allocations else None
    latest_drift = (
        max(drift_reports, key=lambda item: str(item.get("generated_at") or ""))
        if drift_reports
        else None
    )
    latest_balance = (
        max(balances, key=lambda item: str(item.get("generated_at") or ""))
        if balances
        else None
    )
    evidence = {
        "latest_comparison": _promotion_comparison_summary(latest_comparison),
        "latest_budget": _promotion_budget_summary(latest_budget),
        "latest_route": _readiness_route_summary(latest_route),
        "latest_memory": _readiness_memory_summary(latest_memory),
        "latest_quorum": _readiness_quorum_summary(latest_quorum),
        "latest_gate": _promotion_gate_summary(latest_gate),
        "latest_promotion": _readiness_promotion_summary(latest_promotion),
        "latest_suite_report": _promotion_suite_report_summary(latest_suite_report),
        "latest_allocation": _readiness_allocation_summary(latest_allocation),
        "latest_drift": _agent_drift_summary(latest_drift),
        "latest_balance": _agent_balance_summary(latest_balance),
    }
    summary = _readiness_summary(
        spec,
        outcomes=outcomes,
        runs=runs,
        plans=plans,
        variant_summaries=variant_summaries,
        plan_summary=plan_summary,
        evidence=evidence,
    )
    findings = _readiness_findings(
        experiment_slug,
        summary=summary,
        policy=policy,
        evidence=evidence,
    )
    fail_count = sum(1 for item in findings if item.get("severity") == "fail")
    warn_count = sum(1 for item in findings if item.get("severity") == "warn")
    pass_count = sum(1 for item in findings if item.get("severity") == "pass")
    ready = fail_count == 0
    readiness_status = _readiness_status(ready=ready, warn_count=warn_count)
    summary["findings"] = len(findings)
    summary["fail"] = fail_count
    summary["warn"] = warn_count
    summary["pass"] = pass_count
    summary["ready"] = ready
    generated_at = _now()
    readiness_id = _readiness_id(generated_at, experiment_slug, policy, findings)
    payload: dict[str, object] = {
        "schema": AGENT_READINESS_SCHEMA,
        "readiness_id": readiness_id,
        "generated_at": generated_at,
        "experiment": spec.as_dict() if spec else {"name": experiment_slug, "slug": experiment_slug},
        "readiness_status": readiness_status,
        "ready": ready,
        "policy": policy,
        "summary": summary,
        "variant_summaries": variant_summaries,
        "plan_summary": plan_summary,
        "evidence": evidence,
        "findings": findings,
        "recommendations": _readiness_recommendations(findings, readiness_status),
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    readiness_path = safe_child(root, "readiness", f"{readiness_id}.json")
    report_path = safe_child(root, "readiness", f"{readiness_id}.md")
    readiness_path.parent.mkdir(parents=True, exist_ok=True)
    written_json = write_unique_text(
        readiness_path,
        json.dumps(payload, indent=2, sort_keys=True) + "\n",
    )
    written_report = write_unique_text(report_path, _render_readiness_report(payload))
    return AgentReadinessResult(
        experiment=experiment_slug,
        readiness_id=readiness_id,
        ready=ready,
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def plan_agent_rollout(
    vault_dir: Path,
    *,
    experiment: str,
    candidate_variant_id: str | None = None,
    champion_variant_id: str | None = None,
    stages: tuple[float, ...] = DEFAULT_ROLLOUT_STAGES,
    min_observation_runs: int = 3,
    max_stage_failed_outcomes: int = 0,
    require_readiness: bool = False,
    require_promotion: bool = False,
    require_budget: bool = False,
    require_drift: bool = False,
) -> AgentRolloutResult:
    stage_ratios = _rollout_stage_ratios(stages)
    observation_floor = _positive_int(min_observation_runs, field="min_observation_runs")
    failure_ceiling = _non_negative_int(
        max_stage_failed_outcomes,
        field="max_stage_failed_outcomes",
    )
    vault = ensure_vault(vault_dir)
    experiment_slug = slugify(experiment, fallback="agent-experiment")
    root = safe_child(vault, "agent-runs", experiment_slug)
    if not root.exists():
        raise FileNotFoundError(f"Agent experiment does not exist: {experiment_slug}")
    runs = _load_run_records(root)
    if not runs:
        raise FileNotFoundError(f"Agent experiment has no run records: {experiment_slug}")
    _raise_for_active_holds(root, scopes=("rollout",))

    spec = _spec_from_run(runs[-1])
    known_variants = {variant.id for variant in spec.variants}
    champion = (
        _safe_label(champion_variant_id)
        if champion_variant_id
        else _current_champion_variant_id(spec)
    )
    if champion not in known_variants:
        raise ValueError(f"champion variant is not in experiment config: {champion}")

    promotions = _load_schema_records(root, "promotions", AGENT_PROMOTION_SCHEMA)
    readiness_reports = _load_schema_records(root, "readiness", AGENT_READINESS_SCHEMA)
    comparisons = _load_schema_records(root, "comparisons", AGENT_COMPARISON_SCHEMA)
    allocations = _load_schema_records(root, "allocations", AGENT_ALLOCATION_SCHEMA)
    routes = _load_schema_records(root, "routes", AGENT_ROUTE_SCHEMA)
    drift_reports = _load_schema_records(root, "drift", AGENT_DRIFT_SCHEMA)
    budget_reports = _budget_reports_for_experiment(vault, experiment_slug)
    latest_promotion = promotions[-1] if promotions else None
    latest_readiness = readiness_reports[-1] if readiness_reports else None
    latest_comparison = comparisons[-1] if comparisons else None
    latest_allocation = allocations[-1] if allocations else None
    latest_route = routes[-1] if routes else None
    latest_budget = budget_reports[-1] if budget_reports else None
    latest_drift = (
        max(drift_reports, key=lambda item: str(item.get("generated_at") or ""))
        if drift_reports
        else None
    )
    candidate = _rollout_candidate_variant(
        candidate_variant_id,
        latest_promotion=latest_promotion,
        latest_comparison=latest_comparison,
        latest_allocation=latest_allocation,
    )
    if candidate and candidate not in known_variants:
        raise ValueError(f"candidate variant is not in experiment config: {candidate}")
    evidence = {
        "latest_readiness": _rollout_readiness_summary(latest_readiness),
        "latest_promotion": _readiness_promotion_summary(latest_promotion),
        "latest_budget": _promotion_budget_summary(latest_budget),
        "latest_drift": _agent_drift_summary(latest_drift),
        "latest_comparison": _promotion_comparison_summary(latest_comparison),
        "latest_allocation": _readiness_allocation_summary(latest_allocation),
        "latest_route": _readiness_route_summary(latest_route),
    }
    policy = {
        "stages": stage_ratios,
        "min_observation_runs": observation_floor,
        "max_stage_failed_outcomes": failure_ceiling,
        "require_readiness": bool(require_readiness),
        "require_promotion": bool(require_promotion),
        "require_budget": bool(require_budget),
        "require_drift": bool(require_drift),
    }
    findings = _rollout_findings(
        experiment_slug,
        champion_variant_id=champion,
        candidate_variant_id=candidate,
        policy=policy,
        evidence=evidence,
    )
    fail_count = sum(1 for item in findings if item.get("severity") == "fail")
    warn_count = sum(1 for item in findings if item.get("severity") == "warn")
    ready = fail_count == 0
    rollout_status = _rollout_status(ready=ready, warn_count=warn_count)
    stage_entries = _rollout_stage_entries(
        stage_ratios,
        champion_variant_id=champion,
        candidate_variant_id=candidate,
        min_observation_runs=observation_floor,
        max_stage_failed_outcomes=failure_ceiling,
    )
    summary = {
        "stage_count": len(stage_entries),
        "final_candidate_share": stage_entries[-1]["candidate_share"] if stage_entries else None,
        "run_count": len(runs),
        "outcome_count": len(_load_outcome_records(root)),
        "findings": len(findings),
        "fail": fail_count,
        "warn": warn_count,
        "pass": sum(1 for item in findings if item.get("severity") == "pass"),
        "ready": ready,
    }
    generated_at = _now()
    rollout_id = _rollout_id(generated_at, experiment_slug, champion, candidate, policy, findings)
    payload: dict[str, object] = {
        "schema": AGENT_ROLLOUT_SCHEMA,
        "rollout_id": rollout_id,
        "generated_at": generated_at,
        "experiment": spec.as_dict(),
        "rollout_status": rollout_status,
        "ready": ready,
        "champion_variant_id": champion,
        "candidate_variant_id": candidate,
        "policy": policy,
        "summary": summary,
        "evidence": evidence,
        "stages": stage_entries,
        "rollback_policy": _rollout_rollback_policy(failure_ceiling),
        "findings": findings,
        "recommendations": _rollout_recommendations(findings, rollout_status),
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    rollout_path = safe_child(root, "rollouts", f"{rollout_id}.json")
    report_path = safe_child(root, "rollouts", f"{rollout_id}.md")
    rollout_path.parent.mkdir(parents=True, exist_ok=True)
    written_json = write_unique_text(
        rollout_path,
        json.dumps(payload, indent=2, sort_keys=True) + "\n",
    )
    written_report = write_unique_text(report_path, _render_rollout_report(payload))
    return AgentRolloutResult(
        experiment=experiment_slug,
        rollout_id=rollout_id,
        ready=ready,
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def check_agent_rollout_stage(
    vault_dir: Path,
    *,
    rollout_id: str,
    stage_index: int = 1,
    min_stage_outcomes: int | None = None,
    max_stage_failed_outcomes: int | None = None,
    max_share_deviation: float = 0.5,
    min_metric_delta: float | None = None,
    require_budget: bool = False,
    require_readiness: bool = False,
    require_drift: bool = False,
) -> AgentRolloutCheckResult:
    _safe_run_id(rollout_id)
    stage_number = _positive_int(stage_index, field="stage_index")
    stage_min = (
        _positive_int(min_stage_outcomes, field="min_stage_outcomes")
        if min_stage_outcomes is not None
        else None
    )
    failed_ceiling = (
        _non_negative_int(max_stage_failed_outcomes, field="max_stage_failed_outcomes")
        if max_stage_failed_outcomes is not None
        else None
    )
    share_ceiling = _ratio(max_share_deviation, field="max_share_deviation")
    delta_floor = (
        _optional_finite(min_metric_delta, field="min_metric_delta")
        if min_metric_delta is not None
        else None
    )
    vault = ensure_vault(vault_dir)
    rollout_path, rollout = _load_rollout_record(vault, rollout_id)
    experiment = rollout.get("experiment") if isinstance(rollout.get("experiment"), dict) else {}
    experiment_slug = slugify(str(experiment.get("slug") or experiment.get("name") or "agent-experiment"), fallback="agent-experiment")
    root = rollout_path.parent.parent
    if root.name != experiment_slug:
        experiment_slug = root.name
    _raise_for_active_holds(root, scopes=("rollout",))
    stages = rollout.get("stages") if isinstance(rollout.get("stages"), list) else []
    stage = _rollout_stage_by_index(stages, stage_number)
    policy = rollout.get("policy") if isinstance(rollout.get("policy"), dict) else {}
    stage_min = stage_min if stage_min is not None else int(stage.get("min_observation_runs") or 1)
    failed_ceiling = (
        failed_ceiling
        if failed_ceiling is not None
        else int(stage.get("max_failed_outcomes") or policy.get("max_stage_failed_outcomes") or 0)
    )
    previous_check = _latest_rollout_stage_check(root, rollout_id, before_stage_index=stage_number)
    window_start = _rollout_check_window_start(rollout, previous_check=previous_check)
    outcomes = _rollout_stage_outcomes(
        _load_outcome_records(root),
        generated_after=window_start,
        candidate_variant_id=str(rollout.get("candidate_variant_id") or ""),
        champion_variant_id=str(rollout.get("champion_variant_id") or ""),
    )
    budget_reports = _budget_reports_for_experiment(vault, experiment_slug)
    readiness_reports = _load_schema_records(root, "readiness", AGENT_READINESS_SCHEMA)
    drift_reports = _load_schema_records(root, "drift", AGENT_DRIFT_SCHEMA)
    latest_budget = budget_reports[-1] if budget_reports else None
    latest_readiness = readiness_reports[-1] if readiness_reports else None
    latest_drift = (
        max(drift_reports, key=lambda item: str(item.get("generated_at") or ""))
        if drift_reports
        else None
    )
    stage_summary = _rollout_stage_check_summary(
        rollout,
        stage,
        outcomes=outcomes,
        primary_metric=MetricSpec.from_value(experiment.get("primary_metric")),
    )
    check_policy = {
        "stage_index": stage_number,
        "min_stage_outcomes": stage_min,
        "max_stage_failed_outcomes": failed_ceiling,
        "max_share_deviation": share_ceiling,
        "min_metric_delta": delta_floor,
        "require_budget": bool(require_budget),
        "require_readiness": bool(require_readiness),
        "require_drift": bool(require_drift),
    }
    evidence = {
        "rollout": _rollout_check_rollout_summary(rollout),
        "previous_check": _rollout_check_summary(previous_check),
        "latest_budget": _promotion_budget_summary(latest_budget),
        "latest_readiness": _rollout_readiness_summary(latest_readiness),
        "latest_drift": _agent_drift_summary(latest_drift),
    }
    findings = _rollout_check_findings(
        experiment_slug,
        rollout=rollout,
        stage=stage,
        summary=stage_summary,
        policy=check_policy,
        evidence=evidence,
    )
    decision = _rollout_check_decision(findings)
    check_status = decision
    fail_count = sum(1 for item in findings if item.get("severity") == "fail")
    warn_count = sum(1 for item in findings if item.get("severity") == "warn")
    pass_count = sum(1 for item in findings if item.get("severity") == "pass")
    stage_summary["findings"] = len(findings)
    stage_summary["fail"] = fail_count
    stage_summary["warn"] = warn_count
    stage_summary["pass"] = pass_count
    generated_at = _now()
    check_id = _rollout_check_id(generated_at, rollout_id, stage_number, decision, findings)
    payload: dict[str, object] = {
        "schema": AGENT_ROLLOUT_CHECK_SCHEMA,
        "check_id": check_id,
        "rollout_id": rollout_id,
        "generated_at": generated_at,
        "experiment": experiment,
        "check_status": check_status,
        "decision": decision,
        "stage": stage,
        "policy": check_policy,
        "summary": stage_summary,
        "evidence": evidence,
        "window": {
            "started_at": window_start.isoformat(),
            "ended_at": generated_at,
            "basis": "metadata-only-outcomes",
        },
        "findings": findings,
        "recommendations": _rollout_check_recommendations(decision, findings),
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    check_path = safe_child(root, "rollout-checks", f"{check_id}.json")
    report_path = safe_child(root, "rollout-checks", f"{check_id}.md")
    check_path.parent.mkdir(parents=True, exist_ok=True)
    written_json = write_unique_text(
        check_path,
        json.dumps(payload, indent=2, sort_keys=True) + "\n",
    )
    written_report = write_unique_text(report_path, _render_rollout_check_report(payload))
    return AgentRolloutCheckResult(
        experiment=experiment_slug,
        rollout_id=rollout_id,
        check_id=check_id,
        decision=decision,
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def evolve_agent_experiment(
    vault_dir: Path,
    *,
    experiment: str,
    min_trials_per_variant: int | None = None,
    min_samples_per_variant: int | None = None,
    max_lessons: int = 12,
    allocation_strategy: str = "ucb1",
    route_strategy: str = "ucb1",
    exploration_floor: float = 0.05,
    max_share: float = 0.85,
    cost_penalty: float = 0.0,
    champion_variant_id: str | None = None,
    min_delta: float = 0.0,
    max_cost_usd: float | None = None,
    max_total_tokens: int | None = None,
    max_mean_latency_ms: float | None = None,
    require_budget: bool = False,
    require_route: bool = False,
    require_drift: bool = False,
    plan_rollout: bool = False,
    rollout_stages: tuple[float, ...] = DEFAULT_ROLLOUT_STAGES,
) -> AgentEvolveResult:
    vault = ensure_vault(vault_dir)
    experiment_slug = slugify(experiment, fallback="agent-experiment")
    root = safe_child(vault, "agent-runs", experiment_slug)
    if not root.exists():
        raise FileNotFoundError(f"Agent experiment does not exist: {experiment_slug}")
    runs = _load_run_records(root)
    if not runs:
        raise FileNotFoundError(f"Agent experiment has no run records: {experiment_slug}")
    _raise_for_active_holds(root, scopes=("evolve",))

    spec = _spec_from_run(runs[-1])
    min_trials = (
        _positive_int(min_trials_per_variant, field="min_trials_per_variant")
        if min_trials_per_variant is not None
        else spec.min_trials_per_variant
    )
    min_samples = (
        _positive_int(min_samples_per_variant, field="min_samples_per_variant")
        if min_samples_per_variant is not None
        else min_trials
    )
    lesson_limit = _positive_int(max_lessons, field="max_lessons")
    delta_floor = _non_negative_number(min_delta, field="min_delta")
    budget_requested = (
        require_budget
        or max_cost_usd is not None
        or max_total_tokens is not None
        or max_mean_latency_ms is not None
    )
    stage_ratios = _rollout_stage_ratios(rollout_stages) if plan_rollout else []
    steps: list[dict[str, object]] = []

    comparison_result = None
    improvement_result = None
    memory_result = None
    allocation_result = None
    route_result = None
    budget_result = None
    drift_result = None
    promotion_result = None
    readiness_result = None
    rollout_result = None

    def record_step(name: str, result: object, *, artifact_type: str, artifact_id: str) -> None:
        steps.append(
            _evolve_step_record(
                vault,
                name,
                "written",
                artifact_type=artifact_type,
                artifact_id=artifact_id,
                artifact_status=_evolve_artifact_status(getattr(result, "payload", None)),
                path=getattr(result, "path", None),
                report_path=getattr(result, "report_path", None),
            )
        )

    def record_error(name: str, exc: Exception) -> None:
        steps.append(_evolve_error_step(name, exc))

    try:
        comparison_result = compare_agent_experiment(
            vault,
            experiment=experiment_slug,
            min_samples_per_variant=min_samples,
        )
        record_step(
            "compare",
            comparison_result,
            artifact_type="comparison",
            artifact_id=comparison_result.comparison_id,
        )
    except Exception as exc:
        record_error("compare", exc)
    try:
        improvement_result = improve_agent_experiment(
            vault,
            experiment=experiment_slug,
            min_trials_per_variant=min_trials,
        )
        record_step(
            "improve",
            improvement_result,
            artifact_type="improvement",
            artifact_id=improvement_result.loop_id,
        )
    except Exception as exc:
        record_error("improve", exc)
    try:
        memory_result = remember_agent_experiment(
            vault,
            experiment=experiment_slug,
            min_trials_per_variant=min_trials,
            max_lessons=lesson_limit,
        )
        record_step(
            "memory",
            memory_result,
            artifact_type="memory",
            artifact_id=memory_result.memory_id,
        )
    except Exception as exc:
        record_error("memory", exc)
    try:
        allocation_result = allocate_agent_traffic(
            vault,
            experiment=experiment_slug,
            strategy=allocation_strategy,
            exploration_floor=exploration_floor,
            max_share=max_share,
            min_trials_per_variant=min_trials,
            cost_penalty=cost_penalty,
        )
        record_step(
            "allocate",
            allocation_result,
            artifact_type="allocation",
            artifact_id=allocation_result.allocation_id,
        )
    except Exception as exc:
        record_error("allocate", exc)
    try:
        route_result = route_agent_lanes(
            vault,
            experiment=experiment_slug,
            strategy=route_strategy,
            exploration_floor=exploration_floor,
            max_share=max_share,
            min_trials_per_lane_variant=min_trials,
            cost_penalty=cost_penalty,
        )
        record_step(
            "route",
            route_result,
            artifact_type="route",
            artifact_id=route_result.route_id,
        )
    except Exception as exc:
        record_error("route", exc)
    if budget_requested:
        try:
            budget_result = budget_agent_harness(
                vault,
                experiment=experiment_slug,
                max_cost_usd=max_cost_usd,
                max_total_tokens=max_total_tokens,
                max_mean_latency_ms=max_mean_latency_ms,
            )
            record_step(
                "budget",
                budget_result,
                artifact_type="budget",
                artifact_id=budget_result.budget_id,
            )
        except Exception as exc:
            record_error("budget", exc)
    if require_drift:
        try:
            drift_result = detect_agent_drift(
                vault,
                experiment=experiment_slug,
            )
            record_step(
                "drift",
                drift_result,
                artifact_type="drift",
                artifact_id=drift_result.drift_id,
            )
        except Exception as exc:
            record_error("drift", exc)
    try:
        promotion_result = promote_agent_experiment(
            vault,
            experiment=experiment_slug,
            champion_variant_id=champion_variant_id,
            min_trials_per_variant=min_trials,
            min_delta=delta_floor,
            require_budget=require_budget,
            require_drift=require_drift,
        )
        record_step(
            "promote",
            promotion_result,
            artifact_type="promotion",
            artifact_id=promotion_result.promotion_id,
        )
    except Exception as exc:
        record_error("promote", exc)
    try:
        readiness_result = assess_agent_readiness(
            vault,
            experiment=experiment_slug,
            min_outcomes=min_samples,
            require_comparison=True,
            require_budget=require_budget,
            require_route=require_route and route_result is not None,
            require_memory=memory_result is not None,
            require_promotion=promotion_result is not None,
            require_drift=require_drift,
        )
        record_step(
            "readiness",
            readiness_result,
            artifact_type="readiness",
            artifact_id=readiness_result.readiness_id,
        )
    except Exception as exc:
        record_error("readiness", exc)
    if plan_rollout:
        try:
            rollout_result = plan_agent_rollout(
                vault,
                experiment=experiment_slug,
                champion_variant_id=champion_variant_id,
                stages=tuple(stage_ratios),
                min_observation_runs=min_samples,
                require_readiness=readiness_result is not None,
                require_promotion=promotion_result is not None,
                require_budget=require_budget,
                require_drift=require_drift,
            )
            record_step(
                "rollout",
                rollout_result,
                artifact_type="rollout",
                artifact_id=rollout_result.rollout_id,
            )
        except Exception as exc:
            record_error("rollout", exc)

    generated_at = _now()
    summary = _evolve_summary(steps)
    failed = int(summary["failed_steps"]) > 0
    evolve_status = (
        "blocked"
        if failed
        else "needs-review"
        if int(summary["attention_steps"]) > 0
        else "complete"
    )
    evolve_id = _evolve_id(generated_at, experiment_slug, steps)
    payload: dict[str, object] = {
        "schema": AGENT_EVOLVE_SCHEMA,
        "evolve_id": evolve_id,
        "generated_at": generated_at,
        "experiment": spec.as_dict(),
        "evolve_status": evolve_status,
        "summary": summary,
        "policy": {
            "min_trials_per_variant": min_trials,
            "min_samples_per_variant": min_samples,
            "max_lessons": lesson_limit,
            "allocation_strategy": allocation_strategy,
            "route_strategy": route_strategy,
            "exploration_floor": exploration_floor,
            "max_share": max_share,
            "cost_penalty": cost_penalty,
            "min_delta": delta_floor,
            "require_budget": require_budget,
            "require_route": require_route,
            "require_drift": require_drift,
            "plan_rollout": plan_rollout,
            "rollout_stages": stage_ratios,
        },
        "steps": steps,
        "recommendations": _evolve_recommendations(steps, evolve_status),
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    evolve_path = safe_child(root, "evolutions", f"{evolve_id}.json")
    report_path = safe_child(root, "evolutions", f"{evolve_id}.md")
    evolve_path.parent.mkdir(parents=True, exist_ok=True)
    written_json = write_unique_text(
        evolve_path,
        json.dumps(payload, indent=2, sort_keys=True) + "\n",
    )
    written_report = write_unique_text(report_path, _render_evolve_report(payload))
    return AgentEvolveResult(
        experiment=experiment_slug,
        evolve_id=evolve_id,
        failed=failed,
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def compare_agent_experiment(
    vault_dir: Path,
    *,
    experiment: str,
    baseline_variant_id: str | None = None,
    min_samples_per_variant: int | None = None,
) -> AgentComparisonResult:
    vault = ensure_vault(vault_dir)
    experiment_slug = slugify(experiment, fallback="agent-experiment")
    root = safe_child(vault, "agent-runs", experiment_slug)
    if not root.exists():
        raise FileNotFoundError(f"Agent experiment does not exist: {experiment_slug}")
    runs = _load_run_records(root)
    if not runs:
        raise FileNotFoundError(f"Agent experiment has no run records: {experiment_slug}")
    spec = _spec_from_run(runs[-1])
    baseline = _safe_variant_id(
        baseline_variant_id,
        spec=spec,
        fallback=_current_champion_variant_id(spec),
    )
    min_samples = (
        _positive_int(min_samples_per_variant, field="min samples per variant")
        if min_samples_per_variant is not None
        else spec.min_trials_per_variant
    )
    outcomes = _load_outcome_records(root)
    values_by_variant = _metric_values_by_variant(spec, outcomes)
    summaries = _comparison_variant_summaries(spec, outcomes, values_by_variant)
    winner = _comparison_winner(
        spec,
        summaries,
        min_samples=min_samples,
    )
    pairwise = _pairwise_comparisons(
        spec,
        summaries,
        baseline_variant_id=baseline,
        min_samples=min_samples,
    )
    frontier = _efficiency_frontier(
        summaries,
        metric=spec.primary_metric,
        metric_key="primary_metric_mean",
    )
    summary = _comparison_summary(
        spec,
        summaries,
        pairwise,
        min_samples=min_samples,
    )
    recommendations = _comparison_recommendations(
        summaries,
        pairwise,
        baseline_variant_id=baseline,
        winner_variant_id=winner,
        metric=spec.primary_metric,
        min_samples=min_samples,
    )
    recommendations.extend(_efficiency_recommendations(frontier, metric=spec.primary_metric))
    generated_at = _now()
    comparison_id = _comparison_id(generated_at, experiment_slug, baseline, summaries)
    payload: dict[str, object] = {
        "schema": AGENT_COMPARISON_SCHEMA,
        "comparison_id": comparison_id,
        "generated_at": generated_at,
        "experiment": spec.as_dict(),
        "outcome_count": len(outcomes),
        "primary_metric": spec.primary_metric.as_dict(),
        "baseline_variant_id": baseline,
        "winner_variant_id": winner,
        "policy": {
            "min_samples_per_variant": min_samples,
            "confidence_interval": "normal-approx-95",
        },
        "summary": summary,
        "variant_summaries": summaries,
        "efficiency_frontier": frontier,
        "pairwise": pairwise,
        "recommendations": recommendations,
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    comparison_path = safe_child(root, "comparisons", f"{comparison_id}.json")
    report_path = safe_child(root, "comparisons", f"{comparison_id}.md")
    comparison_path.parent.mkdir(parents=True, exist_ok=True)
    written_json = write_unique_text(
        comparison_path,
        json.dumps(payload, indent=2, sort_keys=True) + "\n",
    )
    written_report = write_unique_text(report_path, _render_comparison_report(payload))
    return AgentComparisonResult(
        experiment=experiment_slug,
        comparison_id=comparison_id,
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def balance_agent_experiment(
    vault_dir: Path,
    *,
    experiment: str,
    suite_id: str | None = None,
    plan_id: str | None = None,
    dimensions: tuple[str, ...] = ("variant", "lane"),
    min_count_per_cell: int = 1,
    max_skew: int = 1,
) -> AgentBalanceResult:
    if bool(suite_id) and bool(plan_id):
        raise ValueError("provide at most one of suite_id or plan_id")
    dims = _balance_dimensions(dimensions)
    min_count = _positive_int(min_count_per_cell, field="min_count_per_cell")
    skew_limit = _non_negative_int(max_skew, field="max_skew")
    vault = ensure_vault(vault_dir)
    experiment_slug = slugify(experiment, fallback="agent-experiment")
    root = safe_child(vault, "agent-runs", experiment_slug)
    if not root.exists():
        raise FileNotFoundError(f"Agent experiment does not exist: {experiment_slug}")
    runs = _load_run_records(root)
    if not runs:
        raise FileNotFoundError(f"Agent experiment has no run records: {experiment_slug}")
    spec = _spec_from_run(runs[-1])
    scoped_runs = _balance_scope_runs(
        runs,
        suite_id=suite_id,
        plan_id=plan_id,
    )
    outcomes_by_run = _latest_outcomes_by_run(_load_outcome_records(root))
    cells = _balance_cells(scoped_runs, outcomes_by_run=outcomes_by_run, dimensions=dims)
    summary = _balance_summary(cells)
    findings = _balance_findings(
        summary,
        min_count_per_cell=min_count,
        max_skew=skew_limit,
    )
    balance_status = _balance_status(summary, min_count_per_cell=min_count, max_skew=skew_limit)
    balanced = balance_status == "balanced"
    generated_at = _now()
    scope = _balance_scope(
        experiment_slug,
        suite_id=suite_id,
        plan_id=plan_id,
    )
    balance_id = _balance_id(generated_at, experiment_slug, scope, summary, dims)
    payload: dict[str, object] = {
        "schema": AGENT_BALANCE_SCHEMA,
        "balance_id": balance_id,
        "generated_at": generated_at,
        "experiment": spec.as_dict(),
        "scope": scope,
        "balance_status": balance_status,
        "balanced": balanced,
        "policy": {
            "dimensions": list(dims),
            "min_count_per_cell": min_count,
            "max_skew": skew_limit,
        },
        "summary": summary,
        "cells": cells,
        "findings": findings,
        "recommendations": _balance_recommendations(balance_status, summary, dims),
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    balance_path = safe_child(root, "balances", f"{balance_id}.json")
    report_path = safe_child(root, "balances", f"{balance_id}.md")
    balance_path.parent.mkdir(parents=True, exist_ok=True)
    written_json = write_unique_text(
        balance_path,
        json.dumps(payload, indent=2, sort_keys=True) + "\n",
    )
    written_report = write_unique_text(report_path, _render_balance_report(payload))
    return AgentBalanceResult(
        experiment=experiment_slug,
        balance_id=balance_id,
        balanced=balanced,
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def decide_agent_experiment(
    vault_dir: Path,
    *,
    experiment: str,
    baseline_variant_id: str | None = None,
    candidate_variant_id: str | None = None,
    min_samples_per_variant: int | None = None,
    min_delta: float = 0.0,
    confidence_threshold: float = 0.8,
    max_cost_usd: float | None = None,
    max_total_tokens: int | None = None,
    candidate_metric_floor: float | None = None,
) -> AgentDecisionResult:
    vault = ensure_vault(vault_dir)
    experiment_slug = slugify(experiment, fallback="agent-experiment")
    root = safe_child(vault, "agent-runs", experiment_slug)
    if not root.exists():
        raise FileNotFoundError(f"Agent experiment does not exist: {experiment_slug}")
    runs = _load_run_records(root)
    if not runs:
        raise FileNotFoundError(f"Agent experiment has no run records: {experiment_slug}")
    spec = _spec_from_run(runs[-1])
    baseline = _safe_variant_id(
        baseline_variant_id,
        spec=spec,
        fallback=_current_champion_variant_id(spec),
    )
    min_samples = (
        _positive_int(min_samples_per_variant, field="min samples per variant")
        if min_samples_per_variant is not None
        else spec.min_trials_per_variant
    )
    delta_floor = _non_negative_number(min_delta, field="min_delta")
    confidence_floor = _probability_open_unit(confidence_threshold, field="confidence_threshold")
    cost_limit = _optional_non_negative_number(max_cost_usd, field="max_cost_usd")
    token_limit = _optional_non_negative_int(max_total_tokens, field="max_total_tokens")
    metric_floor = _optional_finite(candidate_metric_floor, field="candidate_metric_floor")
    outcomes = _load_outcome_records(root)
    values_by_variant = _metric_values_by_variant(spec, outcomes)
    summaries = _comparison_variant_summaries(spec, outcomes, values_by_variant)
    candidate = (
        _safe_variant_id(candidate_variant_id, spec=spec, fallback=baseline)
        if candidate_variant_id
        else _decision_candidate_variant_id(
            spec,
            summaries,
            baseline_variant_id=baseline,
        )
    )
    if candidate == baseline and candidate_variant_id:
        raise ValueError("candidate_variant_id must differ from baseline_variant_id")
    if candidate == baseline and len(spec.variants) > 1:
        candidate = _decision_candidate_variant_id(
            spec,
            summaries,
            baseline_variant_id=baseline,
        )
    by_variant = {
        str(item["variant_id"]): item
        for item in summaries
        if isinstance(item.get("variant_id"), str)
    }
    baseline_summary = by_variant.get(baseline)
    candidate_summary = by_variant.get(candidate) if candidate else None
    comparison = (
        _decision_comparison(
            spec,
            baseline_variant_id=baseline,
            candidate_variant_id=candidate,
            baseline=baseline_summary,
            candidate=candidate_summary,
            min_samples=min_samples,
            min_delta=delta_floor,
            confidence_threshold=confidence_floor,
        )
        if candidate
        else _empty_decision_comparison(
            baseline_variant_id=baseline,
            min_samples=min_samples,
            min_delta=delta_floor,
            confidence_threshold=confidence_floor,
        )
    )
    compared_outcomes = _decision_outcomes(
        outcomes,
        baseline_variant_id=baseline,
        candidate_variant_id=candidate,
    )
    guardrails = _decision_guardrails(
        spec,
        compared_outcomes,
        candidate_summary=candidate_summary,
        max_cost_usd=cost_limit,
        max_total_tokens=token_limit,
        candidate_metric_floor=metric_floor,
    )
    decision, decision_status = _decision_result(
        comparison,
        guardrails,
    )
    summary = _decision_summary(
        comparison,
        guardrails,
        outcome_count=len(outcomes),
        compared_outcome_count=len(compared_outcomes),
    )
    recommendations = _decision_recommendations(
        decision=decision,
        decision_status=decision_status,
        comparison=comparison,
        guardrails=guardrails,
        baseline_variant_id=baseline,
        candidate_variant_id=candidate,
        metric=spec.primary_metric,
    )
    generated_at = _now()
    decision_id = _decision_id(
        generated_at,
        experiment_slug,
        baseline,
        candidate,
        summary,
    )
    payload: dict[str, object] = {
        "schema": AGENT_DECISION_SCHEMA,
        "decision_id": decision_id,
        "generated_at": generated_at,
        "experiment": spec.as_dict(),
        "decision": decision,
        "decision_status": decision_status,
        "primary_metric": spec.primary_metric.as_dict(),
        "baseline_variant_id": baseline,
        "candidate_variant_id": candidate,
        "policy": {
            "min_samples_per_variant": min_samples,
            "min_delta": delta_floor,
            "confidence_threshold": confidence_floor,
            "max_cost_usd": cost_limit,
            "max_total_tokens": token_limit,
            "candidate_metric_floor": metric_floor,
            "test": "sequential-one-sided-normal-approximation",
        },
        "summary": summary,
        "variant_evidence": {
            "baseline": _decision_variant_evidence(baseline_summary),
            "candidate": _decision_variant_evidence(candidate_summary),
        },
        "comparison": comparison,
        "guardrails": guardrails,
        "recommendations": recommendations,
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    decision_path = safe_child(root, "decisions", f"{decision_id}.json")
    report_path = safe_child(root, "decisions", f"{decision_id}.md")
    decision_path.parent.mkdir(parents=True, exist_ok=True)
    written_json = write_unique_text(
        decision_path,
        json.dumps(payload, indent=2, sort_keys=True) + "\n",
    )
    written_report = write_unique_text(report_path, _render_decision_report(payload))
    return AgentDecisionResult(
        experiment=experiment_slug,
        decision_id=decision_id,
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def plan_agent_power(
    vault_dir: Path,
    *,
    experiment: str,
    baseline_variant_id: str | None = None,
    min_detectable_effect: float = 0.05,
    alpha: float = 0.05,
    power: float = 0.8,
    fallback_stddev: float | None = None,
    max_cost_usd: float | None = None,
    max_total_tokens: int | None = None,
) -> AgentPowerResult:
    vault = ensure_vault(vault_dir)
    experiment_slug = slugify(experiment, fallback="agent-experiment")
    root = safe_child(vault, "agent-runs", experiment_slug)
    if not root.exists():
        raise FileNotFoundError(f"Agent experiment does not exist: {experiment_slug}")
    runs = _load_run_records(root)
    if not runs:
        raise FileNotFoundError(f"Agent experiment has no run records: {experiment_slug}")
    spec = _spec_from_run(runs[-1])
    baseline = _safe_variant_id(
        baseline_variant_id,
        spec=spec,
        fallback=_current_champion_variant_id(spec),
    )
    mde = _positive_number(min_detectable_effect, field="min_detectable_effect")
    alpha_value = _probability_open_unit(alpha, field="alpha")
    power_value = _probability_open_unit(power, field="power")
    fallback_sigma = (
        _positive_number(fallback_stddev, field="fallback_stddev")
        if fallback_stddev is not None
        else None
    )
    cost_limit = _optional_non_negative_number(max_cost_usd, field="max_cost_usd")
    token_limit = _optional_non_negative_int(max_total_tokens, field="max_total_tokens")
    outcomes = _load_outcome_records(root)
    values_by_variant = _metric_values_by_variant(spec, outcomes)
    summaries = _comparison_variant_summaries(spec, outcomes, values_by_variant)
    usage_means = _power_usage_means(spec, outcomes)
    variants = _power_variant_plans(
        spec,
        summaries,
        values_by_variant,
        usage_means=usage_means,
        baseline_variant_id=baseline,
        min_detectable_effect=mde,
        alpha=alpha_value,
        power=power_value,
        fallback_stddev=fallback_sigma,
        max_cost_usd=cost_limit,
        max_total_tokens=token_limit,
    )
    summary = _power_summary(variants)
    power_status = _power_status(variants)
    generated_at = _now()
    power_id = _power_id(generated_at, experiment_slug, baseline, mde, summary)
    payload: dict[str, object] = {
        "schema": AGENT_POWER_SCHEMA,
        "power_id": power_id,
        "generated_at": generated_at,
        "experiment": spec.as_dict(),
        "power_status": power_status,
        "baseline_variant_id": baseline,
        "primary_metric": spec.primary_metric.as_dict(),
        "policy": {
            "min_detectable_effect": mde,
            "alpha": alpha_value,
            "power": power_value,
            "fallback_stddev": fallback_sigma,
            "max_cost_usd": cost_limit,
            "max_total_tokens": token_limit,
            "test": "two-sample-normal-approximation",
            "tail": "two-sided",
        },
        "summary": summary,
        "variant_plans": variants,
        "recommendations": _power_recommendations(variants, power_status),
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    power_path = safe_child(root, "power", f"{power_id}.json")
    report_path = safe_child(root, "power", f"{power_id}.md")
    power_path.parent.mkdir(parents=True, exist_ok=True)
    written_json = write_unique_text(
        power_path,
        json.dumps(payload, indent=2, sort_keys=True) + "\n",
    )
    written_report = write_unique_text(report_path, _render_power_report(payload))
    return AgentPowerResult(
        experiment=experiment_slug,
        power_id=power_id,
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def schedule_agent_batch(
    vault_dir: Path,
    *,
    experiment: str,
    subject_key: str,
    lanes: tuple[str, ...] | None = None,
    max_runs: int = 24,
    power_id: str | None = None,
    include_budget_limited: bool = False,
    paired: bool = True,
) -> AgentScheduleResult:
    if not subject_key.strip():
        raise ValueError("subject_key is required")
    run_limit = _positive_int(max_runs, field="max_runs")
    vault = ensure_vault(vault_dir)
    experiment_slug = slugify(experiment, fallback="agent-experiment")
    root = safe_child(vault, "agent-runs", experiment_slug)
    if not root.exists():
        raise FileNotFoundError(f"Agent experiment does not exist: {experiment_slug}")
    runs = _load_run_records(root)
    if not runs:
        raise FileNotFoundError(f"Agent experiment has no run records: {experiment_slug}")
    spec = _spec_from_run(runs[-1])
    power_path, power = _load_power_record(vault, experiment_slug=experiment_slug, power_id=power_id)
    lane_specs = _schedule_lanes(root, lanes=lanes)
    generated_at = _now()
    subject_hash = _hash_text(f"subject\0{subject_key}")
    prompt = _content_fingerprint(None, source_name=None)
    assignments, candidate_notes, requested_runs, limited_quotas, truncated = _schedule_assignments(
        power,
        lanes=lane_specs,
        max_runs=run_limit,
        include_budget_limited=include_budget_limited,
        paired=paired,
    )
    scheduled_runs = len(assignments)
    schedule_id = _schedule_id(
        generated_at,
        experiment_slug,
        str(power.get("power_id") or ""),
        limited_quotas,
    )
    plan_id: str | None = None
    plan_path: Path | None = None
    plan_report_path: Path | None = None
    run_results: list[AgentRunResult] = []
    run_records: list[dict[str, object]] = []
    if scheduled_runs:
        plan_id = _plan_id(
            generated_at=generated_at,
            experiment_slug=spec.slug,
            subject_hash=subject_hash,
            prompt_sha256=prompt.get("sha256"),
        )
        run_results, run_records = _write_scheduled_runs(
            vault,
            spec,
            plan_id=plan_id,
            schedule_id=schedule_id,
            power_id=str(power.get("power_id") or ""),
            subject_key=subject_key,
            lanes=lane_specs,
            assignments=assignments,
        )
        plan_payload = _scheduled_plan_payload(
            spec,
            generated_at=generated_at,
            plan_id=plan_id,
            schedule_id=schedule_id,
            power_id=str(power.get("power_id") or ""),
            subject_hash=subject_hash,
            prompt=prompt,
            lanes=lane_specs,
            run_records=run_records,
            paired=paired,
        )
        plan_path = safe_child(root, "plans", f"{plan_id}.json")
        plan_report_path = safe_child(root, "plans", f"{plan_id}.md")
        plan_path.parent.mkdir(parents=True, exist_ok=True)
        plan_path = write_unique_text(
            plan_path,
            json.dumps(plan_payload, indent=2, sort_keys=True) + "\n",
        )
        plan_report_path = write_unique_text(plan_report_path, _render_plan_report(plan_payload))
    schedule_status = (
        "scheduled-partial"
        if truncated and scheduled_runs
        else "scheduled"
        if scheduled_runs
        else "no-runs"
    )
    summary = {
        "candidate_count": len(candidate_notes),
        "requested_runs": requested_runs,
        "scheduled_runs": scheduled_runs,
        "max_runs": run_limit,
        "truncated": truncated,
        "paired": paired,
        "block_count": len(_schedule_blocks_from_records(run_records)),
        "lane_count": len(lane_specs),
        "variant_count": len([count for count in limited_quotas.values() if count > 0]),
    }
    payload: dict[str, object] = {
        "schema": AGENT_SCHEDULE_SCHEMA,
        "schedule_id": schedule_id,
        "generated_at": generated_at,
        "experiment": spec.as_dict(),
        "schedule_status": schedule_status,
        "power_id": power.get("power_id"),
        "power_path": _relative_vault_path(vault, power_path),
        "plan_id": plan_id,
        "plan_path": _relative_vault_path(vault, plan_path) if plan_path else None,
        "plan_report_path": (
            _relative_vault_path(vault, plan_report_path) if plan_report_path else None
        ),
        "summary": summary,
        "policy": {
            "max_runs": run_limit,
            "include_budget_limited": bool(include_budget_limited),
            "strategy": "power-schedule",
            "paired": paired,
        },
        "quotas": [
            {"variant_id": variant_id, "scheduled_runs": count}
            for variant_id, count in sorted(limited_quotas.items())
            if count > 0
        ],
        "candidate_plans": candidate_notes,
        "blocks": _schedule_blocks_from_records(run_records),
        "runs": [
            {
                "run_id": run.run_id,
                "variant_id": run.variant_id,
                "path": _relative_vault_path(vault, run.path),
            }
            for run in run_results
        ],
        "recommendations": _schedule_recommendations(schedule_status, summary),
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["subject_key", "prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    schedule_path = safe_child(root, "schedules", f"{schedule_id}.json")
    report_path = safe_child(root, "schedules", f"{schedule_id}.md")
    schedule_path.parent.mkdir(parents=True, exist_ok=True)
    written_json = write_unique_text(
        schedule_path,
        json.dumps(payload, indent=2, sort_keys=True) + "\n",
    )
    written_report = write_unique_text(report_path, _render_schedule_report(payload))
    return AgentScheduleResult(
        experiment=experiment_slug,
        schedule_id=schedule_id,
        plan_id=plan_id,
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


def report_agent_schedule(
    vault_dir: Path,
    *,
    schedule_id: str,
    min_completed_blocks_ratio: float = 1.0,
) -> AgentScheduleReportResult:
    safe_schedule_id = _safe_run_id(schedule_id)
    completion_floor = _ratio(min_completed_blocks_ratio, field="min_completed_blocks_ratio")
    vault = ensure_vault(vault_dir)
    schedule_path, schedule = _load_schedule_record(vault, safe_schedule_id)
    experiment = schedule.get("experiment") if isinstance(schedule.get("experiment"), dict) else {}
    spec = ExperimentSpec.from_mapping(experiment)
    root = schedule_path.parent.parent
    outcomes_by_run = _latest_outcomes_by_run(_load_outcome_records(root))
    metric = spec.primary_metric
    block_summaries = _schedule_report_blocks(
        schedule,
        outcomes_by_run=outcomes_by_run,
        metric=metric,
    )
    baseline = _schedule_report_baseline(block_summaries, spec=spec)
    pairwise = _schedule_report_pairwise(
        spec,
        block_summaries,
        baseline_variant_id=baseline,
    )
    lane_summaries = _schedule_report_lane_summaries(pairwise)
    winner = _schedule_report_winner(pairwise)
    summary = _schedule_report_summary(
        block_summaries,
        pairwise,
        min_completed_blocks_ratio=completion_floor,
    )
    report_status = _schedule_report_status(summary)
    recommendations = _schedule_report_recommendations(
        summary,
        pairwise,
        baseline_variant_id=baseline,
        winner_variant_id=winner,
    )
    generated_at = _now()
    report_id = _schedule_report_id(generated_at, safe_schedule_id, summary, pairwise)
    payload: dict[str, object] = {
        "schema": AGENT_SCHEDULE_REPORT_SCHEMA,
        "report_id": report_id,
        "schedule_id": safe_schedule_id,
        "generated_at": generated_at,
        "experiment": spec.as_dict(),
        "schedule_path": _relative_vault_path(vault, schedule_path),
        "plan_id": schedule.get("plan_id"),
        "power_id": schedule.get("power_id"),
        "report_status": report_status,
        "primary_metric": metric.as_dict(),
        "baseline_variant_id": baseline,
        "winner_variant_id": winner,
        "policy": {
            "min_completed_blocks_ratio": completion_floor,
            "comparison": "paired-by-schedule-block",
            "confidence_interval": "normal-approx-95",
        },
        "summary": summary,
        "blocks": block_summaries,
        "pairwise": pairwise,
        "lane_summaries": lane_summaries,
        "recommendations": recommendations,
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["subject_key", "prompt_text", "raw_transcript", "raw_output", "error_message"],
        },
    }
    report_path = safe_child(root, "schedule-reports", f"{report_id}.json")
    markdown_path = safe_child(root, "schedule-reports", f"{report_id}.md")
    report_path.parent.mkdir(parents=True, exist_ok=True)
    written_json = write_unique_text(
        report_path,
        json.dumps(payload, indent=2, sort_keys=True) + "\n",
    )
    written_report = write_unique_text(markdown_path, _render_schedule_report_report(payload))
    return AgentScheduleReportResult(
        experiment=spec.slug,
        schedule_id=safe_schedule_id,
        report_id=report_id,
        path=written_json,
        report_path=written_report,
        payload=payload,
    )


