def _judge_panel_recommendations(
    panel_status: str,
    summary: Mapping[str, object],
) -> list[str]:
    if int(summary.get("target_count") or 0) == 0:
        return ["No completed target runs were available; log source plan outcomes or pass --include-pending-targets."]
    if panel_status == "no-runs":
        return ["No judge runs were scheduled; add judge variants or allow self-judges for single-variant target sets."]
    if panel_status == "scheduled-partial":
        return [f"Dispatch the {int(summary.get('scheduled_runs') or 0)} scheduled judge run(s), then rerun agent-judge-panel for remaining targets."]
    return ["Dispatch judge work packets, log judge_score outcomes, then run agent-judge-report."]


def _load_judge_panel_record(vault: Path, panel_id: str) -> tuple[Path, dict[str, object]]:
    panel = _safe_run_id(panel_id)
    root = safe_child(vault, "agent-runs")
    if not root.exists():
        raise FileNotFoundError("No agent judge panels have been recorded")
    matches = sorted(root.glob(f"*/judge-panels/{panel}.json"))
    if not matches:
        raise FileNotFoundError(f"Agent judge panel not found: {panel}")
    if len(matches) > 1:
        raise ValueError(f"Agent judge panel id is ambiguous: {panel}")
    record = _read_json_object(matches[0])
    if record.get("schema") != AGENT_JUDGE_PANEL_SCHEMA:
        raise ValueError(f"Agent judge panel has invalid schema: {panel}")
    return matches[0], record


def _judge_panel_target_summaries(
    panel: Mapping[str, object],
    *,
    outcomes_by_run: Mapping[str, dict[str, object]],
    metric: MetricSpec,
) -> list[dict[str, object]]:
    targets = panel.get("targets") if isinstance(panel.get("targets"), list) else []
    summaries: list[dict[str, object]] = []
    for target in targets:
        if not isinstance(target, dict):
            continue
        judge_runs = target.get("judge_runs") if isinstance(target.get("judge_runs"), list) else []
        judgements = [
            _judge_panel_judgement(run_ref, outcomes_by_run=outcomes_by_run, metric=metric)
            for run_ref in judge_runs
            if isinstance(run_ref, dict)
        ]
        scores = [
            float(item["score"])
            for item in judgements
            if isinstance(item.get("score"), (int, float))
        ]
        mean = sum(scores) / len(scores) if scores else None
        stddev = _sample_stddev(scores, mean=mean) if mean is not None else None
        summaries.append(
            {
                "target_run_id": target.get("target_run_id"),
                "target_variant_id": target.get("target_variant_id"),
                "source_lane_id": target.get("source_lane_id"),
                "outcome_id": target.get("outcome_id"),
                "outcome_status": target.get("outcome_status"),
                "judge_run_count": len(judge_runs),
                "completed_judgements": len(scores),
                "score_mean": round(mean, 6) if mean is not None else None,
                "score_stddev": round(stddev, 6) if stddev is not None else None,
                "score_stderr": (
                    round(stddev / math.sqrt(len(scores)), 6)
                    if stddev is not None and scores
                    else None
                ),
                "score_ci95": _confidence_interval(
                    round(mean, 6) if mean is not None else None,
                    round(stddev / math.sqrt(len(scores)), 6)
                    if stddev is not None and scores
                    else None,
                ),
                "judgements": judgements,
                "status": _judge_panel_target_status(len(scores), len(judge_runs)),
            }
        )
    return summaries


def _judge_panel_judgement(
    run_ref: Mapping[str, object],
    *,
    outcomes_by_run: Mapping[str, dict[str, object]],
    metric: MetricSpec,
) -> dict[str, object]:
    run_id = str(run_ref.get("run_id") or "")
    outcome = outcomes_by_run.get(run_id)
    score = None
    status = "pending"
    outcome_id = None
    if outcome is not None:
        status = str(outcome.get("status") or "unknown")
        outcome_id = outcome.get("outcome_id")
        metrics = outcome.get("metrics") if isinstance(outcome.get("metrics"), dict) else {}
        value = metrics.get(metric.name) if isinstance(metrics, dict) else None
        if isinstance(value, (int, float)) and math.isfinite(float(value)):
            score = round(float(value), 6)
    return {
        "run_id": run_id or None,
        "judge_variant_id": run_ref.get("judge_variant_id"),
        "replica": run_ref.get("replica"),
        "status": status,
        "outcome_id": outcome_id,
        "score": score,
    }


def _judge_panel_target_status(completed: int, expected: int) -> str:
    if expected == 0:
        return "no-judges"
    if completed == 0:
        return "no-outcomes"
    if completed == expected:
        return "complete"
    return "partial"


def _judge_panel_variant_summaries(
    spec: ExperimentSpec,
    target_summaries: list[dict[str, object]],
    *,
    metric: MetricSpec,
) -> list[dict[str, object]]:
    rows: list[dict[str, object]] = []
    for variant in spec.variants:
        targets = [
            item for item in target_summaries if item.get("target_variant_id") == variant.id
        ]
        scores = [
            float(item["score_mean"])
            for item in targets
            if isinstance(item.get("score_mean"), (int, float))
        ]
        mean = sum(scores) / len(scores) if scores else None
        rows.append(
            {
                "rank": 0,
                "variant_id": variant.id,
                "provider": variant.provider,
                "model": variant.model,
                "target_count": len(targets),
                "judged_target_count": len(scores),
                "score_mean": round(mean, 6) if mean is not None else None,
                "completed_judgements": sum(int(item.get("completed_judgements") or 0) for item in targets),
            }
        )
    rows.sort(
        key=lambda item: (
            _metric_sort_value(item.get("score_mean"), metric=metric),
            -int(item.get("judged_target_count") or 0),
            str(item.get("variant_id") or ""),
        )
    )
    for index, row in enumerate(rows, start=1):
        row["rank"] = index
    return rows


def _judge_panel_judge_summaries(
    panel: Mapping[str, object],
    *,
    outcomes_by_run: Mapping[str, dict[str, object]],
    metric: MetricSpec,
) -> list[dict[str, object]]:
    runs = panel.get("runs") if isinstance(panel.get("runs"), list) else []
    by_judge: dict[str, list[dict[str, object]]] = {}
    for run in runs:
        if not isinstance(run, dict):
            continue
        judge_variant_id = str(run.get("judge_variant_id") or run.get("variant_id") or "")
        by_judge.setdefault(judge_variant_id, []).append(run)
    summaries: list[dict[str, object]] = []
    for judge_variant_id, run_refs in sorted(by_judge.items()):
        judgements = [
            _judge_panel_judgement(run_ref, outcomes_by_run=outcomes_by_run, metric=metric)
            for run_ref in run_refs
        ]
        scores = [
            float(item["score"])
            for item in judgements
            if isinstance(item.get("score"), (int, float))
        ]
        mean = sum(scores) / len(scores) if scores else None
        summaries.append(
            {
                "judge_variant_id": judge_variant_id,
                "judge_run_count": len(run_refs),
                "completed_judgements": len(scores),
                "score_mean": round(mean, 6) if mean is not None else None,
            }
        )
    return summaries


def _metric_sort_value(value: object, *, metric: MetricSpec) -> float:
    if not isinstance(value, (int, float)):
        return math.inf
    number = float(value)
    return -number if metric.direction == "maximize" else number


def _judge_panel_winner_target(
    target_summaries: list[dict[str, object]],
    *,
    metric: MetricSpec,
) -> dict[str, object] | None:
    candidates = [
        item for item in target_summaries if isinstance(item.get("score_mean"), (int, float))
    ]
    if not candidates:
        return None
    return sorted(
        candidates,
        key=lambda item: (
            _metric_sort_value(item.get("score_mean"), metric=metric),
            str(item.get("target_run_id") or ""),
        ),
    )[0]


def _judge_panel_winner_variant(
    variant_summaries: list[dict[str, object]],
    *,
    metric: MetricSpec,
) -> str | None:
    candidates = [
        item for item in variant_summaries if isinstance(item.get("score_mean"), (int, float))
    ]
    if not candidates:
        return None
    return str(
        sorted(
            candidates,
            key=lambda item: (
                _metric_sort_value(item.get("score_mean"), metric=metric),
                str(item.get("variant_id") or ""),
            ),
        )[0].get("variant_id")
    )


def _judge_panel_report_summary(
    panel: Mapping[str, object],
    target_summaries: list[dict[str, object]],
    *,
    min_completed_ratio: float,
) -> dict[str, object]:
    runs = panel.get("runs") if isinstance(panel.get("runs"), list) else []
    expected = len(runs)
    completed = sum(int(item.get("completed_judgements") or 0) for item in target_summaries)
    complete_targets = sum(1 for item in target_summaries if item.get("status") == "complete")
    completion_ratio = completed / expected if expected else 0.0
    return {
        "target_count": len(target_summaries),
        "complete_targets": complete_targets,
        "judge_run_count": expected,
        "completed_judgements": completed,
        "completion_ratio": round(completion_ratio, 6),
        "min_completed_ratio": min_completed_ratio,
        "passes_completion_floor": completion_ratio >= min_completed_ratio if expected else False,
    }


def _judge_panel_report_status(summary: Mapping[str, object]) -> str:
    if int(summary.get("completed_judgements") or 0) == 0:
        return "no-outcomes"
    if bool(summary.get("passes_completion_floor")):
        return "complete"
    return "partial"


def _judge_panel_report_recommendations(
    summary: Mapping[str, object],
    *,
    winner_variant_id: str | None,
) -> list[str]:
    recommendations: list[str] = []
    if winner_variant_id:
        recommendations.append(f"Use judge-panel winner {winner_variant_id} as review evidence before promotion.")
    else:
        recommendations.append("Complete judge panel outcomes before using this report as review evidence.")
    if not bool(summary.get("passes_completion_floor")):
        recommendations.append("Dispatch or recover missing judge runs, then rerun agent-judge-report.")
    return recommendations


def _arena_report_matches(
    arena: Mapping[str, object],
    *,
    outcomes_by_run: Mapping[str, dict[str, object]],
    metric: MetricSpec,
) -> list[dict[str, object]]:
    raw_matches = arena.get("matches") if isinstance(arena.get("matches"), list) else []
    results: list[dict[str, object]] = []
    for raw_match in raw_matches:
        if not isinstance(raw_match, dict):
            continue
        runs = raw_match.get("runs") if isinstance(raw_match.get("runs"), list) else []
        run_results = [
            _arena_report_run_result(run_ref, outcomes_by_run=outcomes_by_run, metric=metric)
            for run_ref in runs
            if isinstance(run_ref, dict)
        ]
        if len(run_results) < 2:
            run_results.extend(
                {
                    "run_id": None,
                    "variant_id": None,
                    "arena_role": "missing",
                    "status": "missing-run",
                    "outcome_id": None,
                    "metric": None,
                }
                for _ in range(2 - len(run_results))
            )
        left, right = run_results[0], run_results[1]
        winner = _arena_match_winner(left, right, metric=metric)
        metric_delta = None
        directional_delta = None
        if isinstance(left.get("metric"), (int, float)) and isinstance(right.get("metric"), (int, float)):
            metric_delta = round(float(left["metric"]) - float(right["metric"]), 6)
            directional_delta = (
                metric_delta
                if metric.direction == "maximize"
                else round(-metric_delta, 6)
            )
        results.append(
            {
                "match_id": raw_match.get("match_id"),
                "pair_id": raw_match.get("pair_id"),
                "block_id": raw_match.get("block_id"),
                "lane_id": raw_match.get("lane_id"),
                "replica": raw_match.get("replica"),
                "variant_a_id": left.get("variant_id"),
                "variant_b_id": right.get("variant_id"),
                "winner_variant_id": winner,
                "match_status": _arena_match_status(left, right),
                "metric_delta": metric_delta,
                "directional_delta": directional_delta,
                "runs": run_results[:2],
            }
        )
    return results


def _arena_report_run_result(
    run_ref: Mapping[str, object],
    *,
    outcomes_by_run: Mapping[str, dict[str, object]],
    metric: MetricSpec,
) -> dict[str, object]:
    run_id = str(run_ref.get("run_id") or "")
    variant_id = slugify(str(run_ref.get("variant_id") or "variant"), fallback="variant")
    outcome = outcomes_by_run.get(run_id)
    if outcome is None:
        return {
            "run_id": run_id or None,
            "variant_id": variant_id,
            "arena_role": str(run_ref.get("arena_role") or ""),
            "status": "pending",
            "outcome_id": None,
            "metric": None,
        }
    metrics = outcome.get("metrics") if isinstance(outcome.get("metrics"), dict) else {}
    value = metrics.get(metric.name) if isinstance(metrics, dict) else None
    metric_value = (
        round(float(value), 6)
        if isinstance(value, (int, float)) and math.isfinite(float(value))
        else None
    )
    return {
        "run_id": run_id or None,
        "variant_id": variant_id,
        "arena_role": str(run_ref.get("arena_role") or ""),
        "status": str(outcome.get("status") or "unknown"),
        "outcome_id": outcome.get("outcome_id"),
        "metric": metric_value,
    }


def _arena_match_status(
    left: Mapping[str, object],
    right: Mapping[str, object],
) -> str:
    if isinstance(left.get("metric"), (int, float)) and isinstance(right.get("metric"), (int, float)):
        return "complete"
    statuses = {str(left.get("status") or ""), str(right.get("status") or "")}
    if statuses <= {"pending", "missing-run", ""}:
        return "no-outcomes"
    return "partial"


def _arena_match_winner(
    left: Mapping[str, object],
    right: Mapping[str, object],
    *,
    metric: MetricSpec,
) -> str | None:
    left_metric = left.get("metric")
    right_metric = right.get("metric")
    if not isinstance(left_metric, (int, float)) or not isinstance(right_metric, (int, float)):
        return None
    if float(left_metric) == float(right_metric):
        return None
    left_wins = (
        float(left_metric) > float(right_metric)
        if metric.direction == "maximize"
        else float(left_metric) < float(right_metric)
    )
    return str(left.get("variant_id") if left_wins else right.get("variant_id"))


def _arena_report_pairwise(
    spec: ExperimentSpec,
    matches: list[dict[str, object]],
) -> list[dict[str, object]]:
    variant_ids = {variant.id for variant in spec.variants}
    pair_order = {
        _arena_pair_id(left.id, right.id): (left.id, right.id)
        for left, right in _arena_variant_pairs(spec)
    }
    rows: list[dict[str, object]] = []
    for pair_id, (left_id, right_id) in sorted(pair_order.items()):
        pair_matches = [
            match
            for match in matches
            if str(match.get("pair_id") or "") == pair_id
            and match.get("variant_a_id") in variant_ids
            and match.get("variant_b_id") in variant_ids
        ]
        completed = [match for match in pair_matches if match.get("match_status") == "complete"]
        wins_left = sum(1 for match in completed if match.get("winner_variant_id") == left_id)
        wins_right = sum(1 for match in completed if match.get("winner_variant_id") == right_id)
        ties = sum(1 for match in completed if match.get("winner_variant_id") is None)
        deltas: list[float] = []
        for match in completed:
            runs = match.get("runs") if isinstance(match.get("runs"), list) else []
            metrics = {
                str(run.get("variant_id")): run.get("metric")
                for run in runs
                if isinstance(run, dict) and isinstance(run.get("metric"), (int, float))
            }
            left_metric = metrics.get(left_id)
            right_metric = metrics.get(right_id)
            if isinstance(left_metric, (int, float)) and isinstance(right_metric, (int, float)):
                raw_delta = float(left_metric) - float(right_metric)
                deltas.append(raw_delta if spec.primary_metric.direction == "maximize" else -raw_delta)
        mean = sum(deltas) / len(deltas) if deltas else None
        stddev = _sample_stddev(deltas, mean=mean) if mean is not None else None
        stderr = stddev / math.sqrt(len(deltas)) if stddev is not None and deltas else None
        ci = _confidence_interval(mean, stderr)
        rows.append(
            {
                "pair_id": pair_id,
                "left_variant_id": left_id,
                "right_variant_id": right_id,
                "scheduled_matches": len(pair_matches),
                "completed_matches": len(completed),
                "left_wins": wins_left,
                "right_wins": wins_right,
                "ties": ties,
                "mean_directional_delta_left": round(mean, 6) if mean is not None else None,
                "delta_ci95": ci,
                "winner_variant_id": (
                    left_id
                    if wins_left > wins_right
                    else right_id
                    if wins_right > wins_left
                    else None
                ),
                "status": _arena_pair_status(wins_left, wins_right, ties, len(completed)),
                "match_ids": [
                    str(match.get("match_id"))
                    for match in completed
                    if isinstance(match.get("match_id"), str)
                ],
            }
        )
    return rows


def _arena_pair_status(left_wins: int, right_wins: int, ties: int, completed: int) -> str:
    if completed == 0:
        return "insufficient-data"
    if left_wins > right_wins:
        return "left-leading"
    if right_wins > left_wins:
        return "right-leading"
    if ties == completed:
        return "tied"
    return "split"


def _arena_report_variant_summaries(
    spec: ExperimentSpec,
    matches: list[dict[str, object]],
    *,
    outcomes_by_run: Mapping[str, dict[str, object]],
    metric: MetricSpec,
) -> list[dict[str, object]]:
    arena_run_ids = {
        str(run.get("run_id"))
        for match in matches
        for run in (match.get("runs") if isinstance(match.get("runs"), list) else [])
        if isinstance(run, dict) and isinstance(run.get("run_id"), str)
    }
    arena_outcomes = [
        outcome
        for run_id, outcome in outcomes_by_run.items()
        if run_id in arena_run_ids
    ]
    usage_by_variant = {
        variant.id: _usage_summary(
            [outcome for outcome in arena_outcomes if _outcome_variant_id(outcome) == variant.id]
        )
        for variant in spec.variants
    }
    rows: list[dict[str, object]] = []
    for variant in spec.variants:
        scheduled = [
            match
            for match in matches
            if variant.id
            in {
                str(run.get("variant_id"))
                for run in (match.get("runs") if isinstance(match.get("runs"), list) else [])
                if isinstance(run, dict)
            }
        ]
        completed = [match for match in scheduled if match.get("match_status") == "complete"]
        wins = sum(1 for match in completed if match.get("winner_variant_id") == variant.id)
        ties = sum(1 for match in completed if match.get("winner_variant_id") is None)
        losses = len(completed) - wins - ties
        values = [
            float(run["metric"])
            for match in completed
            for run in (match.get("runs") if isinstance(match.get("runs"), list) else [])
            if isinstance(run, dict)
            and run.get("variant_id") == variant.id
            and isinstance(run.get("metric"), (int, float))
        ]
        mean = sum(values) / len(values) if values else None
        score = wins + (0.5 * ties)
        row: dict[str, object] = {
            "rank": 0,
            "variant_id": variant.id,
            "provider": variant.provider,
            "model": variant.model,
            "scheduled_matches": len(scheduled),
            "completed_matches": len(completed),
            "wins": wins,
            "losses": losses,
            "ties": ties,
            "arena_points": round(score, 6),
            "win_rate": round(score / len(completed), 6) if completed else None,
            "metric_count": len(values),
            "metric_mean": round(mean, 6) if mean is not None else None,
            "arena_rating": round(1000 + (32 * (wins - losses)) + (8 * ties), 6),
        }
        usage = usage_by_variant.get(variant.id, {})
        if usage:
            row["usage"] = usage
        rows.append(row)
    reverse_metric = metric.direction == "maximize"
    rows.sort(
        key=lambda item: (
            -float(item.get("arena_points") or 0.0),
            -float(item.get("win_rate") or 0.0),
            (
                -float(item.get("metric_mean") or 0.0)
                if reverse_metric
                else float(item.get("metric_mean") or 0.0)
            ),
            str(item.get("variant_id") or ""),
        )
    )
    for index, row in enumerate(rows, start=1):
        row["rank"] = index
    return rows


def _arena_report_winner(
    spec: ExperimentSpec,
    variant_summaries: list[dict[str, object]],
) -> str | None:
    del spec
    if not variant_summaries:
        return None
    leader = variant_summaries[0]
    if int(leader.get("completed_matches") or 0) == 0:
        return None
    return str(leader.get("variant_id"))


def _arena_report_summary(
    arena: Mapping[str, object],
    matches: list[dict[str, object]],
    *,
    min_completed_ratio: float,
) -> dict[str, object]:
    complete_matches = sum(1 for match in matches if match.get("match_status") == "complete")
    partial_matches = sum(1 for match in matches if match.get("match_status") == "partial")
    scheduled_matches = len(matches)
    raw_runs = arena.get("runs") if isinstance(arena.get("runs"), list) else []
    completed_run_ids = {
        str(run.get("run_id"))
        for match in matches
        for run in (match.get("runs") if isinstance(match.get("runs"), list) else [])
        if isinstance(run, dict) and isinstance(run.get("outcome_id"), str)
    }
    completion_ratio = complete_matches / scheduled_matches if scheduled_matches else 0.0
    return {
        "scheduled_matches": scheduled_matches,
        "complete_matches": complete_matches,
        "partial_matches": partial_matches,
        "scheduled_runs": len(raw_runs),
        "completed_runs": len(completed_run_ids),
        "variant_count": int((arena.get("summary") if isinstance(arena.get("summary"), dict) else {}).get("variant_count") or 0),
        "pair_count": int((arena.get("summary") if isinstance(arena.get("summary"), dict) else {}).get("pair_count") or 0),
        "completion_ratio": round(completion_ratio, 6),
        "min_completed_ratio": min_completed_ratio,
        "passes_completion_floor": completion_ratio >= min_completed_ratio if scheduled_matches else False,
    }


def _arena_report_status(summary: Mapping[str, object]) -> str:
    if int(summary.get("complete_matches") or 0) == 0:
        return "no-outcomes"
    if bool(summary.get("passes_completion_floor")):
        return "complete"
    return "partial"


def _arena_report_recommendations(
    summary: Mapping[str, object],
    variant_summaries: list[dict[str, object]],
    *,
    winner_variant_id: str | None,
) -> list[str]:
    recommendations: list[str] = []
    if not winner_variant_id:
        recommendations.append("Complete arena match outcomes before declaring an arena champion.")
    else:
        recommendations.append(f"Review leaderboard and promotion controls for arena champion {winner_variant_id}.")
    if not bool(summary.get("passes_completion_floor")):
        recommendations.append("Finish or recover missing arena matches before using this report as promotion evidence.")
    under_sampled = [
        str(item.get("variant_id"))
        for item in variant_summaries
        if int(item.get("completed_matches") or 0) == 0
    ]
    if under_sampled:
        recommendations.append("Collect arena outcomes for unsampled variant(s): " + ", ".join(under_sampled) + ".")
    return recommendations


def _experiment_roots(vault: Path, *, experiment: str | None) -> list[Path]:
    agent_root = safe_child(vault, "agent-runs")
    if experiment:
        root = safe_child(agent_root, slugify(experiment, fallback="agent-experiment"))
        if not root.exists():
            raise FileNotFoundError(f"Agent experiment does not exist: {root.name}")
        return [root]
    if not agent_root.exists():
        return []
    roots = []
    for root in sorted(agent_root.iterdir()):
        if root.name.startswith("_") or not root.is_dir() or root.is_symlink():
            continue
        if any((root / name).is_dir() for name in ("runs", "plans", "suites", "pipelines", "outcomes", "merges", "holds", "quarantines", "circuits", "mix", "snapshots")):
            roots.append(root)
    return roots


def _experiment_status(vault: Path, root: Path) -> dict[str, object]:
    runs = _load_run_records(root)
    plans = _load_schema_records(root, "plans", AGENT_PLAN_SCHEMA)
    suites = _load_schema_records(root, "suites", AGENT_SUITE_SCHEMA)
