def _timeline_report_experiment(
    scope: str,
    *,
    requested_scope: str | None,
    experiment_slugs: set[str],
) -> str | None:
    if requested_scope:
        if scope in ("all", requested_scope):
            return requested_scope
        return None
    if scope == "all":
        return "all"
    if scope in experiment_slugs:
        return scope
    return None


def _timeline_variant_id(record: Mapping[str, object]) -> object:
    variant = record.get("variant")
    if isinstance(variant, dict):
        return variant.get("id")
    return None


def _timeline_event(
    *,
    timestamp: object,
    experiment: str,
    event_type: str,
    artifact_id: object,
    artifact_ref: str,
    message: str,
    run_id: object | None = None,
    plan_id: object | None = None,
    lane_id: object | None = None,
    variant_id: object | None = None,
    status: str | None = None,
) -> dict[str, object]:
    clean_timestamp = _timeline_timestamp(timestamp)
    clean_artifact_id = _optional_timeline_label(artifact_id)
    payload: dict[str, object] = {
        "event_id": _timeline_event_id(clean_timestamp, experiment, event_type, clean_artifact_id),
        "timestamp": clean_timestamp,
        "experiment": experiment,
        "event_type": _safe_label(event_type),
        "artifact": artifact_ref,
        "artifact_id": clean_artifact_id,
        "message": _safe_text_label(message, field="timeline message", max_length=220),
    }
    for key, value in (
        ("run_id", run_id),
        ("plan_id", plan_id),
        ("lane_id", lane_id),
        ("variant_id", variant_id),
        ("status", status),
    ):
        clean_value = _optional_timeline_label(value)
        if clean_value:
            payload[key] = clean_value
    return payload


def _timeline_timestamp(value: object) -> str:
    text = str(value or "").strip()
    if not text:
        return "1970-01-01T00:00:00+00:00"
    parsed = _parse_datetime(text)
    if parsed is None:
        return _safe_text_label(text, field="timestamp", max_length=80)
    return parsed.astimezone(timezone.utc).isoformat()


def _optional_timeline_label(value: object) -> str | None:
    if value is None:
        return None
    text = str(value).strip()
    if not text:
        return None
    return _safe_text_label(text, field="timeline label", max_length=160)


def _gate_findings(
    *,
    lane_summaries: list[dict[str, object]],
    metric: MetricSpec,
    recommended: dict[str, object] | None,
    completed_ratio: float,
    min_completed_ratio: float,
    failed: int,
    max_failures: int,
    metric_threshold: float | None,
    required_lanes: tuple[str, ...],
    pending: int,
    claimed: int,
    expired_claims: int,
) -> list[dict[str, str]]:
    findings: list[dict[str, str]] = []
    if completed_ratio < min_completed_ratio:
        findings.append(
            _gate_finding(
                "fail",
                "completion-ratio",
                f"completed ratio {completed_ratio:.6g} is below required {min_completed_ratio:.6g}",
            )
        )
    if failed > max_failures:
        findings.append(
            _gate_finding(
                "fail",
                "failed-runs",
                f"{failed} failed run(s) exceeds allowed {max_failures}",
            )
        )
    if pending:
        findings.append(
            _gate_finding("warn", "queued-runs", f"{pending} run(s) are still queued")
        )
    if claimed:
        findings.append(
            _gate_finding("warn", "claimed-runs", f"{claimed} run(s) are currently claimed")
        )
    if expired_claims:
        findings.append(
            _gate_finding("warn", "expired-claims", f"{expired_claims} claim(s) are expired")
        )
    lanes = {str(item.get("lane_id")): item for item in lane_summaries}
    for lane_id in required_lanes:
        lane = lanes.get(lane_id)
        if lane is None:
            findings.append(_gate_finding("fail", "required-lane", f"required lane is missing: {lane_id}"))
        elif int(lane.get("completed_runs") or 0) < int(lane.get("expected_runs") or 0):
            findings.append(
                _gate_finding(
                    "fail",
                    "required-lane-incomplete",
                    f"required lane is incomplete: {lane_id}",
                )
            )
    if metric_threshold is not None:
        if recommended is None or not isinstance(recommended.get("metric"), (int, float)):
            findings.append(
                _gate_finding(
                    "fail",
                    "metric-missing",
                    f"no recommended run has the {metric.name} metric",
                )
            )
        else:
            value = float(recommended["metric"])
            threshold_passed = (
                value >= metric_threshold
                if metric.direction == "maximize"
                else value <= metric_threshold
            )
            if not threshold_passed:
                comparison = "below" if metric.direction == "maximize" else "above"
                findings.append(
                    _gate_finding(
                        "fail",
                        "metric-threshold",
                        f"{metric.name} {value:.6g} is {comparison} threshold {metric_threshold:.6g}",
                    )
                )
    if not findings:
        findings.append(_gate_finding("pass", "gate-passed", "all gate checks passed"))
    return findings


def _gate_finding(severity: str, code: str, message: str) -> dict[str, str]:
    return {"severity": severity, "code": code, "message": message}


def _adjudication_lane_decisions(
    lane_summaries: list[dict[str, object]],
) -> list[dict[str, object]]:
    decisions: list[dict[str, object]] = []
    for lane in lane_summaries:
        expected = int(lane.get("expected_runs") or 0)
        completed = int(lane.get("completed_runs") or 0)
        decisions.append(
            {
                "lane_id": lane.get("lane_id"),
                "role": lane.get("role"),
                "status": "decided" if lane.get("best_run_id") else "undecided",
                "expected_runs": expected,
                "completed_runs": completed,
                "completion_ratio": round(completed / expected, 6) if expected else 0.0,
                "best_run_id": lane.get("best_run_id"),
                "best_variant_id": lane.get("best_variant_id"),
                "best_metric": lane.get("best_metric"),
                "success_rate": lane.get("success_rate"),
            }
        )
    return decisions


def _adjudication_consensus(
    lane_decisions: list[dict[str, object]],
    recommended: dict[str, object] | None,
) -> dict[str, object]:
    decided = [
        item
        for item in lane_decisions
        if item.get("status") == "decided" and item.get("best_variant_id")
    ]
    variant_counts: dict[str, int] = {}
    for item in decided:
        variant = str(item["best_variant_id"])
        variant_counts[variant] = variant_counts.get(variant, 0) + 1
    recommended_variant = str(recommended["variant_id"]) if recommended else None
    agreeing = variant_counts.get(recommended_variant, 0) if recommended_variant else 0
    ratio = agreeing / len(decided) if decided else 0.0
    return {
        "recommended_variant_id": recommended_variant,
        "decided_lanes": len(decided),
        "agreeing_lanes": agreeing,
        "agreement_ratio": round(ratio, 6),
        "variant_counts": variant_counts,
    }


def _adjudication_findings(
    *,
    recommended: dict[str, object] | None,
    completed_ratio: float,
    min_completed_ratio: float,
    consensus: Mapping[str, object],
    min_consensus_ratio: float,
    latest_gate: Mapping[str, object] | None,
) -> list[dict[str, str]]:
    findings: list[dict[str, str]] = []
    if recommended is None:
        findings.append(
            _gate_finding("fail", "no-recommendation", "no completed run has the primary metric")
        )
    if completed_ratio < min_completed_ratio:
        findings.append(
            _gate_finding(
                "fail",
                "completion-ratio",
                f"completed ratio {completed_ratio:.6g} is below required {min_completed_ratio:.6g}",
            )
        )
    agreement = float(consensus.get("agreement_ratio") or 0.0)
    if agreement < min_consensus_ratio:
        findings.append(
            _gate_finding(
                "fail",
                "consensus-ratio",
                f"agreement ratio {agreement:.6g} is below required {min_consensus_ratio:.6g}",
            )
        )
    if latest_gate is None:
        findings.append(_gate_finding("warn", "gate-missing", "no prior agent-gate artifact found"))
    elif latest_gate.get("gate_status") != "pass":
        findings.append(_gate_finding("warn", "gate-not-passing", "latest gate is not passing"))
    if not findings:
        findings.append(_gate_finding("pass", "adjudication-accepted", "decision evidence is accepted"))
    return findings


def _adjudication_reference(
    record: Mapping[str, object] | None,
    id_key: str,
    status_key: str,
) -> dict[str, object] | None:
    if record is None:
        return None
    return {
        "id": record.get(id_key),
        "status": record.get(status_key),
        "generated_at": record.get("generated_at"),
    }


def _quorum_lane_votes(lane_summaries: list[dict[str, object]]) -> list[dict[str, object]]:
    votes: list[dict[str, object]] = []
    for lane in lane_summaries:
        expected = int(lane.get("expected_runs") or 0)
        completed = int(lane.get("completed_runs") or 0)
        best_variant = lane.get("best_variant_id")
        results = lane.get("results") if isinstance(lane.get("results"), list) else []
        votes.append(
            {
                "lane_id": _safe_label(str(lane.get("lane_id") or "lane")),
                "role": _safe_text_label(
                    str(lane.get("role") or lane.get("lane_id") or "lane"),
                    field="lane role",
                ),
                "status": "decided" if best_variant else "undecided",
                "expected_runs": expected,
                "completed_runs": completed,
                "completion_ratio": round(completed / expected, 6) if expected else 0.0,
                "vote_variant_id": slugify(str(best_variant), fallback="variant") if best_variant else None,
                "vote_run_id": lane.get("best_run_id"),
                "vote_metric": lane.get("best_metric"),
                "success_rate": lane.get("success_rate"),
                "completed_variant_count": len(
                    {
                        str(item.get("variant_id"))
                        for item in results
                        if isinstance(item, dict) and item.get("status") != "pending"
                    }
                ),
            }
        )
    return votes


def _quorum_consensus(
    lane_votes: list[dict[str, object]],
    recommended: dict[str, object] | None,
) -> dict[str, object]:
    decided = [
        item
        for item in lane_votes
        if item.get("status") == "decided" and item.get("vote_variant_id")
    ]
    variant_counts: dict[str, int] = {}
    variant_lanes: dict[str, list[str]] = {}
    for item in decided:
        variant = str(item["vote_variant_id"])
        lane_id = str(item.get("lane_id") or "")
        variant_counts[variant] = variant_counts.get(variant, 0) + 1
        variant_lanes.setdefault(variant, []).append(lane_id)
    leading_variant = None
    leading_count = 0
    if variant_counts:
        leading_variant, leading_count = sorted(
            variant_counts.items(),
            key=lambda item: (-item[1], item[0]),
        )[0]
    tied_variants = sorted(
        variant
        for variant, count in variant_counts.items()
        if count == leading_count and leading_count > 0
    )
    recommended_variant = str(recommended["variant_id"]) if recommended else None
    recommended_count = variant_counts.get(recommended_variant, 0) if recommended_variant else 0
    agreement_ratio = leading_count / len(decided) if decided else 0.0
    recommended_agreement_ratio = recommended_count / len(decided) if decided else 0.0
    return {
        "leading_variant_id": leading_variant,
        "recommended_variant_id": recommended_variant,
        "decided_lanes": len(decided),
        "leading_lanes": leading_count,
        "agreement_ratio": round(agreement_ratio, 6),
        "recommended_agreement_ratio": round(recommended_agreement_ratio, 6),
        "variant_counts": variant_counts,
        "variant_lanes": variant_lanes,
        "minority_variant_ids": [
            variant for variant in sorted(variant_counts) if variant != leading_variant
        ],
        "tied_variant_ids": tied_variants if len(tied_variants) > 1 else [],
        "split_brain": len(tied_variants) > 1 or (bool(decided) and agreement_ratio < 1.0),
    }


def _quorum_findings(
    *,
    completed_ratio: float,
    min_completed_ratio: float,
    consensus: Mapping[str, object],
    min_agreement_ratio: float,
) -> list[dict[str, str]]:
    findings: list[dict[str, str]] = []
    if int(consensus.get("decided_lanes") or 0) == 0:
        findings.append(_gate_finding("fail", "no-lane-votes", "no lane has a metric-backed vote"))
    if completed_ratio < min_completed_ratio:
        findings.append(
            _gate_finding(
                "fail",
                "completion-ratio",
                f"completed ratio {completed_ratio:.6g} is below required {min_completed_ratio:.6g}",
            )
        )
    agreement = float(consensus.get("agreement_ratio") or 0.0)
    if agreement < min_agreement_ratio:
        findings.append(
            _gate_finding(
                "fail",
                "agreement-ratio",
                f"leading lane agreement {agreement:.6g} is below required {min_agreement_ratio:.6g}",
            )
        )
    if consensus.get("tied_variant_ids"):
        findings.append(_gate_finding("fail", "split-brain-tie", "multiple variants are tied for lane votes"))
    elif consensus.get("split_brain"):
        findings.append(_gate_finding("warn", "minority-votes", "one or more lanes voted for a minority variant"))
    if not findings:
        findings.append(_gate_finding("pass", "quorum-passed", "lane quorum is strong enough for this policy"))
    return findings


def _quorum_status(
    passed: bool,
    completed_ratio: float,
    min_completed_ratio: float,
    consensus: Mapping[str, object],
) -> str:
    if passed:
        return "pass"
    if int(consensus.get("decided_lanes") or 0) == 0:
        return "no-votes"
    if completed_ratio < min_completed_ratio:
        return "incomplete"
    if consensus.get("tied_variant_ids"):
        return "split-brain"
    return "needs-review"


def _quorum_recommendations(
    quorum_status: str,
    consensus: Mapping[str, object],
) -> list[str]:
    if quorum_status == "pass":
        return ["Use agent-adjudicate and agent-gate to turn quorum evidence into a decision ledger."]
    recommendations: list[str] = []
    if quorum_status in {"no-votes", "incomplete"}:
        recommendations.append("Complete more lane work and log metadata-only outcomes before merging.")
    if quorum_status == "split-brain":
        recommendations.append("Run another replica or add a reviewer lane before accepting a tied variant decision.")
    if consensus.get("minority_variant_ids"):
        recommendations.append("Inspect minority lane votes before promotion; they may indicate role-specific model strength.")
    return recommendations or ["Review lane votes before accepting the parallel plan."]


def _variant_from_value(value: object) -> ModelVariant:
    if isinstance(value, str):
        return ModelVariant.from_mapping({"provider": "custom", "model": value, "id": value})
    if not isinstance(value, Mapping):
        raise ValueError("each agent experiment variant must be an object or string")
    return ModelVariant.from_mapping(value)


def _spec_from_run(run: Mapping[str, object]) -> ExperimentSpec:
    experiment = _run_experiment(run)
    variants = run.get("variants")
    if not isinstance(variants, list) or not variants:
        raise ValueError("agent run record is missing variants")
    config = {
        "experiment": experiment["name"],
        "description": experiment.get("description", ""),
        "primary_metric": experiment.get("primary_metric"),
        "rubric": experiment.get("rubric"),
        "traffic_salt": experiment.get("traffic_salt") or DEFAULT_TRAFFIC_SALT,
        "guardrails": experiment.get("guardrails") or [],
        "min_trials_per_variant": experiment.get(
            "min_trials_per_variant",
            DEFAULT_MIN_TRIALS_PER_VARIANT,
        ),
        "variants": variants,
    }
    return ExperimentSpec.from_mapping(config)


def _load_run_record(vault: Path, run_id: str) -> tuple[Path, dict[str, object]]:
    root = safe_child(vault, "agent-runs")
    if not root.exists():
        raise FileNotFoundError("No agent runs have been recorded")
    matches = sorted(root.glob(f"*/runs/{run_id}.json"))
    if not matches:
        raise FileNotFoundError(f"Agent run not found: {run_id}")
    if len(matches) > 1:
        raise ValueError(f"Agent run id is ambiguous: {run_id}")
    return matches[0], _read_json_object(matches[0])


def _load_run_records(root: Path) -> list[dict[str, object]]:
    runs_dir = root / "runs"
    if not runs_dir.is_dir():
        return []
    records = []
    for path in sorted(runs_dir.glob("*.json")):
        record = _read_json_object(path)
        if record.get("schema") == AGENT_RUN_SCHEMA:
            records.append(record)
    return records


def _load_outcome_records(root: Path) -> list[dict[str, object]]:
    return _load_schema_records(root, "outcomes", AGENT_OUTCOME_SCHEMA)


def _load_schema_records(root: Path, directory: str, schema: str) -> list[dict[str, object]]:
    record_dir = root / directory
    if not record_dir.is_dir():
        return []
    records = []
    for path in sorted(record_dir.glob("*.json")):
        record = _read_json_object(path)
        if record.get("schema") == schema:
            records.append(record)
    return records


def _load_agent_snapshot(root: Path, snapshot_id: str) -> dict[str, object]:
    safe_snapshot = _safe_run_id(snapshot_id)
    path = safe_child(root, "snapshots", f"{safe_snapshot}.json")
    if not path.exists():
        raise FileNotFoundError(f"Agent snapshot not found: {safe_snapshot}")
    record = _read_json_object(path)
    if record.get("schema") != AGENT_SNAPSHOT_SCHEMA:
        raise ValueError(f"Agent snapshot has unsupported schema: {safe_snapshot}")
    return record


def _latest_agent_snapshot(root: Path) -> dict[str, object] | None:
    snapshot_dir = root / "snapshots"
    if not snapshot_dir.is_dir():
        return None
    snapshots: list[tuple[int, str, str, dict[str, object]]] = []
    for path in sorted(snapshot_dir.glob("*.json")):
        record = _read_json_object(path)
        if record.get("schema") != AGENT_SNAPSHOT_SCHEMA:
            continue
        snapshots.append(
            (
                path.stat().st_mtime_ns,
                str(record.get("generated_at") or ""),
                str(record.get("snapshot_id") or path.stem),
                record,
            )
        )
    if not snapshots:
        return None
    return max(snapshots, key=lambda item: item[:3])[3]


def _experiment_snapshot_state(vault: Path, root: Path) -> dict[str, object]:
    artifact_records: dict[str, list[dict[str, object]]] = {}
    artifact_counts: dict[str, int] = {}
    records_by_type: dict[str, list[dict[str, object]]] = {}
    for artifact_type, directory, schema in _snapshot_artifact_specs():
        records = _load_schema_records(root, directory, schema)
        records_by_type[artifact_type] = records
        artifact_counts[artifact_type] = len(records)
        artifact_records[artifact_type] = [
            _snapshot_record_ref(record)
            for record in records
        ]
    reports = _snapshot_report_state(vault, root.name)
    return {
        "experiment": _snapshot_experiment_config(root, records_by_type),
        "artifact_counts": artifact_counts,
        "artifacts": artifact_records,
        "reports": reports,
        "outcomes": _snapshot_outcome_summary(records_by_type.get("outcomes", [])),
        "variants": _snapshot_variant_distribution(
            records_by_type.get("runs", []),
            records_by_type.get("outcomes", []),
        ),
        "plans": _snapshot_plan_summary(records_by_type.get("plans", [])),
        "controls": _snapshot_control_summary(records_by_type, reports),
        "snapshot_count": len(_load_schema_records(root, "snapshots", AGENT_SNAPSHOT_SCHEMA)),
    }


