def _snapshot_report_state(vault: Path, experiment_slug: str) -> dict[str, list[dict[str, object]]]:
    report_root = safe_child(vault, "agent-runs")
    reports: dict[str, list[dict[str, object]]] = {}
    for report_type, schema in _snapshot_report_specs():
        records = [
            record
            for record in _load_schema_records(report_root, "_reports", schema)
            if _agent_report_matches_manifest_scope(record, experiment_slug)
        ]
        reports[report_type] = [_snapshot_record_ref(record) for record in records]
    return reports


def _snapshot_record_ref(record: Mapping[str, object]) -> dict[str, object]:
    ref: dict[str, object] = {
        "content_sha256": _hash_json(record),
    }
    artifact_id = _agent_artifact_id(record)
    if artifact_id:
        ref["artifact_id"] = artifact_id
    timestamp = _snapshot_record_timestamp(record)
    if timestamp:
        ref["generated_at"] = timestamp
    status = _snapshot_record_status(record)
    if status:
        ref["status"] = status
    for key in (
        "run_id",
        "plan_id",
        "suite_id",
        "arena_id",
        "panel_id",
        "pipeline_id",
        "schedule_id",
        "variant_id",
        "winner_variant_id",
        "candidate_variant_id",
        "baseline_variant_id",
    ):
        value = record.get(key)
        if isinstance(value, str) and value:
            ref[key] = value
    return ref


def _snapshot_record_timestamp(record: Mapping[str, object]) -> str | None:
    for key in ("generated_at", "logged_at", "created_at"):
        value = record.get(key)
        if isinstance(value, str) and value:
            return value
    claim = record.get("claim")
    if isinstance(claim, Mapping):
        claimed_at = claim.get("claimed_at")
        if isinstance(claimed_at, str) and claimed_at:
            return claimed_at
    heartbeat = record.get("heartbeat")
    if isinstance(heartbeat, Mapping):
        heartbeat_at = heartbeat.get("heartbeat_at")
        if isinstance(heartbeat_at, str) and heartbeat_at:
            return heartbeat_at
    return None


def _snapshot_record_status(record: Mapping[str, object]) -> str | None:
    for key in (
        "snapshot_status",
        "status",
        "merge_status",
        "gate_status",
        "decision_status",
        "quorum_status",
        "promotion_status",
        "readiness_status",
        "rollout_status",
        "evolve_status",
        "power_status",
        "schedule_status",
        "report_status",
        "leaderboard_status",
        "config_status",
        "drift_status",
        "balance_status",
        "capacity_status",
        "slo_status",
        "budget_status",
        "preflight_status",
        "circuit_status",
        "hold_status",
        "quarantine_status",
        "dispatch_status",
        "orchestration_status",
        "recovery_status",
        "cycle_status",
        "loop_status",
        "panel_status",
        "arena_status",
        "pipeline_status",
        "advance_status",
        "ingest_status",
        "decision",
        "action",
    ):
        value = record.get(key)
        if isinstance(value, str) and value:
            return value
    return None


def _snapshot_experiment_config(
    root: Path,
    records_by_type: Mapping[str, list[dict[str, object]]],
) -> dict[str, object]:
    records = [
        record
        for artifact_type in (
            "runs",
            "plans",
            "suites",
            "arenas",
            "judge_panels",
            "pipelines",
            "schedules",
            "leaderboards",
            "config_proposals",
        )
        for record in records_by_type.get(artifact_type, [])
    ]
    config_hashes = sorted(
        {
            str(experiment.get("config_hash"))
            for record in records
            for experiment in [record.get("experiment") if isinstance(record.get("experiment"), Mapping) else {}]
            if isinstance(experiment.get("config_hash"), str)
        }
    )
    if not records:
        return {
            "slug": root.name,
            "config_status": "missing",
            "config_hashes": config_hashes,
        }
    latest = max(
        records,
        key=lambda item: (
            str(_snapshot_record_timestamp(item) or ""),
            str(_agent_artifact_id(item) or ""),
        ),
    )
    experiment = latest.get("experiment") if isinstance(latest.get("experiment"), Mapping) else {}
    variants = latest.get("variants") if isinstance(latest.get("variants"), list) else []
    primary_metric = experiment.get("primary_metric") if isinstance(experiment.get("primary_metric"), Mapping) else {}
    rubric = experiment.get("rubric") if isinstance(experiment.get("rubric"), Mapping) else {}
    guardrails = experiment.get("guardrails") if isinstance(experiment.get("guardrails"), list) else []
    traffic_salt = str(experiment.get("traffic_salt") or "")
    return {
        "slug": str(experiment.get("slug") or root.name),
        "name_sha256": _hash_text(str(experiment.get("name") or root.name)),
        "description_sha256": _hash_text(str(experiment.get("description") or "")),
        "latest_config_hash": experiment.get("config_hash"),
        "config_hashes": config_hashes,
        "primary_metric": dict(primary_metric),
        "rubric_sha256": _hash_json(rubric),
        "rubric_criteria": len(rubric.get("criteria") if isinstance(rubric.get("criteria"), list) else []),
        "traffic_salt_sha256": _hash_text(traffic_salt),
        "guardrail_count": len(guardrails),
        "guardrails_sha256": _hash_json(guardrails),
        "min_trials_per_variant": experiment.get("min_trials_per_variant"),
        "variants": [
            _snapshot_variant_config(item)
            for item in variants
            if isinstance(item, Mapping)
        ],
        "source_artifact_id": _agent_artifact_id(latest),
        "source_generated_at": _snapshot_record_timestamp(latest),
    }


def _snapshot_variant_config(variant: Mapping[str, object]) -> dict[str, object]:
    settings = variant.get("settings") if isinstance(variant.get("settings"), Mapping) else {}
    payload: dict[str, object] = {
        "id": variant.get("id"),
        "provider": variant.get("provider"),
        "model": variant.get("model"),
        "weight": variant.get("weight"),
        "settings_sha256": _hash_json(settings),
    }
    adapter = variant.get("adapter")
    if isinstance(adapter, str) and adapter:
        payload["adapter"] = adapter
    return payload


def _snapshot_outcome_summary(outcomes: list[dict[str, object]]) -> dict[str, object]:
    statuses: dict[str, int] = {}
    metric_names: set[str] = set()
    failure_codes: dict[str, int] = {}
    for outcome in outcomes:
        status = str(outcome.get("status") or "unknown")
        statuses[status] = statuses.get(status, 0) + 1
        metrics = outcome.get("metrics") if isinstance(outcome.get("metrics"), Mapping) else {}
        metric_names.update(str(key) for key in metrics.keys())
        failure_code = outcome.get("failure_code")
        if isinstance(failure_code, str) and failure_code:
            failure_codes[failure_code] = failure_codes.get(failure_code, 0) + 1
    return {
        "count": len(outcomes),
        "statuses": dict(sorted(statuses.items())),
        "metric_names": sorted(metric_names),
        "failure_codes": dict(sorted(failure_codes.items())),
    }


def _snapshot_variant_distribution(
    runs: list[dict[str, object]],
    outcomes: list[dict[str, object]],
) -> dict[str, object]:
    scheduled: dict[str, int] = {}
    completed: dict[str, int] = {}
    failed: dict[str, int] = {}
    for run in runs:
        selected = run.get("selected_variant") if isinstance(run.get("selected_variant"), Mapping) else {}
        variant_id = selected.get("id")
        if isinstance(variant_id, str) and variant_id:
            scheduled[variant_id] = scheduled.get(variant_id, 0) + 1
    for outcome in outcomes:
        variant = outcome.get("variant") if isinstance(outcome.get("variant"), Mapping) else {}
        variant_id = variant.get("id")
        if not isinstance(variant_id, str) or not variant_id:
            continue
        completed[variant_id] = completed.get(variant_id, 0) + 1
        if outcome.get("status") == "failed":
            failed[variant_id] = failed.get(variant_id, 0) + 1
    return {
        "scheduled": dict(sorted(scheduled.items())),
        "completed": dict(sorted(completed.items())),
        "failed": dict(sorted(failed.items())),
    }


def _snapshot_plan_summary(plans: list[dict[str, object]]) -> dict[str, object]:
    lanes: set[str] = set()
    merge_strategies: dict[str, int] = {}
    total_runs = 0
    for plan in plans:
        parallel = plan.get("parallel") if isinstance(plan.get("parallel"), Mapping) else {}
        total_runs += int(parallel.get("run_count") or 0)
        strategy = str(parallel.get("merge_strategy") or "unknown")
        merge_strategies[strategy] = merge_strategies.get(strategy, 0) + 1
        raw_lanes = parallel.get("lanes") if isinstance(parallel.get("lanes"), list) else []
        for lane in raw_lanes:
            if not isinstance(lane, Mapping):
                continue
            lane_id = lane.get("id")
            if isinstance(lane_id, str) and lane_id:
                lanes.add(lane_id)
    return {
        "count": len(plans),
        "scheduled_runs": total_runs,
        "lane_ids": sorted(lanes),
        "merge_strategies": dict(sorted(merge_strategies.items())),
    }


def _snapshot_control_summary(
    records_by_type: Mapping[str, list[dict[str, object]]],
    reports: Mapping[str, list[dict[str, object]]],
) -> dict[str, object]:
    controls: dict[str, object] = {}
    for artifact_type in (
        "gates",
        "quorums",
        "adjudications",
        "promotions",
        "comparisons",
        "decisions",
        "drift",
        "balances",
        "allocations",
        "routes",
        "readiness",
        "rollouts",
        "rollout_checks",
        "evolutions",
        "circuits",
        "leaderboards",
        "config_proposals",
    ):
        latest = _snapshot_latest_ref(records_by_type.get(artifact_type, []))
        if latest:
            controls[artifact_type] = latest
    for report_type in ("budgets", "capacity", "slo", "watchdogs", "preflights", "manifests"):
        latest_report = _snapshot_latest_ref(reports.get(report_type, []))
        if latest_report:
            controls[f"reports.{report_type}"] = latest_report
    return controls


def _snapshot_latest_ref(records: list[dict[str, object]]) -> dict[str, object] | None:
    if not records:
        return None
    return max(
        records,
        key=lambda item: (
            str(item.get("generated_at") or ""),
            str(item.get("artifact_id") or ""),
        ),
    )


def _snapshot_section_hashes(state: Mapping[str, object] | None) -> dict[str, str]:
    if not isinstance(state, Mapping):
        return {}
    section_hashes: dict[str, str] = {}
    for key in ("experiment", "artifact_counts", "outcomes", "variants", "plans", "controls"):
        section_hashes[key] = _hash_json(state.get(key))
    artifacts = state.get("artifacts") if isinstance(state.get("artifacts"), Mapping) else {}
    for artifact_type, records in sorted(artifacts.items()):
        section_hashes[f"artifacts.{artifact_type}"] = _hash_json(records)
    reports = state.get("reports") if isinstance(state.get("reports"), Mapping) else {}
    for report_type, records in sorted(reports.items()):
        section_hashes[f"reports.{report_type}"] = _hash_json(records)
    return section_hashes


def _snapshot_changes(
    current_hashes: Mapping[str, object],
    baseline_hashes: Mapping[str, object],
) -> list[dict[str, object]]:
    changes: list[dict[str, object]] = []
    for section in sorted(set(current_hashes.keys()) | set(baseline_hashes.keys())):
        current = current_hashes.get(section)
        baseline = baseline_hashes.get(section)
        if current == baseline:
            continue
        if baseline is None:
            change_type = "added"
        elif current is None:
            change_type = "removed"
        else:
            change_type = "changed"
        changes.append(
            {
                "section": section,
                "change_type": change_type,
                "baseline_sha256": baseline,
                "current_sha256": current,
            }
        )
    return changes


def _snapshot_summary(
    state: Mapping[str, object],
    changes: list[dict[str, object]],
    baseline_record: Mapping[str, object] | None,
) -> dict[str, object]:
    artifacts = state.get("artifacts") if isinstance(state.get("artifacts"), Mapping) else {}
    reports = state.get("reports") if isinstance(state.get("reports"), Mapping) else {}
    artifact_records = sum(len(value) for value in artifacts.values() if isinstance(value, list))
    report_records = sum(len(value) for value in reports.values() if isinstance(value, list))
    return {
        "artifact_records": artifact_records,
        "report_records": report_records,
        "snapshots": int(state.get("snapshot_count") or 0),
        "changed_sections": len(changes),
        "baseline_snapshot_id": (
            baseline_record.get("snapshot_id")
            if isinstance(baseline_record, Mapping)
            else None
        ),
        "changed_section_names": [
            str(item.get("section"))
            for item in changes
            if isinstance(item.get("section"), str)
        ],
    }


def _agent_manifest_files(
    vault: Path,
    *,
    experiment: str | None,
    include_reports: bool,
) -> list[Path]:
    roots = _experiment_roots(vault, experiment=experiment)
    paths: list[Path] = []
    for root in roots:
        paths.extend(_agent_artifact_files(root))
    if include_reports:
        paths.extend(
            _agent_report_artifact_files(
                vault,
                experiment=slugify(experiment, fallback="all") if experiment else None,
            )
        )
    unique = {_relative_vault_path(vault, path): path for path in paths}
    return [unique[key] for key in sorted(unique)]


def _agent_artifact_files(root: Path) -> list[Path]:
    if not root.is_dir() or root.is_symlink():
        return []
    paths: list[Path] = []
    for path in root.rglob("*"):
        if not path.is_file() or path.is_symlink():
            continue
        if path.suffix not in {".json", ".md", ".html"}:
            continue
        if _agent_manifest_skip_path(path):
            continue
        paths.append(path)
    return sorted(paths)


def _agent_report_artifact_files(vault: Path, *, experiment: str | None) -> list[Path]:
    report_root = safe_child(vault, "agent-runs", "_reports")
    if not report_root.is_dir() or report_root.is_symlink():
        return []
    paths: list[Path] = []
    included_stems: set[str] = set()
    for path in sorted(report_root.glob("*.json")):
        if not path.is_file() or path.is_symlink() or _agent_manifest_skip_path(path):
            continue
        if experiment is not None:
            try:
                record = _read_json_object(path)
            except (OSError, ValueError, json.JSONDecodeError):
                continue
            if not _agent_report_matches_manifest_scope(record, experiment):
                continue
        paths.append(path)
        included_stems.add(path.stem)
    for path in sorted(report_root.glob("*.md")):
        if not path.is_file() or path.is_symlink() or _agent_manifest_skip_path(path):
            continue
        if experiment is None or path.stem in included_stems:
            paths.append(path)
    return sorted(paths)


def _agent_report_matches_manifest_scope(record: Mapping[str, object], experiment: str) -> bool:
    raw_scope = record.get("scope")
    if isinstance(raw_scope, str):
        return raw_scope in {"all", experiment}
    if isinstance(raw_scope, Mapping):
        scope_experiment = raw_scope.get("experiment")
        if scope_experiment in {"all", experiment}:
            return True
        experiments = raw_scope.get("experiments")
        if isinstance(experiments, list) and experiment in {str(item) for item in experiments}:
            return True
    raw_experiment = record.get("experiment")
    if isinstance(raw_experiment, str):
        return raw_experiment == experiment
    if isinstance(raw_experiment, Mapping):
        return raw_experiment.get("slug") == experiment or raw_experiment.get("name") == experiment
    return False


def _agent_manifest_skip_path(path: Path) -> bool:
    return path.name.startswith(("agent-manifest-", "agent-manifest-verification-"))


def _agent_manifest_artifact(vault: Path, path: Path) -> dict[str, object]:
    relative = _relative_vault_path(vault, path)
    stat = path.stat()
    artifact: dict[str, object] = {
        "path": relative,
        "artifact_type": _agent_artifact_type(relative),
        "suffix": path.suffix,
        "bytes": stat.st_size,
        "sha256": _sha256_file(path),
    }
    if path.suffix == ".json":
        try:
            parsed = _read_json_object(path)
        except (OSError, ValueError, json.JSONDecodeError):
            parsed = {}
        schema = parsed.get("schema")
        if isinstance(schema, str):
            artifact["schema"] = schema
        generated_at = parsed.get("generated_at")
        if isinstance(generated_at, str):
            artifact["generated_at"] = generated_at
        artifact_id = _agent_artifact_id(parsed)
        if artifact_id:
            artifact["artifact_id"] = artifact_id
    return artifact


def _agent_artifact_type(relative_path: str) -> str:
    parts = PurePath(relative_path).parts
    if len(parts) >= 3 and parts[0] == "agent-runs":
        if parts[1] == "_reports":
            return "report"
        return parts[2]
    return "artifact"


def _agent_artifact_id(record: Mapping[str, object]) -> str | None:
    for key in (
        "run_id",
        "plan_id",
        "suite_id",
        "report_id",
        "arena_id",
        "panel_id",
        "pipeline_id",
        "advance_id",
        "outcome_id",
        "claim_id",
        "dispatch_id",
        "hold_id",
        "heartbeat_id",
        "retry_id",
        "packet_id",
        "merge_id",
        "gate_id",
        "quorum_id",
        "adjudication_id",
        "promotion_id",
        "loop_id",
        "memory_id",
        "curriculum_id",
        "allocation_id",
        "route_id",
        "readiness_id",
        "rollout_id",
        "check_id",
        "evolve_id",
        "power_id",
        "schedule_id",
        "leaderboard_id",
        "config_id",
        "comparison_id",
        "decision_id",
        "drift_id",
        "balance_id",
        "audit_id",
        "preflight_id",
        "timeline_id",
        "watchdog_id",
        "capacity_id",
        "slo_id",
        "mix_id",
        "snapshot_id",
        "budget_id",
        "dashboard_id",
        "orchestration_id",
        "recovery_id",
        "cycle_id",
    ):
        value = record.get(key)
        if isinstance(value, str) and value:
            return value
    return None


def _load_agent_manifest(
    vault: Path,
    *,
    manifest_id: str | None,
) -> tuple[Path, dict[str, object]]:
    report_root = safe_child(vault, "agent-runs", "_reports")
    if manifest_id:
        safe_manifest = _safe_run_id(manifest_id)
        path = safe_child(report_root, f"{safe_manifest}.json")
        if not path.exists():
            raise FileNotFoundError(f"Agent manifest not found: {safe_manifest}")
        record = _read_json_object(path)
        if record.get("schema") != AGENT_MANIFEST_SCHEMA:
            raise ValueError(f"Agent manifest has unsupported schema: {safe_manifest}")
        return path, record
    manifests = _load_schema_records(safe_child(vault, "agent-runs"), "_reports", AGENT_MANIFEST_SCHEMA)
    if not manifests:
        raise FileNotFoundError("No agent manifests have been recorded")
    latest = max(manifests, key=lambda item: str(item.get("generated_at") or ""))
    latest_id = str(latest.get("manifest_id") or "")
    if not latest_id:
        raise ValueError("Latest agent manifest is missing manifest_id")
    path = safe_child(report_root, f"{_safe_run_id(latest_id)}.json")
    return path, latest


def _agent_manifest_target(vault: Path, relative_path: str) -> Path:
    if "\\" in relative_path:
        raise ValueError("agent manifest paths must use forward slashes")
    pure = PurePath(relative_path)
    if pure.is_absolute() or not pure.parts or any(part == ".." for part in pure.parts):
        raise ValueError("agent manifest contains unsafe artifact path")
    return safe_child(vault, *pure.parts)


def _manifest_finding(
    severity: str,
    code: str,
    path: str,
    message: str,
) -> dict[str, object]:
    return {
        "severity": severity,
        "code": code,
        "path": _safe_text_label(path, field="manifest path", max_length=500),
        "message": message,
    }


def _sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


