def _provider_mix_summary(
    spec: ExperimentSpec,
    runs: list[dict[str, object]],
    outcomes: list[dict[str, object]],
) -> list[dict[str, object]]:
    providers: dict[str, dict[str, object]] = {}
    total_weight = sum(variant.weight for variant in spec.variants)
    for variant in spec.variants:
        provider = variant.provider
        entry = providers.setdefault(provider, _empty_provider_mix(provider))
        entry["configured_variants"] = int(entry["configured_variants"]) + 1
        entry["configured_weight"] = round(float(entry["configured_weight"]) + variant.weight, 6)
        _mix_set_add(entry, "variant_ids", variant.id)
        _mix_set_add(entry, "models", variant.model)
        if variant.adapter:
            _mix_set_add(entry, "adapters", variant.adapter)
    for run in runs:
        selected = run.get("selected_variant") if isinstance(run.get("selected_variant"), Mapping) else {}
        provider = _safe_provider(str(selected.get("provider") or "custom"))
        entry = providers.setdefault(provider, _empty_provider_mix(provider))
        entry["scheduled_runs"] = int(entry["scheduled_runs"]) + 1
        variant_id = selected.get("id")
        if isinstance(variant_id, str) and variant_id:
            _mix_set_add(entry, "scheduled_variant_ids", variant_id)
        model = selected.get("model")
        if isinstance(model, str) and model:
            _mix_set_add(entry, "models", model)
        adapter = selected.get("adapter")
        if isinstance(adapter, str) and adapter:
            _mix_set_add(entry, "adapters", adapter)
    for outcome in outcomes:
        variant = outcome.get("variant") if isinstance(outcome.get("variant"), Mapping) else {}
        provider = _safe_provider(str(variant.get("provider") or "custom"))
        entry = providers.setdefault(provider, _empty_provider_mix(provider))
        entry["completed_outcomes"] = int(entry["completed_outcomes"]) + 1
        if outcome.get("status") == "failed":
            entry["failed_outcomes"] = int(entry["failed_outcomes"]) + 1
        variant_id = variant.get("id")
        if isinstance(variant_id, str) and variant_id:
            _mix_set_add(entry, "completed_variant_ids", variant_id)
        model = variant.get("model")
        if isinstance(model, str) and model:
            _mix_set_add(entry, "models", model)
    scheduled_total = sum(int(item["scheduled_runs"]) for item in providers.values())
    completed_total = sum(int(item["completed_outcomes"]) for item in providers.values())
    rows: list[dict[str, object]] = []
    for provider, entry in providers.items():
        configured_weight = float(entry["configured_weight"])
        scheduled_runs = int(entry["scheduled_runs"])
        completed_outcomes = int(entry["completed_outcomes"])
        row = {
            "provider": provider,
            "local": provider in LOCAL_AGENT_PROVIDERS,
            "configured_variants": int(entry["configured_variants"]),
            "configured_weight": round(configured_weight, 6),
            "configured_weight_share": (
                round(configured_weight / total_weight, 6)
                if total_weight > 0
                else None
            ),
            "scheduled_runs": scheduled_runs,
            "scheduled_share": (
                round(scheduled_runs / scheduled_total, 6)
                if scheduled_total
                else None
            ),
            "completed_outcomes": completed_outcomes,
            "completed_share": (
                round(completed_outcomes / completed_total, 6)
                if completed_total
                else None
            ),
            "failed_outcomes": int(entry["failed_outcomes"]),
            "variant_ids": sorted(entry["variant_ids"]),
            "scheduled_variant_ids": sorted(entry["scheduled_variant_ids"]),
            "completed_variant_ids": sorted(entry["completed_variant_ids"]),
            "models": sorted(entry["models"]),
            "adapters": sorted(entry["adapters"]),
        }
        rows.append(row)
    rows.sort(key=lambda item: (-float(item.get("configured_weight_share") or 0.0), str(item["provider"])))
    return rows


def _empty_provider_mix(provider: str) -> dict[str, object]:
    return {
        "provider": provider,
        "configured_variants": 0,
        "configured_weight": 0.0,
        "scheduled_runs": 0,
        "completed_outcomes": 0,
        "failed_outcomes": 0,
        "variant_ids": set(),
        "scheduled_variant_ids": set(),
        "completed_variant_ids": set(),
        "models": set(),
        "adapters": set(),
    }


def _mix_set_add(entry: dict[str, object], key: str, value: str) -> None:
    values = entry.get(key)
    if isinstance(values, set) and value:
        values.add(value)


def _lane_provider_mix(
    runs: list[dict[str, object]],
    outcomes: list[dict[str, object]],
) -> list[dict[str, object]]:
    outcomes_by_run = _latest_outcomes_by_run(outcomes)
    lane_entries: dict[str, dict[str, dict[str, int]]] = {}
    for run in runs:
        run_id = run.get("run_id")
        parallel = run.get("parallel") if isinstance(run.get("parallel"), Mapping) else {}
        lane_id = str(parallel.get("lane_id") or "single")
        selected = run.get("selected_variant") if isinstance(run.get("selected_variant"), Mapping) else {}
        provider = _safe_provider(str(selected.get("provider") or "custom"))
        lane = lane_entries.setdefault(lane_id, {})
        provider_counts = lane.setdefault(provider, {"scheduled_runs": 0, "completed_outcomes": 0})
        provider_counts["scheduled_runs"] += 1
        if isinstance(run_id, str) and run_id in outcomes_by_run:
            provider_counts["completed_outcomes"] += 1
    rows: list[dict[str, object]] = []
    for lane_id, providers in sorted(lane_entries.items()):
        scheduled = sum(item["scheduled_runs"] for item in providers.values())
        completed = sum(item["completed_outcomes"] for item in providers.values())
        rows.append(
            {
                "lane_id": lane_id,
                "provider_count": len(providers),
                "scheduled_runs": scheduled,
                "completed_outcomes": completed,
                "providers": [
                    {
                        "provider": provider,
                        "scheduled_runs": counts["scheduled_runs"],
                        "completed_outcomes": counts["completed_outcomes"],
                    }
                    for provider, counts in sorted(providers.items())
                ],
            }
        )
    return rows


def _mix_findings(
    experiment: str,
    providers: list[dict[str, object]],
    *,
    policy: Mapping[str, object],
) -> list[dict[str, object]]:
    findings: list[dict[str, object]] = []
    configured_providers = [item for item in providers if int(item.get("configured_variants") or 0) > 0]
    configured_variants = sum(int(item.get("configured_variants") or 0) for item in configured_providers)
    local_providers = [item for item in configured_providers if item.get("local") is True]
    if len(configured_providers) < int(policy["min_provider_count"]):
        findings.append(
            _mix_finding(
                "fail",
                "provider-count",
                experiment,
                f"Experiment config has {len(configured_providers)} provider(s).",
                actual=len(configured_providers),
                limit=int(policy["min_provider_count"]),
            )
        )
    if configured_variants < int(policy["min_variant_count"]):
        findings.append(
            _mix_finding(
                "fail",
                "variant-count",
                experiment,
                f"Experiment config has {configured_variants} variant(s).",
                actual=configured_variants,
                limit=int(policy["min_variant_count"]),
            )
        )
    max_weight = max((float(item.get("configured_weight_share") or 0.0) for item in configured_providers), default=0.0)
    if max_weight > float(policy["max_provider_weight_share"]):
        findings.append(
            _mix_finding(
                "fail",
                "provider-weight-concentration",
                experiment,
                "Configured traffic weight is too concentrated in one provider.",
                actual=max_weight,
                limit=float(policy["max_provider_weight_share"]),
            )
        )
    scheduled_providers = [item for item in providers if int(item.get("scheduled_runs") or 0) > 0]
    if not scheduled_providers:
        findings.append(_mix_finding("warn", "no-scheduled-runs", experiment, "No scheduled runs were found."))
    else:
        max_scheduled = max(float(item.get("scheduled_share") or 0.0) for item in scheduled_providers)
        if max_scheduled > float(policy["max_scheduled_provider_share"]):
            findings.append(
                _mix_finding(
                    "fail",
                    "scheduled-provider-concentration",
                    experiment,
                    "Scheduled runs are too concentrated in one provider.",
                    actual=max_scheduled,
                    limit=float(policy["max_scheduled_provider_share"]),
                )
            )
    completed_providers = [item for item in providers if int(item.get("completed_outcomes") or 0) > 0]
    if not completed_providers:
        findings.append(_mix_finding("warn", "no-completed-outcomes", experiment, "No completed outcomes were found."))
    else:
        max_completed = max(float(item.get("completed_share") or 0.0) for item in completed_providers)
        if max_completed > float(policy["max_completed_provider_share"]):
            findings.append(
                _mix_finding(
                    "fail",
                    "completed-provider-concentration",
                    experiment,
                    "Completed outcomes are too concentrated in one provider.",
                    actual=max_completed,
                    limit=float(policy["max_completed_provider_share"]),
                )
            )
    if bool(policy.get("require_local_provider")) and not local_providers:
        findings.append(
            _mix_finding(
                "fail",
                "local-provider-missing",
                experiment,
                "No configured provider is marked as local-first.",
            )
        )
    if not any(item.get("severity") == "fail" for item in findings):
        findings.append(
            _mix_finding(
                "pass",
                "mix-ready",
                experiment,
                "Provider and variant mix meets the configured diversity policy.",
            )
        )
    return findings


def _mix_summary(
    providers: list[dict[str, object]],
    lanes: list[dict[str, object]],
    findings: list[dict[str, object]],
) -> dict[str, object]:
    configured = [item for item in providers if int(item.get("configured_variants") or 0) > 0]
    scheduled = [item for item in providers if int(item.get("scheduled_runs") or 0) > 0]
    completed = [item for item in providers if int(item.get("completed_outcomes") or 0) > 0]
    adapters = {
        str(adapter)
        for item in providers
        for adapter in (item.get("adapters") if isinstance(item.get("adapters"), list) else [])
    }
    return {
        "provider_count": len(configured),
        "variant_count": sum(int(item.get("configured_variants") or 0) for item in configured),
        "adapter_count": len(adapters),
        "local_provider_count": sum(1 for item in configured if item.get("local") is True),
        "scheduled_provider_count": len(scheduled),
        "completed_provider_count": len(completed),
        "scheduled_runs": sum(int(item.get("scheduled_runs") or 0) for item in providers),
        "completed_outcomes": sum(int(item.get("completed_outcomes") or 0) for item in providers),
        "failed_outcomes": sum(int(item.get("failed_outcomes") or 0) for item in providers),
        "lane_count": len(lanes),
        "lanes_with_multiple_providers": sum(1 for item in lanes if int(item.get("provider_count") or 0) > 1),
        "max_provider_weight_share": max((float(item.get("configured_weight_share") or 0.0) for item in configured), default=0.0),
        "max_scheduled_provider_share": max((float(item.get("scheduled_share") or 0.0) for item in scheduled), default=0.0),
        "max_completed_provider_share": max((float(item.get("completed_share") or 0.0) for item in completed), default=0.0),
        "pass": sum(1 for item in findings if item.get("severity") == "pass"),
        "warn": sum(1 for item in findings if item.get("severity") == "warn"),
        "fail": sum(1 for item in findings if item.get("severity") == "fail"),
        "findings": len(findings),
    }


def _mix_recommendations(
    providers: list[dict[str, object]],
    lanes: list[dict[str, object]],
    findings: list[dict[str, object]],
    *,
    policy: Mapping[str, object],
) -> list[str]:
    codes = {str(item.get("code") or "") for item in findings}
    recommendations: list[str] = []
    if "provider-count" in codes or "variant-count" in codes:
        recommendations.append("Add at least one non-dominant provider variant before treating the experiment as cross-model.")
    if "provider-weight-concentration" in codes:
        recommendations.append("Lower the dominant provider weight or raise exploration weight for other providers.")
    if "scheduled-provider-concentration" in codes:
        recommendations.append("Run agent-matrix or agent-suite so scheduled work covers providers evenly.")
    if "completed-provider-concentration" in codes:
        recommendations.append("Complete outcomes for under-covered providers before trusting A/B or promotion evidence.")
    if "local-provider-missing" in codes:
        recommendations.append("Add an Ollama/local variant or drop --require-local-provider for cloud-only experiments.")
    if not lanes:
        recommendations.append("Create a parallel or matrix plan to evaluate provider coverage across agent lanes.")
    elif any(int(item.get("provider_count") or 0) < int(policy["min_provider_count"]) for item in lanes):
        recommendations.append("Use matrix plans for role-sensitive lanes so each lane sees more than one provider.")
    return recommendations or ["Provider mix is ready for cross-model comparison and promotion gates."]


def _mix_finding(
    severity: str,
    code: str,
    experiment: str,
    message: str,
    *,
    actual: float | int | None = None,
    limit: float | int | None = None,
) -> dict[str, object]:
    finding: dict[str, object] = {
        "severity": severity,
        "code": code,
        "experiment": experiment,
        "message": message,
    }
    if actual is not None:
        finding["actual"] = actual
    if limit is not None:
        finding["limit"] = limit
    return finding


def _orchestration_report_experiments(report: Mapping[str, object]) -> set[str]:
    scope = report.get("scope")
    if not isinstance(scope, Mapping):
        return set()
    experiments = scope.get("experiments")
    if not isinstance(experiments, list):
        return set()
    return {str(item) for item in experiments if isinstance(item, str) and item}


def _latest_schema_record(root: Path, directory: str, schema: str) -> dict[str, object] | None:
    records = _load_schema_records(root, directory, schema)
    return records[-1] if records else None


def _load_plan_record(vault: Path, plan_id: str) -> tuple[Path, dict[str, object]]:
    root = safe_child(vault, "agent-runs")
    if not root.exists():
        raise FileNotFoundError("No agent plans have been recorded")
    matches = sorted(root.glob(f"*/plans/{plan_id}.json"))
    if not matches:
        raise FileNotFoundError(f"Agent plan not found: {plan_id}")
    if len(matches) > 1:
        raise ValueError(f"Agent plan id is ambiguous: {plan_id}")
    return matches[0], _read_json_object(matches[0])


def _load_rollout_record(vault: Path, rollout_id: str) -> tuple[Path, dict[str, object]]:
    root = safe_child(vault, "agent-runs")
    if not root.exists():
        raise FileNotFoundError("No agent rollouts have been recorded")
    matches = sorted(root.glob(f"*/rollouts/{rollout_id}.json"))
    if not matches:
        raise FileNotFoundError(f"Agent rollout not found: {rollout_id}")
    if len(matches) > 1:
        raise ValueError(f"Agent rollout id is ambiguous: {rollout_id}")
    return matches[0], _read_json_object(matches[0])


def _load_suite_record(vault: Path, suite_id: str) -> tuple[Path, dict[str, object]]:
    suite = _safe_run_id(suite_id)
    root = safe_child(vault, "agent-runs")
    if not root.exists():
        raise FileNotFoundError("No agent suites have been recorded")
    matches = sorted(root.glob(f"*/suites/{suite}.json"))
    if not matches:
        raise FileNotFoundError(f"Agent suite not found: {suite}")
    if len(matches) > 1:
        raise ValueError(f"Agent suite id is ambiguous: {suite}")
    return matches[0], _read_json_object(matches[0])


def _load_curriculum_record(
    root: Path,
    *,
    curriculum_id: str | None,
) -> dict[str, object]:
    if curriculum_id:
        safe_id = _safe_run_id(curriculum_id)
        path = safe_child(root, "curricula", f"{safe_id}.json")
        if not path.exists():
            raise FileNotFoundError(f"Agent curriculum not found: {safe_id}")
        record = _read_json_object(path)
        if record.get("schema") != AGENT_CURRICULUM_SCHEMA:
            raise ValueError(f"Not an agent curriculum artifact: {safe_id}")
        return record
    record = _latest_schema_record(root, "curricula", AGENT_CURRICULUM_SCHEMA)
    if not record:
        raise FileNotFoundError(f"Agent experiment has no curriculum artifacts: {root.name}")
    return record


def _load_claim_record(vault: Path, claim_id: str) -> tuple[Path, dict[str, object]]:
    claim = _safe_run_id(claim_id)
    root = safe_child(vault, "agent-runs")
    if not root.exists():
        raise FileNotFoundError("No agent claims have been recorded")
    matches = sorted(root.glob(f"*/claims/{claim}.json"))
    if not matches:
        raise FileNotFoundError(f"Agent claim not found: {claim}")
    if len(matches) > 1:
        raise ValueError(f"Agent claim id is ambiguous: {claim}")
    return matches[0], _read_json_object(matches[0])


def _read_json_object(path: Path) -> dict[str, object]:
    parsed = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(parsed, dict):
        raise ValueError(f"Expected JSON object: {path.name}")
    return parsed


def _run_experiment(run: Mapping[str, object]) -> dict[str, object]:
    experiment = run.get("experiment")
    if not isinstance(experiment, dict):
        raise ValueError("agent run record is missing experiment metadata")
    slug = experiment.get("slug")
    name = experiment.get("name")
    if not isinstance(slug, str) or not slug:
        raise ValueError("agent run record is missing experiment slug")
    if not isinstance(name, str) or not name:
        raise ValueError("agent run record is missing experiment name")
    return experiment


def _run_selected_variant(run: Mapping[str, object]) -> dict[str, object]:
    selected = run.get("selected_variant")
    if not isinstance(selected, dict) or not isinstance(selected.get("id"), str):
        raise ValueError("agent run record is missing selected variant")
    return selected


def _plan_experiment(plan: Mapping[str, object]) -> dict[str, object]:
    experiment = plan.get("experiment")
    if not isinstance(experiment, dict):
        raise ValueError("agent plan record is missing experiment metadata")
    slug = experiment.get("slug")
    name = experiment.get("name")
    if not isinstance(slug, str) or not slug:
        raise ValueError("agent plan record is missing experiment slug")
    if not isinstance(name, str) or not name:
        raise ValueError("agent plan record is missing experiment name")
    return experiment


def _suite_experiment(suite: Mapping[str, object]) -> dict[str, object]:
    experiment = suite.get("experiment")
    if not isinstance(experiment, dict):
        raise ValueError("agent suite record is missing experiment metadata")
    slug = experiment.get("slug")
    name = experiment.get("name")
    if not isinstance(slug, str) or not slug:
        raise ValueError("agent suite record is missing experiment slug")
    if not isinstance(name, str) or not name:
        raise ValueError("agent suite record is missing experiment name")
    return experiment


def _spec_from_suite(suite: Mapping[str, object]) -> ExperimentSpec:
    experiment = _suite_experiment(suite)
    variants = suite.get("variants")
    if not isinstance(variants, list) or not variants:
        raise ValueError("agent suite record is missing variants")
    config = {
        "experiment": experiment["name"],
        "description": experiment.get("description", ""),
        "primary_metric": experiment.get("primary_metric"),
        "rubric": experiment.get("rubric"),
        "traffic_salt": experiment.get("traffic_salt") or DEFAULT_TRAFFIC_SALT,
        "guardrails": experiment.get("guardrails") or [],
        "min_trials_per_variant": experiment.get(
            "min_trials_per_variant",
            DEFAULT_MIN_TRIALS_PER_VARIANT,
        ),
        "variants": variants,
    }
    return ExperimentSpec.from_mapping(config)


def _plan_runs(plan: Mapping[str, object]) -> list[dict[str, object]]:
    raw_runs = plan.get("runs")
    if not isinstance(raw_runs, list):
        raise ValueError("agent plan record is missing runs")
    runs: list[dict[str, object]] = []
    for raw in raw_runs:
        if not isinstance(raw, dict):
            raise ValueError("agent plan run entry must be an object")
        run_id = str(raw.get("run_id") or "")
        _safe_run_id(run_id)
        lane_id = _safe_label(str(raw.get("lane_id") or "lane"))
        role = _safe_text_label(str(raw.get("role") or lane_id), field="lane role")
        variant_id = slugify(str(raw.get("variant_id") or "variant"), fallback="variant")
        replica = raw.get("replica", 1)
        runs.append(
            {
                "run_id": run_id,
                "lane_id": lane_id,
                "role": role,
                "variant_id": variant_id,
                "replica": _positive_int(replica, field="replica"),
            }
        )
    return runs


def _effective_plan_runs(root: Path, plan: Mapping[str, object]) -> list[dict[str, object]]:
    runs = _plan_runs(plan)
    by_run_id = {str(item["run_id"]): dict(item) for item in runs}
    order = [str(item["run_id"]) for item in runs]
    plan_id = str(plan.get("plan_id") or "")
    retries = _load_schema_records(root, "retries", AGENT_RETRY_SCHEMA)
    for retry in retries:
        if retry.get("plan_id") != plan_id:
            continue
        if retry.get("replacement_policy") != "supersede-original":
            continue
        original_run_id = retry.get("original_run_id")
        replacement = retry.get("replacement_run")
        if not isinstance(original_run_id, str) or not isinstance(replacement, dict):
            continue
        replacement_run = _retry_plan_run(replacement, fallback=by_run_id.get(original_run_id))
        if replacement_run is None:
            continue
        try:
            index = order.index(original_run_id)
        except ValueError:
            order.append(str(replacement_run["run_id"]))
        else:
            order[index] = str(replacement_run["run_id"])
            by_run_id.pop(original_run_id, None)
        by_run_id[str(replacement_run["run_id"])] = replacement_run
    return [by_run_id[run_id] for run_id in order if run_id in by_run_id]


def _claim_strategy(value: str | None) -> str:
    if value is None:
        return DEFAULT_CLAIM_STRATEGY
    strategy = slugify(str(value), fallback=DEFAULT_CLAIM_STRATEGY)
    if strategy not in CLAIM_STRATEGIES:
        allowed = ", ".join(CLAIM_STRATEGIES)
        raise ValueError(f"claim_strategy must be one of: {allowed}")
    return strategy


@contextmanager
def _agent_claim_lock(root: Path, plan_id: str):
    safe_plan = _safe_plan_id(plan_id)
    lock_path = safe_child(root, "claim-locks", f"{safe_plan}.lock")
    lock_path.parent.mkdir(parents=True, exist_ok=True)
    deadline = time.monotonic() + CLAIM_LOCK_TIMEOUT_SECONDS
    acquired = False
    while not acquired:
        try:
            with lock_path.open("x", encoding="utf-8") as handle:
                handle.write(
                    json.dumps(
                        {
                            "schema": "griosai.agent-claim-lock.v1",
                            "plan_id": safe_plan,
                            "created_at": _now(),
                        },
                        sort_keys=True,
                    )
                    + "\n"
                )
            acquired = True
        except FileExistsError:
            try:
                age = time.time() - lock_path.stat().st_mtime
            except FileNotFoundError:
                continue
            if age > CLAIM_LOCK_STALE_SECONDS:
                try:
                    lock_path.unlink()
                    continue
                except FileNotFoundError:
                    continue
            if time.monotonic() >= deadline:
                raise TimeoutError(f"Timed out waiting for agent claim lock: {safe_plan}")
            time.sleep(CLAIM_LOCK_POLL_SECONDS)
    try:
        yield
    finally:
        if acquired:
            try:
                lock_path.unlink()
            except FileNotFoundError:
                pass


def _claim_candidates(
    plan_runs: list[dict[str, object]],
    *,
    requested_lane: str | None,
    outcomes_by_run: Mapping[str, dict[str, object]],
    active_claims: Mapping[str, dict[str, object]],
    active_quarantines: list[dict[str, object]],
    run_records_by_id: Mapping[str, dict[str, object]],
) -> list[tuple[int, dict[str, object]]]:
    candidates: list[tuple[int, dict[str, object]]] = []
    for index, run in enumerate(plan_runs):
        run_id = str(run["run_id"])
        if requested_lane and run["lane_id"] != requested_lane:
            continue
        if run_id in outcomes_by_run:
            continue
        if run_id in active_claims:
            continue
        run_record = run_records_by_id.get(run_id)
        selected = _run_selected_variant(run_record) if isinstance(run_record, Mapping) else {}
        if _run_quarantine_summaries(run, selected, active_quarantines):
            continue
        candidates.append((index, run))
    return candidates


def _select_claim_candidate(
    plan_runs: list[dict[str, object]],
    candidates: list[tuple[int, dict[str, object]]],
    *,
    requested_lane: str | None,
    outcomes_by_run: Mapping[str, dict[str, object]],
    active_claims: Mapping[str, dict[str, object]],
    strategy: str,
) -> dict[str, object] | None:
    if not candidates:
        return None
    if strategy == "fifo":
        return dict(candidates[0][1])
    loads = _claim_loads(
        plan_runs,
        requested_lane=requested_lane,
        outcomes_by_run=outcomes_by_run,
        active_claims=active_claims,
    )
    _order, selected = min(
        candidates,
        key=lambda item: _claim_candidate_key(item[0], item[1], strategy=strategy, loads=loads),
    )
    return dict(selected)


def _claim_loads(
    plan_runs: list[dict[str, object]],
    *,
    requested_lane: str | None,
    outcomes_by_run: Mapping[str, dict[str, object]],
    active_claims: Mapping[str, dict[str, object]],
) -> dict[str, dict[str, int]]:
    loads = {"lane": {}, "variant": {}, "cell": {}}
    for run in plan_runs:
        if requested_lane and run["lane_id"] != requested_lane:
            continue
        run_id = str(run["run_id"])
        if run_id not in outcomes_by_run and run_id not in active_claims:
            continue
        lane_id = str(run["lane_id"])
        variant_id = str(run["variant_id"])
        cell_id = f"{lane_id}\0{variant_id}"
        loads["lane"][lane_id] = loads["lane"].get(lane_id, 0) + 1
        loads["variant"][variant_id] = loads["variant"].get(variant_id, 0) + 1
        loads["cell"][cell_id] = loads["cell"].get(cell_id, 0) + 1
    return loads


def _claim_candidate_key(
    order: int,
    run: Mapping[str, object],
    *,
    strategy: str,
    loads: Mapping[str, dict[str, int]],
) -> tuple[int, ...]:
    lane_id = str(run["lane_id"])
    variant_id = str(run["variant_id"])
    cell_id = f"{lane_id}\0{variant_id}"
    lane_load = loads["lane"].get(lane_id, 0)
    variant_load = loads["variant"].get(variant_id, 0)
    cell_load = loads["cell"].get(cell_id, 0)
    if strategy == "lane-balanced":
        return (lane_load, order)
    if strategy == "variant-balanced":
        return (variant_load, order)
    if strategy == "lane-variant-balanced":
        return (cell_load, lane_load, variant_load, order)
    return (order,)


def _retry_plan_run(
    replacement: Mapping[str, object],
    *,
    fallback: Mapping[str, object] | None,
) -> dict[str, object] | None:
    run_id = str(replacement.get("run_id") or "")
    try:
        _safe_run_id(run_id)
    except ValueError:
        return None
    lane_id = replacement.get("lane_id") or (fallback.get("lane_id") if fallback else "lane")
    role = replacement.get("role") or (fallback.get("role") if fallback else lane_id)
    variant_id = replacement.get("variant_id") or (fallback.get("variant_id") if fallback else "variant")
    replica = replacement.get("replica") or (fallback.get("replica") if fallback else 1)
    return {
        "run_id": run_id,
        "lane_id": _safe_label(str(lane_id or "lane")),
        "role": _safe_text_label(str(role or lane_id or "lane"), field="lane role"),
        "variant_id": slugify(str(variant_id or "variant"), fallback="variant"),
        "replica": _positive_int(replica, field="replica"),
        "retry_of_run_id": replacement.get("retry_of_run_id"),
    }


def _latest_outcomes_by_run(outcomes: list[dict[str, object]]) -> dict[str, dict[str, object]]:
    latest: dict[str, dict[str, object]] = {}
    for outcome in sorted(outcomes, key=lambda item: str(item.get("logged_at") or "")):
        run_id = outcome.get("run_id")
        if isinstance(run_id, str) and run_id:
            latest[run_id] = outcome
    return latest


def _active_claims_by_run(
    claims: list[dict[str, object]],
    *,
    heartbeats: list[dict[str, object]] | None = None,
    now: datetime,
) -> dict[str, dict[str, object]]:
    active: dict[str, dict[str, object]] = {}
    heartbeats_by_claim = _latest_heartbeats_by_claim(heartbeats or [])
    for claim in sorted(claims, key=lambda item: str(item.get("generated_at") or "")):
        run = claim.get("run")
        if not isinstance(run, dict) or not isinstance(run.get("run_id"), str):
            continue
        if not _claim_is_active(claim, heartbeats_by_claim=heartbeats_by_claim, now=now):
            continue
        active[str(run["run_id"])] = claim
    return active


def _latest_claims_by_run(claims: list[dict[str, object]]) -> dict[str, dict[str, object]]:
    latest: dict[str, dict[str, object]] = {}
    for claim in sorted(claims, key=lambda item: str(item.get("generated_at") or "")):
        run = claim.get("run")
        if isinstance(run, dict) and isinstance(run.get("run_id"), str):
            latest[str(run["run_id"])] = claim
    return latest


def _latest_heartbeats_by_claim(
    heartbeats: list[dict[str, object]],
) -> dict[str, dict[str, object]]:
    latest: dict[str, dict[str, object]] = {}
    for heartbeat in sorted(heartbeats, key=lambda item: str(item.get("generated_at") or "")):
        claim_id = heartbeat.get("claim_id")
        if isinstance(claim_id, str) and claim_id:
            latest[claim_id] = heartbeat
    return latest


def _claim_is_active(
    claim: Mapping[str, object],
    *,
    heartbeats_by_claim: Mapping[str, dict[str, object]] | None = None,
    now: datetime,
) -> bool:
    claim_body = claim.get("claim")
    if not isinstance(claim_body, dict):
        return False
    if str(claim_body.get("status") or "active") != "active":
        return False
    expires_at = _claim_effective_expires_at(claim, heartbeats_by_claim=heartbeats_by_claim)
    return expires_at is not None and expires_at > now


def _claim_is_expired(
    claim: Mapping[str, object],
    *,
    heartbeats_by_claim: Mapping[str, dict[str, object]] | None = None,
    now: datetime,
) -> bool:
    claim_body = claim.get("claim")
    if not isinstance(claim_body, dict):
        return False
    expires_at = _claim_effective_expires_at(claim, heartbeats_by_claim=heartbeats_by_claim)
    return expires_at is not None and expires_at <= now


def _claim_effective_expires_at(
    claim: Mapping[str, object],
    *,
    heartbeats_by_claim: Mapping[str, dict[str, object]] | None = None,
) -> datetime | None:
    claim_id = claim.get("claim_id")
    heartbeat = (
        heartbeats_by_claim.get(str(claim_id))
        if heartbeats_by_claim and isinstance(claim_id, str)
        else None
    )
    if isinstance(heartbeat, dict):
        heartbeat_body = heartbeat.get("heartbeat")
        if isinstance(heartbeat_body, dict):
            expires_at = _parse_datetime(str(heartbeat_body.get("expires_at") or ""))
            if expires_at is not None:
                return expires_at
    claim_body = claim.get("claim")
    if not isinstance(claim_body, dict):
        return None
    return _parse_datetime(str(claim_body.get("expires_at") or ""))


def _claim_reference_time(
    claim: Mapping[str, object],
    *,
    heartbeats_by_claim: Mapping[str, dict[str, object]],
) -> datetime | None:
    claim_id = claim.get("claim_id")
    heartbeat = heartbeats_by_claim.get(str(claim_id)) if isinstance(claim_id, str) else None
    if isinstance(heartbeat, dict):
        heartbeat_body = heartbeat.get("heartbeat")
        if isinstance(heartbeat_body, dict):
            heartbeat_at = _parse_datetime(str(heartbeat_body.get("heartbeat_at") or ""))
            if heartbeat_at is not None:
                return heartbeat_at
    claim_body = claim.get("claim")
    if not isinstance(claim_body, dict):
        return None
    return _parse_datetime(str(claim_body.get("claimed_at") or claim.get("generated_at") or ""))


def _claim_is_stale(
    claim: Mapping[str, object],
    *,
    heartbeats_by_claim: Mapping[str, dict[str, object]],
    now: datetime,
    stale_after_seconds: int,
) -> bool:
    if not _claim_is_active(claim, heartbeats_by_claim=heartbeats_by_claim, now=now):
        return False
    reference = _claim_reference_time(claim, heartbeats_by_claim=heartbeats_by_claim)
    if reference is None:
        return True
    return now - reference >= timedelta(seconds=stale_after_seconds)


def _plan_lane_summaries(
    plan: Mapping[str, object],
    outcomes_by_run: Mapping[str, dict[str, object]],
    *,
    primary_metric: MetricSpec,
    plan_runs: list[dict[str, object]] | None = None,
) -> list[dict[str, object]]:
    lanes: dict[str, dict[str, object]] = {}
    for run in (plan_runs if plan_runs is not None else _plan_runs(plan)):
        lane = lanes.setdefault(
            str(run["lane_id"]),
            {
                "lane_id": run["lane_id"],
                "role": run["role"],
                "expected_runs": 0,
                "completed_runs": 0,
                "succeeded": 0,
                "failed": 0,
                "pending": 0,
                "results": [],
            },
        )
        lane["expected_runs"] = int(lane["expected_runs"]) + 1
        outcome = outcomes_by_run.get(str(run["run_id"]))
        result: dict[str, object] = {
            "run_id": run["run_id"],
            "variant_id": run["variant_id"],
            "replica": run["replica"],
            "status": "pending",
            "metric": None,
            "output": None,
        }
        if outcome is None:
            lane["pending"] = int(lane["pending"]) + 1
        else:
            status = str(outcome.get("status") or "unknown")
            metrics = outcome.get("metrics") if isinstance(outcome.get("metrics"), dict) else {}
            metric_value = metrics.get(primary_metric.name) if isinstance(metrics, dict) else None
            result["status"] = status
            result["metric"] = metric_value if isinstance(metric_value, (int, float)) else None
            result["output"] = outcome.get("output") if isinstance(outcome.get("output"), dict) else None
            lane["completed_runs"] = int(lane["completed_runs"]) + 1
            if status == "succeeded":
                lane["succeeded"] = int(lane["succeeded"]) + 1
            elif status == "failed":
                lane["failed"] = int(lane["failed"]) + 1
        lane["results"].append(result)

    summaries: list[dict[str, object]] = []
    for lane in lanes.values():
        results = lane["results"] if isinstance(lane["results"], list) else []
        best = _best_plan_result(results, primary_metric=primary_metric)
        completed = int(lane["completed_runs"])
        expected = int(lane["expected_runs"])
        summaries.append(
            {
                "lane_id": lane["lane_id"],
                "role": lane["role"],
                "expected_runs": expected,
                "completed_runs": completed,
                "pending_runs": int(lane["pending"]),
                "success_rate": round(int(lane["succeeded"]) / completed, 6) if completed else None,
                "best_run_id": best["run_id"] if best else None,
                "best_variant_id": best["variant_id"] if best else None,
                "best_metric": best["metric"] if best else None,
                "results": results,
            }
        )
    return summaries


def _best_plan_result(
    results: list[object],
    *,
    primary_metric: MetricSpec,
) -> dict[str, object] | None:
    candidates = [
        item
        for item in results
        if isinstance(item, dict) and isinstance(item.get("metric"), (int, float))
    ]
    if not candidates:
        return None
    if primary_metric.direction == "maximize":
        return max(candidates, key=lambda item: float(item["metric"]))
    return min(candidates, key=lambda item: float(item["metric"]))


def _recommended_plan_run(
    lane_summaries: list[dict[str, object]],
    *,
    primary_metric: MetricSpec,
) -> dict[str, object] | None:
    candidates = []
    for lane in lane_summaries:
        if isinstance(lane.get("best_metric"), (int, float)) and lane.get("best_run_id"):
            candidates.append(
                {
                    "run_id": lane["best_run_id"],
                    "variant_id": lane["best_variant_id"],
                    "metric": lane["best_metric"],
                }
            )
    return _best_plan_result(candidates, primary_metric=primary_metric)


def _variant_summaries(
    spec: ExperimentSpec,
    outcomes: list[dict[str, object]],
) -> list[dict[str, object]]:
    summaries: list[dict[str, object]] = []
    metric_name = spec.primary_metric.name
    for variant in spec.variants:
        variant_outcomes = [
            item for item in outcomes if _outcome_variant_id(item) == variant.id
        ]
        values = [
            float(item["metrics"][metric_name])
            for item in variant_outcomes
            if isinstance(item.get("metrics"), dict)
            and isinstance(item["metrics"].get(metric_name), (int, float))
            and math.isfinite(float(item["metrics"][metric_name]))
        ]
        mean = sum(values) / len(values) if values else None
        stddev = _sample_stddev(values, mean=mean) if mean is not None else None
        trials = len(variant_outcomes)
        successes = sum(1 for item in variant_outcomes if item.get("status") == "succeeded")
        failures = sum(1 for item in variant_outcomes if item.get("status") == "failed")
        usage = _usage_summary(variant_outcomes)
        summary: dict[str, object] = {
            "variant_id": variant.id,
            "provider": variant.provider,
            "model": variant.model,
            "trials": trials,
            "successes": successes,
            "failures": failures,
            "success_rate": round(successes / trials, 6) if trials else None,
            "primary_metric_count": len(values),
            "primary_metric_mean": round(mean, 6) if mean is not None else None,
            "primary_metric_stddev": round(stddev, 6) if stddev is not None else None,
            "primary_metric_stderr": (
                round(stddev / math.sqrt(len(values)), 6)
                if stddev is not None and values
                else None
            ),
        }
        if usage:
            summary["usage"] = usage
        summaries.append(summary)
    return summaries


def _usage_summary(outcomes: list[dict[str, object]]) -> dict[str, object]:
    summary: dict[str, object] = {}
    for key in ("total_tokens", "latency_ms", "cost_usd"):
        values = [
            float(usage[key])
            for usage in (
                outcome.get("usage")
                for outcome in outcomes
                if isinstance(outcome.get("usage"), dict)
            )
            if isinstance(usage.get(key), (int, float))
            and math.isfinite(float(usage[key]))
        ]
        if values:
            summary[f"{key}_count"] = len(values)
            summary[f"{key}_mean"] = round(sum(values) / len(values), 6)
            summary[f"{key}_total"] = round(sum(values), 6)
    return summary


def _balance_dimensions(dimensions: tuple[str, ...] | None) -> tuple[str, ...]:
    raw = dimensions or ("variant", "lane")
    normalized: list[str] = []
    allowed = {"variant", "lane", "case"}
    for item in raw:
        name = slugify(str(item), fallback="dimension")
        if name not in allowed:
            raise ValueError("balance dimensions must be selected from: variant, lane, case")
        if name not in normalized:
            normalized.append(name)
    if not normalized:
        raise ValueError("at least one balance dimension is required")
    return tuple(normalized)


def _balance_scope_runs(
    runs: list[dict[str, object]],
    *,
    suite_id: str | None,
    plan_id: str | None,
) -> list[dict[str, object]]:
    safe_suite = _safe_run_id(suite_id) if suite_id else None
    safe_plan = _safe_plan_id(plan_id) if plan_id else None
    scoped: list[dict[str, object]] = []
    for run in runs:
        parallel = run.get("parallel") if isinstance(run.get("parallel"), Mapping) else {}
        if safe_suite and parallel.get("suite_id") != safe_suite:
            continue
        if safe_plan and parallel.get("plan_id") != safe_plan:
            continue
        scoped.append(run)
    if (safe_suite or safe_plan) and not scoped:
        scope_name = safe_suite or safe_plan or "scope"
        raise ValueError(f"no run records matched balance scope: {scope_name}")
    return scoped


def _balance_scope(
    experiment_slug: str,
    *,
    suite_id: str | None,
    plan_id: str | None,
) -> dict[str, object]:
    scope = {
        "experiment": experiment_slug,
        "mode": "suite" if suite_id else "plan" if plan_id else "experiment",
    }
    if suite_id:
        scope["suite_id"] = _safe_run_id(suite_id)
    if plan_id:
        scope["plan_id"] = _safe_plan_id(plan_id)
    return scope


def _balance_cells(
    runs: list[dict[str, object]],
    *,
    outcomes_by_run: Mapping[str, dict[str, object]],
    dimensions: tuple[str, ...],
) -> list[dict[str, object]]:
    cells_by_key: dict[tuple[str, ...], dict[str, object]] = {}
    for run in runs:
        key = tuple(_balance_dimension_value(run, dimension) for dimension in dimensions)
        cell = cells_by_key.setdefault(
            key,
            {
                "cell_id": "|".join(key),
                "dimensions": {dimension: value for dimension, value in zip(dimensions, key)},
                "expected_count": 0,
                "completed_count": 0,
                "succeeded_count": 0,
                "failed_count": 0,
                "missing_count": 0,
                "run_ids": [],
                "completed_run_ids": [],
            },
        )
        cell["expected_count"] = int(cell["expected_count"]) + 1
        run_id = str(run.get("run_id") or "")
        run_ids = cell["run_ids"] if isinstance(cell.get("run_ids"), list) else []
        run_ids.append(_safe_text_label(run_id, field="run_id", max_length=180))
        cell["run_ids"] = run_ids[:12]
        outcome = outcomes_by_run.get(run_id)
        if not outcome:
            continue
        cell["completed_count"] = int(cell["completed_count"]) + 1
        completed_ids = cell["completed_run_ids"] if isinstance(cell.get("completed_run_ids"), list) else []
        completed_ids.append(_safe_text_label(run_id, field="run_id", max_length=180))
        cell["completed_run_ids"] = completed_ids[:12]
        if outcome.get("status") == "failed":
            cell["failed_count"] = int(cell["failed_count"]) + 1
        else:
            cell["succeeded_count"] = int(cell["succeeded_count"]) + 1
    for cell in cells_by_key.values():
        cell["missing_count"] = int(cell["expected_count"]) - int(cell["completed_count"])
        expected = int(cell["expected_count"])
        completed = int(cell["completed_count"])
        cell["completion_ratio"] = round(completed / expected, 6) if expected else 0.0
    return sorted(
        cells_by_key.values(),
        key=lambda item: str(item.get("cell_id") or ""),
    )


def _balance_dimension_value(run: Mapping[str, object], dimension: str) -> str:
    selected = run.get("selected_variant") if isinstance(run.get("selected_variant"), Mapping) else {}
    parallel = run.get("parallel") if isinstance(run.get("parallel"), Mapping) else {}
    if dimension == "variant":
        return slugify(str(selected.get("id") or "unknown"), fallback="unknown")
    if dimension == "lane":
        return slugify(str(parallel.get("lane_id") or "unlaned"), fallback="unlaned")
    if dimension == "case":
        return slugify(str(parallel.get("case_id") or "uncased"), fallback="uncased")
    return "unknown"


def _balance_summary(cells: list[dict[str, object]]) -> dict[str, object]:
    completed_counts = [int(cell.get("completed_count") or 0) for cell in cells]
    expected_counts = [int(cell.get("expected_count") or 0) for cell in cells]
    total_expected = sum(expected_counts)
    total_completed = sum(completed_counts)
    min_completed = min(completed_counts) if completed_counts else 0
    max_completed = max(completed_counts) if completed_counts else 0
    skew = max_completed - min_completed if completed_counts else 0
    return {
        "cell_count": len(cells),
        "expected_runs": total_expected,
        "completed_runs": total_completed,
        "missing_runs": total_expected - total_completed,
        "complete_cells": sum(1 for cell in cells if int(cell.get("missing_count") or 0) == 0),
        "empty_cells": sum(1 for count in completed_counts if count == 0),
        "min_completed_per_cell": min_completed,
        "max_completed_per_cell": max_completed,
        "sample_skew": skew,
        "sample_balance_ratio": (
            round(min_completed / max_completed, 6)
            if max_completed
            else None
        ),
    }


def _balance_findings(
    summary: Mapping[str, object],
    *,
    min_count_per_cell: int,
    max_skew: int,
) -> list[dict[str, object]]:
    findings: list[dict[str, object]] = []
    if int(summary.get("cell_count") or 0) == 0:
        findings.append(_balance_finding("fail", "no-cells", "No scheduled run cells were found."))
    if int(summary.get("completed_runs") or 0) == 0:
        findings.append(_balance_finding("fail", "no-outcomes", "No completed outcomes were found for this balance scope."))
    if int(summary.get("min_completed_per_cell") or 0) < min_count_per_cell:
        findings.append(
            _balance_finding(
                "fail",
                "under-sampled-cells",
                f"At least one cell has fewer than {min_count_per_cell} completed outcome(s).",
            )
        )
    if int(summary.get("sample_skew") or 0) > max_skew:
        findings.append(
            _balance_finding(
                "fail",
                "sample-skew",
                f"Completed sample skew exceeds allowed max_skew={max_skew}.",
            )
        )
    if not findings:
        findings.append(_balance_finding("pass", "balance-passed", "Completed outcomes are balanced for this policy."))
    return findings


def _balance_status(
    summary: Mapping[str, object],
    *,
    min_count_per_cell: int,
    max_skew: int,
) -> str:
    if int(summary.get("cell_count") or 0) == 0:
        return "no-cells"
    if int(summary.get("completed_runs") or 0) == 0:
        return "no-outcomes"
    if int(summary.get("min_completed_per_cell") or 0) < min_count_per_cell:
        return "insufficient"
    if int(summary.get("sample_skew") or 0) > max_skew:
        return "imbalanced"
    return "balanced"


def _balance_finding(severity: str, code: str, message: str) -> dict[str, object]:
    return {
        "severity": severity,
        "code": code,
        "message": message,
    }


def _balance_recommendations(
    balance_status: str,
    summary: Mapping[str, object],
    dimensions: tuple[str, ...],
) -> list[str]:
    if balance_status == "balanced":
        return ["Use this balance report as coverage evidence before agent-decision, agent-promote, or rollout."]
    if balance_status in {"no-cells", "no-outcomes"}:
        return ["Schedule and complete matrix or suite runs before trusting cross-model comparisons."]
    if balance_status == "insufficient":
        return [
            "Dispatch or recover runs for under-sampled cells before promotion.",
            "Run agent-schedule or agent-curriculum-plan when the current matrix lacks enough completed outcomes.",
        ]
    if balance_status == "imbalanced":
        return [
            f"Add outcomes to the lower-count {', '.join(dimensions)} cell(s) until sample skew is within policy.",
            f"Current completed sample skew is {int(summary.get('sample_skew') or 0)}.",
        ]
    return ["Review balance findings before using comparison evidence."]


def _memory_failure_modes(outcomes: list[dict[str, object]]) -> list[dict[str, object]]:
    modes: dict[tuple[str, str], dict[str, object]] = {}
    for outcome in outcomes:
        if outcome.get("status") != "failed":
            continue
        code = (
            _safe_label(str(outcome["failure_code"]))
            if isinstance(outcome.get("failure_code"), str)
            else "failed"
        )
        variant_id = _outcome_variant_id(outcome) or "unknown"
        key = (code, variant_id)
        entry = modes.setdefault(
            key,
            {
                "failure_code": code,
                "variant_id": variant_id,
                "count": 0,
                "run_ids": [],
            },
        )
        entry["count"] = int(entry["count"]) + 1
        run_id = outcome.get("run_id")
        if isinstance(run_id, str):
            cast_run_ids = entry["run_ids"] if isinstance(entry["run_ids"], list) else []
            cast_run_ids.append(_safe_text_label(run_id, field="run_id", max_length=180))
            entry["run_ids"] = cast_run_ids[:8]
    return sorted(
        modes.values(),
        key=lambda item: (-int(item.get("count") or 0), str(item.get("failure_code") or ""), str(item.get("variant_id") or "")),
    )


def _memory_source_artifacts(vault: Path, root: Path, experiment_slug: str) -> dict[str, object]:
    artifacts: dict[str, object] = {}
    comparison = _latest_schema_record(root, "comparisons", AGENT_COMPARISON_SCHEMA)
    allocation = _latest_schema_record(root, "allocations", AGENT_ALLOCATION_SCHEMA)
    improvement = _latest_schema_record(root, "improvements", AGENT_IMPROVEMENT_SCHEMA)
    promotion = _latest_schema_record(root, "promotions", AGENT_PROMOTION_SCHEMA)
    if comparison:
        artifacts["comparison"] = _memory_report_ref(
            comparison,
            id_key="comparison_id",
            status_key=None,
            winner_key="winner_variant_id",
        )
    if allocation:
        artifacts["allocation"] = _memory_report_ref(
            allocation,
            id_key="allocation_id",
            status_key="strategy",
            winner_key="winner_variant_id",
        )
    if improvement:
        artifacts["improvement"] = _memory_report_ref(
            improvement,
            id_key="loop_id",
            status_key=None,
            winner_key="winner_variant_id",
        )
    if promotion:
        artifacts["promotion"] = _memory_report_ref(
            promotion,
            id_key="promotion_id",
            status_key="promotion_status",
            winner_key="candidate_variant_id",
        )
    budget_reports = _budget_reports_for_experiment(vault, experiment_slug)
    if budget_reports:
        budget = budget_reports[-1]
        artifacts["budget"] = _memory_report_ref(
            budget,
            id_key="budget_id",
            status_key="budget_status",
            winner_key=None,
            extra={"over_budget": bool(budget.get("over_budget"))},
        )
    return artifacts


def _memory_report_ref(
    report: Mapping[str, object],
    *,
    id_key: str,
    status_key: str | None,
    winner_key: str | None,
    extra: Mapping[str, object] | None = None,
) -> dict[str, object]:
    payload: dict[str, object] = {
        "artifact_id": _safe_text_label(str(report.get(id_key) or ""), field=id_key, max_length=180),
        "generated_at": _safe_text_label(str(report.get("generated_at") or ""), field="generated_at", max_length=80),
    }
    if status_key and report.get(status_key) is not None:
        payload["status"] = _safe_text_label(str(report.get(status_key)), field=status_key, max_length=120)
    if winner_key and report.get(winner_key) is not None:
        payload["winner_variant_id"] = slugify(str(report.get(winner_key)), fallback="variant")
    if extra:
        payload.update(dict(extra))
    return payload


def _curriculum_metric_threshold(
    spec: ExperimentSpec,
    outcomes: list[dict[str, object]],
    *,
    explicit_threshold: float | None,
) -> tuple[float | None, str]:
    if explicit_threshold is not None:
        return explicit_threshold, "explicit"
    values = [
        float(metrics[spec.primary_metric.name])
        for outcome in outcomes
        for metrics in (outcome.get("metrics"),)
        if isinstance(metrics, Mapping)
        and isinstance(metrics.get(spec.primary_metric.name), (int, float))
        and math.isfinite(float(metrics[spec.primary_metric.name]))
    ]
    if not values:
        return None, "unavailable"
    return round(sum(values) / len(values), 6), "observed-mean"


def _curriculum_hard_cases(
    spec: ExperimentSpec,
    outcomes: list[dict[str, object]],
    *,
    run_by_id: Mapping[str, Mapping[str, object]],
    threshold: float | None,
    include_failed: bool,
    include_low_metric: bool,
) -> list[dict[str, object]]:
    cases: list[dict[str, object]] = []
    metric_name = spec.primary_metric.name
    for outcome in outcomes:
        run_id = outcome.get("run_id")
        if not isinstance(run_id, str):
            continue
        run = run_by_id.get(run_id, {})
        metrics = outcome.get("metrics") if isinstance(outcome.get("metrics"), Mapping) else {}
        metric_value = metrics.get(metric_name) if isinstance(metrics, Mapping) else None
        metric_number = (
            float(metric_value)
            if isinstance(metric_value, (int, float)) and math.isfinite(float(metric_value))
            else None
        )
        status = str(outcome.get("status") or "")
        failed = status != "succeeded"
        weak = _curriculum_metric_is_weak(
            metric_number,
            threshold=threshold,
            direction=spec.primary_metric.direction,
        )
        missing_metric = metric_number is None
        reasons: list[str] = []
        if include_failed and failed:
            reasons.append("failed-outcome")
        if include_low_metric and weak:
            reasons.append("weak-primary-metric")
        if include_low_metric and missing_metric:
            reasons.append("missing-primary-metric")
        if not reasons:
            continue
        cases.append(
            _curriculum_case_record(
                outcome,
                run,
                metric_name=metric_name,
                metric_value=metric_number,
                threshold=threshold,
                reasons=reasons,
            )
        )
    cases.sort(
        key=lambda item: (
            int(item.get("priority_rank") or 99),
            str(item.get("variant_id") or ""),
            str(item.get("lane_id") or ""),
            str(item.get("run_id") or ""),
        )
    )
    for index, item in enumerate(cases, start=1):
        item["rank"] = index
    return cases


def _curriculum_metric_is_weak(
    value: float | None,
    *,
    threshold: float | None,
    direction: str,
) -> bool:
    if value is None or threshold is None:
        return False
    if direction == "maximize":
        return value < threshold
    return value > threshold


def _curriculum_case_record(
    outcome: Mapping[str, object],
    run: Mapping[str, object],
    *,
    metric_name: str,
    metric_value: float | None,
    threshold: float | None,
    reasons: list[str],
) -> dict[str, object]:
    parallel = run.get("parallel") if isinstance(run.get("parallel"), Mapping) else {}
    assignment = run.get("assignment") if isinstance(run.get("assignment"), Mapping) else {}
    output = outcome.get("output") if isinstance(outcome.get("output"), Mapping) else {}
    prompt = run.get("prompt") if isinstance(run.get("prompt"), Mapping) else {}
    priority_rank = 0 if "failed-outcome" in reasons else 1 if "missing-primary-metric" in reasons else 2
    priority = "p0" if priority_rank == 0 else "p1" if priority_rank == 1 else "p2"
    record: dict[str, object] = {
        "rank": 0,
        "priority": priority,
        "priority_rank": priority_rank,
        "reasons": reasons,
        "run_id": _safe_text_label(str(outcome.get("run_id") or ""), field="run_id", max_length=180),
        "outcome_id": _safe_text_label(str(outcome.get("outcome_id") or ""), field="outcome_id", max_length=180),
        "status": _safe_text_label(str(outcome.get("status") or ""), field="status", max_length=40),
        "variant_id": slugify(str(_outcome_variant_id(outcome) or "unknown"), fallback="unknown"),
        "metric_name": metric_name,
        "metric_value": round(metric_value, 6) if metric_value is not None else None,
        "metric_threshold": threshold,
        "subject_hash": assignment.get("subject_hash"),
        "prompt_sha256": prompt.get("sha256"),
        "output_sha256": output.get("sha256"),
    }
    for key in ("plan_id", "lane_id", "role", "suite_id", "case_id", "case_hash", "pipeline_id", "stage_id"):
        value = parallel.get(key)
        if isinstance(value, (str, int, float)) and str(value):
            record[key] = _safe_text_label(str(value), field=key, max_length=180)
    if outcome.get("failure_code") is not None:
        record["failure_code"] = _safe_label(str(outcome.get("failure_code")))
    usage = outcome.get("usage") if isinstance(outcome.get("usage"), Mapping) else {}
    if usage:
        record["usage"] = {
            key: round(float(usage[key]), 6)
            for key in ("total_tokens", "latency_ms", "cost_usd")
            if isinstance(usage.get(key), (int, float)) and math.isfinite(float(usage[key]))
        }
    return record


def _curriculum_variant_focus(
    spec: ExperimentSpec,
    hard_cases: list[dict[str, object]],
    *,
    summaries: list[dict[str, object]],
) -> list[dict[str, object]]:
    summaries_by_variant = {
        str(item.get("variant_id")): item
        for item in summaries
        if isinstance(item.get("variant_id"), str)
    }
    rows: list[dict[str, object]] = []
    for variant in spec.variants:
        cases = [item for item in hard_cases if item.get("variant_id") == variant.id]
        if not cases:
            continue
        summary = summaries_by_variant.get(variant.id, {})
        lanes = sorted(
            {
                str(item.get("lane_id"))
                for item in cases
                if isinstance(item.get("lane_id"), str) and item.get("lane_id")
            }
        )
        row = {
            "variant_id": variant.id,
            "provider": variant.provider,
            "model": variant.model,
            "hard_case_count": len(cases),
            "failed_count": sum(1 for item in cases if "failed-outcome" in item.get("reasons", [])),
            "weak_metric_count": sum(1 for item in cases if "weak-primary-metric" in item.get("reasons", [])),
            "missing_metric_count": sum(1 for item in cases if "missing-primary-metric" in item.get("reasons", [])),
            "primary_metric_mean": summary.get("primary_metric_mean"),
            "primary_metric_count": int(summary.get("primary_metric_count") or 0),
            "focus_lanes": lanes[:6],
        }
        rows.append(row)
    rows.sort(
        key=lambda item: (
            -int(item.get("failed_count") or 0),
            -int(item.get("hard_case_count") or 0),
            str(item.get("variant_id") or ""),
        )
    )
    return rows


def _curriculum_lane_focus(hard_cases: list[dict[str, object]]) -> list[dict[str, object]]:
    by_lane: dict[str, dict[str, object]] = {}
    for item in hard_cases:
        lane_id = str(item.get("lane_id") or "unlaned")
        entry = by_lane.setdefault(
            lane_id,
            {
                "lane_id": lane_id,
                "role": item.get("role"),
                "hard_case_count": 0,
                "failed_count": 0,
                "variant_ids": set(),
                "case_ids": set(),
            },
        )
        entry["hard_case_count"] = int(entry["hard_case_count"]) + 1
        if "failed-outcome" in item.get("reasons", []):
            entry["failed_count"] = int(entry["failed_count"]) + 1
        if item.get("variant_id"):
            cast_variants = entry["variant_ids"]
            if isinstance(cast_variants, set):
                cast_variants.add(str(item["variant_id"]))
        if item.get("case_id"):
            cast_cases = entry["case_ids"]
            if isinstance(cast_cases, set):
                cast_cases.add(str(item["case_id"]))
    rows: list[dict[str, object]] = []
    for entry in by_lane.values():
        variants = sorted(entry["variant_ids"]) if isinstance(entry.get("variant_ids"), set) else []
        cases = sorted(entry["case_ids"]) if isinstance(entry.get("case_ids"), set) else []
        rows.append(
            {
                "lane_id": entry["lane_id"],
                "role": entry.get("role"),
                "hard_case_count": entry["hard_case_count"],
                "failed_count": entry["failed_count"],
                "variant_ids": variants[:8],
                "case_ids": cases[:12],
            }
        )
    rows.sort(
        key=lambda item: (
            -int(item.get("failed_count") or 0),
            -int(item.get("hard_case_count") or 0),
            str(item.get("lane_id") or ""),
        )
    )
    return rows


def _curriculum_next_wave(
    weak_variants: list[dict[str, object]],
    weak_lanes: list[dict[str, object]],
    *,
    case_limit: int,
) -> dict[str, object]:
    focus_variants = [str(item["variant_id"]) for item in weak_variants[:6] if item.get("variant_id")]
    focus_lanes = [
        str(item["lane_id"])
        for item in weak_lanes[:6]
        if item.get("lane_id") and item.get("lane_id") != "unlaned"
    ]
    return {
        "mode": "focused-matrix",
        "focus_variants": focus_variants,
        "focus_lanes": focus_lanes,
        "recommended_case_count": min(case_limit, max(1, sum(int(item.get("hard_case_count") or 0) for item in weak_lanes))),
        "requires_private_prompt_source": True,
        "operator_recipe": [
            "Review hard_cases and map case hashes back to private prompts in the local vault.",
            "Create or update a private suite file with the hard prompts; do not commit it if it contains private content.",
            "Run agent-suite or agent-matrix across the focused lanes and variants, then log outcomes and rerun agent-curriculum.",
        ],
    }


def _curriculum_case_rank(
    curriculum_context: Mapping[str, object],
    *,
    case_id: str,
    case_hash: str,
) -> int | None:
    ranks = curriculum_context.get("case_ranks")
    if not isinstance(ranks, Mapping):
        return None
    for key in (case_id, case_hash):
        value = ranks.get(key)
        if isinstance(value, int):
            return value
    return None


def _curriculum_suite_data(
    suite_data: Mapping[str, object],
    *,
    hard_cases: list[object],
    max_cases: int | None,
) -> dict[str, object]:
    cases = _suite_cases(suite_data)
    limit = _optional_positive_int(max_cases, field="max_cases")
    wanted_ids: set[str] = set()
    wanted_hashes: set[str] = set()
    ranks: dict[str, int] = {}
    for index, item in enumerate(hard_cases, start=1):
        if not isinstance(item, Mapping):
            continue
        case_id = item.get("case_id")
        case_hash = item.get("case_hash")
        if isinstance(case_id, str) and case_id:
            wanted_ids.add(case_id)
            ranks[case_id] = int(item.get("rank") or index)
        if isinstance(case_hash, str) and case_hash:
            wanted_hashes.add(case_hash)
            ranks[case_hash] = int(item.get("rank") or index)
    if not wanted_ids and not wanted_hashes:
        raise ValueError("curriculum hard cases have no case ids or hashes to match against the suite file")
    matched = [
        case
        for case in cases
        if case.id in wanted_ids or case.case_hash in wanted_hashes
    ]
    matched.sort(key=lambda case: min(ranks.get(case.id, 10_000), ranks.get(case.case_hash, 10_000)))
    if limit is not None:
        matched = matched[:limit]
    if not matched:
        raise ValueError("suite file does not contain prompts matching curriculum hard case ids or hashes")
    suite_name = _suite_name(suite_data)
    return {
        "suite": f"{suite_name} Curriculum",
        "description": _optional_safe_text(
            suite_data.get("description") if isinstance(suite_data, Mapping) else None,
            field="suite description",
            max_length=240,
        )
        or "Focused hard-case curriculum rerun.",
        "cases": [
            {
                "id": case.id,
                "prompt": case.prompt,
                "tags": sorted(set(case.tags + ("curriculum", "hard-case"))),
            }
            for case in matched
        ],
    }


def _curriculum_plan_variant_ids(
    spec: ExperimentSpec,
    curriculum: Mapping[str, object],
    *,
    explicit_variant_ids: tuple[str, ...] | None,
    baseline_variant_id: str | None,
) -> tuple[str, ...]:
    if explicit_variant_ids:
        return tuple(variant.id for variant in _matrix_variant_choices(spec, explicit_variant_ids))
    next_wave = curriculum.get("next_wave") if isinstance(curriculum.get("next_wave"), Mapping) else {}
    focus = next_wave.get("focus_variants") if isinstance(next_wave.get("focus_variants"), list) else []
    selected: list[str] = []
    baseline = _safe_variant_id(
        baseline_variant_id,
        spec=spec,
        fallback=_current_champion_variant_id(spec),
    )
    selected.append(baseline)
    for item in focus:
        variant_id = slugify(str(item), fallback="variant")
        if variant_id not in selected:
            selected.append(variant_id)
    return tuple(variant.id for variant in _matrix_variant_choices(spec, tuple(selected)))


def _curriculum_plan_lanes(
    curriculum: Mapping[str, object],
    *,
    explicit_lanes: tuple[str, ...] | None,
) -> tuple[str, ...] | None:
    if explicit_lanes:
        return explicit_lanes
    next_wave = curriculum.get("next_wave") if isinstance(curriculum.get("next_wave"), Mapping) else {}
    focus = next_wave.get("focus_lanes") if isinstance(next_wave.get("focus_lanes"), list) else []
    lanes = tuple(
        slugify(str(item), fallback="lane")
        for item in focus
        if str(item).strip()
    )
    return lanes or None


def _curriculum_plan_context(
    curriculum: Mapping[str, object],
    selected_suite: Mapping[str, object],
    *,
    selected_variant_ids: tuple[str, ...],
    selected_lanes: tuple[str, ...] | None,
) -> dict[str, object]:
    hard_cases = curriculum.get("hard_cases") if isinstance(curriculum.get("hard_cases"), list) else []
    selected_cases = _suite_cases(selected_suite)
    case_ranks: dict[str, int] = {}
    for index, item in enumerate(hard_cases, start=1):
        if not isinstance(item, Mapping):
            continue
        rank = int(item.get("rank") or index)
        if isinstance(item.get("case_id"), str):
            case_ranks[str(item["case_id"])] = rank
        if isinstance(item.get("case_hash"), str):
            case_ranks[str(item["case_hash"])] = rank
    return {
        "curriculum_id": curriculum.get("curriculum_id"),
        "curriculum_status": curriculum.get("curriculum_status"),
        "source_generated_at": curriculum.get("generated_at"),
        "selected_case_count": len(selected_cases),
        "selected_case_ids": [case.id for case in selected_cases],
        "selected_case_hashes": [case.case_hash for case in selected_cases],
        "selected_variant_ids": list(selected_variant_ids),
        "selected_lane_ids": list(selected_lanes or ()),
        "source_hard_case_count": int(
            (curriculum.get("summary") if isinstance(curriculum.get("summary"), Mapping) else {}).get("hard_case_count")
            or 0
        ),
        "case_ranks": case_ranks,
    }


def _curriculum_source_artifacts(
    vault: Path,
    root: Path,
    experiment_slug: str,
) -> dict[str, object]:
    artifacts: dict[str, object] = {}
    specs = {
        "comparison": ("comparisons", AGENT_COMPARISON_SCHEMA, "comparison_id", None, "winner_variant_id"),
        "decision": ("decisions", AGENT_DECISION_SCHEMA, "decision_id", "decision_status", "candidate_variant_id"),
        "memory": ("memories", AGENT_MEMORY_SCHEMA, "memory_id", None, None),
        "leaderboard": ("leaderboards", AGENT_LEADERBOARD_SCHEMA, "leaderboard_id", "leaderboard_status", "winner_variant_id"),
        "suite_report": ("suite-reports", AGENT_SUITE_REPORT_SCHEMA, "report_id", None, "winner_variant_id"),
    }
    for name, (directory, schema, id_key, status_key, winner_key) in specs.items():
        record = _latest_schema_record(root, directory, schema)
        if record:
            artifacts[name] = _memory_report_ref(
                record,
                id_key=id_key,
                status_key=status_key,
                winner_key=winner_key,
            )
    budget_reports = _budget_reports_for_experiment(vault, experiment_slug)
    if budget_reports:
        artifacts["budget"] = _memory_report_ref(
            budget_reports[-1],
            id_key="budget_id",
            status_key="budget_status",
            winner_key=None,
            extra={"over_budget": bool(budget_reports[-1].get("over_budget"))},
        )
    return artifacts


def _curriculum_summary(
    hard_cases: list[dict[str, object]],
    *,
    outcomes: list[dict[str, object]],
    summaries: list[dict[str, object]],
    threshold: float | None,
    threshold_source: str,
) -> dict[str, object]:
    return {
        "outcome_count": len(outcomes),
        "variant_count": len(summaries),
        "hard_case_count": len(hard_cases),
        "failed_case_count": sum(1 for item in hard_cases if "failed-outcome" in item.get("reasons", [])),
        "weak_metric_case_count": sum(1 for item in hard_cases if "weak-primary-metric" in item.get("reasons", [])),
        "missing_metric_case_count": sum(1 for item in hard_cases if "missing-primary-metric" in item.get("reasons", [])),
        "metric_threshold": threshold,
        "metric_threshold_source": threshold_source,
        "case_ref_count": sum(1 for item in hard_cases if item.get("case_id")),
        "lane_ref_count": len({item.get("lane_id") for item in hard_cases if item.get("lane_id")}),
    }


def _curriculum_status(summary: Mapping[str, object]) -> str:
    if int(summary.get("outcome_count") or 0) == 0:
        return "no-outcomes"
    if int(summary.get("hard_case_count") or 0) == 0:
        return "no-hard-cases"
    return "ready"


def _curriculum_recommendations(
    status: str,
    weak_variants: list[dict[str, object]],
    weak_lanes: list[dict[str, object]],
    metric: MetricSpec,
) -> list[str]:
    if status == "no-outcomes":
        return ["Log outcomes before mining a hard-case curriculum."]
    if status == "no-hard-cases":
        return [f"No hard cases were found for {metric.name}; raise the threshold or continue routine exploration."]
    recommendations = ["Use the hard-case curriculum as the next private suite or matrix wave before promoting broadly."]
    if weak_variants:
        recommendations.append(
            "Focus model repair/evaluation on variant(s): "
            + ", ".join(str(item["variant_id"]) for item in weak_variants[:4])
            + "."
        )
    if weak_lanes:
        recommendations.append(
            "Prioritize lane(s): "
            + ", ".join(str(item["lane_id"]) for item in weak_lanes[:4])
            + "."
        )
    recommendations.append("Keep raw prompts in the vault; this artifact only stores hashes and metadata.")
    return recommendations


def _memory_lessons(
    spec: ExperimentSpec,
    *,
    summaries: list[dict[str, object]],
    outcomes: list[dict[str, object]],
    failure_modes: list[dict[str, object]],
    source_artifacts: Mapping[str, object],
    min_trials: int,
) -> list[dict[str, object]]:
    lessons: list[dict[str, object]] = []
    if not outcomes:
        lessons.append(
            _memory_lesson(
                "coverage",
                "p0",
                "no-outcomes",
                {"outcome_count": 0},
                "Log metadata-only outcomes before changing model traffic or promotion policy.",
            )
        )
        return lessons
    under_sampled = [
        str(item["variant_id"])
        for item in summaries
        if int(item.get("primary_metric_count") or 0) < min_trials
    ]
    if under_sampled:
        lessons.append(
            _memory_lesson(
                "coverage",
                "p1",
                "under-sampled-variants",
                {
                    "min_trials_per_variant": min_trials,
                    "variant_ids": under_sampled,
                    "variant_count": len(under_sampled),
                },
                "Run agent-matrix or agent-suite to collect balanced evidence before exploiting a winner.",
            )
        )
    missing_usage = sum(1 for outcome in outcomes if not isinstance(outcome.get("usage"), dict) or not outcome.get("usage"))
    if missing_usage:
        lessons.append(
            _memory_lesson(
                "budget",
                "p1",
                "missing-usage-metadata",
                {"missing_usage_count": missing_usage, "outcome_count": len(outcomes)},
                "Require workers to log usage, latency, and cost metadata for every outcome.",
            )
        )
    if failure_modes:
        top = failure_modes[0]
        lessons.append(
            _memory_lesson(
                "reliability",
                "p1",
                "top-failure-mode",
                {
                    "failure_code": top.get("failure_code"),
                    "variant_id": top.get("variant_id"),
                    "count": int(top.get("count") or 0),
                },
                "Use agent-recover for affected runs and adjust adapter timeouts, prompts, or model routing before scaling.",
            )
        )
    for item in summaries:
        trials = int(item.get("trials") or 0)
        success_rate = item.get("success_rate")
        if trials and isinstance(success_rate, (int, float)) and float(success_rate) < 0.7:
            lessons.append(
                _memory_lesson(
                    "reliability",
                    "p2",
                    "low-variant-success-rate",
                    {
                        "variant_id": item.get("variant_id"),
                        "trials": trials,
                        "success_rate": round(float(success_rate), 6),
                    },
                    "Keep this variant in exploration until failures are understood or route it away from critical lanes.",
                )
            )
    lessons.extend(_memory_cost_lessons(summaries))
    winner = _winner_variant_id(spec, summaries)
    enough_data = all(int(item.get("primary_metric_count") or 0) >= min_trials for item in summaries)
    if winner and enough_data:
        lessons.append(
            _memory_lesson(
                "routing",
                "p2",
                "measured-winner",
                {"winner_variant_id": winner, "primary_metric": spec.primary_metric.as_dict()},
                "Use agent-allocate and gated agent-promote evidence before increasing champion traffic.",
            )
        )
    budget = source_artifacts.get("budget") if isinstance(source_artifacts.get("budget"), Mapping) else None
    if budget and budget.get("over_budget") is True:
        lessons.append(
            _memory_lesson(
                "budget",
                "p1",
                "latest-budget-over-limit",
                {"budget_id": budget.get("artifact_id"), "status": budget.get("status")},
                "Reduce expensive variants or tighten per-run budgets before launching another large fanout.",
            )
        )
    promotion = source_artifacts.get("promotion") if isinstance(source_artifacts.get("promotion"), Mapping) else None
    if promotion and promotion.get("status") == "ready":
        lessons.append(
            _memory_lesson(
                "promotion",
                "p2",
                "ready-promotion",
                {
                    "promotion_id": promotion.get("artifact_id"),
                    "candidate_variant_id": promotion.get("winner_variant_id"),
                },
                "Review the promotion patch and keep a rollback record before changing traffic weights.",
            )
        )
    return sorted(lessons, key=_memory_priority_key)


def _memory_cost_lessons(summaries: list[dict[str, object]]) -> list[dict[str, object]]:
    lessons: list[dict[str, object]] = []
    for key, label in (
        ("cost_usd_mean", "cost"),
        ("latency_ms_mean", "latency"),
        ("total_tokens_mean", "usage"),
    ):
        measured: list[tuple[float, dict[str, object]]] = []
        for item in summaries:
            usage = item.get("usage") if isinstance(item.get("usage"), dict) else {}
            value = usage.get(key) if isinstance(usage, dict) else None
            if isinstance(value, (int, float)) and math.isfinite(float(value)) and float(value) > 0:
                measured.append((float(value), item))
        if len(measured) < 2:
            continue
        measured.sort(key=lambda pair: pair[0])
        low_value, low_item = measured[0]
        high_value, high_item = measured[-1]
        if high_value >= low_value * 2:
            lessons.append(
                _memory_lesson(
                    "efficiency",
                    "p2",
                    f"high-{label}-variant",
                    {
                        "variant_id": high_item.get("variant_id"),
                        "mean": round(high_value, 6),
                        "lowest_variant_id": low_item.get("variant_id"),
                        "lowest_mean": round(low_value, 6),
                    },
                    "Apply a cost penalty in agent-allocate or reserve this variant for lanes where quality justifies the spend.",
                )
            )
    return lessons


def _memory_lesson(
    category: str,
    priority: str,
    code: str,
    evidence: Mapping[str, object],
    recommendation: str,
) -> dict[str, object]:
    payload = {
        "category": _safe_label(category),
        "priority": _safe_label(priority),
        "code": _safe_label(code),
        "evidence": _sanitize_memory_evidence(evidence),
        "recommendation": _safe_text_label(recommendation, field="recommendation", max_length=320),
    }
    payload["lesson_id"] = f"lesson-{_hash_json(payload)[:12]}"
    return payload


def _sanitize_memory_evidence(evidence: Mapping[str, object]) -> dict[str, object]:
    safe: dict[str, object] = {}
    for key, value in evidence.items():
        safe_key = _safe_label(str(key))
        if isinstance(value, str):
            safe[safe_key] = _safe_text_label(value, field=safe_key, max_length=220)
        elif isinstance(value, bool):
            safe[safe_key] = value
        elif isinstance(value, int):
            safe[safe_key] = value
        elif isinstance(value, float) and math.isfinite(value):
            safe[safe_key] = round(value, 6)
        elif isinstance(value, Mapping):
            safe[safe_key] = _sanitize_memory_evidence(value)
        elif isinstance(value, list):
            safe[safe_key] = [
                _safe_text_label(str(item), field=safe_key, max_length=220)
                if not isinstance(item, (int, float, bool))
                else item
                for item in value[:16]
            ]
    return safe


def _memory_priority_key(lesson: Mapping[str, object]) -> tuple[int, str]:
    order = {"p0": 0, "p1": 1, "p2": 2, "p3": 3}
    return (
        order.get(str(lesson.get("priority") or "p3"), 9),
        str(lesson.get("code") or ""),
    )


def _memory_summary(
    summaries: list[dict[str, object]],
    *,
    outcomes: list[dict[str, object]],
    failure_modes: list[dict[str, object]],
    lessons: list[dict[str, object]],
) -> dict[str, object]:
    return {
        "variant_count": len(summaries),
        "measured_variants": sum(1 for item in summaries if int(item.get("trials") or 0) > 0),
        "outcome_count": len(outcomes),
        "succeeded_outcomes": sum(1 for item in outcomes if item.get("status") == "succeeded"),
        "failed_outcomes": sum(1 for item in outcomes if item.get("status") == "failed"),
        "failure_mode_count": len(failure_modes),
        "lesson_count": len(lessons),
        "p0_lessons": sum(1 for item in lessons if item.get("priority") == "p0"),
        "p1_lessons": sum(1 for item in lessons if item.get("priority") == "p1"),
        "p2_lessons": sum(1 for item in lessons if item.get("priority") == "p2"),
    }


def _memory_recommendations(
    lessons: list[dict[str, object]],
    summaries: list[dict[str, object]],
    *,
    min_trials: int,
) -> list[str]:
    recommendations: list[str] = []
    codes = {str(item.get("code") or "") for item in lessons}
    if "under-sampled-variants" in codes:
        recommendations.append(f"Collect at least {min_trials} primary-metric sample(s) per variant before promotion.")
    if "top-failure-mode" in codes:
        recommendations.append("Run agent-recover and keep failed variants under observation until retries land.")
    if "missing-usage-metadata" in codes:
        recommendations.append("Make cost, latency, and aggregate usage metadata required in worker result ingestion.")
    if any(str(item.get("code") or "").startswith("high-") for item in lessons):
        recommendations.append("Use agent-allocate --cost-penalty before raising traffic on expensive variants.")
    if summaries and all(int(item.get("primary_metric_count") or 0) >= min_trials for item in summaries):
        recommendations.append("Run agent-compare, agent-allocate, and gated agent-promote with this memory report as context.")
    return recommendations or ["No new metadata-only lessons were found; continue collecting balanced outcomes."]


def _route_lane_contexts(
    runs: list[dict[str, object]],
    outcomes: list[dict[str, object]],
) -> list[dict[str, object]]:
    contexts: dict[str, dict[str, object]] = {}
    runs_by_id = {
        str(run.get("run_id")): run
        for run in runs
        if isinstance(run.get("run_id"), str)
    }
    for run in runs:
        lane = _run_lane_context(run)
        contexts.setdefault(str(lane["lane_id"]), lane)
    for outcome in outcomes:
        run_id = outcome.get("run_id")
        run = runs_by_id.get(str(run_id)) if isinstance(run_id, str) else None
        lane = _run_lane_context(run) if run is not None else _default_lane_context()
        contexts.setdefault(str(lane["lane_id"]), lane)
    if not contexts:
        contexts["default"] = _default_lane_context()
    return sorted(contexts.values(), key=lambda item: str(item.get("lane_id") or ""))


def _run_lane_context(run: Mapping[str, object] | None) -> dict[str, object]:
    if run is None:
        return _default_lane_context()
    parallel = run.get("parallel") if isinstance(run.get("parallel"), Mapping) else {}
    lane_id = slugify(str(parallel.get("lane_id") or "default"), fallback="default")
    role = _safe_text_label(str(parallel.get("role") or lane_id), field="lane role", max_length=120)
    payload: dict[str, object] = {"lane_id": lane_id, "role": role}
    objective = parallel.get("objective") if isinstance(parallel, Mapping) else None
    if isinstance(objective, str) and objective.strip():
        payload["objective"] = _safe_text_label(objective, field="lane objective", max_length=240)
    return payload


def _default_lane_context() -> dict[str, object]:
    return {"lane_id": "default", "role": "default"}


def _route_lane_policy(
    spec: ExperimentSpec,
    lane: Mapping[str, object],
    *,
    outcomes: list[dict[str, object]],
    runs_by_id: Mapping[str, dict[str, object]],
    strategy: str,
    exploration_floor: float,
    max_share: float,
    min_trials: int,
    cost_penalty: float,
) -> dict[str, object]:
    lane_id = slugify(str(lane.get("lane_id") or "default"), fallback="default")
    lane_outcomes = [
        outcome
        for outcome in outcomes
        if _outcome_lane_id(outcome, runs_by_id=runs_by_id) == lane_id
    ]
    summaries = _variant_summaries(spec, lane_outcomes)
    allocations = _allocation_entries(
        spec,
        summaries,
        strategy=strategy,
        exploration_floor=exploration_floor,
        max_share=max_share,
        min_trials=min_trials,
        cost_penalty=cost_penalty,
    )
    winner = _allocation_winner(allocations)
    return {
        "lane_id": lane_id,
        "role": _safe_text_label(str(lane.get("role") or lane_id), field="lane role", max_length=120),
        "objective": _safe_text_label(str(lane.get("objective")), field="lane objective", max_length=240)
        if isinstance(lane.get("objective"), str) and str(lane.get("objective")).strip()
        else None,
        "outcome_count": len(lane_outcomes),
        "measured_variants": sum(1 for item in summaries if int(item.get("primary_metric_count") or 0) > 0),
        "winner_variant_id": winner,
        "under_sampled_variants": sum(1 for item in allocations if item.get("under_sampled") is True),
        "allocations": allocations,
    }


def _outcome_lane_id(
    outcome: Mapping[str, object],
    *,
    runs_by_id: Mapping[str, dict[str, object]],
) -> str:
    run_id = outcome.get("run_id")
    run = runs_by_id.get(str(run_id)) if isinstance(run_id, str) else None
    lane = _run_lane_context(run)
    return str(lane["lane_id"])


def _route_summary(lane_policies: list[dict[str, object]], *, outcome_count: int) -> dict[str, object]:
    return {
        "lane_count": len(lane_policies),
        "measured_lanes": sum(1 for lane in lane_policies if int(lane.get("outcome_count") or 0) > 0),
        "outcome_count": outcome_count,
        "recommended_routes": sum(1 for lane in lane_policies if lane.get("winner_variant_id")),
        "under_sampled_lanes": sum(1 for lane in lane_policies if int(lane.get("under_sampled_variants") or 0) > 0),
        "under_sampled_lane_variants": sum(int(lane.get("under_sampled_variants") or 0) for lane in lane_policies),
    }


def _route_next_config(
    spec: ExperimentSpec,
    lane_policies: list[dict[str, object]],
    *,
    generated_at: str,
) -> dict[str, object]:
    config = spec.as_dict()
    config["traffic_salt"] = f"{spec.traffic_salt}:route:{_compact_timestamp(generated_at)}"
    config["lane_routing_policy"] = {
        "generated_at": generated_at,
        "policy": "lane-aware-route",
        "lanes": [
            {
                "lane_id": lane["lane_id"],
                "winner_variant_id": lane.get("winner_variant_id"),
                "variant_shares": [
                    {
                        "variant_id": item.get("variant_id"),
                        "recommended_share": item.get("recommended_share"),
                        "recommended_weight": item.get("recommended_weight"),
                        "reason": item.get("reason"),
                    }
                    for item in lane.get("allocations", [])
                    if isinstance(item, Mapping)
                ],
            }
            for lane in lane_policies
        ],
    }
    return config


def _route_recommendations(
    lane_policies: list[dict[str, object]],
    *,
    min_trials: int,
) -> list[str]:
    recommendations: list[str] = []
    if not lane_policies:
        return ["Create parallel lane runs before writing a lane routing policy."]
    if any(int(lane.get("outcome_count") or 0) == 0 for lane in lane_policies):
        recommendations.append("Collect at least one metadata-only outcome for every lane before relying on lane routing.")
    if any(int(lane.get("under_sampled_variants") or 0) > 0 for lane in lane_policies):
        recommendations.append(f"Use agent-matrix until every lane and variant has at least {min_trials} primary-metric sample(s).")
    if any(lane.get("winner_variant_id") for lane in lane_policies):
        recommendations.append("Use this route policy as an overlay for worker assignment while preserving exploration shares.")
    return recommendations or ["Lane routing has enough metadata for the current policy."]


def _usage_values(outcomes: list[dict[str, object]], key: str) -> list[float]:
    values: list[float] = []
    for outcome in outcomes:
        usage = outcome.get("usage") if isinstance(outcome.get("usage"), dict) else {}
        value = usage.get(key) if isinstance(usage, dict) else None
        if isinstance(value, (int, float)) and math.isfinite(float(value)):
            values.append(float(value))
    return values


def _drift_windows(
    spec: ExperimentSpec,
    outcomes: list[dict[str, object]],
    *,
    runs_by_id: Mapping[str, Mapping[str, object]],
    metric_name: str,
    baseline_window: int,
    recent_window: int,
    min_samples: int,
    max_metric_drop: float,
    max_cost_increase_ratio: float | None,
    max_latency_increase_ratio: float | None,
) -> list[dict[str, object]]:
    groups: dict[tuple[str, str], list[dict[str, object]]] = {}
    for outcome in outcomes:
        variant_id = _outcome_variant_id(outcome)
        if not variant_id:
            continue
        groups.setdefault(("variant", variant_id), []).append(outcome)
        lane_id = _drift_outcome_lane(outcome, runs_by_id=runs_by_id)
        if lane_id:
            groups.setdefault(("lane-variant", f"{lane_id}/{variant_id}"), []).append(outcome)
    windows: list[dict[str, object]] = []
    for (scope, name), scoped in sorted(groups.items()):
        record = _drift_window_record(
            scope,
            name,
            scoped,
            metric_name=metric_name,
            direction=spec.primary_metric.direction,
            baseline_window=baseline_window,
            recent_window=recent_window,
            min_samples=min_samples,
            max_metric_drop=max_metric_drop,
            max_cost_increase_ratio=max_cost_increase_ratio,
            max_latency_increase_ratio=max_latency_increase_ratio,
        )
        if record is not None:
            windows.append(record)
    return windows


def _drift_window_record(
    scope: str,
    name: str,
    outcomes: list[dict[str, object]],
    *,
    metric_name: str,
    direction: str,
    baseline_window: int,
    recent_window: int,
    min_samples: int,
    max_metric_drop: float,
    max_cost_increase_ratio: float | None,
    max_latency_increase_ratio: float | None,
) -> dict[str, object] | None:
    ordered = sorted(outcomes, key=_drift_outcome_sort_key)
    if len(ordered) < min_samples * 2:
        return None
    recent = ordered[-recent_window:]
    baseline_pool = ordered[: -recent_window] if len(ordered) > recent_window else []
    baseline = baseline_pool[-baseline_window:]
    if len(recent) < min_samples or len(baseline) < min_samples:
        return None
    baseline_metrics = _drift_metric_values(baseline, metric_name)
    recent_metrics = _drift_metric_values(recent, metric_name)
    baseline_usage = _usage_summary(baseline)
    recent_usage = _usage_summary(recent)
    metric_baseline = _rounded_mean(baseline_metrics)
    metric_recent = _rounded_mean(recent_metrics)
    metric_regression = _drift_metric_regression(
        metric_baseline,
        metric_recent,
        direction=direction,
    )
    cost_ratio = _drift_increase_ratio(
        _summary_number(baseline_usage, "cost_usd_mean"),
        _summary_number(recent_usage, "cost_usd_mean"),
    )
    latency_ratio = _drift_increase_ratio(
        _summary_number(baseline_usage, "latency_ms_mean"),
        _summary_number(recent_usage, "latency_ms_mean"),
    )
    status = _drift_window_status(
        metric_regression=metric_regression,
        max_metric_drop=max_metric_drop,
        cost_increase_ratio=cost_ratio,
        max_cost_increase_ratio=max_cost_increase_ratio,
        latency_increase_ratio=latency_ratio,
        max_latency_increase_ratio=max_latency_increase_ratio,
    )
    return {
        "scope": scope,
        "name": name,
        "status": status,
        "baseline_count": len(baseline),
        "recent_count": len(recent),
        "metric": {
            "name": metric_name,
            "direction": direction,
            "baseline_mean": metric_baseline,
            "recent_mean": metric_recent,
            "regression": metric_regression,
            "max_allowed_regression": max_metric_drop,
        },
        "usage": {
            "baseline": baseline_usage,
            "recent": recent_usage,
            "cost_increase_ratio": cost_ratio,
            "max_cost_increase_ratio": max_cost_increase_ratio,
            "latency_increase_ratio": latency_ratio,
            "max_latency_increase_ratio": max_latency_increase_ratio,
        },
    }


def _drift_metric_values(outcomes: list[dict[str, object]], metric_name: str) -> list[float]:
    values: list[float] = []
    for outcome in outcomes:
        metrics = outcome.get("metrics") if isinstance(outcome.get("metrics"), dict) else {}
        value = metrics.get(metric_name) if isinstance(metrics, dict) else None
        if isinstance(value, (int, float)) and math.isfinite(float(value)):
            values.append(float(value))
    return values


def _drift_outcome_lane(
    outcome: Mapping[str, object],
    *,
    runs_by_id: Mapping[str, Mapping[str, object]],
) -> str | None:
    run_id = outcome.get("run_id")
    run = runs_by_id.get(str(run_id)) if isinstance(run_id, str) else None
    parallel = run.get("parallel") if isinstance(run, Mapping) and isinstance(run.get("parallel"), dict) else None
    if not isinstance(parallel, dict):
        return None
    lane_id = parallel.get("lane_id")
    return slugify(str(lane_id), fallback="lane") if lane_id else None


def _drift_outcome_sort_key(outcome: Mapping[str, object]) -> tuple[str, str]:
    timestamp = outcome.get("logged_at") or outcome.get("generated_at") or ""
    outcome_id = outcome.get("outcome_id") or outcome.get("run_id") or ""
    return str(timestamp), str(outcome_id)


def _drift_metric_regression(
    baseline_mean: float | None,
    recent_mean: float | None,
    *,
    direction: str,
) -> float | None:
    if baseline_mean is None or recent_mean is None:
        return None
    if direction == "minimize":
        return round(recent_mean - baseline_mean, 6)
    return round(baseline_mean - recent_mean, 6)


def _drift_increase_ratio(baseline_mean: float | None, recent_mean: float | None) -> float | None:
    if baseline_mean is None or recent_mean is None or baseline_mean <= 0:
        return None
    return round((recent_mean - baseline_mean) / baseline_mean, 6)


def _drift_window_status(
    *,
    metric_regression: float | None,
    max_metric_drop: float,
    cost_increase_ratio: float | None,
    max_cost_increase_ratio: float | None,
    latency_increase_ratio: float | None,
    max_latency_increase_ratio: float | None,
) -> str:
    if metric_regression is not None and metric_regression > max_metric_drop:
        return "metric-regressed"
    if (
        max_cost_increase_ratio is not None
        and cost_increase_ratio is not None
        and cost_increase_ratio > max_cost_increase_ratio
    ):
        return "cost-regressed"
    if (
        max_latency_increase_ratio is not None
        and latency_increase_ratio is not None
        and latency_increase_ratio > max_latency_increase_ratio
    ):
        return "latency-regressed"
    return "stable"


def _drift_findings(windows: list[dict[str, object]]) -> list[dict[str, object]]:
    if not windows:
        return [
            _drift_finding(
                "warn",
                "drift-insufficient-data",
                "all",
                "No variant or lane/variant window has enough baseline and recent samples.",
            )
        ]
    findings: list[dict[str, object]] = []
    for window in windows:
        status = str(window.get("status") or "stable")
        if status == "stable":
            continue
        metric = window.get("metric") if isinstance(window.get("metric"), dict) else {}
        usage = window.get("usage") if isinstance(window.get("usage"), dict) else {}
        scope = f"{window.get('scope')}:{window.get('name')}"
        if status == "metric-regressed":
            findings.append(
                _drift_finding(
                    "fail",
                    "metric-regression",
                    scope,
                    f"Recent {metric.get('name')} regressed by {_table_number(metric.get('regression'))}.",
                )
            )
        elif status == "cost-regressed":
            findings.append(
                _drift_finding(
                    "fail",
                    "cost-regression",
                    scope,
                    f"Recent mean cost increased by {_table_number(usage.get('cost_increase_ratio'))}.",
                )
            )
        elif status == "latency-regressed":
            findings.append(
                _drift_finding(
                    "fail",
                    "latency-regression",
                    scope,
                    f"Recent mean latency increased by {_table_number(usage.get('latency_increase_ratio'))}.",
                )
            )
    return findings


def _drift_finding(
    severity: str,
    code: str,
    scope: str,
    message: str,
) -> dict[str, object]:
    return {
        "severity": severity,
        "code": code,
        "scope": _safe_text_label(scope, field="drift scope", max_length=180),
        "message": message,
    }


def _drift_recommendations(findings: list[dict[str, object]], drift_status: str) -> list[str]:
    if drift_status == "stable":
        return ["Keep monitoring drift before promotion and rollout gates."]
    codes = {str(item.get("code") or "") for item in findings}
    recommendations: list[str] = []
    if "drift-insufficient-data" in codes:
        recommendations.append("Collect more recent and baseline outcomes before trusting drift evidence.")
    if "metric-regression" in codes:
        recommendations.append("Run agent-curriculum and a focused suite on regressed variants or lanes before promotion.")
    if "cost-regression" in codes or "latency-regression" in codes:
        recommendations.append("Run agent-budget and agent-route before increasing traffic for regressed variants or lanes.")
    if drift_status == "stable-with-warnings":
        recommendations.append("Review warning findings before rollout, but no configured drift limit failed.")
    return recommendations or ["Resolve drift findings before promotion or rollout."]


def _rounded_sum(values: list[float]) -> float:
    return round(sum(values), 6) if values else 0.0


def _rounded_mean(values: list[float]) -> float | None:
    return round(sum(values) / len(values), 6) if values else None


def _rounded_max(values: list[float]) -> float | None:
    return round(max(values), 6) if values else None


def _efficiency_frontier(
    summaries: list[dict[str, object]],
    *,
    metric: MetricSpec,
    metric_key: str,
) -> list[dict[str, object]]:
    entries = [
        _efficiency_entry(summary, metric=metric, metric_key=metric_key)
        for summary in summaries
        if isinstance(summary.get(metric_key), (int, float))
    ]
    for entry in entries:
        dominated_by = [
            other["variant_id"]
            for other in entries
            if other["variant_id"] != entry["variant_id"]
            and _efficiency_dominates(other, entry)
        ]
        entry["dominated_by"] = dominated_by
        entry["pareto_frontier"] = bool(entry.get("usage_dimensions")) and not dominated_by
    frontier = [entry for entry in entries if entry.get("pareto_frontier") is True]
    frontier.sort(
        key=lambda item: (
            -float(item.get("directional_metric") or 0.0),
            float(item.get("cost_usd_mean") or math.inf),
            float(item.get("latency_ms_mean") or math.inf),
            float(item.get("total_tokens_mean") or math.inf),
            str(item.get("variant_id") or ""),
        )
    )
    return frontier


def _efficiency_entry(
    summary: Mapping[str, object],
    *,
    metric: MetricSpec,
    metric_key: str,
) -> dict[str, object]:
    raw_metric = _summary_number(summary, metric_key)
    directional_metric = (
        raw_metric if raw_metric is not None and metric.direction == "maximize"
        else (-raw_metric if raw_metric is not None else None)
    )
    usage = summary.get("usage") if isinstance(summary.get("usage"), dict) else {}
    entry: dict[str, object] = {
        "variant_id": str(summary.get("variant_id") or ""),
        "metric": round(raw_metric, 6) if raw_metric is not None else None,
        "directional_metric": round(directional_metric, 6) if directional_metric is not None else None,
        "usage_dimensions": [],
    }
    for key in ("cost_usd", "latency_ms", "total_tokens"):
        mean_key = f"{key}_mean"
        value = usage.get(mean_key) if isinstance(usage, dict) else None
        if isinstance(value, (int, float)) and math.isfinite(float(value)):
            entry[mean_key] = round(float(value), 6)
            dimensions = entry["usage_dimensions"]
            if isinstance(dimensions, list):
                dimensions.append(key)
    cost = entry.get("cost_usd_mean")
    if (
        raw_metric is not None
        and metric.direction == "maximize"
        and isinstance(cost, (int, float))
        and float(cost) > 0
    ):
        entry["metric_per_usd"] = round(raw_metric / float(cost), 6)
    tokens = entry.get("total_tokens_mean")
    if (
        raw_metric is not None
        and metric.direction == "maximize"
        and isinstance(tokens, (int, float))
        and float(tokens) > 0
    ):
        entry["metric_per_1k_tokens"] = round(raw_metric / (float(tokens) / 1000.0), 6)
    return entry


def _efficiency_dominates(candidate: Mapping[str, object], incumbent: Mapping[str, object]) -> bool:
    candidate_metric = _summary_number(candidate, "directional_metric")
    incumbent_metric = _summary_number(incumbent, "directional_metric")
    if candidate_metric is None or incumbent_metric is None or candidate_metric < incumbent_metric:
        return False
    strictly_better = candidate_metric > incumbent_metric
    shared_usage = 0
    for key in ("cost_usd_mean", "latency_ms_mean", "total_tokens_mean"):
        candidate_value = _summary_number(candidate, key)
        incumbent_value = _summary_number(incumbent, key)
        if candidate_value is None or incumbent_value is None:
            continue
        shared_usage += 1
        if candidate_value > incumbent_value:
            return False
        if candidate_value < incumbent_value:
            strictly_better = True
    return shared_usage > 0 and strictly_better


def _efficiency_recommendations(
    frontier: list[dict[str, object]],
    *,
    metric: MetricSpec,
) -> list[str]:
    if not frontier:
        return [
            "Log usage metadata for all variants to produce a cost, latency, and token Pareto frontier."
        ]
    return [
        "Review Pareto-efficient variant(s) before promotion: "
        f"{', '.join(str(item['variant_id']) for item in frontier)} "
        f"on {metric.name} plus usage metadata."
    ]


def _suite_case_summaries(
    suite: Mapping[str, object],
    *,
    outcomes_by_run: Mapping[str, dict[str, object]],
    metric: MetricSpec,
    variants: tuple[ModelVariant, ...],
) -> list[dict[str, object]]:
    plan_refs = suite.get("plans")
    if not isinstance(plan_refs, list):
        raise ValueError("agent suite record is missing plans")
    summaries: list[dict[str, object]] = []
    for plan_ref in plan_refs:
        if not isinstance(plan_ref, dict):
            continue
        run_refs = plan_ref.get("runs")
        if not isinstance(run_refs, list):
            run_refs = []
        variant_results = _suite_case_variant_results(
            run_refs,
            outcomes_by_run=outcomes_by_run,
            metric=metric,
            variants=variants,
        )
        expected = sum(int(item["expected_runs"]) for item in variant_results)
        completed = sum(int(item["completed_runs"]) for item in variant_results)
        metric_candidates = [
            item for item in variant_results if isinstance(item.get("metric_mean"), (int, float))
        ]
        best = _suite_best_variant(metric_candidates, metric=metric)
        baseline_values = {
            str(item["variant_id"]): item.get("metric_mean")
            for item in variant_results
            if isinstance(item.get("metric_mean"), (int, float))
        }
        summaries.append(
            {
                "case_id": _safe_case_id(plan_ref.get("case_id"), index=len(summaries) + 1),
                "case_hash": _optional_safe_text(plan_ref.get("case_hash"), field="case_hash", max_length=80),
                "plan_id": _optional_timeline_label(plan_ref.get("plan_id")),
                "expected_runs": expected,
                "completed_runs": completed,
                "completed_ratio": round(completed / expected, 6) if expected else 0.0,
                "status": "complete" if expected and completed == expected else ("partial" if completed else "no-outcomes"),
                "best_variant_id": best.get("variant_id") if best else None,
                "best_metric": best.get("metric_mean") if best else None,
                "measured_variant_count": len(baseline_values),
                "missing_variants": [
                    variant.id for variant in variants if variant.id not in baseline_values
                ],
                "variant_results": variant_results,
            }
        )
    return summaries


def _suite_case_variant_results(
    run_refs: list[object],
    *,
    outcomes_by_run: Mapping[str, dict[str, object]],
    metric: MetricSpec,
    variants: tuple[ModelVariant, ...],
) -> list[dict[str, object]]:
    by_variant: dict[str, dict[str, object]] = {
        variant.id: {
            "variant_id": variant.id,
            "provider": variant.provider,
            "model": variant.model,
            "expected_runs": 0,
            "completed_runs": 0,
            "succeeded_runs": 0,
            "failed_runs": 0,
            "metric_values": [],
            "outcomes": [],
            "best_run_id": None,
            "best_metric": None,
        }
        for variant in variants
    }
    for raw_ref in run_refs:
        if not isinstance(raw_ref, dict):
            continue
        variant_id = slugify(str(raw_ref.get("variant_id") or "variant"), fallback="variant")
        cell = by_variant.setdefault(
            variant_id,
            {
                "variant_id": variant_id,
                "provider": "",
                "model": "",
                "expected_runs": 0,
                "completed_runs": 0,
                "succeeded_runs": 0,
                "failed_runs": 0,
                "metric_values": [],
                "outcomes": [],
                "best_run_id": None,
                "best_metric": None,
            },
        )
        cell["expected_runs"] = int(cell["expected_runs"]) + 1
        run_id = str(raw_ref.get("run_id") or "")
        outcome = outcomes_by_run.get(run_id)
        if not outcome:
            continue
        cell["completed_runs"] = int(cell["completed_runs"]) + 1
        if outcome.get("status") == "succeeded":
            cell["succeeded_runs"] = int(cell["succeeded_runs"]) + 1
        if outcome.get("status") == "failed":
            cell["failed_runs"] = int(cell["failed_runs"]) + 1
        outcomes = cell["outcomes"]
        if isinstance(outcomes, list):
            outcomes.append(outcome)
        metrics = outcome.get("metrics")
        value = metrics.get(metric.name) if isinstance(metrics, dict) else None
        if isinstance(value, (int, float)) and math.isfinite(float(value)):
            metric_values = cell["metric_values"]
            if isinstance(metric_values, list):
                metric_values.append(float(value))
            best_metric = cell.get("best_metric")
            better = (
                best_metric is None
                or (metric.direction == "maximize" and float(value) > float(best_metric))
                or (metric.direction == "minimize" and float(value) < float(best_metric))
            )
            if better:
                cell["best_metric"] = round(float(value), 6)
                cell["best_run_id"] = run_id
    results: list[dict[str, object]] = []
    for variant_id in by_variant:
        cell = by_variant[variant_id]
        values = [float(value) for value in cell["metric_values"] if isinstance(value, (int, float))]
        mean = sum(values) / len(values) if values else None
        outcomes = [item for item in cell["outcomes"] if isinstance(item, dict)]
        result = {
            "variant_id": cell["variant_id"],
            "provider": cell["provider"],
            "model": cell["model"],
            "expected_runs": int(cell["expected_runs"]),
            "completed_runs": int(cell["completed_runs"]),
            "succeeded_runs": int(cell["succeeded_runs"]),
            "failed_runs": int(cell["failed_runs"]),
            "success_rate": (
                round(int(cell["succeeded_runs"]) / int(cell["completed_runs"]), 6)
                if int(cell["completed_runs"])
                else None
            ),
            "metric_count": len(values),
            "metric_mean": round(mean, 6) if mean is not None else None,
            "best_run_id": cell["best_run_id"],
            "best_metric": cell["best_metric"],
        }
        usage = _usage_summary(outcomes)
        if usage:
            result["usage"] = usage
        results.append(result)
    return results


def _suite_best_variant(
    candidates: list[dict[str, object]],
    *,
    metric: MetricSpec,
) -> dict[str, object] | None:
    if not candidates:
        return None
    if metric.direction == "maximize":
        return max(candidates, key=lambda item: float(item["metric_mean"]))
    return min(candidates, key=lambda item: float(item["metric_mean"]))


def _suite_report_variant_summaries(
    spec: ExperimentSpec,
    suite: Mapping[str, object],
    *,
    outcomes_by_run: Mapping[str, dict[str, object]],
    case_summaries: list[dict[str, object]],
) -> list[dict[str, object]]:
    outcomes_by_variant = _suite_outcomes_by_variant(suite, outcomes_by_run=outcomes_by_run)
    summaries: list[dict[str, object]] = []
    for variant in spec.variants:
        case_values = [
            float(result["metric_mean"])
            for case in case_summaries
            for result in case.get("variant_results", [])
            if isinstance(result, dict)
            and result.get("variant_id") == variant.id
            and isinstance(result.get("metric_mean"), (int, float))
        ]
        mean = sum(case_values) / len(case_values) if case_values else None
        stddev = _sample_stddev(case_values, mean=mean) if mean is not None else None
        outcomes = outcomes_by_variant.get(variant.id, [])
        usage = _usage_summary(outcomes)
        summary: dict[str, object] = {
            "variant_id": variant.id,
            "provider": variant.provider,
            "model": variant.model,
            "measured_cases": len(case_values),
            "case_metric_mean": round(mean, 6) if mean is not None else None,
            "case_metric_stddev": round(stddev, 6) if stddev is not None else None,
            "case_metric_stderr": (
                round(stddev / math.sqrt(len(case_values)), 6)
                if stddev is not None and case_values
                else None
            ),
            "case_wins": sum(1 for case in case_summaries if case.get("best_variant_id") == variant.id),
            "outcome_count": len(outcomes),
            "successes": sum(1 for item in outcomes if item.get("status") == "succeeded"),
            "failures": sum(1 for item in outcomes if item.get("status") == "failed"),
        }
        if usage:
            summary["usage"] = usage
        summaries.append(summary)
    return summaries


def _suite_outcomes_by_variant(
    suite: Mapping[str, object],
    *,
    outcomes_by_run: Mapping[str, dict[str, object]],
) -> dict[str, list[dict[str, object]]]:
    outcomes: dict[str, list[dict[str, object]]] = {}
    for run_ref in _suite_run_refs(suite):
        variant_id = slugify(str(run_ref.get("variant_id") or "variant"), fallback="variant")
        run_id = str(run_ref.get("run_id") or "")
        outcome = outcomes_by_run.get(run_id)
        if outcome:
            outcomes.setdefault(variant_id, []).append(outcome)
    return outcomes


def _suite_run_refs(suite: Mapping[str, object]) -> list[dict[str, object]]:
    refs: list[dict[str, object]] = []
    plans = suite.get("plans")
    if not isinstance(plans, list):
        return refs
    for plan_ref in plans:
        if not isinstance(plan_ref, dict):
            continue
        runs = plan_ref.get("runs")
        if isinstance(runs, list):
            refs.extend(item for item in runs if isinstance(item, dict))
    return refs


def _suite_pairwise_comparisons(
    spec: ExperimentSpec,
    case_summaries: list[dict[str, object]],
    *,
    baseline_variant_id: str,
) -> list[dict[str, object]]:
    comparisons: list[dict[str, object]] = []
    for variant in spec.variants:
        if variant.id == baseline_variant_id:
            continue
        deltas: list[float] = []
        case_deltas: list[dict[str, object]] = []
        for case in case_summaries:
            baseline = _suite_case_metric(case, baseline_variant_id)
            candidate = _suite_case_metric(case, variant.id)
            if baseline is None or candidate is None:
                continue
            raw_delta = candidate - baseline
            directional_delta = raw_delta if spec.primary_metric.direction == "maximize" else -raw_delta
            deltas.append(directional_delta)
            case_deltas.append(
                {
                    "case_id": case.get("case_id"),
                    "baseline_metric": round(baseline, 6),
                    "candidate_metric": round(candidate, 6),
                    "directional_delta": round(directional_delta, 6),
                }
            )
        mean = sum(deltas) / len(deltas) if deltas else None
        stddev = _sample_stddev(deltas, mean=mean) if mean is not None else None
        stderr = stddev / math.sqrt(len(deltas)) if stddev is not None and deltas else None
        ci = _confidence_interval(mean, stderr)
        comparisons.append(
            {
                "baseline_variant_id": baseline_variant_id,
                "candidate_variant_id": variant.id,
                "paired_cases": len(deltas),
                "mean_directional_delta": round(mean, 6) if mean is not None else None,
                "delta_stddev": round(stddev, 6) if stddev is not None else None,
                "delta_stderr": round(stderr, 6) if stderr is not None else None,
                "delta_ci95": ci,
                "wins": sum(1 for value in deltas if value > 0),
                "losses": sum(1 for value in deltas if value < 0),
                "ties": sum(1 for value in deltas if value == 0),
                "confidence": _comparison_confidence_label(
                    (mean / stderr) if mean is not None and stderr and stderr > 0 else None
                ),
                "status": _suite_pairwise_status(mean, ci, len(deltas)),
                "case_deltas": case_deltas,
            }
        )
    return comparisons


def _suite_case_metric(case: Mapping[str, object], variant_id: str) -> float | None:
    results = case.get("variant_results")
    if not isinstance(results, list):
        return None
    for result in results:
        if not isinstance(result, dict) or result.get("variant_id") != variant_id:
            continue
        value = result.get("metric_mean")
        if isinstance(value, (int, float)) and math.isfinite(float(value)):
            return float(value)
    return None


def _suite_pairwise_status(
    mean_delta: float | None,
    delta_ci: Mapping[str, object] | None,
    paired_cases: int,
) -> str:
    if paired_cases == 0 or mean_delta is None:
        return "insufficient-data"
    if isinstance(delta_ci, Mapping):
        low = delta_ci.get("low")
        high = delta_ci.get("high")
        if isinstance(low, (int, float)) and low > 0:
            return "beats-baseline"
        if isinstance(high, (int, float)) and high < 0:
            return "trails-baseline"
    if mean_delta > 0:
        return "candidate-ahead"
    if mean_delta < 0:
        return "candidate-behind"
    return "tied"


def _suite_report_winner(
    spec: ExperimentSpec,
    variant_summaries: list[dict[str, object]],
) -> str | None:
    candidates = [
        item for item in variant_summaries if isinstance(item.get("case_metric_mean"), (int, float))
    ]
    if not candidates:
        return None
    if spec.primary_metric.direction == "maximize":
        winner = max(candidates, key=lambda item: (float(item["case_metric_mean"]), int(item.get("case_wins") or 0)))
    else:
        winner = min(candidates, key=lambda item: (float(item["case_metric_mean"]), -int(item.get("case_wins") or 0)))
    return str(winner["variant_id"])


def _suite_report_summary(
    case_summaries: list[dict[str, object]],
    pairwise: list[dict[str, object]],
    *,
    min_completed_ratio: float,
) -> dict[str, object]:
    case_count = len(case_summaries)
    expected = sum(int(item.get("expected_runs") or 0) for item in case_summaries)
    completed = sum(int(item.get("completed_runs") or 0) for item in case_summaries)
    complete_cases = sum(
        1 for item in case_summaries if float(item.get("completed_ratio") or 0.0) >= min_completed_ratio
    )
    return {
        "case_count": case_count,
        "complete_cases": complete_cases,
        "expected_runs": expected,
        "completed_runs": completed,
        "completed_ratio": round(completed / expected, 6) if expected else 0.0,
        "paired_comparisons": sum(int(item.get("paired_cases") or 0) for item in pairwise),
        "beats_baseline": sum(1 for item in pairwise if item.get("status") == "beats-baseline"),
        "trails_baseline": sum(1 for item in pairwise if item.get("status") == "trails-baseline"),
        "inconclusive": sum(1 for item in pairwise if item.get("status") in {"candidate-ahead", "candidate-behind", "tied"}),
        "insufficient_data": sum(1 for item in pairwise if item.get("status") == "insufficient-data"),
    }


def _suite_report_recommendations(
    summary: Mapping[str, object],
    pairwise: list[dict[str, object]],
    *,
    baseline_variant_id: str,
    winner_variant_id: str | None,
    metric: MetricSpec,
) -> list[str]:
    recommendations: list[str] = []
    if int(summary.get("complete_cases") or 0) < int(summary.get("case_count") or 0):
        recommendations.append("Finish missing suite case outcomes before using this report for promotion.")
    strong = [
        str(item["candidate_variant_id"])
        for item in pairwise
        if item.get("status") == "beats-baseline"
    ]
    if strong:
        recommendations.append(
            f"Review promotion evidence for suite variant(s) beating baseline {baseline_variant_id}: {', '.join(strong)}."
        )
    if winner_variant_id:
        recommendations.append(
            f"Current suite winner is {winner_variant_id} on paired case {metric.name} ({metric.direction})."
        )
    else:
        recommendations.append("Collect paired suite outcomes before declaring a suite winner.")
    return recommendations


def _metric_values_by_variant(
    spec: ExperimentSpec,
    outcomes: list[dict[str, object]],
) -> dict[str, list[float]]:
    metric_name = spec.primary_metric.name
    values_by_variant = {variant.id: [] for variant in spec.variants}
    for outcome in outcomes:
        variant_id = _outcome_variant_id(outcome)
        if variant_id not in values_by_variant:
            continue
        metrics = outcome.get("metrics")
        if not isinstance(metrics, dict):
            continue
        value = metrics.get(metric_name)
        if isinstance(value, (int, float)) and math.isfinite(float(value)):
            values_by_variant[variant_id].append(float(value))
    return values_by_variant


def _comparison_variant_summaries(
    spec: ExperimentSpec,
    outcomes: list[dict[str, object]],
    values_by_variant: Mapping[str, list[float]],
) -> list[dict[str, object]]:
    summaries = _variant_summaries(spec, outcomes)
    for summary in summaries:
        values = values_by_variant.get(str(summary["variant_id"]), [])
        mean = _summary_number(summary, "primary_metric_mean")
        stderr = _summary_number(summary, "primary_metric_stderr")
        summary["primary_metric_min"] = round(min(values), 6) if values else None
        summary["primary_metric_max"] = round(max(values), 6) if values else None
        summary["primary_metric_ci95"] = _confidence_interval(mean, stderr)
    return summaries


def _confidence_interval(mean: float | None, stderr: float | None) -> dict[str, object] | None:
    if mean is None or stderr is None:
        return None
    margin = 1.96 * stderr
    return {
        "low": round(mean - margin, 6),
        "high": round(mean + margin, 6),
        "margin": round(margin, 6),
    }


def _comparison_winner(
    spec: ExperimentSpec,
    summaries: list[dict[str, object]],
    *,
    min_samples: int,
) -> str | None:
    eligible = [
        item
        for item in summaries
        if int(item.get("primary_metric_count") or 0) >= min_samples
        and isinstance(item.get("primary_metric_mean"), (int, float))
    ]
    if not eligible:
        return None
    if spec.primary_metric.direction == "maximize":
        winner = max(eligible, key=lambda item: float(item["primary_metric_mean"]))
    else:
        winner = min(eligible, key=lambda item: float(item["primary_metric_mean"]))
    return str(winner["variant_id"])


def _pairwise_comparisons(
    spec: ExperimentSpec,
    summaries: list[dict[str, object]],
    *,
    baseline_variant_id: str,
    min_samples: int,
) -> list[dict[str, object]]:
    by_variant = {
        str(item["variant_id"]): item
        for item in summaries
        if isinstance(item.get("variant_id"), str)
    }
    baseline = by_variant.get(baseline_variant_id)
    comparisons: list[dict[str, object]] = []
    for variant in spec.variants:
        if variant.id == baseline_variant_id:
            continue
        candidate = by_variant.get(variant.id)
        comparisons.append(
            _pairwise_comparison(
                metric=spec.primary_metric,
                baseline_variant_id=baseline_variant_id,
                candidate_variant_id=variant.id,
                baseline=baseline,
                candidate=candidate,
                min_samples=min_samples,
            )
        )
    return comparisons


def _pairwise_comparison(
    *,
    metric: MetricSpec,
    baseline_variant_id: str,
    candidate_variant_id: str,
    baseline: Mapping[str, object] | None,
    candidate: Mapping[str, object] | None,
    min_samples: int,
) -> dict[str, object]:
    baseline_mean = _summary_number(baseline, "primary_metric_mean")
    candidate_mean = _summary_number(candidate, "primary_metric_mean")
    baseline_count = int(baseline.get("primary_metric_count") or 0) if baseline else 0
    candidate_count = int(candidate.get("primary_metric_count") or 0) if candidate else 0
    baseline_stderr = _summary_number(baseline, "primary_metric_stderr")
    candidate_stderr = _summary_number(candidate, "primary_metric_stderr")
    raw_delta = (
        round(candidate_mean - baseline_mean, 6)
        if baseline_mean is not None and candidate_mean is not None
        else None
    )
    directional_delta = raw_delta
    if raw_delta is not None and metric.direction == "minimize":
        directional_delta = round(-raw_delta, 6)
    combined = (
        math.sqrt(baseline_stderr**2 + candidate_stderr**2)
        if baseline_stderr is not None and candidate_stderr is not None
        else None
    )
    z_score = (
        directional_delta / combined
        if isinstance(directional_delta, (int, float)) and combined and combined > 0
        else None
    )
    delta_ci = _confidence_interval(
        float(directional_delta) if isinstance(directional_delta, (int, float)) else None,
        combined,
    )
    status = _comparison_status(
        directional_delta=directional_delta,
        delta_ci=delta_ci,
        baseline_count=baseline_count,
        candidate_count=candidate_count,
        min_samples=min_samples,
    )
    lift_percent = None
    if isinstance(directional_delta, (int, float)) and baseline_mean not in (None, 0.0):
        lift_percent = round((float(directional_delta) / abs(float(baseline_mean))) * 100.0, 6)
    return {
        "baseline_variant_id": baseline_variant_id,
        "candidate_variant_id": candidate_variant_id,
        "baseline_samples": baseline_count,
        "candidate_samples": candidate_count,
        "baseline_mean": round(baseline_mean, 6) if baseline_mean is not None else None,
        "candidate_mean": round(candidate_mean, 6) if candidate_mean is not None else None,
        "raw_delta": raw_delta,
        "directional_delta": directional_delta,
        "lift_percent": lift_percent,
        "combined_stderr": round(combined, 6) if combined is not None else None,
        "z_score": round(z_score, 6) if z_score is not None else None,
        "delta_ci95": delta_ci,
        "confidence": _comparison_confidence_label(z_score),
        "status": status,
    }


def _comparison_status(
    *,
    directional_delta: object,
    delta_ci: Mapping[str, object] | None,
    baseline_count: int,
    candidate_count: int,
    min_samples: int,
) -> str:
    if baseline_count < min_samples or candidate_count < min_samples:
        return "insufficient-data"
    if not isinstance(directional_delta, (int, float)):
        return "insufficient-data"
    if isinstance(delta_ci, Mapping):
        low = delta_ci.get("low")
        high = delta_ci.get("high")
        if isinstance(low, (int, float)) and low > 0:
            return "beats-baseline"
        if isinstance(high, (int, float)) and high < 0:
            return "trails-baseline"
    if float(directional_delta) > 0:
        return "candidate-ahead"
    if float(directional_delta) < 0:
        return "candidate-behind"
    return "tied"


def _comparison_confidence_label(z_score: float | None) -> str:
    if z_score is None:
        return "unknown"
    magnitude = abs(z_score)
    if magnitude >= 1.96:
        return "strong"
    if magnitude >= 1.0:
        return "moderate"
    return "weak"


def _decision_candidate_variant_id(
    spec: ExperimentSpec,
    summaries: list[dict[str, object]],
    *,
    baseline_variant_id: str,
) -> str | None:
    candidates = [
        item
        for item in summaries
        if item.get("variant_id") != baseline_variant_id
        and isinstance(item.get("primary_metric_mean"), (int, float))
    ]
    if candidates:
        if spec.primary_metric.direction == "maximize":
            winner = max(candidates, key=lambda item: float(item["primary_metric_mean"]))
        else:
            winner = min(candidates, key=lambda item: float(item["primary_metric_mean"]))
        return str(winner["variant_id"])
    for variant in spec.variants:
        if variant.id != baseline_variant_id:
            return variant.id
    return None


def _decision_comparison(
    spec: ExperimentSpec,
    *,
    baseline_variant_id: str,
    candidate_variant_id: str,
    baseline: Mapping[str, object] | None,
    candidate: Mapping[str, object] | None,
    min_samples: int,
    min_delta: float,
    confidence_threshold: float,
) -> dict[str, object]:
    pairwise = _pairwise_comparison(
        metric=spec.primary_metric,
        baseline_variant_id=baseline_variant_id,
        candidate_variant_id=candidate_variant_id,
        baseline=baseline,
        candidate=candidate,
        min_samples=min_samples,
    )
    directional_delta = _summary_number(pairwise, "directional_delta")
    z_score = _summary_number(pairwise, "z_score")
    if z_score is None and directional_delta is not None:
        combined = _summary_number(pairwise, "combined_stderr")
        if combined == 0:
            z_score = math.inf if directional_delta > 0 else -math.inf if directional_delta < 0 else 0.0
    confidence = _decision_one_sided_confidence(z_score)
    baseline_confidence = _decision_one_sided_confidence(
        -z_score if z_score is not None and math.isfinite(z_score) else z_score
    )
    if z_score == math.inf:
        baseline_confidence = 0.0
    elif z_score == -math.inf:
        baseline_confidence = 1.0
    eligible = (
        int(pairwise.get("baseline_samples") or 0) >= min_samples
        and int(pairwise.get("candidate_samples") or 0) >= min_samples
        and directional_delta is not None
    )
    beats = bool(
        eligible
        and directional_delta is not None
        and directional_delta >= min_delta
        and confidence is not None
        and confidence >= confidence_threshold
    )
    trails = bool(
        eligible
        and directional_delta is not None
        and directional_delta <= -min_delta
        and baseline_confidence is not None
        and baseline_confidence >= confidence_threshold
    )
    status = "candidate-ready" if beats else "baseline-ready" if trails else "continue"
    if not eligible:
        status = "insufficient-data"
    pairwise.update(
        {
            "decision_status": status,
            "min_delta": min_delta,
            "confidence_threshold": confidence_threshold,
            "one_sided_confidence": round(confidence, 6) if confidence is not None else None,
            "baseline_one_sided_confidence": (
                round(baseline_confidence, 6) if baseline_confidence is not None else None
            ),
            "eligible": eligible,
            "candidate_beats_threshold": beats,
            "baseline_beats_threshold": trails,
        }
    )
    return pairwise


def _empty_decision_comparison(
    *,
    baseline_variant_id: str,
    min_samples: int,
    min_delta: float,
    confidence_threshold: float,
) -> dict[str, object]:
    return {
        "baseline_variant_id": baseline_variant_id,
        "candidate_variant_id": None,
        "baseline_samples": 0,
        "candidate_samples": 0,
        "baseline_mean": None,
        "candidate_mean": None,
        "raw_delta": None,
        "directional_delta": None,
        "lift_percent": None,
        "combined_stderr": None,
        "z_score": None,
        "delta_ci95": None,
        "confidence": "unknown",
        "status": "insufficient-data",
        "decision_status": "insufficient-data",
        "min_delta": min_delta,
        "confidence_threshold": confidence_threshold,
        "one_sided_confidence": None,
        "baseline_one_sided_confidence": None,
        "eligible": False,
        "candidate_beats_threshold": False,
        "baseline_beats_threshold": False,
    }


def _decision_one_sided_confidence(z_score: float | None) -> float | None:
    if z_score is None:
        return None
    if z_score == math.inf:
        return 1.0
    if z_score == -math.inf:
        return 0.0
    return NormalDist().cdf(z_score)


def _decision_outcomes(
    outcomes: list[dict[str, object]],
    *,
    baseline_variant_id: str,
    candidate_variant_id: str | None,
) -> list[dict[str, object]]:
    variant_ids = {baseline_variant_id}
    if candidate_variant_id:
        variant_ids.add(candidate_variant_id)
    return [outcome for outcome in outcomes if _outcome_variant_id(outcome) in variant_ids]


def _decision_guardrails(
    spec: ExperimentSpec,
    compared_outcomes: list[dict[str, object]],
    *,
    candidate_summary: Mapping[str, object] | None,
    max_cost_usd: float | None,
    max_total_tokens: int | None,
    candidate_metric_floor: float | None,
) -> dict[str, object]:
    checks: list[dict[str, object]] = []
    usage = _usage_summary(compared_outcomes)
    if max_cost_usd is not None:
        total_cost = _summary_number(usage, "cost_usd_total")
        checks.append(
            {
                "name": "max_cost_usd",
                "status": _decision_limit_status(total_cost, max_cost_usd, lower_is_better=True),
                "observed": round(total_cost, 6) if total_cost is not None else None,
                "limit": max_cost_usd,
            }
        )
    if max_total_tokens is not None:
        total_tokens = _summary_number(usage, "total_tokens_total")
        checks.append(
            {
                "name": "max_total_tokens",
                "status": _decision_limit_status(total_tokens, float(max_total_tokens), lower_is_better=True),
                "observed": round(total_tokens, 6) if total_tokens is not None else None,
                "limit": max_total_tokens,
            }
        )
    if candidate_metric_floor is not None:
        candidate_mean = _summary_number(candidate_summary, "primary_metric_mean")
        passed = (
            candidate_mean is not None
            and (
                candidate_mean >= candidate_metric_floor
                if spec.primary_metric.direction == "maximize"
                else candidate_mean <= candidate_metric_floor
            )
        )
        checks.append(
            {
                "name": "candidate_metric_floor",
                "status": "pass" if passed else "fail" if candidate_mean is not None else "unknown",
                "observed": round(candidate_mean, 6) if candidate_mean is not None else None,
                "limit": candidate_metric_floor,
                "direction": spec.primary_metric.direction,
            }
        )
    status = "pass"
    if any(item.get("status") == "fail" for item in checks):
        status = "fail"
    elif any(item.get("status") == "unknown" for item in checks):
        status = "unknown"
    return {
        "status": status,
        "checks": checks,
        "usage": usage,
    }


def _decision_limit_status(
    observed: float | None,
    limit: float,
    *,
    lower_is_better: bool,
) -> str:
    if observed is None:
        return "unknown"
    if lower_is_better:
        return "pass" if observed <= limit else "fail"
    return "pass" if observed >= limit else "fail"


def _decision_result(
    comparison: Mapping[str, object],
    guardrails: Mapping[str, object],
) -> tuple[str, str]:
    guardrail_status = str(guardrails.get("status") or "pass")
    if guardrail_status == "fail":
        return "blocked", "blocked-by-guardrail"
    if guardrail_status == "unknown":
        return "continue", "guardrail-unknown"
    if comparison.get("candidate_beats_threshold") is True:
        return "stop-promote", "ready"
    if comparison.get("baseline_beats_threshold") is True:
        return "stop-baseline", "ready"
    if comparison.get("decision_status") == "insufficient-data":
        return "continue", "insufficient-data"
    return "continue", "inconclusive"


def _decision_summary(
    comparison: Mapping[str, object],
    guardrails: Mapping[str, object],
    *,
    outcome_count: int,
    compared_outcome_count: int,
) -> dict[str, object]:
    return {
        "outcome_count": outcome_count,
        "compared_outcome_count": compared_outcome_count,
        "baseline_samples": int(comparison.get("baseline_samples") or 0),
        "candidate_samples": int(comparison.get("candidate_samples") or 0),
        "directional_delta": comparison.get("directional_delta"),
        "lift_percent": comparison.get("lift_percent"),
        "z_score": comparison.get("z_score"),
        "confidence": comparison.get("one_sided_confidence"),
        "baseline_confidence": comparison.get("baseline_one_sided_confidence"),
        "guardrail_status": guardrails.get("status"),
    }


def _decision_variant_evidence(
    summary: Mapping[str, object] | None,
) -> dict[str, object] | None:
    if not isinstance(summary, Mapping):
        return None
    evidence = {
        key: summary.get(key)
        for key in (
            "variant_id",
            "provider",
            "model",
            "trials",
            "successes",
            "failures",
            "success_rate",
            "primary_metric_count",
            "primary_metric_mean",
            "primary_metric_stddev",
            "primary_metric_stderr",
            "primary_metric_ci95",
            "usage",
        )
        if key in summary
    }
    return evidence


def _decision_recommendations(
    *,
    decision: str,
    decision_status: str,
    comparison: Mapping[str, object],
    guardrails: Mapping[str, object],
    baseline_variant_id: str,
    candidate_variant_id: str | None,
    metric: MetricSpec,
) -> list[str]:
    if not candidate_variant_id:
        return ["Add a challenger variant before requesting a sequential decision."]
    if decision == "stop-promote":
        return [
            f"Stop the A/B test and review promotion controls for {candidate_variant_id}.",
            f"Candidate cleared the {metric.name} ({metric.direction}) delta and confidence policy against {baseline_variant_id}.",
        ]
    if decision == "stop-baseline":
        return [
            f"Stop the A/B test and keep baseline {baseline_variant_id}.",
            f"Candidate {candidate_variant_id} trails by the configured delta and confidence policy.",
        ]
    if decision_status == "blocked-by-guardrail":
        failed = [
            str(item.get("name"))
            for item in guardrails.get("checks", [])
            if isinstance(item, Mapping) and item.get("status") == "fail"
        ]
        return [
            "Do not promote until failed decision guardrail(s) are resolved: "
            + ", ".join(failed or ["unknown"])
            + "."
        ]
    if decision_status == "guardrail-unknown":
        return ["Log usage or metric metadata needed to evaluate configured decision guardrails."]
    if decision_status == "insufficient-data":
        return [
            f"Continue sampling until both {baseline_variant_id} and {candidate_variant_id} meet the minimum sample policy."
        ]
    confidence = comparison.get("one_sided_confidence")
    delta = comparison.get("directional_delta")
    return [
        f"Continue the A/B test; observed delta {_table_number(delta)} has confidence {_table_number(confidence)}.",
        "Run agent-power or agent-schedule if this decision remains inconclusive after the current batch.",
    ]


def _power_variant_plans(
    spec: ExperimentSpec,
    summaries: list[dict[str, object]],
    values_by_variant: Mapping[str, list[float]],
    *,
    usage_means: Mapping[str, dict[str, float | None]],
    baseline_variant_id: str,
    min_detectable_effect: float,
    alpha: float,
    power: float,
    fallback_stddev: float | None,
    max_cost_usd: float | None,
    max_total_tokens: int | None,
) -> list[dict[str, object]]:
    by_variant = {
        str(item["variant_id"]): item
        for item in summaries
        if isinstance(item.get("variant_id"), str)
    }
    baseline = by_variant.get(baseline_variant_id, {})
    baseline_values = values_by_variant.get(baseline_variant_id, [])
    all_values = [value for values in values_by_variant.values() for value in values]
    global_stddev = _sample_stddev(all_values, mean=_rounded_mean(all_values))
    plans: list[dict[str, object]] = []
    for variant in spec.variants:
        if variant.id == baseline_variant_id:
            continue
        candidate = by_variant.get(variant.id, {})
        candidate_values = values_by_variant.get(variant.id, [])
        sigma, sigma_source = _power_stddev(
            baseline_values,
            candidate_values,
            global_stddev=global_stddev,
            fallback_stddev=fallback_stddev,
        )
        required = (
            _power_required_samples_per_variant(
                sigma,
                min_detectable_effect=min_detectable_effect,
                alpha=alpha,
                power=power,
            )
            if sigma is not None
            else None
        )
        baseline_count = int(baseline.get("primary_metric_count") or 0)
        candidate_count = int(candidate.get("primary_metric_count") or 0)
        additional_baseline = (
            max(0, int(required) - baseline_count)
            if isinstance(required, int)
            else None
        )
        additional_candidate = (
            max(0, int(required) - candidate_count)
            if isinstance(required, int)
            else None
        )
        additional_total = (
            int(additional_baseline) + int(additional_candidate)
            if additional_baseline is not None and additional_candidate is not None
            else None
        )
        cost_estimate = _power_estimated_usage(
            usage_means,
            key="cost_usd_mean",
            baseline_variant_id=baseline_variant_id,
            candidate_variant_id=variant.id,
            additional_baseline=additional_baseline,
            additional_candidate=additional_candidate,
        )
        token_estimate = _power_estimated_usage(
            usage_means,
            key="total_tokens_mean",
            baseline_variant_id=baseline_variant_id,
            candidate_variant_id=variant.id,
            additional_baseline=additional_baseline,
            additional_candidate=additional_candidate,
        )
        status = _power_variant_status(
            required=required,
            additional_total=additional_total,
            estimated_additional_cost_usd=cost_estimate,
            estimated_additional_tokens=token_estimate,
            max_cost_usd=max_cost_usd,
            max_total_tokens=max_total_tokens,
        )
        candidate_mean = _summary_number(candidate, "primary_metric_mean")
        baseline_mean = _summary_number(baseline, "primary_metric_mean")
        directional_delta = _power_directional_delta(
            candidate_mean,
            baseline_mean,
            direction=spec.primary_metric.direction,
        )
        plans.append(
            {
                "candidate_variant_id": variant.id,
                "provider": variant.provider,
                "model": variant.model,
                "status": status,
                "baseline_samples": baseline_count,
                "candidate_samples": candidate_count,
                "required_samples_per_variant": required,
                "additional_baseline_samples": additional_baseline,
                "additional_candidate_samples": additional_candidate,
                "additional_total_samples": additional_total,
                "observed_directional_delta": directional_delta,
                "observed_baseline_mean": (
                    round(baseline_mean, 6) if baseline_mean is not None else None
                ),
                "observed_candidate_mean": (
                    round(candidate_mean, 6) if candidate_mean is not None else None
                ),
                "pooled_stddev": round(sigma, 6) if sigma is not None else None,
                "stddev_source": sigma_source,
                "estimated_additional_cost_usd": (
                    round(cost_estimate, 6) if cost_estimate is not None else None
                ),
                "estimated_additional_tokens": (
                    int(math.ceil(token_estimate)) if token_estimate is not None else None
                ),
            }
        )
    return plans


def _power_stddev(
    baseline_values: list[float],
    candidate_values: list[float],
    *,
    global_stddev: float | None,
    fallback_stddev: float | None,
) -> tuple[float | None, str]:
    paired = _pooled_two_sample_stddev(baseline_values, candidate_values)
    if paired is not None and paired > 0:
        return paired, "observed-baseline-candidate"
    if global_stddev is not None and global_stddev > 0:
        return global_stddev, "observed-experiment"
    if fallback_stddev is not None:
        return fallback_stddev, "fallback"
    return None, "missing"


def _pooled_two_sample_stddev(values_a: list[float], values_b: list[float]) -> float | None:
    parts: list[tuple[list[float], float]] = []
    for values in (values_a, values_b):
        mean = _rounded_mean(values)
        stddev = _sample_stddev(values, mean=mean)
        if stddev is not None and len(values) >= 2:
            parts.append((values, stddev))
    degrees = sum(len(values) - 1 for values, _stddev in parts)
    if degrees <= 0:
        return None
    variance = sum((len(values) - 1) * (stddev**2) for values, stddev in parts) / degrees
    return math.sqrt(variance)


def _power_required_samples_per_variant(
    stddev: float,
    *,
    min_detectable_effect: float,
    alpha: float,
    power: float,
) -> int:
    if stddev <= 0:
        return 2
    z_alpha = NormalDist().inv_cdf(1.0 - alpha / 2.0)
    z_power = NormalDist().inv_cdf(power)
    required = 2.0 * ((z_alpha + z_power) * stddev / min_detectable_effect) ** 2
    return max(2, int(math.ceil(required)))


def _power_usage_means(
    spec: ExperimentSpec,
    outcomes: list[dict[str, object]],
) -> dict[str, dict[str, float | None]]:
    usage: dict[str, dict[str, float | None]] = {}
    for variant in spec.variants:
        variant_outcomes = [
            outcome for outcome in outcomes if _outcome_variant_id(outcome) == variant.id
        ]
        usage[variant.id] = _power_usage_mean_record(variant_outcomes)
    usage["_all"] = _power_usage_mean_record(outcomes)
    return usage


def _power_usage_mean_record(outcomes: list[dict[str, object]]) -> dict[str, float | None]:
    return {
        "cost_usd_mean": _rounded_mean(_usage_values(outcomes, "cost_usd")),
        "total_tokens_mean": _rounded_mean(_usage_values(outcomes, "total_tokens")),
    }


def _power_estimated_usage(
    usage_means: Mapping[str, dict[str, float | None]],
    *,
    key: str,
    baseline_variant_id: str,
    candidate_variant_id: str,
    additional_baseline: int | None,
    additional_candidate: int | None,
) -> float | None:
    if additional_baseline is None or additional_candidate is None:
        return None
    global_mean = (usage_means.get("_all") or {}).get(key)
    baseline_mean = (usage_means.get(baseline_variant_id) or {}).get(key)
    candidate_mean = (usage_means.get(candidate_variant_id) or {}).get(key)
    baseline_value = baseline_mean if baseline_mean is not None else global_mean
    candidate_value = candidate_mean if candidate_mean is not None else global_mean
    if baseline_value is None or candidate_value is None:
        return None
    return additional_baseline * float(baseline_value) + additional_candidate * float(candidate_value)


def _power_directional_delta(
    candidate_mean: float | None,
    baseline_mean: float | None,
    *,
    direction: str,
) -> float | None:
    if candidate_mean is None or baseline_mean is None:
        return None
    delta = candidate_mean - baseline_mean
    if direction == "minimize":
        delta = -delta
    return round(delta, 6)


def _power_variant_status(
    *,
    required: int | None,
    additional_total: int | None,
    estimated_additional_cost_usd: float | None,
    estimated_additional_tokens: float | None,
    max_cost_usd: float | None,
    max_total_tokens: int | None,
) -> str:
    if required is None or additional_total is None:
        return "insufficient-data"
    if additional_total == 0:
        return "ready"
    if max_cost_usd is not None:
        if estimated_additional_cost_usd is None:
            return "budget-unknown"
        if estimated_additional_cost_usd > max_cost_usd:
            return "budget-limited"
    if max_total_tokens is not None:
        if estimated_additional_tokens is None:
            return "budget-unknown"
        if estimated_additional_tokens > max_total_tokens:
            return "budget-limited"
    return "needs-samples"


def _power_summary(variant_plans: list[dict[str, object]]) -> dict[str, object]:
    required_values = [
        int(item["required_samples_per_variant"])
        for item in variant_plans
        if isinstance(item.get("required_samples_per_variant"), int)
    ]
    additional_values = [
        int(item["additional_total_samples"])
        for item in variant_plans
        if isinstance(item.get("additional_total_samples"), int)
    ]
    cost_values = [
        float(item["estimated_additional_cost_usd"])
        for item in variant_plans
        if isinstance(item.get("estimated_additional_cost_usd"), (int, float))
    ]
    token_values = [
        int(item["estimated_additional_tokens"])
        for item in variant_plans
        if isinstance(item.get("estimated_additional_tokens"), int)
    ]
    statuses = [str(item.get("status") or "") for item in variant_plans]
    return {
        "candidate_count": len(variant_plans),
        "ready_candidates": statuses.count("ready"),
        "needs_sample_candidates": statuses.count("needs-samples"),
        "budget_limited_candidates": statuses.count("budget-limited"),
        "budget_unknown_candidates": statuses.count("budget-unknown"),
        "insufficient_data_candidates": statuses.count("insufficient-data"),
        "max_required_samples_per_variant": max(required_values) if required_values else None,
        "total_additional_samples": sum(additional_values),
        "estimated_additional_cost_usd": round(sum(cost_values), 6) if cost_values else None,
        "estimated_additional_tokens": sum(token_values) if token_values else None,
    }


def _power_status(variant_plans: list[dict[str, object]]) -> str:
    if not variant_plans:
        return "insufficient-data"
    statuses = {str(item.get("status") or "") for item in variant_plans}
    if "budget-limited" in statuses:
        return "budget-limited"
    if "budget-unknown" in statuses:
        return "budget-unknown"
    if "insufficient-data" in statuses:
        return "insufficient-data"
    if "needs-samples" in statuses:
        return "needs-samples"
    return "ready"


def _power_recommendations(
    variant_plans: list[dict[str, object]],
    power_status: str,
) -> list[str]:
    if power_status == "ready":
        return ["Current outcome counts satisfy the requested power plan for every candidate."]
    if power_status == "insufficient-data":
        return ["Collect pilot outcomes or provide --fallback-stddev before trusting a power plan."]
    if power_status == "budget-limited":
        return ["Reduce the minimum detectable effect target, raise the budget, or run fewer candidate comparisons."]
    if power_status == "budget-unknown":
        return ["Log usage metadata or omit budget limits before using this power plan for spend decisions."]
    needs = [
        f"{item.get('candidate_variant_id')} (+{int(item.get('additional_total_samples') or 0)} samples)"
        for item in variant_plans
        if item.get("status") == "needs-samples"
    ]
    if needs:
        return ["Schedule more balanced matrix or suite runs for: " + ", ".join(needs) + "."]
    return ["Review the power plan before scheduling the next batch."]


def _load_power_record(
    vault: Path,
    *,
    experiment_slug: str,
    power_id: str | None,
) -> tuple[Path, dict[str, object]]:
    root = safe_child(vault, "agent-runs", experiment_slug)
    if power_id:
        safe_power = _safe_run_id(power_id)
        matches = sorted(root.glob(f"power/{safe_power}.json"))
        if not matches:
            raise FileNotFoundError(f"Agent power report not found: {safe_power}")
        return matches[-1], _read_json_object(matches[-1])
    power_dir = safe_child(root, "power")
    reports = sorted(power_dir.glob("*.json")) if power_dir.exists() else []
    parsed = []
    for path in reports:
        record = _read_json_object(path)
        if record.get("schema") == AGENT_POWER_SCHEMA:
            parsed.append((path, record))
    if not parsed:
        raise FileNotFoundError("Run agent-power before agent-schedule")
    return parsed[-1]


def _schedule_lanes(root: Path, *, lanes: tuple[str, ...] | None) -> tuple[AgentLane, ...]:
    if lanes:
        return tuple(AgentLane.from_value(item) for item in lanes)
    plans = _load_schema_records(root, "plans", AGENT_PLAN_SCHEMA)
    if plans:
        parallel = plans[-1].get("parallel") if isinstance(plans[-1].get("parallel"), dict) else {}
        raw_lanes = parallel.get("lanes") if isinstance(parallel, dict) else None
        if isinstance(raw_lanes, list) and raw_lanes:
            return tuple(AgentLane.from_value(item) for item in raw_lanes)
    return tuple(AgentLane.from_value(item) for item in DEFAULT_PARALLEL_LANES)


def _schedule_variant_quotas(
    power: Mapping[str, object],
    *,
    include_budget_limited: bool,
) -> tuple[dict[str, int], list[dict[str, object]]]:
    baseline = slugify(
        str(power.get("baseline_variant_id") or "baseline"),
        fallback="baseline",
    )
    allowed = {"needs-samples"}
    if include_budget_limited:
        allowed.update({"budget-limited", "budget-unknown"})
    quotas: dict[str, int] = {}
    baseline_needed = 0
    notes: list[dict[str, object]] = []
    plans = power.get("variant_plans") if isinstance(power.get("variant_plans"), list) else []
    for item in plans:
        if not isinstance(item, dict):
            continue
        status = str(item.get("status") or "")
        candidate = slugify(
            str(item.get("candidate_variant_id") or "candidate"),
            fallback="candidate",
        )
        add_baseline = _non_negative_count(item.get("additional_baseline_samples"))
        add_candidate = _non_negative_count(item.get("additional_candidate_samples"))
        notes.append(
            {
                "candidate_variant_id": candidate,
                "power_status": status,
                "additional_baseline_samples": add_baseline,
                "additional_candidate_samples": add_candidate,
                "scheduled": status in allowed and (add_baseline + add_candidate) > 0,
            }
        )
        if status not in allowed:
            continue
        baseline_needed = max(baseline_needed, add_baseline)
        quotas[candidate] = max(quotas.get(candidate, 0), add_candidate)
    if baseline_needed:
        quotas[baseline] = max(quotas.get(baseline, 0), baseline_needed)
    return quotas, notes


def _schedule_assignments(
    power: Mapping[str, object],
    *,
    lanes: tuple[AgentLane, ...],
    max_runs: int,
    include_budget_limited: bool,
    paired: bool,
) -> tuple[list[dict[str, object]], list[dict[str, object]], int, dict[str, int], bool]:
    if paired:
        return _schedule_paired_assignments(
            power,
            lanes=lanes,
            max_runs=max_runs,
            include_budget_limited=include_budget_limited,
        )
    quotas, notes = _schedule_variant_quotas(
        power,
        include_budget_limited=include_budget_limited,
    )
    requested_runs = sum(quotas.values())
    limited_quotas = _cap_schedule_quotas(quotas, max_runs=max_runs)
    assignments = _schedule_unpaired_assignments(limited_quotas, lanes=lanes)
    return assignments, notes, requested_runs, limited_quotas, len(assignments) < requested_runs


def _schedule_paired_assignments(
    power: Mapping[str, object],
    *,
    lanes: tuple[AgentLane, ...],
    max_runs: int,
    include_budget_limited: bool,
) -> tuple[list[dict[str, object]], list[dict[str, object]], int, dict[str, int], bool]:
    baseline = slugify(
        str(power.get("baseline_variant_id") or "baseline"),
        fallback="baseline",
    )
    allowed = {"needs-samples"}
    if include_budget_limited:
        allowed.update({"budget-limited", "budget-unknown"})
    assignments: list[dict[str, object]] = []
    notes: list[dict[str, object]] = []
    requested_runs = 0
    pair_index = 0
    plans = power.get("variant_plans") if isinstance(power.get("variant_plans"), list) else []
    for item in plans:
        if not isinstance(item, dict):
            continue
        status = str(item.get("status") or "")
        candidate = slugify(
            str(item.get("candidate_variant_id") or "candidate"),
            fallback="candidate",
        )
        add_baseline = _non_negative_count(item.get("additional_baseline_samples"))
        add_candidate = _non_negative_count(item.get("additional_candidate_samples"))
        requested_pairs = max(add_baseline, add_candidate) if status in allowed else 0
        requested_runs += requested_pairs * 2
        scheduled_pairs = 0
        for sample_index in range(1, requested_pairs + 1):
            if len(assignments) + 2 > max_runs:
                continue
            pair_index += 1
            scheduled_pairs += 1
            lane = lanes[(pair_index - 1) % len(lanes)]
            block_id = _schedule_block_id(candidate, pair_index)
            assignments.extend(
                [
                    {
                        "variant_id": baseline,
                        "lane": lane,
                        "sample_index": sample_index,
                        "block_id": block_id,
                        "comparison_role": "baseline",
                        "candidate_variant_id": candidate,
                    },
                    {
                        "variant_id": candidate,
                        "lane": lane,
                        "sample_index": sample_index,
                        "block_id": block_id,
                        "comparison_role": "candidate",
                        "candidate_variant_id": candidate,
                    },
                ]
            )
        notes.append(
            {
                "candidate_variant_id": candidate,
                "power_status": status,
                "additional_baseline_samples": add_baseline,
                "additional_candidate_samples": add_candidate,
                "requested_pairs": requested_pairs,
                "scheduled_pairs": scheduled_pairs,
                "scheduled": scheduled_pairs > 0,
            }
        )
    quotas = _schedule_assignment_quotas(assignments)
    return assignments, notes, requested_runs, quotas, len(assignments) < requested_runs


def _schedule_unpaired_assignments(
    quotas: Mapping[str, int],
    *,
    lanes: tuple[AgentLane, ...],
) -> list[dict[str, object]]:
    assignments: list[dict[str, object]] = []
    lane_index = 0
    for variant_id, count in sorted(quotas.items()):
        for sample_index in range(1, max(0, int(count)) + 1):
            lane = lanes[lane_index % len(lanes)]
            lane_index += 1
            assignments.append(
                {
                    "variant_id": variant_id,
                    "lane": lane,
                    "sample_index": sample_index,
                }
            )
    return assignments


def _schedule_assignment_quotas(assignments: list[dict[str, object]]) -> dict[str, int]:
    quotas: dict[str, int] = {}
    for assignment in assignments:
        variant_id = str(assignment.get("variant_id") or "")
        if variant_id:
            quotas[variant_id] = quotas.get(variant_id, 0) + 1
    return quotas


def _schedule_block_id(candidate_variant_id: str, pair_index: int) -> str:
    return _safe_text_label(
        f"block-{slugify(candidate_variant_id, fallback='candidate')}-{pair_index:04d}",
        field="block_id",
        max_length=120,
    )


def _non_negative_count(value: object) -> int:
    if isinstance(value, int) and value > 0:
        return value
    return 0


def _cap_schedule_quotas(quotas: Mapping[str, int], *, max_runs: int) -> dict[str, int]:
    remaining = {variant: max(0, int(count)) for variant, count in quotas.items()}
    capped = {variant: 0 for variant in remaining}
    while sum(capped.values()) < max_runs and any(count > 0 for count in remaining.values()):
        for variant_id in sorted(remaining):
            if remaining[variant_id] <= 0:
                continue
            capped[variant_id] += 1
            remaining[variant_id] -= 1
            if sum(capped.values()) >= max_runs:
                break
    return capped


def _write_scheduled_runs(
    vault: Path,
    spec: ExperimentSpec,
    *,
    plan_id: str,
    schedule_id: str,
    power_id: str,
    subject_key: str,
    lanes: tuple[AgentLane, ...],
    assignments: list[dict[str, object]],
) -> tuple[list[AgentRunResult], list[dict[str, object]]]:
    variants = {variant.id: variant for variant in spec.variants}
    results: list[AgentRunResult] = []
    records: list[dict[str, object]] = []
    del lanes
    for index, assignment in enumerate(assignments, start=1):
        variant_id = str(assignment.get("variant_id") or "")
        variant = variants.get(variant_id)
        if variant is None:
            raise ValueError(f"scheduled variant is not in experiment config: {variant_id}")
        lane = assignment.get("lane")
        if not isinstance(lane, AgentLane):
            raise ValueError("scheduled assignment is missing lane metadata")
        sample_index = int(assignment.get("sample_index") or index)
        block_id = assignment.get("block_id") if isinstance(assignment.get("block_id"), str) else None
        comparison_role = (
            assignment.get("comparison_role")
            if isinstance(assignment.get("comparison_role"), str)
            else None
        )
        candidate_variant_id = (
            assignment.get("candidate_variant_id")
            if isinstance(assignment.get("candidate_variant_id"), str)
            else None
        )
        child_subject = (
            f"{subject_key}\0{schedule_id}\0{plan_id}\0"
            f"{variant_id}\0{lane.id}\0{sample_index}\0{block_id or 'unpaired'}"
        )
        context = {
            "plan_id": plan_id,
            "schedule_id": schedule_id,
            "power_id": power_id,
            "lane_id": lane.id,
            "role": lane.role,
            "replica": sample_index,
            "merge_strategy": "scoreboard",
            "strategy": "power-schedule",
            "scheduled_variant_id": variant_id,
        }
        if block_id:
            context["block_id"] = block_id
        if comparison_role:
            context["comparison_role"] = comparison_role
        if candidate_variant_id:
            context["block_candidate_variant_id"] = candidate_variant_id
        if lane.objective:
            context["objective"] = lane.objective
        run = _write_agent_run(
            vault,
            spec,
            selected=variant,
            bucket=_matrix_assignment_bucket(spec, variant),
            subject_key=child_subject,
            prompt_text=None,
            prompt_source_name=None,
            parallel_context=context,
            assignment_strategy="power-schedule",
        )
        results.append(run)
        record = {
            "run_id": run.run_id,
            "lane_id": lane.id,
            "role": lane.role,
            "replica": sample_index,
            "variant_id": run.variant_id,
            "path": _relative_vault_path(vault, run.path),
            "schedule_id": schedule_id,
            "power_id": power_id,
        }
        if block_id:
            record["block_id"] = block_id
        if comparison_role:
            record["comparison_role"] = comparison_role
        if candidate_variant_id:
            record["block_candidate_variant_id"] = candidate_variant_id
        records.append(record)
    return results, records


def _scheduled_plan_payload(
    spec: ExperimentSpec,
    *,
    generated_at: str,
    plan_id: str,
    schedule_id: str,
    power_id: str,
    subject_hash: str,
    prompt: Mapping[str, object],
    lanes: tuple[AgentLane, ...],
    run_records: list[dict[str, object]],
    paired: bool,
) -> dict[str, object]:
    blocks = _schedule_blocks_from_records(run_records)
    return {
        "schema": AGENT_PLAN_SCHEMA,
        "plan_id": plan_id,
        "generated_at": generated_at,
        "experiment": {
            "name": spec.name,
            "slug": spec.slug,
            "config_hash": _hash_json(spec.as_dict()),
            "description": spec.description,
            "primary_metric": spec.primary_metric.as_dict(),
            "rubric": spec.rubric.as_dict(),
            "traffic_salt": spec.traffic_salt,
            "guardrails": list(spec.guardrails),
            "min_trials_per_variant": spec.min_trials_per_variant,
        },
        "parallel": {
            "strategy": "power-schedule",
            "merge_strategy": "scoreboard",
            "replicas": 1,
            "lane_count": len(lanes),
            "variant_count": len({str(item.get("variant_id")) for item in run_records}),
            "run_count": len(run_records),
            "lanes": [item.as_dict() for item in lanes],
            "subject_hash": subject_hash,
        },
        "schedule": {
            "schedule_id": schedule_id,
            "power_id": power_id,
            "strategy": "power-schedule",
            "paired": paired,
            "block_count": len(blocks),
            "blocks": blocks,
        },
        "variants": [item.as_dict() for item in spec.variants],
        "prompt": dict(prompt),
        "runs": run_records,
        "privacy": {
            "mode": "metadata-only",
            "omitted_fields": ["subject_key", "prompt_text", "raw_transcript", "raw_output"],
        },
    }


def _schedule_blocks_from_records(run_records: list[dict[str, object]]) -> list[dict[str, object]]:
    blocks: dict[str, dict[str, object]] = {}
    for record in run_records:
        block_id = record.get("block_id")
        if not isinstance(block_id, str):
            continue
        block = blocks.setdefault(
            block_id,
            {
                "block_id": block_id,
                "lane_id": record.get("lane_id"),
                "candidate_variant_id": record.get("block_candidate_variant_id"),
                "runs": [],
            },
        )
        runs = block.get("runs")
        if isinstance(runs, list):
            runs.append(
                {
                    "run_id": record.get("run_id"),
                    "variant_id": record.get("variant_id"),
                    "comparison_role": record.get("comparison_role"),
                }
            )
    return [
        block
        for block in sorted(blocks.values(), key=lambda item: str(item.get("block_id") or ""))
        if isinstance(block.get("runs"), list) and len(block["runs"]) == 2
    ]


def _schedule_recommendations(
    schedule_status: str,
    summary: Mapping[str, object],
) -> list[str]:
    if schedule_status == "no-runs":
        return ["No additional runs were scheduled; review the latest agent-power report or lower the target effect size."]
    if schedule_status == "scheduled-partial":
        return [
            f"Dispatch the {int(summary.get('scheduled_runs') or 0)} scheduled run(s), then rerun agent-schedule for the remaining power gap."
        ]
    return ["Dispatch the scheduled plan, run workers, then ingest metadata-only outcomes and rerun agent-power."]


def _load_schedule_record(vault: Path, schedule_id: str) -> tuple[Path, dict[str, object]]:
    agent_root = safe_child(vault, "agent-runs")
    if not agent_root.is_dir():
        raise FileNotFoundError(f"Agent schedule not found: {schedule_id}")
    matches: list[tuple[Path, dict[str, object]]] = []
    for root in sorted(agent_root.iterdir()):
        if root.name.startswith("_") or not root.is_dir() or root.is_symlink():
            continue
        path = root / "schedules" / f"{schedule_id}.json"
        if not path.is_file():
            continue
        record = _read_json_object(path)
        if record.get("schema") == AGENT_SCHEDULE_SCHEMA and record.get("schedule_id") == schedule_id:
            matches.append((path, record))
    if not matches:
        raise FileNotFoundError(f"Agent schedule not found: {schedule_id}")
    return matches[-1]


def _schedule_report_blocks(
    schedule: Mapping[str, object],
    *,
    outcomes_by_run: Mapping[str, dict[str, object]],
    metric: MetricSpec,
) -> list[dict[str, object]]:
    raw_blocks = schedule.get("blocks")
    if not isinstance(raw_blocks, list):
        return []
    blocks: list[dict[str, object]] = []
    for raw_block in raw_blocks:
        if not isinstance(raw_block, dict):
            continue
        block_id = _safe_text_label(
            str(raw_block.get("block_id") or "block"),
            field="block_id",
            max_length=120,
        )
        candidate_variant_id = slugify(
            str(raw_block.get("candidate_variant_id") or "candidate"),
            fallback="candidate",
        )
        lane_id = _optional_safe_text(raw_block.get("lane_id"), field="lane_id", max_length=80)
        runs = raw_block.get("runs") if isinstance(raw_block.get("runs"), list) else []
        baseline_ref, candidate_ref = _schedule_report_role_refs(
            runs,
            candidate_variant_id=candidate_variant_id,
        )
        baseline = _schedule_report_run_result(
            baseline_ref,
            outcomes_by_run=outcomes_by_run,
            metric=metric,
            expected_role="baseline",
        )
        candidate = _schedule_report_run_result(
            candidate_ref,
            outcomes_by_run=outcomes_by_run,
            metric=metric,
            expected_role="candidate",
        )
        baseline_metric = baseline.get("metric")
        candidate_metric = candidate.get("metric")
        has_pair = isinstance(baseline_metric, (int, float)) and isinstance(candidate_metric, (int, float))
        raw_delta = None
        directional_delta = None
        if has_pair:
            raw_delta = round(float(candidate_metric) - float(baseline_metric), 6)
            directional_delta = raw_delta if metric.direction == "maximize" else round(-raw_delta, 6)
        status = _schedule_report_block_status(baseline, candidate, has_pair=has_pair)
        block: dict[str, object] = {
            "block_id": block_id,
            "lane_id": lane_id,
            "candidate_variant_id": candidate_variant_id,
            "block_status": status,
            "baseline_run_id": baseline.get("run_id"),
            "candidate_run_id": candidate.get("run_id"),
            "baseline_variant_id": baseline.get("variant_id"),
            "candidate_variant_id_observed": candidate.get("variant_id"),
            "baseline_status": baseline.get("status"),
            "candidate_status": candidate.get("status"),
            "baseline_metric": baseline_metric,
            "candidate_metric": candidate_metric,
            "raw_delta": raw_delta,
            "directional_delta": directional_delta,
            "comparison_status": _schedule_report_delta_status(directional_delta),
            "runs": [baseline, candidate],
        }
        blocks.append(block)
    return blocks


def _schedule_report_role_refs(
    runs: list[object],
    *,
    candidate_variant_id: str,
) -> tuple[Mapping[str, object] | None, Mapping[str, object] | None]:
    refs = [item for item in runs if isinstance(item, dict)]
    baseline = next((item for item in refs if item.get("comparison_role") == "baseline"), None)
    candidate = next((item for item in refs if item.get("comparison_role") == "candidate"), None)
    if baseline is not None and candidate is not None:
        return baseline, candidate
    candidate = next(
        (
            item
            for item in refs
            if slugify(str(item.get("variant_id") or ""), fallback="variant") == candidate_variant_id
        ),
        candidate,
    )
    if candidate is not None:
        baseline = next((item for item in refs if item is not candidate), baseline)
    elif len(refs) >= 2:
        baseline, candidate = refs[0], refs[1]
    return baseline, candidate


def _schedule_report_run_result(
    run_ref: Mapping[str, object] | None,
    *,
    outcomes_by_run: Mapping[str, dict[str, object]],
    metric: MetricSpec,
    expected_role: str,
) -> dict[str, object]:
    if run_ref is None:
        return {
            "run_id": None,
            "variant_id": None,
            "comparison_role": expected_role,
            "status": "missing-run",
            "outcome_id": None,
            "metric": None,
        }
    run_id = str(run_ref.get("run_id") or "")
    variant_id = slugify(str(run_ref.get("variant_id") or "variant"), fallback="variant")
    outcome = outcomes_by_run.get(run_id)
    if outcome is None:
        return {
            "run_id": run_id or None,
            "variant_id": variant_id,
            "comparison_role": str(run_ref.get("comparison_role") or expected_role),
            "status": "pending",
            "outcome_id": None,
            "metric": None,
        }
    metrics = outcome.get("metrics") if isinstance(outcome.get("metrics"), dict) else {}
    value = metrics.get(metric.name) if isinstance(metrics, dict) else None
    metric_value = (
        round(float(value), 6)
        if isinstance(value, (int, float)) and math.isfinite(float(value))
        else None
    )
    return {
        "run_id": run_id or None,
        "variant_id": variant_id,
        "comparison_role": str(run_ref.get("comparison_role") or expected_role),
        "status": str(outcome.get("status") or "unknown"),
        "outcome_id": outcome.get("outcome_id"),
        "metric": metric_value,
    }


def _schedule_report_block_status(
    baseline: Mapping[str, object],
    candidate: Mapping[str, object],
    *,
    has_pair: bool,
) -> str:
    if has_pair:
        return "complete"
    statuses = {str(baseline.get("status") or ""), str(candidate.get("status") or "")}
    if statuses <= {"pending", "missing-run", ""}:
        return "no-outcomes"
    return "partial"


def _schedule_report_delta_status(directional_delta: object) -> str:
    if not isinstance(directional_delta, (int, float)):
        return "insufficient-data"
    if float(directional_delta) > 0:
        return "candidate-ahead"
    if float(directional_delta) < 0:
        return "candidate-behind"
    return "tied"


def _schedule_report_baseline(
    block_summaries: list[dict[str, object]],
    *,
    spec: ExperimentSpec,
) -> str:
    observed = [
        str(item.get("baseline_variant_id"))
        for item in block_summaries
        if isinstance(item.get("baseline_variant_id"), str)
    ]
    if observed:
        return max(sorted(set(observed)), key=observed.count)
    return _current_champion_variant_id(spec)


def _schedule_report_pairwise(
    spec: ExperimentSpec,
    block_summaries: list[dict[str, object]],
    *,
    baseline_variant_id: str,
) -> list[dict[str, object]]:
    observed_candidates = {
        str(item.get("candidate_variant_id"))
        for item in block_summaries
        if isinstance(item.get("candidate_variant_id"), str)
    }
    variant_candidates = {variant.id for variant in spec.variants if variant.id != baseline_variant_id}
    candidates = sorted(observed_candidates | variant_candidates)
    pairwise: list[dict[str, object]] = []
    for candidate_id in candidates:
        candidate_blocks = [
            item
            for item in block_summaries
            if item.get("candidate_variant_id") == candidate_id
        ]
        deltas = [
            float(item["directional_delta"])
            for item in candidate_blocks
            if isinstance(item.get("directional_delta"), (int, float))
        ]
        mean = sum(deltas) / len(deltas) if deltas else None
        stddev = _sample_stddev(deltas, mean=mean) if mean is not None else None
        stderr = stddev / math.sqrt(len(deltas)) if stddev is not None and deltas else None
        ci = _confidence_interval(mean, stderr)
        z_score = mean / stderr if mean is not None and stderr and stderr > 0 else None
        block_deltas = [
            {
                "block_id": item.get("block_id"),
                "lane_id": item.get("lane_id"),
                "baseline_run_id": item.get("baseline_run_id"),
                "candidate_run_id": item.get("candidate_run_id"),
                "baseline_metric": item.get("baseline_metric"),
                "candidate_metric": item.get("candidate_metric"),
                "directional_delta": item.get("directional_delta"),
                "status": item.get("comparison_status"),
            }
            for item in candidate_blocks
            if isinstance(item.get("directional_delta"), (int, float))
        ]
        pairwise.append(
            {
                "baseline_variant_id": baseline_variant_id,
                "candidate_variant_id": candidate_id,
                "scheduled_blocks": len(candidate_blocks),
                "paired_blocks": len(deltas),
                "mean_directional_delta": round(mean, 6) if mean is not None else None,
                "delta_stddev": round(stddev, 6) if stddev is not None else None,
                "delta_stderr": round(stderr, 6) if stderr is not None else None,
                "delta_ci95": ci,
                "wins": sum(1 for value in deltas if value > 0),
                "losses": sum(1 for value in deltas if value < 0),
                "ties": sum(1 for value in deltas if value == 0),
                "confidence": _comparison_confidence_label(z_score),
                "status": _suite_pairwise_status(mean, ci, len(deltas)),
                "block_deltas": block_deltas,
            }
        )
    return pairwise


def _schedule_report_lane_summaries(pairwise: list[dict[str, object]]) -> list[dict[str, object]]:
    lanes: dict[tuple[str, str], dict[str, object]] = {}
    for comparison in pairwise:
        candidate_id = str(comparison.get("candidate_variant_id") or "")
        block_deltas = comparison.get("block_deltas")
        if not isinstance(block_deltas, list):
            continue
        for delta in block_deltas:
            if not isinstance(delta, dict) or not isinstance(delta.get("directional_delta"), (int, float)):
                continue
            lane_id = str(delta.get("lane_id") or "")
            key = (candidate_id, lane_id)
            lane = lanes.setdefault(
                key,
                {
                    "candidate_variant_id": candidate_id,
                    "lane_id": lane_id,
                    "paired_blocks": 0,
                    "wins": 0,
                    "losses": 0,
                    "ties": 0,
                    "_deltas": [],
                },
            )
            value = float(delta["directional_delta"])
            lane["paired_blocks"] = int(lane["paired_blocks"]) + 1
            if value > 0:
                lane["wins"] = int(lane["wins"]) + 1
            elif value < 0:
                lane["losses"] = int(lane["losses"]) + 1
            else:
                lane["ties"] = int(lane["ties"]) + 1
            deltas = lane["_deltas"]
            if isinstance(deltas, list):
                deltas.append(value)
    summaries: list[dict[str, object]] = []
    for lane in lanes.values():
        deltas = [float(value) for value in lane.pop("_deltas", []) if isinstance(value, (int, float))]
        mean = sum(deltas) / len(deltas) if deltas else None
        summaries.append(
            {
                "candidate_variant_id": lane["candidate_variant_id"],
                "lane_id": lane["lane_id"],
                "paired_blocks": lane["paired_blocks"],
                "mean_directional_delta": round(mean, 6) if mean is not None else None,
                "wins": lane["wins"],
                "losses": lane["losses"],
                "ties": lane["ties"],
                "status": _schedule_report_delta_status(mean),
            }
        )
    return sorted(
        summaries,
        key=lambda item: (
            str(item.get("candidate_variant_id") or ""),
            str(item.get("lane_id") or ""),
        ),
    )


def _schedule_report_winner(pairwise: list[dict[str, object]]) -> str | None:
    scored = [
        item
        for item in pairwise
        if isinstance(item.get("mean_directional_delta"), (int, float))
        and int(item.get("paired_blocks") or 0) > 0
    ]
    if not scored:
        return None
    ranked_status = {
        "beats-baseline": 4,
        "candidate-ahead": 3,
        "tied": 2,
        "candidate-behind": 1,
        "trails-baseline": 0,
    }
    winner = max(
        scored,
        key=lambda item: (
            ranked_status.get(str(item.get("status") or ""), -1),
            float(item.get("mean_directional_delta") or 0.0),
            int(item.get("wins") or 0),
        ),
    )
    if float(winner.get("mean_directional_delta") or 0.0) <= 0:
        return None
    return str(winner["candidate_variant_id"])


def _schedule_report_summary(
    block_summaries: list[dict[str, object]],
    pairwise: list[dict[str, object]],
    *,
    min_completed_blocks_ratio: float,
) -> dict[str, object]:
    block_count = len(block_summaries)
    complete_blocks = sum(1 for item in block_summaries if item.get("block_status") == "complete")
    partial_blocks = sum(1 for item in block_summaries if item.get("block_status") == "partial")
    no_outcome_blocks = sum(1 for item in block_summaries if item.get("block_status") == "no-outcomes")
    completed_ratio = round(complete_blocks / block_count, 6) if block_count else 0.0
    return {
        "block_count": block_count,
        "complete_blocks": complete_blocks,
        "partial_blocks": partial_blocks,
        "no_outcome_blocks": no_outcome_blocks,
        "completed_ratio": completed_ratio,
        "required_completed_ratio": min_completed_blocks_ratio,
        "ready": bool(block_count and completed_ratio >= min_completed_blocks_ratio),
        "paired_comparisons": sum(int(item.get("paired_blocks") or 0) for item in pairwise),
        "beats_baseline": sum(1 for item in pairwise if item.get("status") == "beats-baseline"),
        "trails_baseline": sum(1 for item in pairwise if item.get("status") == "trails-baseline"),
        "inconclusive": sum(
            1
            for item in pairwise
            if item.get("status") in {"candidate-ahead", "candidate-behind", "tied"}
        ),
        "insufficient_data": sum(1 for item in pairwise if item.get("status") == "insufficient-data"),
    }


def _schedule_report_status(summary: Mapping[str, object]) -> str:
    block_count = int(summary.get("block_count") or 0)
    complete_blocks = int(summary.get("complete_blocks") or 0)
    if block_count == 0:
        return "no-blocks"
    if complete_blocks == 0:
        return "no-outcomes"
    if not summary.get("ready"):
        return "partial"
    return "complete"


def _schedule_report_recommendations(
    summary: Mapping[str, object],
    pairwise: list[dict[str, object]],
    *,
    baseline_variant_id: str,
    winner_variant_id: str | None,
) -> list[str]:
    if int(summary.get("block_count") or 0) == 0:
        return ["Run a paired agent-schedule batch before requesting schedule evidence."]
    recommendations: list[str] = []
    if not summary.get("ready"):
        missing = int(summary.get("block_count") or 0) - int(summary.get("complete_blocks") or 0)
        recommendations.append(
            f"Log metadata-only outcomes for {missing} incomplete schedule block(s), then rerun agent-schedule-report."
        )
    strong = [
        str(item["candidate_variant_id"])
        for item in pairwise
        if item.get("status") == "beats-baseline"
    ]
    ahead = [
        str(item["candidate_variant_id"])
        for item in pairwise
        if item.get("status") == "candidate-ahead"
    ]
    if strong:
        recommendations.append(
            f"Review promotion or rollout evidence for candidate(s) beating baseline {baseline_variant_id}: {', '.join(strong)}."
        )
    elif ahead:
        recommendations.append(
            f"Candidate(s) ahead without strong interval evidence: {', '.join(ahead)}. Continue paired sampling before promotion."
        )
    elif int(summary.get("paired_comparisons") or 0):
        recommendations.append(
            f"No candidate has beaten baseline {baseline_variant_id}; keep the baseline or schedule another powered batch."
        )
    if winner_variant_id:
        recommendations.append(f"Current paired schedule winner is {winner_variant_id}.")
    if not recommendations:
        recommendations.append("No paired schedule evidence is ready yet.")
    return recommendations


def _leaderboard_evidence_records(
    vault: Path,
    root: Path,
    experiment_slug: str,
) -> dict[str, dict[str, object] | None]:
    budget_reports = _budget_reports_for_experiment(vault, experiment_slug)
    return {
        "comparison": _latest_schema_record(root, "comparisons", AGENT_COMPARISON_SCHEMA),
        "suite_report": _latest_schema_record(root, "suite-reports", AGENT_SUITE_REPORT_SCHEMA),
        "arena_report": _latest_schema_record(root, "arena-reports", AGENT_ARENA_REPORT_SCHEMA),
        "judge_report": _latest_schema_record(root, "judge-panel-reports", AGENT_JUDGE_PANEL_REPORT_SCHEMA),
        "schedule": _latest_schema_record(root, "schedules", AGENT_SCHEDULE_SCHEMA),
        "schedule_report": _latest_schema_record(root, "schedule-reports", AGENT_SCHEDULE_REPORT_SCHEMA),
        "allocation": _latest_schema_record(root, "allocations", AGENT_ALLOCATION_SCHEMA),
        "route": _latest_schema_record(root, "routes", AGENT_ROUTE_SCHEMA),
        "promotion": _latest_schema_record(root, "promotions", AGENT_PROMOTION_SCHEMA),
        "decision": _latest_schema_record(root, "decisions", AGENT_DECISION_SCHEMA),
        "readiness": _latest_schema_record(root, "readiness", AGENT_READINESS_SCHEMA),
        "power": _latest_schema_record(root, "power", AGENT_POWER_SCHEMA),
        "budget": budget_reports[-1] if budget_reports else None,
    }


def _leaderboard_source_artifacts(
    records: Mapping[str, Mapping[str, object] | None],
) -> dict[str, object]:
    artifact_specs = {
        "comparison": ("comparison_id", None, "winner_variant_id"),
        "suite_report": ("report_id", None, "winner_variant_id"),
        "arena_report": ("report_id", "report_status", "winner_variant_id"),
        "judge_report": ("report_id", "report_status", "winner_variant_id"),
        "schedule": ("schedule_id", "schedule_status", None),
        "schedule_report": ("report_id", "report_status", "winner_variant_id"),
        "allocation": ("allocation_id", "strategy", "winner_variant_id"),
        "route": ("route_id", None, None),
        "promotion": ("promotion_id", "promotion_status", "candidate_variant_id"),
        "decision": ("decision_id", "decision_status", "candidate_variant_id"),
        "readiness": ("readiness_id", "readiness_status", None),
        "power": ("power_id", "power_status", None),
        "budget": ("budget_id", "budget_status", None),
    }
    refs: dict[str, object] = {}
    for name, record in records.items():
        if not isinstance(record, Mapping):
            continue
        id_key, status_key, winner_key = artifact_specs[name]
        extra: dict[str, object] = {}
        if name == "budget":
            extra["over_budget"] = bool(record.get("over_budget"))
        if name == "route":
            summary = record.get("summary") if isinstance(record.get("summary"), dict) else {}
            extra["recommended_routes"] = int(summary.get("recommended_routes") or 0)
        refs[name] = _memory_report_ref(
            record,
            id_key=id_key,
            status_key=status_key,
            winner_key=winner_key,
            extra=extra,
        )
    return refs


def _leaderboard_rows(
    spec: ExperimentSpec,
    summaries: list[dict[str, object]],
    records: Mapping[str, Mapping[str, object] | None],
    *,
    baseline_variant_id: str,
    min_samples: int,
) -> list[dict[str, object]]:
    summary_by_variant = {
        str(item["variant_id"]): item
        for item in summaries
        if isinstance(item.get("variant_id"), str)
    }
    metric_ranks = _leaderboard_metric_ranks(spec, summaries, min_samples=min_samples)
    comparison = records.get("comparison")
    suite_report = records.get("suite_report")
    arena_report = records.get("arena_report")
    judge_report = records.get("judge_report")
    schedule_report = records.get("schedule_report")
    allocation = records.get("allocation")
    route = records.get("route")
    promotion = records.get("promotion")
    decision = records.get("decision")
    rows: list[dict[str, object]] = []
    for variant in spec.variants:
        summary = summary_by_variant.get(variant.id, {})
        usage = summary.get("usage") if isinstance(summary.get("usage"), dict) else {}
        metric_points = metric_ranks.get(variant.id, 0.0)
        comparison_evidence = _leaderboard_pairwise_evidence(
            comparison,
            variant.id,
            baseline_variant_id=baseline_variant_id,
            paired_count_key=None,
        )
        suite_evidence = _leaderboard_pairwise_evidence(
            suite_report,
            variant.id,
            baseline_variant_id=baseline_variant_id,
            paired_count_key="paired_cases",
        )
        arena_evidence = _leaderboard_arena_evidence(arena_report, variant.id)
        judge_evidence = _leaderboard_judge_evidence(judge_report, variant.id)
        schedule_evidence = _leaderboard_pairwise_evidence(
            schedule_report,
            variant.id,
            baseline_variant_id=baseline_variant_id,
            paired_count_key="paired_blocks",
        )
        allocation_evidence = _leaderboard_allocation_evidence(allocation, variant.id)
        route_evidence = _leaderboard_route_evidence(route, variant.id)
        promotion_evidence = _leaderboard_promotion_evidence(promotion, variant.id)
        decision_evidence = _leaderboard_decision_evidence(decision, variant.id)
        frontier_points = _leaderboard_frontier_points(
            variant.id,
            comparison=comparison,
            suite_report=suite_report,
        )
        evidence_score = round(
            metric_points
            + float(comparison_evidence["points"])
            + float(suite_evidence["points"])
            + float(arena_evidence["points"])
            + float(judge_evidence["points"])
            + float(schedule_evidence["points"])
            + float(allocation_evidence["points"])
            + float(route_evidence["points"])
            + float(promotion_evidence["points"])
            + float(decision_evidence["points"])
            + frontier_points,
            6,
        )
        row = {
            "rank": 0,
            "variant_id": variant.id,
            "provider": variant.provider,
            "model": variant.model,
            "adapter": variant.adapter,
            "current_weight": round(variant.weight, 6),
            "primary_metric_count": int(summary.get("primary_metric_count") or 0),
            "primary_metric_mean": summary.get("primary_metric_mean"),
            "primary_metric_stderr": summary.get("primary_metric_stderr"),
            "success_rate": summary.get("success_rate"),
            "trials": int(summary.get("trials") or 0),
            "failures": int(summary.get("failures") or 0),
            "usage": usage,
            "metric_rank_points": round(metric_points, 6),
            "evidence_score": evidence_score,
            "evidence": {
                "comparison": comparison_evidence,
                "suite": suite_evidence,
                "arena": arena_evidence,
                "judge": judge_evidence,
                "schedule": schedule_evidence,
                "allocation": allocation_evidence,
                "route": route_evidence,
                "promotion": promotion_evidence,
                "decision": decision_evidence,
                "pareto_frontier_points": frontier_points,
            },
            "reasons": _leaderboard_row_reasons(
                metric_points=metric_points,
                comparison=comparison_evidence,
                suite=suite_evidence,
                arena=arena_evidence,
                judge=judge_evidence,
                schedule=schedule_evidence,
                allocation=allocation_evidence,
                route=route_evidence,
                promotion=promotion_evidence,
                decision=decision_evidence,
                frontier_points=frontier_points,
            ),
        }
        rows.append(row)
    rows.sort(
        key=lambda item: (
            -float(item.get("evidence_score") or 0.0),
            -int(item.get("primary_metric_count") or 0),
            str(item.get("variant_id") or ""),
        )
    )
    for rank, row in enumerate(rows, start=1):
        row["rank"] = rank
    return rows


def _leaderboard_metric_ranks(
    spec: ExperimentSpec,
    summaries: list[dict[str, object]],
    *,
    min_samples: int,
) -> dict[str, float]:
    measured = [
        item
        for item in summaries
        if int(item.get("primary_metric_count") or 0) >= min_samples
        and isinstance(item.get("primary_metric_mean"), (int, float))
    ]
    reverse = spec.primary_metric.direction == "maximize"
    measured.sort(
        key=lambda item: float(item.get("primary_metric_mean") or 0.0),
        reverse=reverse,
    )
    total = len(measured)
    return {
        str(item["variant_id"]): float(total - index)
        for index, item in enumerate(measured)
        if isinstance(item.get("variant_id"), str)
    }


def _leaderboard_pairwise_evidence(
    record: Mapping[str, object] | None,
    variant_id: str,
    *,
    baseline_variant_id: str,
    paired_count_key: str | None,
) -> dict[str, object]:
    if not isinstance(record, Mapping):
        return {"status": "missing", "points": 0.0}
    if variant_id == baseline_variant_id:
        return {
            "status": "baseline",
            "points": _leaderboard_baseline_points(record, baseline_variant_id=baseline_variant_id),
        }
    pairwise = record.get("pairwise") if isinstance(record.get("pairwise"), list) else []
    for item in pairwise:
        if not isinstance(item, dict) or item.get("candidate_variant_id") != variant_id:
            continue
        status = str(item.get("status") or "unknown")
        mean = item.get("mean_directional_delta")
        count = (
            int(item.get(paired_count_key) or 0)
            if paired_count_key
            else min(
                int(item.get("baseline_samples") or 0),
                int(item.get("candidate_samples") or 0),
            )
        )
        return {
            "status": status,
            "points": _leaderboard_status_points(status),
            "mean_directional_delta": round(float(mean), 6) if isinstance(mean, (int, float)) else None,
            "paired_count": count,
            "confidence": item.get("confidence"),
        }
    return {"status": "missing-candidate", "points": 0.0}


def _leaderboard_baseline_points(
    record: Mapping[str, object],
    *,
    baseline_variant_id: str,
) -> float:
    pairwise = record.get("pairwise") if isinstance(record.get("pairwise"), list) else []
    statuses = [
        str(item.get("status") or "")
        for item in pairwise
        if isinstance(item, dict) and item.get("baseline_variant_id") == baseline_variant_id
    ]
    if statuses and all(status in {"trails-baseline", "candidate-behind"} for status in statuses):
        return 1.0
    if statuses and any(status == "beats-baseline" for status in statuses):
        return -1.0
    return 0.0


def _leaderboard_status_points(status: str) -> float:
    return {
        "beats-baseline": 3.0,
        "candidate-ahead": 1.0,
        "tied": 0.0,
        "candidate-behind": -1.0,
        "trails-baseline": -3.0,
        "insufficient-data": 0.0,
    }.get(status, 0.0)


def _leaderboard_arena_evidence(
    arena_report: Mapping[str, object] | None,
    variant_id: str,
) -> dict[str, object]:
    if not isinstance(arena_report, Mapping):
        return {"status": "missing", "points": 0.0}
    summaries = (
        arena_report.get("variant_summaries")
        if isinstance(arena_report.get("variant_summaries"), list)
        else []
    )
    variant_count = max(1, len([item for item in summaries if isinstance(item, dict)]))
    for item in summaries:
        if not isinstance(item, dict) or item.get("variant_id") != variant_id:
            continue
        rank = int(item.get("rank") or variant_count)
        completed = int(item.get("completed_matches") or 0)
        win_rate = item.get("win_rate")
        champion_bonus = 1.5 if arena_report.get("winner_variant_id") == variant_id else 0.0
        rank_points = max(0.0, (variant_count - rank + 1) / variant_count)
        win_points = float(win_rate) if isinstance(win_rate, (int, float)) else 0.0
        return {
            "status": "champion" if champion_bonus else "ranked",
            "rank": rank,
            "completed_matches": completed,
            "wins": int(item.get("wins") or 0),
            "losses": int(item.get("losses") or 0),
            "ties": int(item.get("ties") or 0),
            "win_rate": round(win_points, 6) if completed else None,
            "points": round(champion_bonus + rank_points + win_points, 6),
        }
    return {"status": "missing-variant", "points": 0.0}


def _leaderboard_judge_evidence(
    judge_report: Mapping[str, object] | None,
    variant_id: str,
) -> dict[str, object]:
    if not isinstance(judge_report, Mapping):
        return {"status": "missing", "points": 0.0}
    summaries = (
        judge_report.get("variant_summaries")
        if isinstance(judge_report.get("variant_summaries"), list)
        else []
    )
    variant_count = max(1, len([item for item in summaries if isinstance(item, dict)]))
    for item in summaries:
        if not isinstance(item, dict) or item.get("variant_id") != variant_id:
            continue
        rank = int(item.get("rank") or variant_count)
        judged = int(item.get("judged_target_count") or 0)
        if judged <= 0:
            return {
                "status": "no-judgements",
                "rank": rank,
                "judged_target_count": judged,
                "score_mean": item.get("score_mean"),
                "points": 0.0,
            }
        champion_bonus = 1.5 if judge_report.get("winner_variant_id") == variant_id else 0.0
        rank_points = max(0.0, (variant_count - rank + 1) / variant_count)
        coverage_points = min(1.0, judged / max(1, int(item.get("target_count") or judged or 1)))
        return {
            "status": "winner" if champion_bonus else "ranked",
            "rank": rank,
            "judged_target_count": judged,
            "score_mean": item.get("score_mean"),
            "points": round(champion_bonus + rank_points + coverage_points, 6),
        }
    return {"status": "missing-variant", "points": 0.0}


def _leaderboard_allocation_evidence(
    allocation: Mapping[str, object] | None,
    variant_id: str,
) -> dict[str, object]:
    if not isinstance(allocation, Mapping):
        return {"status": "missing", "points": 0.0}
    allocations = allocation.get("allocations") if isinstance(allocation.get("allocations"), list) else []
    for item in allocations:
        if not isinstance(item, dict) or item.get("variant_id") != variant_id:
            continue
        share = item.get("recommended_share")
        share_number = float(share) if isinstance(share, (int, float)) else 0.0
        winner_bonus = 1.0 if allocation.get("winner_variant_id") == variant_id else 0.0
        return {
            "status": "winner" if allocation.get("winner_variant_id") == variant_id else "allocated",
            "recommended_share": round(share_number, 6),
            "reason": item.get("reason"),
            "points": round(winner_bonus + share_number, 6),
        }
    return {"status": "missing-variant", "points": 0.0}


def _leaderboard_route_evidence(
    route: Mapping[str, object] | None,
    variant_id: str,
) -> dict[str, object]:
    if not isinstance(route, Mapping):
        return {"status": "missing", "points": 0.0, "lane_wins": 0}
    lanes = route.get("lane_policies") if isinstance(route.get("lane_policies"), list) else []
    lane_wins = [
        str(lane.get("lane_id") or "")
        for lane in lanes
        if isinstance(lane, dict) and lane.get("winner_variant_id") == variant_id
    ]
    return {
        "status": "lane-winner" if lane_wins else "no-lane-wins",
        "lane_wins": len(lane_wins),
        "lanes": lane_wins,
        "points": round(0.5 * len(lane_wins), 6),
    }


def _leaderboard_promotion_evidence(
    promotion: Mapping[str, object] | None,
    variant_id: str,
) -> dict[str, object]:
    if not isinstance(promotion, Mapping):
        return {"status": "missing", "points": 0.0}
    candidate = promotion.get("candidate_variant_id")
    status = str(promotion.get("promotion_status") or "")
    if candidate == variant_id and promotion.get("ready") is True:
        points = 3.0
    elif candidate == variant_id and status in {"collect-more-data", "hold"}:
        points = 0.5
    elif promotion.get("champion_variant_id") == variant_id and status == "keep-champion":
        points = 1.0
    else:
        points = 0.0
    return {
        "status": status or "unknown",
        "candidate": candidate == variant_id,
        "ready": bool(promotion.get("ready")),
        "points": points,
    }


def _leaderboard_decision_evidence(
    decision: Mapping[str, object] | None,
    variant_id: str,
) -> dict[str, object]:
    if not isinstance(decision, Mapping):
        return {"status": "missing", "points": 0.0}
    candidate = decision.get("candidate_variant_id")
    baseline = decision.get("baseline_variant_id")
    action = str(decision.get("decision") or "")
    status = str(decision.get("decision_status") or "")
    if candidate == variant_id and action == "stop-promote":
        points = 3.0
    elif candidate == variant_id and action == "continue":
        points = 0.5
    elif baseline == variant_id and action == "stop-baseline":
        points = 1.5
    else:
        points = 0.0
    summary = decision.get("summary") if isinstance(decision.get("summary"), Mapping) else {}
    return {
        "status": status or action or "unknown",
        "decision": action,
        "candidate": candidate == variant_id,
        "baseline": baseline == variant_id,
        "confidence": summary.get("confidence"),
        "directional_delta": summary.get("directional_delta"),
        "points": points,
    }


def _leaderboard_frontier_points(
    variant_id: str,
    *,
    comparison: Mapping[str, object] | None,
    suite_report: Mapping[str, object] | None,
) -> float:
    points = 0.0
    for record in (comparison, suite_report):
        if not isinstance(record, Mapping):
            continue
        frontier = record.get("efficiency_frontier") if isinstance(record.get("efficiency_frontier"), list) else []
        if any(isinstance(item, dict) and item.get("variant_id") == variant_id for item in frontier):
            points += 0.75
    return round(points, 6)


def _leaderboard_row_reasons(
    *,
    metric_points: float,
    comparison: Mapping[str, object],
    suite: Mapping[str, object],
    arena: Mapping[str, object],
    judge: Mapping[str, object],
    schedule: Mapping[str, object],
    allocation: Mapping[str, object],
    route: Mapping[str, object],
    promotion: Mapping[str, object],
    decision: Mapping[str, object],
    frontier_points: float,
) -> list[str]:
    reasons: list[str] = []
    if metric_points:
        reasons.append("primary-metric-ranked")
    for label, evidence in (("comparison", comparison), ("suite", suite), ("schedule", schedule)):
        status = str(evidence.get("status") or "")
        if status in {"beats-baseline", "candidate-ahead", "trails-baseline", "candidate-behind", "baseline"}:
            reasons.append(f"{label}:{status}")
    if arena.get("status") == "champion":
        reasons.append("arena:champion")
    elif int(arena.get("wins") or 0):
        reasons.append(f"arena:{int(arena.get('wins') or 0)}-wins")
    if judge.get("status") == "winner":
        reasons.append("judge:winner")
    elif int(judge.get("judged_target_count") or 0):
        reasons.append("judge:ranked")
    if allocation.get("status") == "winner":
        reasons.append("allocation:winner")
    lane_wins = int(route.get("lane_wins") or 0)
    if lane_wins:
        reasons.append(f"route:{lane_wins}-lane-wins")
    if promotion.get("ready") is True:
        reasons.append("promotion:ready")
    if decision.get("decision") in {"stop-promote", "stop-baseline"}:
        reasons.append(f"decision:{decision.get('decision')}")
    if frontier_points:
        reasons.append("pareto-frontier")
    return reasons


def _leaderboard_winner(rows: list[dict[str, object]]) -> str | None:
    if not rows:
        return None
    top = rows[0]
    if float(top.get("evidence_score") or 0.0) <= 0:
        return None
    return str(top["variant_id"])


def _leaderboard_summary(
    rows: list[dict[str, object]],
    *,
    outcomes: list[dict[str, object]],
    source_artifacts: Mapping[str, object],
    min_samples: int,
) -> dict[str, object]:
    measured = [row for row in rows if int(row.get("primary_metric_count") or 0) > 0]
    under_sampled = [
        str(row["variant_id"])
        for row in rows
        if int(row.get("primary_metric_count") or 0) < min_samples
    ]
    top_score = float(rows[0].get("evidence_score") or 0.0) if rows else 0.0
    return {
        "variant_count": len(rows),
        "outcome_count": len(outcomes),
        "measured_variants": len(measured),
        "under_sampled_variants": under_sampled,
        "min_samples_per_variant": min_samples,
        "evidence_sources": len(source_artifacts),
        "top_score": round(top_score, 6),
        "winner_variant_id": _leaderboard_winner(rows),
    }


def _leaderboard_status(summary: Mapping[str, object]) -> str:
    if int(summary.get("outcome_count") or 0) == 0:
        return "no-outcomes"
    if int(summary.get("evidence_sources") or 0) <= 1:
        return "needs-evidence"
    if summary.get("under_sampled_variants"):
        return "needs-samples"
    if summary.get("winner_variant_id"):
        return "ready"
    return "inconclusive"


def _leaderboard_recommendations(
    summary: Mapping[str, object],
    *,
    source_artifacts: Mapping[str, object],
    baseline_variant_id: str,
    winner_variant_id: str | None,
) -> list[str]:
    recommendations: list[str] = []
    if int(summary.get("outcome_count") or 0) == 0:
        return ["Run agent-matrix or agent-suite, then ingest metadata-only outcomes before ranking variants."]
    missing = summary.get("under_sampled_variants")
    if isinstance(missing, list) and missing:
        recommendations.append(
            "Collect at least "
            f"{int(summary.get('min_samples_per_variant') or 0)} primary-metric sample(s) for: "
            f"{', '.join(str(item) for item in missing)}."
        )
    if "comparison" not in source_artifacts:
        recommendations.append("Run agent-compare so the leaderboard includes pairwise baseline evidence.")
    if "suite_report" not in source_artifacts:
        recommendations.append("Run agent-suite-report for paired case evidence before promotion.")
    if "schedule" in source_artifacts and "schedule_report" not in source_artifacts:
        recommendations.append("Run agent-schedule-report to fold scheduled paired blocks into the leaderboard.")
    if "route" not in source_artifacts:
        recommendations.append("Run agent-route so lane-specific strengths are visible in the leaderboard.")
    if winner_variant_id:
        if "promotion" not in source_artifacts:
            recommendations.append(
                f"Run agent-promote with champion {baseline_variant_id} before changing weights toward {winner_variant_id}."
            )
        else:
            recommendations.append(f"Review promotion and rollout controls for leaderboard winner {winner_variant_id}.")
    if not recommendations:
        recommendations.append("Leaderboard evidence is current; use it as the operator decision surface for the next loop.")
    return recommendations


def _config_source(value: str) -> str:
    source = _safe_label(str(value or "auto"))
    allowed = {"auto", "promotion", "leaderboard", "allocation", "route", "improvement"}
    if source not in allowed:
        raise ValueError("config source must be auto, promotion, leaderboard, allocation, route, or improvement")
    return source


def _config_source_records(
    vault: Path,
    root: Path,
    experiment_slug: str,
) -> dict[str, dict[str, object] | None]:
    del vault, experiment_slug
    return {
        "promotion": _latest_schema_record(root, "promotions", AGENT_PROMOTION_SCHEMA),
        "leaderboard": _latest_schema_record(root, "leaderboards", AGENT_LEADERBOARD_SCHEMA),
        "allocation": _latest_schema_record(root, "allocations", AGENT_ALLOCATION_SCHEMA),
        "route": _latest_schema_record(root, "routes", AGENT_ROUTE_SCHEMA),
        "improvement": _latest_schema_record(root, "improvements", AGENT_IMPROVEMENT_SCHEMA),
    }


def _select_config_proposal(
    spec: ExperimentSpec,
    records: Mapping[str, Mapping[str, object] | None],
    *,
    source: str,
    exploration_floor: float,
    max_share: float,
) -> dict[str, object]:
    order = (
        ("promotion", "ready-promotion"),
        ("leaderboard", "leaderboard-evidence"),
        ("allocation", "adaptive-allocation"),
        ("route", "lane-routing"),
        ("improvement", "improvement-loop"),
    )
    if source != "auto":
        order = tuple(item for item in order if item[0] == source)
    for name, reason in order:
        record = records.get(name)
        if not isinstance(record, Mapping):
            continue
        proposal = _config_proposal_from_record(
            spec,
            name,
            record,
            reason=reason,
            exploration_floor=exploration_floor,
            max_share=max_share,
            explicit=source != "auto",
        )
        if proposal is not None:
            return proposal
    fallback = spec.as_dict()
    fallback["config_policy"] = "no-change"
    return {
        "source": source,
        "reason": "no-config-producing-artifact",
        "artifact": None,
        "proposed_config": fallback,
        "ready": False,
    }


def _config_proposal_from_record(
    spec: ExperimentSpec,
    source: str,
    record: Mapping[str, object],
    *,
    reason: str,
    exploration_floor: float,
    max_share: float,
    explicit: bool,
) -> dict[str, object] | None:
    if source == "promotion":
        if record.get("ready") is not True and not explicit:
            return None
        config = record.get("candidate_config")
        id_key = "promotion_id"
        ready = record.get("ready") is True
    elif source == "leaderboard":
        if record.get("winner_variant_id") is None and not explicit:
            return None
        config = _config_from_leaderboard(
            spec,
            record,
            exploration_floor=exploration_floor,
            max_share=max_share,
        )
        id_key = "leaderboard_id"
        ready = record.get("winner_variant_id") is not None
    elif source == "allocation":
        config = record.get("next_config")
        id_key = "allocation_id"
        ready = record.get("winner_variant_id") is not None
    elif source == "route":
        config = record.get("next_config")
        id_key = "route_id"
        ready = bool((record.get("summary") if isinstance(record.get("summary"), dict) else {}).get("recommended_routes"))
    elif source == "improvement":
        config = record.get("next_config")
        id_key = "loop_id"
        ready = record.get("winner_variant_id") is not None
    else:
        return None
    if not isinstance(config, Mapping):
        return None
    return {
        "source": source,
        "reason": reason,
        "artifact": _config_artifact_ref(record, id_key=id_key),
        "proposed_config": _sanitize_proposed_config(config),
        "ready": bool(ready),
    }


def _config_artifact_ref(record: Mapping[str, object], *, id_key: str) -> dict[str, object]:
    ref = {
        "artifact_id": _safe_text_label(str(record.get(id_key) or ""), field=id_key, max_length=180),
        "generated_at": _safe_text_label(str(record.get("generated_at") or ""), field="generated_at", max_length=80),
    }
    for key in (
        "promotion_status",
        "leaderboard_status",
        "strategy",
        "winner_variant_id",
        "candidate_variant_id",
    ):
        if record.get(key) is not None:
            ref[key] = _safe_text_label(str(record.get(key)), field=key, max_length=180)
    return ref


def _sanitize_proposed_config(config: Mapping[str, object]) -> dict[str, object]:
    spec = ExperimentSpec.from_mapping(config)
    sanitized = spec.as_dict()
    for key in (
        "allocation_policy",
        "improvement_policy",
        "promotion_policy",
        "promoted_variant_id",
        "lane_routing_policy",
        "leaderboard_policy",
        "config_policy",
    ):
        if key in config:
            value = config[key]
            sanitized[key] = _sanitize_config_extension(value)
    return sanitized


def _sanitize_config_extension(value: object) -> object:
    if isinstance(value, Mapping):
        return {
            _safe_text_label(str(key), field="config extension key", max_length=120): _sanitize_config_extension(item)
            for key, item in value.items()
        }
    if isinstance(value, list):
        return [_sanitize_config_extension(item) for item in value]
    if isinstance(value, str):
        return _safe_text_label(value, field="config extension value", max_length=240)
    if isinstance(value, bool) or value is None:
        return value
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError("config extension numbers must be finite")
        return round(value, 6)
    return _safe_text_label(str(value), field="config extension value", max_length=240)


def _config_from_leaderboard(
    spec: ExperimentSpec,
    leaderboard: Mapping[str, object],
    *,
    exploration_floor: float,
    max_share: float,
) -> dict[str, object]:
    rows = leaderboard.get("leaderboard") if isinstance(leaderboard.get("leaderboard"), list) else []
    score_by_variant = {
        str(row.get("variant_id")): max(0.0, float(row.get("evidence_score") or 0.0))
        for row in rows
        if isinstance(row, dict) and isinstance(row.get("variant_id"), str)
    }
    variant_count = max(len(spec.variants), 1)
    floor = min(exploration_floor, 1.0 / variant_count)
    cap = max(max_share, floor, 1.0 / variant_count)
    total_floor = floor * variant_count
    exploit_pool = max(0.0, 1.0 - total_floor)
    total_score = sum(score_by_variant.get(variant.id, 0.0) for variant in spec.variants)
    if total_score <= 0:
        shares = {variant.id: 1.0 / variant_count for variant in spec.variants}
    else:
        shares = {
            variant.id: floor + exploit_pool * (score_by_variant.get(variant.id, 0.0) / total_score)
            for variant in spec.variants
        }
    capped = _cap_config_shares([shares[variant.id] for variant in spec.variants], cap=cap)
    variants = []
    for variant, share in zip(spec.variants, capped):
        payload = variant.as_dict()
        payload["weight"] = round(max(share, 0.000001), 6)
        variants.append(payload)
    config = spec.as_dict()
    config["variants"] = variants
    config["traffic_salt"] = f"{spec.traffic_salt}:leaderboard:{leaderboard.get('leaderboard_id') or 'latest'}"
    config["allocation_policy"] = "leaderboard-evidence"
    config["leaderboard_policy"] = {
        "leaderboard_id": leaderboard.get("leaderboard_id"),
        "winner_variant_id": leaderboard.get("winner_variant_id"),
        "exploration_floor": floor,
        "max_share": cap,
    }
    return _sanitize_proposed_config(config)


def _cap_config_shares(shares: list[float], *, cap: float) -> list[float]:
    if not shares:
        return []
    capped = [min(max(share, 0.0), cap) for share in shares]
    for _ in range(len(capped) + 1):
        total = sum(capped)
        if total <= 0:
            return [round(1.0 / len(capped), 6) for _item in capped]
        if abs(total - 1.0) <= 0.000001:
            break
        if total < 1.0:
            receivers = [index for index, share in enumerate(capped) if share < cap - 0.000001]
            if not receivers:
                break
            missing = 1.0 - total
            room = sum(cap - capped[index] for index in receivers)
            for index in receivers:
                capped[index] += missing * ((cap - capped[index]) / room) if room else 0.0
        else:
            excess = total - 1.0
            positive = [index for index, share in enumerate(capped) if share > 0]
            room = sum(capped[index] for index in positive)
            for index in positive:
                capped[index] -= excess * (capped[index] / room) if room else 0.0
    total = sum(capped)
    normalized = [share / total for share in capped] if total > 0 else [1.0 / len(capped) for _item in capped]
    rounded = [round(value, 6) for value in normalized]
    drift = round(1.0 - sum(rounded), 6)
    if rounded and drift:
        best = max(range(len(rounded)), key=lambda index: rounded[index])
        rounded[best] = round(rounded[best] + drift, 6)
    return rounded


def _config_patch(current: Mapping[str, object], proposed: Mapping[str, object]) -> dict[str, object]:
    operations: list[dict[str, object]] = []
    keys = sorted(set(current) | set(proposed))
    for key in keys:
        if current.get(key) == proposed.get(key):
            continue
        op = "replace" if key in current else "add"
        operation = {
            "op": op,
            "path": "/" + _json_pointer_escape(key),
        }
        if key in proposed:
            operation["value"] = proposed[key]
        else:
            operation["op"] = "remove"
        operations.append(operation)
    return {
        "format": "json-patch",
        "operations": operations,
    }


def _json_pointer_escape(value: str) -> str:
    return str(value).replace("~", "~0").replace("/", "~1")


def _config_proposal_summary(
    current: Mapping[str, object],
    proposed: Mapping[str, object],
    patch: Mapping[str, object],
) -> dict[str, object]:
    operations = patch.get("operations") if isinstance(patch.get("operations"), list) else []
    current_variants = current.get("variants") if isinstance(current.get("variants"), list) else []
    proposed_variants = proposed.get("variants") if isinstance(proposed.get("variants"), list) else []
    changed_weights = _config_changed_weights(current_variants, proposed_variants)
    return {
        "operation_count": len(operations),
        "variant_count": len(proposed_variants),
        "changed_variant_weights": changed_weights,
        "changed_weight_count": len(changed_weights),
        "traffic_salt_changed": current.get("traffic_salt") != proposed.get("traffic_salt"),
    }


def _config_changed_weights(
    current_variants: list[object],
    proposed_variants: list[object],
) -> list[dict[str, object]]:
    current = {
        str(item.get("id")): item
        for item in current_variants
        if isinstance(item, dict) and item.get("id") is not None
    }
    changed: list[dict[str, object]] = []
    for item in proposed_variants:
        if not isinstance(item, dict) or item.get("id") is None:
            continue
        variant_id = str(item.get("id"))
        current_weight = (current.get(variant_id) or {}).get("weight")
        next_weight = item.get("weight")
        if current_weight != next_weight:
            changed.append(
                {
                    "variant_id": slugify(variant_id, fallback="variant"),
                    "current_weight": current_weight,
                    "proposed_weight": next_weight,
                }
            )
    return changed


def _config_proposal_status(
    proposal: Mapping[str, object],
    patch: Mapping[str, object],
) -> str:
    operations = patch.get("operations") if isinstance(patch.get("operations"), list) else []
    if not operations:
        return "no-change"
    if proposal.get("ready") is True:
        return "ready"
    return "needs-review"


def _config_proposal_recommendations(
    config_status: str,
    proposal: Mapping[str, object],
    *,
    patch: Mapping[str, object],
) -> list[str]:
    if config_status == "no-change":
        return ["No config change is proposed; collect more evidence or choose a different source."]
    operations = patch.get("operations") if isinstance(patch.get("operations"), list) else []
    recommendations = [
        f"Review the {len(operations)} JSON Patch operation(s) before using the proposed experiment config.",
        "Use the written .experiment.json file as the next run's --config-file only after operator review.",
    ]
    if proposal.get("ready") is not True:
        recommendations.append("The selected source is not fully ready, so treat this as a draft config proposal.")
    return recommendations


def _comparison_summary(
    spec: ExperimentSpec,
    summaries: list[dict[str, object]],
    pairwise: list[dict[str, object]],
    *,
    min_samples: int,
) -> dict[str, object]:
    counts = [int(item.get("primary_metric_count") or 0) for item in summaries]
    measured = [count for count in counts if count > 0]
    eligible = [
        str(item["variant_id"])
        for item in summaries
        if int(item.get("primary_metric_count") or 0) >= min_samples
    ]
    under_sampled = [
        str(item["variant_id"])
        for item in summaries
        if int(item.get("primary_metric_count") or 0) < min_samples
    ]
    balance_ratio = round(min(measured) / max(measured), 6) if measured else None
    return {
        "variant_count": len(spec.variants),
        "eligible_variant_count": len(eligible),
        "eligible_variants": eligible,
        "under_sampled_variants": under_sampled,
        "sample_balance_ratio": balance_ratio,
        "beats_baseline": sum(1 for item in pairwise if item.get("status") == "beats-baseline"),
        "trails_baseline": sum(1 for item in pairwise if item.get("status") == "trails-baseline"),
        "inconclusive": sum(1 for item in pairwise if item.get("status") in {"candidate-ahead", "candidate-behind", "tied"}),
        "insufficient_data": sum(1 for item in pairwise if item.get("status") == "insufficient-data"),
    }


def _comparison_recommendations(
    summaries: list[dict[str, object]],
    pairwise: list[dict[str, object]],
    *,
    baseline_variant_id: str,
    winner_variant_id: str | None,
    metric: MetricSpec,
    min_samples: int,
) -> list[str]:
    recommendations: list[str] = []
    under_sampled = [
        str(item["variant_id"])
        for item in summaries
        if int(item.get("primary_metric_count") or 0) < min_samples
    ]
    if under_sampled:
        recommendations.append(
            "Collect at least "
            f"{min_samples} {metric.name} sample(s) for under-sampled variants: "
            f"{', '.join(under_sampled)}."
        )
    strong = [
        str(item["candidate_variant_id"])
        for item in pairwise
        if item.get("status") == "beats-baseline"
    ]
    if strong:
        recommendations.append(
            f"Review promotion evidence for variant(s) beating baseline {baseline_variant_id}: "
            f"{', '.join(strong)}."
        )
    if winner_variant_id:
        recommendations.append(
            f"Current eligible winner is {winner_variant_id} on {metric.name} ({metric.direction})."
        )
    else:
        recommendations.append(
            f"No eligible winner yet; continue matrix or A/B sampling until each variant reaches {min_samples} sample(s)."
        )
    measured_counts = [
        int(item.get("primary_metric_count") or 0)
        for item in summaries
        if int(item.get("primary_metric_count") or 0) > 0
    ]
    if measured_counts and min(measured_counts) / max(measured_counts) < 0.5:
        recommendations.append(
            "Use agent-matrix for the next loop to rebalance uneven model coverage."
        )
    return recommendations


def _sample_stddev(values: list[float], *, mean: float | None) -> float | None:
    if mean is None or len(values) < 2:
        return None
    variance = sum((value - mean) ** 2 for value in values) / (len(values) - 1)
    return math.sqrt(variance)


def _outcome_variant_id(outcome: Mapping[str, object]) -> str | None:
    variant = outcome.get("variant")
    if isinstance(variant, dict) and isinstance(variant.get("id"), str):
        return str(variant["id"])
    return None


def _winner_variant_id(
    spec: ExperimentSpec,
    summaries: list[dict[str, object]],
) -> str | None:
    candidates = [
        item for item in summaries if isinstance(item.get("primary_metric_mean"), (int, float))
    ]
    if not candidates:
        return None
    if spec.primary_metric.direction == "maximize":
        winner = max(
            candidates,
            key=lambda item: (
                float(item["primary_metric_mean"]),
                float(item.get("success_rate") or 0.0),
                int(item.get("trials") or 0),
            ),
        )
    else:
        winner = min(
            candidates,
            key=lambda item: (
                float(item["primary_metric_mean"]),
                -float(item.get("success_rate") or 0.0),
                -int(item.get("trials") or 0),
            ),
        )
    return str(winner["variant_id"])


def _allocation_entries(
    spec: ExperimentSpec,
    summaries: list[dict[str, object]],
    *,
    strategy: str,
    exploration_floor: float,
    max_share: float,
    min_trials: int,
    cost_penalty: float,
) -> list[dict[str, object]]:
    by_variant = {
        str(item["variant_id"]): item
        for item in summaries
        if isinstance(item.get("variant_id"), str)
    }
    total_samples = sum(int(item.get("primary_metric_count") or 0) for item in summaries)
    variant_count = len(spec.variants)
    floor_share = min(exploration_floor, 1.0 / variant_count)
    exploit_pool = max(0.0, 1.0 - floor_share * variant_count)
    current_weight_total = sum(variant.weight for variant in spec.variants)
    scored: list[dict[str, object]] = []
    for variant in spec.variants:
        summary = by_variant.get(variant.id, {})
        count = int(summary.get("primary_metric_count") or 0)
        directional = _allocation_directional_metric(spec.primary_metric, summary)
        usage = summary.get("usage") if isinstance(summary.get("usage"), dict) else {}
        cost_mean = usage.get("cost_usd_mean") if isinstance(usage, dict) else None
        reward = directional if directional is not None else 0.0
        cost_adjustment = (
            penalty_cost := float(cost_mean) * cost_penalty
            if isinstance(cost_mean, (int, float)) and math.isfinite(float(cost_mean))
            else 0.0
        )
        reward_score = reward - cost_adjustment
        exploration_bonus = _allocation_exploration_bonus(
            strategy,
            count=count,
            total_samples=total_samples,
            min_trials=min_trials,
        )
        allocation_score = reward_score + exploration_bonus
        scored.append(
            {
                "variant_id": variant.id,
                "provider": variant.provider,
                "model": variant.model,
                "current_weight": round(variant.weight, 6),
                "current_share": (
                    round(variant.weight / current_weight_total, 6)
                    if current_weight_total
                    else None
                ),
                "trials": int(summary.get("trials") or 0),
                "primary_metric_count": count,
                "primary_metric_mean": summary.get("primary_metric_mean"),
                "success_rate": summary.get("success_rate"),
                "reward_score": round(reward_score, 6),
                "exploration_bonus": round(exploration_bonus, 6),
                "allocation_score": round(allocation_score, 6),
                "under_sampled": count < min_trials,
                "reason": _allocation_reason(count=count, min_trials=min_trials, directional=directional),
            }
        )
        if isinstance(usage, dict) and usage:
            scored[-1]["usage"] = usage
        if cost_adjustment:
            scored[-1]["cost_penalty"] = round(penalty_cost, 6)

    raw_weights = _allocation_raw_weights(scored, strategy=strategy, metric=spec.primary_metric)
    shares = [
        floor_share + exploit_pool * (weight / sum(raw_weights))
        if raw_weights and sum(raw_weights) > 0
        else 1.0 / variant_count
        for weight in raw_weights
    ]
    shares = _cap_allocation_shares(shares, floor=floor_share, max_share=max_share)
    for item, share in zip(scored, shares):
        item["recommended_share"] = round(share, 6)
        item["recommended_weight"] = round(max(share, 0.000001), 6)
    scored.sort(
        key=lambda item: (
            -float(item.get("recommended_share") or 0.0),
            str(item.get("variant_id") or ""),
        )
    )
    return scored


def _allocation_directional_metric(
    metric: MetricSpec,
    summary: Mapping[str, object],
) -> float | None:
    value = summary.get("primary_metric_mean")
    if not isinstance(value, (int, float)) or not math.isfinite(float(value)):
        return None
    number = float(value)
    return number if metric.direction == "maximize" else -number


def _allocation_exploration_bonus(
    strategy: str,
    *,
    count: int,
    total_samples: int,
    min_trials: int,
) -> float:
    missing = max(0, min_trials - count)
    if strategy == "epsilon-greedy":
        return float(missing)
    if strategy == "equalize":
        return float(missing + 1)
    denominator = max(count, 1)
    ucb = math.sqrt(2.0 * math.log(max(total_samples, 1) + 1.0) / denominator)
    return ucb + float(missing)


def _allocation_raw_weights(
    entries: list[dict[str, object]],
    *,
    strategy: str,
    metric: MetricSpec,
) -> list[float]:
    if not entries:
        return []
    if strategy == "equalize":
        return [1.0 for _item in entries]
    under_sampled = [item for item in entries if item.get("under_sampled") is True]
    if strategy == "epsilon-greedy":
        candidates = under_sampled or entries
        if metric.direction == "maximize":
            winner = max(candidates, key=lambda item: float(item.get("reward_score") or 0.0))
        else:
            winner = max(candidates, key=lambda item: float(item.get("reward_score") or 0.0))
        winner_id = winner.get("variant_id")
        return [1.0 if item.get("variant_id") == winner_id else 0.0 for item in entries]
    scores = [float(item.get("allocation_score") or 0.0) for item in entries]
    minimum = min(scores)
    shifted = [score - minimum + 0.000001 for score in scores]
    if not any(value > 0 for value in shifted):
        return [1.0 for _item in entries]
    return shifted


def _cap_allocation_shares(
    shares: list[float],
    *,
    floor: float,
    max_share: float,
) -> list[float]:
    if not shares:
        return []
    cap = max(max_share, floor, 1.0 / len(shares))
    result = [max(floor, share) for share in shares]
    for _ in range(len(result) + 1):
        surplus = 0.0
        for index, value in enumerate(result):
            if value > cap:
                surplus += value - cap
                result[index] = cap
        receivers = [
            index for index, value in enumerate(result)
            if value < cap - 0.000000001
        ]
        if surplus <= 0.000000001 or not receivers:
            break
        room = sum(cap - result[index] for index in receivers)
        if room <= 0:
            break
        for index in receivers:
            result[index] += surplus * ((cap - result[index]) / room)
    total = sum(result)
    if total <= 0:
        return [round(1.0 / len(result), 6) for _item in result]
    normalized = [value / total for value in result]
    rounded = [round(value, 6) for value in normalized]
    drift = round(1.0 - sum(rounded), 6)
    if rounded and drift:
        best_index = max(range(len(rounded)), key=lambda index: rounded[index])
        rounded[best_index] = round(rounded[best_index] + drift, 6)
    return rounded


def _allocation_reason(
    *,
    count: int,
    min_trials: int,
    directional: float | None,
) -> str:
    if count < min_trials:
        return "explore-under-sampled"
    if directional is None:
        return "explore-missing-primary-metric"
    return "exploit-measured-reward"


def _allocation_winner(allocations: list[dict[str, object]]) -> str | None:
    if not allocations:
        return None
    winner = max(
        allocations,
        key=lambda item: (
            float(item.get("recommended_share") or 0.0),
            float(item.get("reward_score") or 0.0),
        ),
    )
    return str(winner["variant_id"])


def _allocation_next_config(
    spec: ExperimentSpec,
    allocations: list[dict[str, object]],
    *,
    generated_suffix: str,
) -> dict[str, object]:
    weights = {
        str(item["variant_id"]): float(item.get("recommended_weight") or 0.000001)
        for item in allocations
    }
    variants: list[dict[str, object]] = []
    for variant in spec.variants:
        payload = variant.as_dict()
        payload["weight"] = round(weights.get(variant.id, variant.weight), 6)
        variants.append(payload)
    next_config = spec.as_dict()
    next_config["variants"] = variants
    next_config["allocation_policy"] = generated_suffix
    return next_config


def _allocation_summary(
    allocations: list[dict[str, object]],
    *,
    outcome_count: int,
) -> dict[str, object]:
    return {
        "variant_count": len(allocations),
        "outcome_count": outcome_count,
        "measured_variants": sum(
            1 for item in allocations if int(item.get("primary_metric_count") or 0) > 0
        ),
        "under_sampled_variants": sum(
            1 for item in allocations if item.get("under_sampled") is True
        ),
        "max_recommended_share": max(
            (float(item.get("recommended_share") or 0.0) for item in allocations),
            default=0.0,
        ),
        "exploration_share": round(
            sum(
                float(item.get("recommended_share") or 0.0)
                for item in allocations
                if item.get("under_sampled") is True
            ),
            6,
        ),
    }


def _allocation_recommendations(
    allocations: list[dict[str, object]],
    *,
    metric: MetricSpec,
    min_trials: int,
    strategy: str,
    cost_penalty: float,
) -> list[str]:
    if not allocations:
        return ["Create agent outcomes before allocating traffic."]
    recommendations: list[str] = [
        f"Use {strategy} allocation as the next traffic proposal for {metric.name} ({metric.direction})."
    ]
    under = [
        str(item["variant_id"])
        for item in allocations
        if item.get("under_sampled") is True
    ]
    if under:
        recommendations.append(
            "Keep exploration active until each variant has at least "
            f"{min_trials} primary-metric sample(s): {', '.join(under)}."
        )
    winner = _allocation_winner(allocations)
    if winner:
        recommendations.append(f"Highest recommended traffic share is currently {winner}.")
    if cost_penalty:
        recommendations.append("Cost penalty is active, so high-cost variants need higher reward to win traffic.")
    if any(int(item.get("primary_metric_count") or 0) == 0 for item in allocations):
        recommendations.append("Run an agent-matrix or suite wave to collect first samples for unmeasured variants.")
    return recommendations


def _allocation_strategy(value: str) -> str:
    strategy = _safe_label(str(value or "ucb1"))
    if strategy not in {"ucb1", "epsilon-greedy", "equalize"}:
        raise ValueError("allocation strategy must be ucb1, epsilon-greedy, or equalize")
    return strategy


def _allocation_floor(value: float) -> float:
    floor = _ratio(value, field="exploration_floor")
    if floor >= 1:
        raise ValueError("exploration_floor must leave room for allocation")
    return floor


def _allocation_max_share(value: float) -> float:
    share = _ratio(value, field="max_share")
    if share <= 0:
        raise ValueError("max_share must be greater than 0")
    return share


def _next_config(
    spec: ExperimentSpec,
    *,
    winner_variant_id: str | None,
    enough_data: bool,
) -> dict[str, object]:
    next_weights: dict[str, float] = {}
    for variant in spec.variants:
        if winner_variant_id and variant.id == winner_variant_id:
            next_weights[variant.id] = 3.0 if enough_data else 2.0
        else:
            next_weights[variant.id] = 1.0
    variants = []
    for variant in spec.variants:
        payload = variant.as_dict()
        payload["weight"] = next_weights[variant.id]
        variants.append(payload)
    next_config = spec.as_dict()
    next_config["traffic_salt"] = f"{spec.traffic_salt}:loop"
    next_config["variants"] = variants
    if not winner_variant_id:
        next_config["improvement_policy"] = "collect-more-data"
    elif enough_data:
        next_config["improvement_policy"] = "evidence-rebalance"
    else:
        next_config["improvement_policy"] = "provisional-rebalance"
    return next_config


def _recommendations(
    summaries: list[dict[str, object]],
    *,
    primary_metric: MetricSpec,
    winner_variant_id: str | None,
    min_trials: int,
    enough_data: bool,
) -> list[str]:
    if not summaries or sum(int(item["trials"]) for item in summaries) == 0:
        return ["Collect outcome metrics before changing model allocation."]
    missing = [
        str(item["variant_id"])
        for item in summaries
        if int(item.get("trials") or 0) < min_trials
    ]
    recommendations: list[str] = []
    if missing:
        recommendations.append(
            "Keep exploration active until each variant has at least "
            f"{min_trials} outcome(s); under-sampled variants: {', '.join(missing)}."
        )
    if winner_variant_id:
        scope = "Promote" if enough_data else "Provisionally favor"
        recommendations.append(
            f"{scope} {winner_variant_id} for the next loop based on "
            f"{primary_metric.name} ({primary_metric.direction})."
        )
    else:
        recommendations.append(
            f"No winner yet because no outcomes include the {primary_metric.name} metric."
        )
    failed = [
        str(item["variant_id"])
        for item in summaries
        if int(item.get("failures") or 0) > 0
    ]
    if failed:
        recommendations.append(
            "Review adapter, timeout, or tool constraints for failing variants: "
            f"{', '.join(failed)}."
        )
    return recommendations


def _score_rubric(
    rubric: RubricSpec,
    scores: Mapping[str, object],
) -> dict[str, object]:
    if not isinstance(scores, Mapping):
        raise ValueError("scores must be a JSON object")
    normalized_scores = {
        _safe_label(str(key)): _finite_number(value, field=f"score {key}")
        for key, value in scores.items()
    }
    expected = {criterion.name for criterion in rubric.criteria}
    provided = set(normalized_scores)
    missing = sorted(expected - provided)
    unknown = sorted(provided - expected)
    if missing:
        raise ValueError(f"missing rubric score(s): {', '.join(missing)}")
    if unknown:
        raise ValueError(f"unknown rubric score(s): {', '.join(unknown)}")

    criteria: list[dict[str, object]] = []
    weighted_sum = 0.0
    total_weight = sum(item.weight for item in rubric.criteria)
    for criterion in rubric.criteria:
        raw_score = normalized_scores[criterion.name]
        if raw_score < criterion.min_score or raw_score > criterion.max_score:
            raise ValueError(
                f"{criterion.name} score must be between "
                f"{criterion.min_score:g} and {criterion.max_score:g}"
            )
        span = criterion.max_score - criterion.min_score
        normalized = (raw_score - criterion.min_score) / span
        if criterion.direction == "minimize":
            normalized = 1.0 - normalized
        normalized = round(normalized, 6)
        weighted = normalized * criterion.weight
        weighted_sum += weighted
        criteria.append(
            {
                "name": criterion.name,
                "raw_score": raw_score,
                "normalized_score": normalized,
                "weight": criterion.weight,
                "weighted_score": round(weighted, 6),
                "direction": criterion.direction,
                "min": criterion.min_score,
                "max": criterion.max_score,
            }
        )
    aggregate = weighted_sum / total_weight if total_weight else 0.0
    return {
        "aggregate_metric": rubric.aggregate_metric,
        "aggregate_score": round(aggregate, 6),
        "criteria": criteria,
    }


def _scorecard_metrics(scored: Mapping[str, object]) -> dict[str, float]:
    metrics = {
        _safe_label(str(scored["aggregate_metric"])): float(scored["aggregate_score"]),
    }
    criteria = scored.get("criteria")
    if isinstance(criteria, list):
        for item in criteria:
            if not isinstance(item, dict):
                continue
            name = _safe_label(str(item.get("name") or "criterion"))
            raw = item.get("raw_score")
            normalized = item.get("normalized_score")
            if isinstance(raw, (int, float)) and math.isfinite(float(raw)):
                metrics[f"{name}_raw"] = float(raw)
            if isinstance(normalized, (int, float)) and math.isfinite(float(normalized)):
                metrics[f"{name}_normalized"] = float(normalized)
    return metrics


def _work_parallel_context(run: Mapping[str, object]) -> dict[str, object] | None:
    parallel = run.get("parallel")
    if not isinstance(parallel, dict):
        return None
    context: dict[str, object] = {}
    for key in ("plan_id", "lane_id", "role", "objective", "replica", "merge_strategy"):
        value = parallel.get(key)
        if value is None:
            continue
        if isinstance(value, str):
            context[key] = _safe_text_label(value, field=f"parallel {key}", max_length=200)
        elif isinstance(value, int):
            context[key] = value
    return context or None


def _claim_summary(
    vault: Path,
    path: Path,
    claim: Mapping[str, object],
) -> dict[str, object]:
    claim_body = claim.get("claim")
    if not isinstance(claim_body, dict):
        raise ValueError("agent claim record is missing claim metadata")
    now = _utc_now()
    status = "active" if _claim_is_active(claim, now=now) else "expired"
    return {
        "claim_id": claim.get("claim_id"),
        "path": _relative_vault_path(vault, path),
        "client_id": claim_body.get("client_id"),
        "claimed_at": claim_body.get("claimed_at"),
        "expires_at": claim_body.get("expires_at"),
        "status": status,
    }


def _ingest_items(results_data: Mapping[str, object]) -> list[dict[str, object]]:
    raw_items = results_data.get("results")
    if raw_items is None:
        raw_items = results_data.get("outcomes")
    if raw_items is None and isinstance(results_data.get("run_id"), str):
        raw_items = [results_data]
    if not isinstance(raw_items, list) or not raw_items:
        raise ValueError("ingest payload must include a non-empty results or outcomes list")
    items: list[dict[str, object]] = []
    for index, item in enumerate(raw_items):
        if not isinstance(item, dict):
            raise ValueError(f"ingest result at index {index} must be an object")
        items.append(item)
    return items


def _ingest_one_result(vault: Path, item: Mapping[str, object]) -> dict[str, object]:
    _reject_raw_ingest_fields(item)
    run_id = _safe_run_id(str(item.get("run_id") or ""))
    status = str(item.get("status") or "succeeded")
    usage = item.get("usage") if isinstance(item.get("usage"), Mapping) else None
    output = item.get("output") if isinstance(item.get("output"), Mapping) else None
    failure_code = (
        _safe_label(str(item["failure_code"]))
        if item.get("failure_code") is not None
        else None
    )
    if isinstance(item.get("scores"), Mapping):
        scorecard = score_agent_run(
            vault,
            run_id=run_id,
            status=status,
            scores=item["scores"],  # type: ignore[arg-type]
            usage=usage,
            output_fingerprint=output,
            failure_code=failure_code,
        )
        return {
            "mode": "score",
            "experiment": scorecard.experiment,
            "run_id": run_id,
            "variant_id": scorecard.variant_id,
            "status": scorecard.payload["status"],
            "scorecard_id": scorecard.scorecard_id,
            "scorecard_path": _relative_vault_path(vault, scorecard.path),
            "scorecard_report_path": _relative_vault_path(vault, scorecard.report_path),
            "outcome_id": scorecard.outcome.payload["outcome_id"],
            "outcome_path": _relative_vault_path(vault, scorecard.outcome.path),
        }
    metrics = item.get("metrics")
    if not isinstance(metrics, Mapping):
        raise ValueError("ingest result must include metrics or scores")
    outcome = log_agent_outcome(
        vault,
        run_id=run_id,
        status=status,
        metrics=metrics,
        usage=usage,
        output_fingerprint=output,
        failure_code=failure_code,
    )
    return {
        "mode": "outcome",
        "experiment": outcome.experiment,
        "run_id": run_id,
        "variant_id": outcome.variant_id,
        "status": outcome.payload["status"],
        "outcome_id": outcome.payload["outcome_id"],
        "outcome_path": _relative_vault_path(vault, outcome.path),
    }


def _reject_raw_ingest_fields(item: Mapping[str, object]) -> None:
    raw_fields = {
        "prompt",
        "prompt_text",
        "raw_prompt",
        "transcript",
        "raw_transcript",
        "output_text",
        "raw_output",
        "error",
        "error_message",
    }
    present = sorted(key for key in raw_fields if key in item)
    if present:
        raise ValueError(
            "ingest results must not include raw prompt, transcript, output, or error fields: "
            f"{', '.join(present)}"
        )


def _ingest_error(index: int, item: Mapping[str, object], exc: BaseException) -> dict[str, object]:
    run_id = item.get("run_id")
    payload: dict[str, object] = {
        "index": index,
        "code": _safe_label(exc.__class__.__name__),
        "message": _safe_text_label(str(exc), field="ingest error", max_length=220),
    }
    if isinstance(run_id, str):
        payload["run_id"] = _safe_text_label(run_id, field="run_id", max_length=160)
    return payload


def _dispatch_entry(
    vault: Path,
    claim: AgentClaimResult,
    packet: AgentWorkPacketResult,
    *,
    worker_id: str,
) -> dict[str, object]:
    run = claim.payload["run"] if isinstance(claim.payload.get("run"), dict) else {}
    variant = packet.payload["variant"] if isinstance(packet.payload.get("variant"), dict) else {}
    parallel = packet.payload.get("parallel") if isinstance(packet.payload.get("parallel"), dict) else {}
    entry: dict[str, object] = {
        "worker_id": worker_id,
        "claim_id": claim.claim_id,
        "claim_path": _relative_vault_path(vault, claim.path),
        "work_packet_id": packet.packet_id,
        "work_packet_path": _relative_vault_path(vault, packet.path),
        "work_packet_report_path": _relative_vault_path(vault, packet.report_path),
        "run_id": claim.run_id,
        "lane_id": run.get("lane_id") or parallel.get("lane_id"),
        "role": run.get("role") or parallel.get("role"),
        "replica": run.get("replica") or parallel.get("replica"),
        "variant_id": variant.get("id"),
        "provider": variant.get("provider"),
        "model": variant.get("model"),
        "adapter": variant.get("adapter"),
    }
    return {key: value for key, value in entry.items() if value is not None}


def _work_packet_instructions() -> list[str]:
    return [
        "Call the selected adapter outside the core harness.",
        "Keep raw prompts, transcripts, screenshots, and model outputs outside agent-runs.",
        "Use the lane role and objective as the worker scope.",
        "Return only privacy-preserving metric logs or scorecards to the harness.",
        "Run agent-score or agent-outcome before the claim expires.",
    ]


def _work_packet_commands(run_id: str, rubric: RubricSpec) -> list[str]:
    score_stub = {
        criterion.name: criterion.max_score
        for criterion in rubric.criteria
    }
    return [
        "griosai agent-score "
        f"--vault <vault> --run-id {run_id} "
        f"--scores-json '{json.dumps(score_stub, sort_keys=True)}'",
        "griosai agent-outcome "
        f"--vault <vault> --run-id {run_id} --status succeeded "
        f"--metrics-json '{{\"{rubric.aggregate_metric}\": 0.0}}'",
    ]


def _current_champion_variant_id(spec: ExperimentSpec) -> str:
    return max(spec.variants, key=lambda variant: variant.weight).id


def _safe_variant_id(
    value: str | None,
    *,
    spec: ExperimentSpec,
    fallback: str,
) -> str:
    variant_id = slugify(value, fallback=fallback) if value else fallback
    known = {variant.id for variant in spec.variants}
    if variant_id not in known:
        raise ValueError(f"unknown variant id: {variant_id}")
    return variant_id


def _retry_variant(
    run: Mapping[str, object],
    *,
    spec: ExperimentSpec,
    variant_id: str | None,
) -> ModelVariant:
    selected = _run_selected_variant(run)
    requested = slugify(variant_id, fallback=str(selected["id"])) if variant_id else str(selected["id"])
    for variant in spec.variants:
        if variant.id == requested:
            return variant
    raise ValueError(f"unknown retry variant id: {requested}")


def _promotion_decision(
    *,
    spec: ExperimentSpec,
    summaries: list[dict[str, object]],
    champion_variant_id: str,
    candidate_variant_id: str | None,
    min_trials: int,
    min_delta: float,
    require_passing_gate: bool,
    require_suite_report: bool,
    require_pareto: bool,
    require_budget: bool,
    require_balance: bool,
    require_drift: bool,
    latest_gate: Mapping[str, object] | None,
    latest_suite_report: Mapping[str, object] | None,
    latest_comparison: Mapping[str, object] | None,
    latest_budget: Mapping[str, object] | None,
    latest_balance: Mapping[str, object] | None,
    latest_drift: Mapping[str, object] | None,
) -> dict[str, object]:
    by_variant = {
        str(item["variant_id"]): item
        for item in summaries
        if isinstance(item.get("variant_id"), str)
    }
    under_sampled = [
        variant.id
        for variant in spec.variants
        if int(by_variant.get(variant.id, {}).get("primary_metric_count") or 0) < min_trials
    ]
    latest_gate_summary = _promotion_gate_summary(latest_gate)
    latest_suite_summary = _promotion_suite_report_summary(latest_suite_report)
    latest_comparison_summary = _promotion_comparison_summary(latest_comparison)
    latest_budget_summary = _promotion_budget_summary(latest_budget)
    latest_balance_summary = _agent_balance_summary(latest_balance)
    latest_drift_summary = _agent_drift_summary(latest_drift)
    pareto_variants = _promotion_pareto_variants(latest_suite_report, latest_comparison)
    champion_summary = by_variant.get(champion_variant_id)
    candidate_summary = by_variant.get(candidate_variant_id or "")
    metric_gap = _metric_gap(
        champion_summary,
        candidate_summary,
        direction=spec.primary_metric.direction,
    )
    confidence = _promotion_confidence(
        champion_summary,
        candidate_summary,
        metric_gap=metric_gap,
    )
    evidence: dict[str, object] = {
        "under_sampled_variants": under_sampled,
        "metric_gap": metric_gap,
        "confidence": confidence,
        "latest_gate": latest_gate_summary,
        "latest_suite_report": latest_suite_summary,
        "latest_comparison": latest_comparison_summary,
        "latest_budget": latest_budget_summary,
        "latest_balance": latest_balance_summary,
        "latest_drift": latest_drift_summary,
        "pareto_variants": pareto_variants,
    }
    if not candidate_variant_id:
        return {
            "status": "collect-more-data",
            "ready": False,
            "reason": f"no outcome includes the {spec.primary_metric.name} metric",
            "evidence": evidence,
        }
    if under_sampled:
        return {
            "status": "collect-more-data",
            "ready": False,
            "reason": "minimum primary metric sample count is not met",
            "evidence": evidence,
        }
    if require_passing_gate and (
        not latest_gate_summary or latest_gate_summary.get("gate_status") != "pass"
    ):
        return {
            "status": "blocked-by-gate",
            "ready": False,
            "reason": "latest gate is missing or not passing",
            "evidence": evidence,
        }
    if require_suite_report:
        if latest_suite_summary is None:
            return {
                "status": "blocked-by-suite-report",
                "ready": False,
                "reason": "latest suite report is missing",
                "evidence": evidence,
            }
        if latest_suite_summary.get("winner_variant_id") != candidate_variant_id:
            return {
                "status": "blocked-by-suite-report",
                "ready": False,
                "reason": "latest suite report winner does not match the aggregate candidate",
                "evidence": evidence,
            }
        if latest_suite_summary.get("complete") is not True:
            return {
                "status": "blocked-by-suite-report",
                "ready": False,
                "reason": "latest suite report does not cover all configured cases",
                "evidence": evidence,
            }
    if require_pareto and candidate_variant_id not in pareto_variants:
        return {
            "status": "blocked-by-pareto",
            "ready": False,
            "reason": "candidate is not on the latest Pareto frontier",
            "evidence": evidence,
        }
    if require_budget and (
        not latest_budget_summary
        or latest_budget_summary.get("budget_status") != "within-budget"
    ):
        return {
            "status": "blocked-by-budget",
            "ready": False,
            "reason": "latest budget report is missing or over budget",
            "evidence": evidence,
        }
    if require_balance and (
        not latest_balance_summary
        or latest_balance_summary.get("balance_status") != "balanced"
        or latest_balance_summary.get("balanced") is not True
    ):
        return {
            "status": "blocked-by-balance",
            "ready": False,
            "reason": "latest balance report is missing or not balanced",
            "evidence": evidence,
        }
    if require_drift and (
        not latest_drift_summary
        or latest_drift_summary.get("drift_status") != "stable"
        or latest_drift_summary.get("drift_detected") is True
    ):
        return {
            "status": "blocked-by-drift",
            "ready": False,
            "reason": "latest drift report is missing or not stable",
            "evidence": evidence,
        }
    if candidate_variant_id == champion_variant_id:
        return {
            "status": "keep-champion",
            "ready": False,
            "reason": "current champion remains the best measured variant",
            "evidence": evidence,
        }
    if metric_gap is None:
        return {
            "status": "collect-more-data",
            "ready": False,
            "reason": "candidate or champion metric evidence is missing",
            "evidence": evidence,
        }
    if metric_gap < min_delta:
        return {
            "status": "hold",
            "ready": False,
            "reason": f"metric gap {metric_gap:.6g} is below required {min_delta:.6g}",
            "evidence": evidence,
        }
    return {
        "status": "ready",
        "ready": True,
        "reason": "candidate beats champion under the configured policy",
        "evidence": evidence,
    }


