def _readiness_plan_summary(
    root: Path,
    plans: list[dict[str, object]],
    claims: list[dict[str, object]],
    heartbeats: list[dict[str, object]],
    outcomes: list[dict[str, object]],
) -> dict[str, object]:
    outcomes_by_run = _latest_outcomes_by_run(outcomes)
    active_claims = _active_claims_by_run(claims, heartbeats=heartbeats, now=_utc_now())
    plan_statuses = [
        _plan_status(
            plan,
            outcomes_by_run=outcomes_by_run,
            active_claims=active_claims,
            plan_runs=_effective_plan_runs(root, plan),
        )
        for plan in plans
    ]
    return {
        "plan_count": len(plan_statuses),
        "expected_runs": sum(int(item.get("expected_runs") or 0) for item in plan_statuses),
        "completed_runs": sum(int(item.get("completed_runs") or 0) for item in plan_statuses),
        "claimed_runs": sum(int(item.get("claimed_runs") or 0) for item in plan_statuses),
        "pending_runs": sum(int(item.get("pending_runs") or 0) for item in plan_statuses),
        "failed_runs": sum(int(item.get("failed_runs") or 0) for item in plan_statuses),
        "complete_plans": sum(1 for item in plan_statuses if item.get("status") == "complete"),
    }


def _readiness_summary(
    spec: ExperimentSpec | None,
    *,
    outcomes: list[dict[str, object]],
    runs: list[dict[str, object]],
    plans: list[dict[str, object]],
    variant_summaries: list[dict[str, object]],
    plan_summary: Mapping[str, object],
    evidence: Mapping[str, object],
) -> dict[str, object]:
    latest_budget = evidence.get("latest_budget") if isinstance(evidence.get("latest_budget"), dict) else None
    latest_quorum = evidence.get("latest_quorum") if isinstance(evidence.get("latest_quorum"), dict) else None
    latest_promotion = evidence.get("latest_promotion") if isinstance(evidence.get("latest_promotion"), dict) else None
    latest_balance = evidence.get("latest_balance") if isinstance(evidence.get("latest_balance"), dict) else None
    latest_drift = evidence.get("latest_drift") if isinstance(evidence.get("latest_drift"), dict) else None
    return {
        "run_count": len(runs),
        "plan_count": len(plans),
        "outcome_count": len(outcomes),
        "succeeded_outcomes": sum(1 for item in outcomes if item.get("status") == "succeeded"),
        "failed_outcomes": sum(1 for item in outcomes if item.get("status") == "failed"),
        "variant_count": len(spec.variants) if spec else 0,
        "sampled_variants": sum(
            1
            for item in variant_summaries
            if int(item.get("primary_metric_count") or item.get("trials") or 0) > 0
        ),
        "pending_plan_runs": int(plan_summary.get("pending_runs") or 0),
        "claimed_plan_runs": int(plan_summary.get("claimed_runs") or 0),
        "comparison_present": evidence.get("latest_comparison") is not None,
        "budget_present": latest_budget is not None,
        "budget_status": latest_budget.get("budget_status") if latest_budget else None,
        "balance_present": latest_balance is not None,
        "balance_status": latest_balance.get("balance_status") if latest_balance else None,
        "balanced": latest_balance.get("balanced") if latest_balance else None,
        "drift_present": latest_drift is not None,
        "drift_status": latest_drift.get("drift_status") if latest_drift else None,
        "drift_detected": latest_drift.get("drift_detected") if latest_drift else None,
        "route_present": evidence.get("latest_route") is not None,
        "memory_present": evidence.get("latest_memory") is not None,
        "quorum_present": latest_quorum is not None,
        "quorum_status": latest_quorum.get("quorum_status") if latest_quorum else None,
        "promotion_present": latest_promotion is not None,
        "promotion_status": latest_promotion.get("promotion_status") if latest_promotion else None,
        "suite_report_present": evidence.get("latest_suite_report") is not None,
        "gate_present": evidence.get("latest_gate") is not None,
    }


def _readiness_findings(
    experiment: str,
    *,
    summary: Mapping[str, object],
    policy: Mapping[str, object],
    evidence: Mapping[str, object],
) -> list[dict[str, object]]:
    findings: list[dict[str, object]] = []
    outcome_count = int(summary.get("outcome_count") or 0)
    failed_outcomes = int(summary.get("failed_outcomes") or 0)
    min_outcomes = int(policy.get("min_outcomes") or 0)
    max_failed = int(policy.get("max_failed_outcomes") or 0)
    if int(summary.get("run_count") or 0) == 0:
        findings.append(
            _readiness_finding(
                "fail",
                "no-runs",
                experiment,
                "No run records were found for this experiment.",
            )
        )
    if outcome_count < min_outcomes:
        findings.append(
            _readiness_finding(
                "fail",
                "outcome-count",
                experiment,
                f"{outcome_count} outcome(s) found, required {min_outcomes}.",
            )
        )
    if failed_outcomes > max_failed:
        findings.append(
            _readiness_finding(
                "fail",
                "failed-outcomes",
                experiment,
                f"{failed_outcomes} failed outcome(s) exceeds allowed {max_failed}.",
            )
        )
    elif failed_outcomes:
        findings.append(
            _readiness_finding(
                "warn",
                "failed-outcomes-present",
                experiment,
                f"{failed_outcomes} failed outcome(s) are inside the configured ceiling.",
            )
        )
    if int(summary.get("pending_plan_runs") or 0):
        findings.append(
            _readiness_finding(
                "warn",
                "queued-plan-runs",
                experiment,
                f"{int(summary.get('pending_plan_runs') or 0)} plan run(s) are still queued.",
            )
        )
    if int(summary.get("claimed_plan_runs") or 0):
        findings.append(
            _readiness_finding(
                "warn",
                "claimed-plan-runs",
                experiment,
                f"{int(summary.get('claimed_plan_runs') or 0)} plan run(s) are currently claimed.",
            )
        )
    comparison = evidence.get("latest_comparison") if isinstance(evidence.get("latest_comparison"), dict) else None
    if policy.get("require_comparison") and comparison is None:
        findings.append(
            _readiness_finding("fail", "comparison-missing", experiment, "No comparison artifact was found.")
        )
    elif comparison is not None:
        if not comparison.get("winner_variant_id"):
            findings.append(
                _readiness_finding(
                    "fail" if policy.get("require_comparison") else "warn",
                    "comparison-inconclusive",
                    experiment,
                    "Latest comparison does not name a winning variant.",
                    artifact_id=str(comparison.get("comparison_id") or ""),
                )
            )
        eligible = int(comparison.get("eligible_variant_count") or 0)
        variant_count = int(comparison.get("variant_count") or 0)
        if variant_count and eligible < variant_count:
            findings.append(
                _readiness_finding(
                    "fail" if policy.get("require_comparison") else "warn",
                    "comparison-partial",
                    experiment,
                    f"Latest comparison covers {eligible} of {variant_count} variants.",
                    artifact_id=str(comparison.get("comparison_id") or ""),
                )
            )
    budget = evidence.get("latest_budget") if isinstance(evidence.get("latest_budget"), dict) else None
    if policy.get("require_budget") and budget is None:
        findings.append(
            _readiness_finding("fail", "budget-missing", experiment, "No budget artifact was found.")
        )
    elif budget is not None and budget.get("budget_status") != "within-budget":
        findings.append(
            _readiness_finding(
                "fail",
                "budget-over",
                experiment,
                "Latest budget artifact is over configured limits.",
                artifact_id=str(budget.get("budget_id") or ""),
            )
        )
    balance = evidence.get("latest_balance") if isinstance(evidence.get("latest_balance"), dict) else None
    if policy.get("require_balance") and balance is None:
        findings.append(
            _readiness_finding("fail", "balance-missing", experiment, "No balance artifact was found.")
        )
    elif balance is not None and (
        balance.get("balance_status") != "balanced" or balance.get("balanced") is not True
    ):
        findings.append(
            _readiness_finding(
                "fail" if policy.get("require_balance") else "warn",
                "balance-not-passing",
                experiment,
                "Latest balance artifact is not balanced.",
                artifact_id=str(balance.get("balance_id") or ""),
            )
        )
    drift = evidence.get("latest_drift") if isinstance(evidence.get("latest_drift"), dict) else None
    if policy.get("require_drift") and drift is None:
        findings.append(
            _readiness_finding("fail", "drift-missing", experiment, "No drift artifact was found.")
        )
    elif drift is not None and (
        drift.get("drift_status") != "stable" or drift.get("drift_detected") is True
    ):
        findings.append(
            _readiness_finding(
                "fail" if policy.get("require_drift") else "warn",
                "drift-not-stable",
                experiment,
                "Latest drift artifact is not stable.",
                artifact_id=str(drift.get("drift_id") or ""),
            )
        )
    route = evidence.get("latest_route") if isinstance(evidence.get("latest_route"), dict) else None
    if policy.get("require_route") and route is None:
        findings.append(
            _readiness_finding("fail", "route-missing", experiment, "No lane routing artifact was found.")
        )
    elif route is None and outcome_count and int(summary.get("plan_count") or 0):
        findings.append(
            _readiness_finding("warn", "route-not-written", experiment, "No lane routing artifact was found.")
        )
    elif route is not None and int(route.get("recommended_routes") or 0) == 0:
        findings.append(
            _readiness_finding(
                "fail" if policy.get("require_route") else "warn",
                "route-inconclusive",
                experiment,
                "Latest lane routing artifact has no recommended routes.",
                artifact_id=str(route.get("route_id") or ""),
            )
        )
    memory = evidence.get("latest_memory") if isinstance(evidence.get("latest_memory"), dict) else None
    if policy.get("require_memory") and memory is None:
        findings.append(
            _readiness_finding("fail", "memory-missing", experiment, "No memory artifact was found.")
        )
    elif memory is None and outcome_count:
        findings.append(
            _readiness_finding(
                "warn",
                "memory-not-written",
                experiment,
                "No metadata-only memory artifact was found.",
            )
        )
    quorum = evidence.get("latest_quorum") if isinstance(evidence.get("latest_quorum"), dict) else None
    if policy.get("require_quorum") and quorum is None:
        findings.append(
            _readiness_finding("fail", "quorum-missing", experiment, "No lane quorum artifact was found.")
        )
    elif quorum is None and int(summary.get("plan_count") or 0):
        findings.append(
            _readiness_finding("warn", "quorum-not-written", experiment, "No lane quorum artifact was found.")
        )
    elif quorum is not None and quorum.get("passed") is not True:
        findings.append(
            _readiness_finding(
                "fail" if policy.get("require_quorum") else "warn",
                "quorum-not-passing",
                experiment,
                "Latest lane quorum artifact is not passing.",
                artifact_id=str(quorum.get("quorum_id") or ""),
            )
        )
    promotion = evidence.get("latest_promotion") if isinstance(evidence.get("latest_promotion"), dict) else None
    if policy.get("require_promotion") and promotion is None:
        findings.append(
            _readiness_finding("fail", "promotion-missing", experiment, "No promotion artifact was found.")
        )
    elif promotion is not None and promotion.get("ready") is not True:
        findings.append(
            _readiness_finding(
                "fail" if policy.get("require_promotion") else "warn",
                "promotion-not-ready",
                experiment,
                "Latest promotion artifact is not ready.",
                artifact_id=str(promotion.get("promotion_id") or ""),
            )
        )
    if not any(item.get("severity") == "fail" for item in findings):
        findings.append(
            _readiness_finding(
                "pass",
                "readiness-eligible",
                experiment,
                "Experiment meets the configured readiness policy.",
            )
        )
    return findings


def _readiness_finding(
    severity: str,
    code: str,
    experiment: str,
    message: str,
    *,
    artifact_id: str | None = None,
) -> dict[str, object]:
    finding: dict[str, object] = {
        "severity": severity,
        "code": code,
        "experiment": experiment,
        "message": message,
    }
    if artifact_id:
        finding["artifact_id"] = _safe_text_label(artifact_id, field="artifact_id", max_length=180)
    return finding


def _readiness_status(*, ready: bool, warn_count: int) -> str:
    if not ready:
        return "blocked"
    if warn_count:
        return "ready-with-warnings"
    return "ready"


def _readiness_recommendations(
    findings: list[dict[str, object]],
    readiness_status: str,
) -> list[str]:
    if readiness_status == "ready":
        return ["Proceed under the configured readiness policy and keep logging metadata-only outcomes."]
    recommendations: list[str] = []
    codes = {str(item.get("code") or "") for item in findings}
    if "outcome-count" in codes or "no-runs" in codes:
        recommendations.append("Create more runs and log outcomes before scale-up.")
    if "failed-outcomes" in codes or "failed-outcomes-present" in codes:
        recommendations.append("Run agent-recover or inspect failed adapters before scale-up.")
    if "comparison-missing" in codes or "comparison-inconclusive" in codes:
        recommendations.append("Run agent-compare and review the latest comparison evidence.")
    if "budget-missing" in codes or "budget-over" in codes:
        recommendations.append("Run agent-budget with the intended limits before scale-up.")
    if "balance-missing" in codes or "balance-not-passing" in codes:
        recommendations.append("Run agent-balance and complete under-sampled cells before promotion or rollout.")
    if "drift-missing" in codes or "drift-not-stable" in codes:
        recommendations.append("Run agent-drift and resolve recent regressions before promotion or rollout.")
    if "route-missing" in codes or "route-not-written" in codes or "route-inconclusive" in codes:
        recommendations.append("Run agent-route so lanes can use model-specific evidence.")
    if "memory-missing" in codes or "memory-not-written" in codes:
        recommendations.append("Run agent-memory so the next loop has metadata-only lessons.")
    if "quorum-missing" in codes or "quorum-not-written" in codes or "quorum-not-passing" in codes:
        recommendations.append("Run agent-quorum on completed parallel plans before scale-up.")
    if "promotion-missing" in codes or "promotion-not-ready" in codes:
        recommendations.append("Run agent-promote with the required controls before changing model weights.")
    if "queued-plan-runs" in codes or "claimed-plan-runs" in codes:
        recommendations.append("Finish queued and claimed plan runs before treating the experiment as settled.")
    if readiness_status == "ready-with-warnings":
        recommendations.append("Review warning findings before increasing worker count or traffic share.")
    return recommendations or ["Review readiness findings before scale-up."]


