def _rollout_stage_ratios(stages: tuple[float, ...]) -> list[float]:
    if not stages:
        raise ValueError("rollout stages must include at least one share")
    ratios: list[float] = []
    previous = 0.0
    for index, value in enumerate(stages, start=1):
        ratio = _ratio(value, field=f"rollout stage {index}")
        if ratio <= 0:
            raise ValueError("rollout stages must be greater than 0")
        if ratio <= previous:
            raise ValueError("rollout stages must be strictly increasing")
        ratios.append(round(ratio, 6))
        previous = ratio
    return ratios


def _rollout_candidate_variant(
    requested: str | None,
    *,
    latest_promotion: Mapping[str, object] | None,
    latest_comparison: Mapping[str, object] | None,
    latest_allocation: Mapping[str, object] | None,
) -> str | None:
    if requested:
        return _safe_label(requested)
    for record, key in (
        (latest_promotion, "candidate_variant_id"),
        (latest_comparison, "winner_variant_id"),
        (latest_allocation, "winner_variant_id"),
    ):
        if isinstance(record, Mapping) and isinstance(record.get(key), str) and record.get(key):
            return _safe_label(str(record[key]))
    return None


def _rollout_readiness_summary(readiness: Mapping[str, object] | None) -> dict[str, object] | None:
    if readiness is None:
        return None
    summary = readiness.get("summary") if isinstance(readiness.get("summary"), dict) else {}
    return {
        "readiness_id": readiness.get("readiness_id"),
        "readiness_status": readiness.get("readiness_status"),
        "ready": readiness.get("ready"),
        "fail": summary.get("fail"),
        "warn": summary.get("warn"),
        "generated_at": readiness.get("generated_at"),
    }


def _rollout_findings(
    experiment: str,
    *,
    champion_variant_id: str,
    candidate_variant_id: str | None,
    policy: Mapping[str, object],
    evidence: Mapping[str, object],
) -> list[dict[str, object]]:
    findings: list[dict[str, object]] = []
    if not candidate_variant_id:
        findings.append(
            _readiness_finding(
                "fail",
                "candidate-missing",
                experiment,
                "No challenger variant could be inferred for rollout.",
            )
        )
    elif candidate_variant_id == champion_variant_id:
        findings.append(
            _readiness_finding(
                "fail",
                "candidate-is-champion",
                experiment,
                "Rollout challenger matches the current champion.",
            )
        )
    readiness = evidence.get("latest_readiness") if isinstance(evidence.get("latest_readiness"), dict) else None
    if policy.get("require_readiness") and readiness is None:
        findings.append(
            _readiness_finding("fail", "readiness-missing", experiment, "No readiness artifact was found.")
        )
    elif readiness is not None:
        status = str(readiness.get("readiness_status") or "")
        if status not in {"ready", "ready-with-warnings"}:
            findings.append(
                _readiness_finding(
                    "fail" if policy.get("require_readiness") else "warn",
                    "readiness-not-ready",
                    experiment,
                    "Latest readiness artifact is not ready.",
                    artifact_id=str(readiness.get("readiness_id") or ""),
                )
            )
        elif status == "ready-with-warnings":
            findings.append(
                _readiness_finding(
                    "warn",
                    "readiness-warnings",
                    experiment,
                    "Latest readiness artifact has warning findings.",
                    artifact_id=str(readiness.get("readiness_id") or ""),
                )
            )
    promotion = evidence.get("latest_promotion") if isinstance(evidence.get("latest_promotion"), dict) else None
    if policy.get("require_promotion") and promotion is None:
        findings.append(
            _readiness_finding("fail", "promotion-missing", experiment, "No promotion artifact was found.")
        )
    elif promotion is not None:
        promotion_candidate = promotion.get("candidate_variant_id")
        if promotion.get("ready") is not True:
            findings.append(
                _readiness_finding(
                    "fail" if policy.get("require_promotion") else "warn",
                    "promotion-not-ready",
                    experiment,
                    "Latest promotion artifact is not ready.",
                    artifact_id=str(promotion.get("promotion_id") or ""),
                )
            )
        if candidate_variant_id and promotion_candidate and promotion_candidate != candidate_variant_id:
            findings.append(
                _readiness_finding(
                    "fail" if policy.get("require_promotion") else "warn",
                    "promotion-candidate-mismatch",
                    experiment,
                    "Latest promotion candidate does not match rollout challenger.",
                    artifact_id=str(promotion.get("promotion_id") or ""),
                )
            )
    budget = evidence.get("latest_budget") if isinstance(evidence.get("latest_budget"), dict) else None
    if policy.get("require_budget") and budget is None:
        findings.append(
            _readiness_finding("fail", "budget-missing", experiment, "No budget artifact was found.")
        )
    elif budget is not None and budget.get("budget_status") != "within-budget":
        findings.append(
            _readiness_finding(
                "fail",
                "budget-over",
                experiment,
                "Latest budget artifact is over configured limits.",
                artifact_id=str(budget.get("budget_id") or ""),
            )
        )
    drift = evidence.get("latest_drift") if isinstance(evidence.get("latest_drift"), dict) else None
    if policy.get("require_drift") and drift is None:
        findings.append(
            _readiness_finding("fail", "drift-missing", experiment, "No drift artifact was found.")
        )
    elif drift is not None:
        stable = drift.get("drift_status") == "stable" and drift.get("drift_detected") is not True
        if not stable:
            findings.append(
                _readiness_finding(
                    "fail" if policy.get("require_drift") else "warn",
                    "drift-not-stable",
                    experiment,
                    "Latest drift artifact is not stable.",
                    artifact_id=str(drift.get("drift_id") or ""),
                )
            )
    comparison = evidence.get("latest_comparison") if isinstance(evidence.get("latest_comparison"), dict) else None
    if comparison is not None and candidate_variant_id:
        winner = comparison.get("winner_variant_id")
        if winner and winner != candidate_variant_id:
            findings.append(
                _readiness_finding(
                    "warn",
                    "comparison-winner-mismatch",
                    experiment,
                    "Latest comparison winner differs from rollout challenger.",
                    artifact_id=str(comparison.get("comparison_id") or ""),
                )
            )
    if not any(item.get("severity") == "fail" for item in findings):
        findings.append(
            _readiness_finding(
                "pass",
                "rollout-planned",
                experiment,
                "Rollout plan meets the configured policy.",
            )
        )
    return findings


def _rollout_status(*, ready: bool, warn_count: int) -> str:
    if not ready:
        return "blocked"
    if warn_count:
        return "ready-with-warnings"
    return "ready"


def _rollout_stage_entries(
    stage_ratios: list[float],
    *,
    champion_variant_id: str,
    candidate_variant_id: str | None,
    min_observation_runs: int,
    max_stage_failed_outcomes: int,
) -> list[dict[str, object]]:
    entries: list[dict[str, object]] = []
    previous_share = 0.0
    for index, share in enumerate(stage_ratios, start=1):
        entries.append(
            {
                "stage_index": index,
                "candidate_variant_id": candidate_variant_id,
                "champion_variant_id": champion_variant_id,
                "candidate_share": share,
                "champion_share": round(1.0 - share, 6),
                "previous_candidate_share": round(previous_share, 6),
                "min_observation_runs": min_observation_runs,
                "max_failed_outcomes": max_stage_failed_outcomes,
                "entry_requirements": _rollout_stage_entry_requirements(index),
                "exit_checks": [
                    "log-stage-outcomes",
                    "agent-budget",
                    "agent-drift",
                    "agent-readiness",
                    "agent-timeline",
                ],
                "rollback_if": [
                    "failed-outcomes-above-stage-limit",
                    "budget-over",
                    "drift-detected",
                    "readiness-blocked",
                    "operator-hold",
                ],
            }
        )
        previous_share = share
    return entries


def _rollout_stage_entry_requirements(stage_index: int) -> list[str]:
    if stage_index == 1:
        return ["readiness-reviewed", "promotion-reviewed", "budget-reviewed", "drift-reviewed"]
    return ["previous-stage-complete", "latest-stage-checks-reviewed"]


def _rollout_rollback_policy(max_stage_failed_outcomes: int) -> dict[str, object]:
    return {
        "fallback": "return-to-champion",
        "max_stage_failed_outcomes": max_stage_failed_outcomes,
        "checks": [
            "stage-failed-outcomes",
            "stage-budget",
            "stage-drift",
            "stage-readiness",
            "operator-hold",
        ],
        "review_commands": [
            "agent-budget",
            "agent-drift",
            "agent-readiness",
            "agent-timeline",
            "agent-dashboard",
        ],
    }


def _rollout_recommendations(
    findings: list[dict[str, object]],
    rollout_status: str,
) -> list[str]:
    if rollout_status == "ready":
        return ["Begin stage 1 only after reviewing the rollout report and current readiness evidence."]
    recommendations: list[str] = []
    codes = {str(item.get("code") or "") for item in findings}
    if "candidate-missing" in codes or "candidate-is-champion" in codes:
        recommendations.append("Select an explicit challenger variant or generate a ready promotion first.")
    if "readiness-missing" in codes or "readiness-not-ready" in codes:
        recommendations.append("Run agent-readiness with the intended controls before rollout.")
    if "promotion-missing" in codes or "promotion-not-ready" in codes or "promotion-candidate-mismatch" in codes:
        recommendations.append("Run agent-promote and confirm the challenger matches the rollout.")
    if "budget-missing" in codes or "budget-over" in codes:
        recommendations.append("Run agent-budget with the intended limits before rollout.")
    if "drift-missing" in codes or "drift-not-stable" in codes:
        recommendations.append("Run agent-drift and resolve recent regressions before rollout.")
    if "comparison-winner-mismatch" in codes:
        recommendations.append("Review comparison evidence before assigning rollout stages.")
    if rollout_status == "ready-with-warnings":
        recommendations.append("Review warning findings before beginning stage 1.")
    return recommendations or ["Resolve rollout findings before beginning stage 1."]


def _rollout_stage_by_index(stages: list[object], stage_index: int) -> dict[str, object]:
    for stage in stages:
        if not isinstance(stage, dict):
            continue
        if int(stage.get("stage_index") or 0) == stage_index:
            return stage
    raise ValueError(f"rollout stage not found: {stage_index}")


def _latest_rollout_stage_check(
    root: Path,
    rollout_id: str,
    *,
    before_stage_index: int | None = None,
) -> dict[str, object] | None:
    checks = [
        check
        for check in _load_schema_records(root, "rollout-checks", AGENT_ROLLOUT_CHECK_SCHEMA)
        if check.get("rollout_id") == rollout_id
    ]
    if before_stage_index is not None:
        checks = [
            check
            for check in checks
            if int((check.get("stage") if isinstance(check.get("stage"), dict) else {}).get("stage_index") or 0)
            < before_stage_index
        ]
    return checks[-1] if checks else None


def _rollout_check_window_start(
    rollout: Mapping[str, object],
    *,
    previous_check: Mapping[str, object] | None,
) -> datetime:
    if previous_check is not None:
        parsed = _parse_datetime(str(previous_check.get("generated_at") or ""))
        if parsed is not None:
            return parsed
    parsed = _parse_datetime(str(rollout.get("generated_at") or ""))
    return parsed if parsed is not None else datetime.fromtimestamp(0, tz=timezone.utc)


def _rollout_stage_outcomes(
    outcomes: list[dict[str, object]],
    *,
    generated_after: datetime,
    candidate_variant_id: str,
    champion_variant_id: str,
) -> list[dict[str, object]]:
    variant_ids = {candidate_variant_id, champion_variant_id} - {""}
    selected: list[dict[str, object]] = []
    for outcome in outcomes:
        logged_at = _parse_datetime(str(outcome.get("logged_at") or ""))
        if logged_at is None or logged_at <= generated_after:
            continue
        variant_id = _outcome_variant_id(outcome)
        if variant_id in variant_ids:
            selected.append(outcome)
    return selected


def _rollout_stage_check_summary(
    rollout: Mapping[str, object],
    stage: Mapping[str, object],
    *,
    outcomes: list[dict[str, object]],
    primary_metric: MetricSpec,
) -> dict[str, object]:
    candidate = str(rollout.get("candidate_variant_id") or "")
    champion = str(rollout.get("champion_variant_id") or "")
    candidate_outcomes = [item for item in outcomes if _outcome_variant_id(item) == candidate]
    champion_outcomes = [item for item in outcomes if _outcome_variant_id(item) == champion]
    candidate_values = _rollout_metric_values(candidate_outcomes, primary_metric.name)
    champion_values = _rollout_metric_values(champion_outcomes, primary_metric.name)
    candidate_mean = _rounded_mean(candidate_values)
    champion_mean = _rounded_mean(champion_values)
    metric_gap = _rollout_metric_gap(
        candidate_mean,
        champion_mean,
        direction=primary_metric.direction,
    )
    total_variant_outcomes = len(candidate_outcomes) + len(champion_outcomes)
    observed_share = len(candidate_outcomes) / total_variant_outcomes if total_variant_outcomes else None
    target_share = _summary_number(stage, "candidate_share")
    share_deviation = (
        abs(float(observed_share) - float(target_share))
        if observed_share is not None and target_share is not None
        else None
    )
    failed_candidate = sum(1 for item in candidate_outcomes if item.get("status") == "failed")
    failed_total = sum(1 for item in outcomes if item.get("status") == "failed")
    return {
        "candidate_variant_id": candidate or None,
        "champion_variant_id": champion or None,
        "stage_index": int(stage.get("stage_index") or 0),
        "target_candidate_share": target_share,
        "observed_candidate_share": round(observed_share, 6) if observed_share is not None else None,
        "share_deviation": round(share_deviation, 6) if share_deviation is not None else None,
        "outcome_count": len(outcomes),
        "candidate_outcome_count": len(candidate_outcomes),
        "champion_outcome_count": len(champion_outcomes),
        "failed_candidate_outcomes": failed_candidate,
        "failed_outcomes": failed_total,
        "candidate_metric_count": len(candidate_values),
        "champion_metric_count": len(champion_values),
        "candidate_metric_mean": round(candidate_mean, 6) if candidate_mean is not None else None,
        "champion_metric_mean": round(champion_mean, 6) if champion_mean is not None else None,
        "metric_gap": metric_gap,
        "primary_metric": primary_metric.as_dict(),
        "usage": _budget_usage_stats(outcomes),
    }


def _rollout_metric_values(outcomes: list[dict[str, object]], metric_name: str) -> list[float]:
    values: list[float] = []
    for outcome in outcomes:
        metrics = outcome.get("metrics")
        if not isinstance(metrics, dict):
            continue
        value = metrics.get(metric_name)
        if isinstance(value, (int, float)) and math.isfinite(float(value)):
            values.append(float(value))
    return values


def _rollout_metric_gap(
    candidate_mean: float | None,
    champion_mean: float | None,
    *,
    direction: str,
) -> float | None:
    if candidate_mean is None or champion_mean is None:
        return None
    gap = candidate_mean - champion_mean if direction == "maximize" else champion_mean - candidate_mean
    return round(gap, 6)


def _rollout_check_rollout_summary(rollout: Mapping[str, object]) -> dict[str, object]:
    summary = rollout.get("summary") if isinstance(rollout.get("summary"), dict) else {}
    return {
        "rollout_id": rollout.get("rollout_id"),
        "rollout_status": rollout.get("rollout_status"),
        "ready": rollout.get("ready"),
        "candidate_variant_id": rollout.get("candidate_variant_id"),
        "champion_variant_id": rollout.get("champion_variant_id"),
        "stage_count": summary.get("stage_count"),
        "generated_at": rollout.get("generated_at"),
    }


def _rollout_check_summary(check: Mapping[str, object] | None) -> dict[str, object] | None:
    if check is None:
        return None
    stage = check.get("stage") if isinstance(check.get("stage"), dict) else {}
    return {
        "check_id": check.get("check_id"),
        "decision": check.get("decision"),
        "check_status": check.get("check_status"),
        "stage_index": stage.get("stage_index"),
        "generated_at": check.get("generated_at"),
    }


def _rollout_check_findings(
    experiment: str,
    *,
    rollout: Mapping[str, object],
    stage: Mapping[str, object],
    summary: Mapping[str, object],
    policy: Mapping[str, object],
    evidence: Mapping[str, object],
) -> list[dict[str, object]]:
    findings: list[dict[str, object]] = []
    stage_index = int(stage.get("stage_index") or 0)
    if rollout.get("ready") is not True:
        findings.append(
            _readiness_finding(
                "fail",
                "rollout-not-ready",
                experiment,
                "Rollout plan is not ready.",
                artifact_id=str(rollout.get("rollout_id") or ""),
            )
        )
    if stage_index > 1:
        previous = evidence.get("previous_check") if isinstance(evidence.get("previous_check"), dict) else None
        expected_previous = stage_index - 1
        if previous is None or int(previous.get("stage_index") or 0) != expected_previous:
            findings.append(
                _readiness_finding(
                    "fail",
                    "previous-stage-missing",
                    experiment,
                    "Previous rollout stage check is missing.",
                )
            )
        elif previous.get("decision") != "advance":
            findings.append(
                _readiness_finding(
                    "fail",
                    "previous-stage-not-advanced",
                    experiment,
                    "Previous rollout stage has not advanced.",
                    artifact_id=str(previous.get("check_id") or ""),
                )
            )
    min_outcomes = int(policy.get("min_stage_outcomes") or 0)
    candidate_outcomes = int(summary.get("candidate_outcome_count") or 0)
    if candidate_outcomes < min_outcomes:
        findings.append(
            _readiness_finding(
                "warn",
                "stage-observations-low",
                experiment,
                f"{candidate_outcomes} challenger outcome(s) found, required {min_outcomes}.",
            )
        )
    failed = int(summary.get("failed_candidate_outcomes") or 0)
    failed_ceiling = int(policy.get("max_stage_failed_outcomes") or 0)
    if failed > failed_ceiling:
        findings.append(
            _readiness_finding(
                "fail",
                "stage-failed-outcomes",
                experiment,
                f"{failed} challenger failed outcome(s) exceeds allowed {failed_ceiling}.",
            )
        )
    share_deviation = _summary_number(summary, "share_deviation")
    share_ceiling = _summary_number(policy, "max_share_deviation")
    if share_deviation is not None and share_ceiling is not None and share_deviation > share_ceiling:
        findings.append(
            _readiness_finding(
                "warn",
                "stage-share-deviation",
                experiment,
                "Observed challenger share differs from the rollout stage target.",
            )
        )
    metric_gap = _summary_number(summary, "metric_gap")
    delta_floor = _summary_number(policy, "min_metric_delta")
    if delta_floor is not None and metric_gap is not None and metric_gap < delta_floor:
        findings.append(
            _readiness_finding(
                "fail",
                "stage-metric-delta",
                experiment,
                f"Stage metric gap {metric_gap:.6g} is below required {delta_floor:.6g}.",
            )
        )
    budget = evidence.get("latest_budget") if isinstance(evidence.get("latest_budget"), dict) else None
    if policy.get("require_budget") and budget is None:
        findings.append(
            _readiness_finding("fail", "budget-missing", experiment, "No budget artifact was found.")
        )
    elif budget is not None and budget.get("budget_status") != "within-budget":
        findings.append(
            _readiness_finding(
                "fail",
                "budget-over",
                experiment,
                "Latest budget artifact is over configured limits.",
                artifact_id=str(budget.get("budget_id") or ""),
            )
        )
    readiness = evidence.get("latest_readiness") if isinstance(evidence.get("latest_readiness"), dict) else None
    if policy.get("require_readiness") and readiness is None:
        findings.append(
            _readiness_finding("fail", "readiness-missing", experiment, "No readiness artifact was found.")
        )
    elif readiness is not None and readiness.get("readiness_status") not in {"ready", "ready-with-warnings"}:
        findings.append(
            _readiness_finding(
                "fail",
                "readiness-blocked",
                experiment,
                "Latest readiness artifact is blocked.",
                artifact_id=str(readiness.get("readiness_id") or ""),
            )
        )
    drift = evidence.get("latest_drift") if isinstance(evidence.get("latest_drift"), dict) else None
    if policy.get("require_drift") and drift is None:
        findings.append(
            _readiness_finding("fail", "drift-missing", experiment, "No drift artifact was found.")
        )
    elif drift is not None:
        stable = drift.get("drift_status") == "stable" and drift.get("drift_detected") is not True
        if not stable:
            findings.append(
                _readiness_finding(
                    "fail" if policy.get("require_drift") else "warn",
                    "drift-not-stable",
                    experiment,
                    "Latest drift artifact is not stable.",
                    artifact_id=str(drift.get("drift_id") or ""),
                )
            )
    if not findings:
        findings.append(
            _readiness_finding(
                "pass",
                "stage-advance",
                experiment,
                "Rollout stage meets the configured advance policy.",
            )
        )
    return findings


def _rollout_check_decision(findings: list[dict[str, object]]) -> str:
    codes = {str(item.get("code") or "") for item in findings if item.get("severity") == "fail"}
    rollback_codes = {
        "stage-failed-outcomes",
        "stage-metric-delta",
        "budget-over",
        "readiness-blocked",
        "drift-not-stable",
    }
    if codes & rollback_codes:
        return "rollback"
    if codes:
        return "blocked"
    if any(item.get("code") == "stage-observations-low" for item in findings):
        return "hold"
    return "advance"


def _rollout_check_recommendations(
    decision: str,
    findings: list[dict[str, object]],
) -> list[str]:
    if decision == "advance":
        return ["Advance to the next rollout stage or complete the rollout if this was the final stage."]
    codes = {str(item.get("code") or "") for item in findings}
    recommendations: list[str] = []
    if decision == "hold":
        recommendations.append("Keep the current stage active until enough challenger outcomes are logged.")
    if decision == "rollback":
        recommendations.append("Return traffic to the champion and review stage evidence before retrying rollout.")
    if "rollout-not-ready" in codes:
        recommendations.append("Create a ready rollout plan before checking stages.")
    if "previous-stage-missing" in codes or "previous-stage-not-advanced" in codes:
        recommendations.append("Advance the previous rollout stage before checking this one.")
    if "stage-failed-outcomes" in codes:
        recommendations.append("Investigate challenger failures before continuing rollout.")
    if "stage-metric-delta" in codes:
        recommendations.append("Keep the challenger in analysis until stage metrics recover.")
    if "budget-missing" in codes or "budget-over" in codes:
        recommendations.append("Run agent-budget with the intended limits before advancing.")
    if "readiness-missing" in codes or "readiness-blocked" in codes:
        recommendations.append("Run agent-readiness and resolve findings before advancing.")
    if "drift-missing" in codes or "drift-not-stable" in codes:
        recommendations.append("Run agent-drift and resolve recent regressions before advancing.")
    return recommendations or ["Review rollout check findings before changing stage."]


def _evolve_step_record(
    vault: Path,
    step: str,
    status: str,
    *,
    artifact_type: str,
    artifact_id: str,
    artifact_status: str | None,
    path: object | None,
    report_path: object | None,
) -> dict[str, object]:
    record: dict[str, object] = {
        "step": _safe_label(step),
        "status": _safe_label(status),
        "artifact_type": _safe_label(artifact_type),
        "artifact_id": _safe_text_label(artifact_id, field="artifact_id", max_length=180),
    }
    if artifact_status:
        record["artifact_status"] = _safe_text_label(
            artifact_status,
            field="artifact_status",
            max_length=120,
        )
    if isinstance(path, Path):
        record["path"] = _relative_vault_path(vault, path)
    if isinstance(report_path, Path):
        record["report_path"] = _relative_vault_path(vault, report_path)
    return record


def _evolve_error_step(step: str, exc: Exception) -> dict[str, object]:
    return {
        "step": _safe_label(step),
        "status": "error",
        "error_type": _safe_text_label(exc.__class__.__name__, field="error_type", max_length=120),
        "message": _safe_text_label(_scrub_error_message(str(exc)), field="error message", max_length=220),
    }


def _scrub_error_message(message: str) -> str:
    text = _single_line(message) or "step failed"
    text = _OPENAI_STYLE_KEY_RE.sub("[redacted]", text)
    text = _SECRET_VALUE_RE.sub("[redacted]", text)
    if len(text) > 220:
        text = text[:217] + "..."
    return text


def _evolve_artifact_status(payload: object) -> str | None:
    if not isinstance(payload, Mapping):
        return None
    for key in (
        "budget_status",
        "drift_status",
        "readiness_status",
        "rollout_status",
        "promotion_status",
        "check_status",
        "gate_status",
        "quorum_status",
    ):
        value = payload.get(key)
        if isinstance(value, str) and value.strip():
            return _single_line(value)
    decision = payload.get("decision")
    if isinstance(decision, str) and decision.strip():
        return _single_line(decision)
    ready = payload.get("ready")
    if isinstance(ready, bool):
        return "ready" if ready else "not-ready"
    over_budget = payload.get("over_budget")
    if isinstance(over_budget, bool):
        return "over-budget" if over_budget else "within-budget"
    return None


def _evolve_summary(steps: list[dict[str, object]]) -> dict[str, object]:
    attention_statuses = {
        "blocked",
        "fail",
        "hold",
        "needs-review",
        "not-ready",
        "over-budget",
        "rollback",
        "stable-with-warnings",
        "drift-detected",
    }
    artifact_statuses = [str(item.get("artifact_status") or "") for item in steps]
    return {
        "step_count": len(steps),
        "written_steps": sum(1 for item in steps if item.get("status") == "written"),
        "failed_steps": sum(1 for item in steps if item.get("status") == "error"),
        "attention_steps": sum(
            1
            for status in artifact_statuses
            if status in attention_statuses or status.startswith("blocked")
        ),
        "artifacts": sum(1 for item in steps if item.get("artifact_id")),
    }


def _evolve_recommendations(
    steps: list[dict[str, object]],
    evolve_status: str,
) -> list[str]:
    failed = [str(item.get("step") or "") for item in steps if item.get("status") == "error"]
    if evolve_status == "complete":
        return ["Review readiness and rollout outputs, then continue staged rollout checks as outcomes arrive."]
    if evolve_status == "needs-review":
        attention = [
            str(item.get("step") or "")
            for item in steps
            if (
                str(item.get("artifact_status") or "")
                in {
                    "blocked",
                    "fail",
                    "hold",
                    "needs-review",
                    "not-ready",
                    "over-budget",
                    "rollback",
                    "stable-with-warnings",
                    "drift-detected",
                }
                or str(item.get("artifact_status") or "").startswith("blocked")
            )
        ]
        named = ", ".join(item for item in attention if item) or "child artifacts"
        return [f"Review non-passing evolve output from {named} before scaling traffic."]
    recommendations: list[str] = []
    if "compare" in failed:
        recommendations.append("Log more primary-metric outcomes before comparing variants.")
    if "memory" in failed:
        recommendations.append("Run agent-memory after outcome and failure metadata is available.")
    if "route" in failed:
        recommendations.append("Run lane or matrix plans before requiring lane-aware routing.")
    if "budget" in failed:
        recommendations.append("Run agent-budget with valid limits before budget-gated evolution.")
    if "drift" in failed:
        recommendations.append("Run agent-drift after enough baseline and recent outcome metadata is available.")
    if "promote" in failed:
        recommendations.append("Resolve promotion policy findings before planning rollout.")
    if "readiness" in failed:
        recommendations.append("Resolve readiness findings before scale-up.")
    if "rollout" in failed:
        recommendations.append("Create a ready promotion and readiness gate before rollout planning.")
    return recommendations or ["Review failed evolve steps and rerun the evolve pass."]


def _promotion_pareto_variants(
    suite_report: Mapping[str, object] | None,
    comparison: Mapping[str, object] | None,
) -> list[str]:
    for record in (suite_report, comparison):
        if not isinstance(record, Mapping):
            continue
        frontier = record.get("efficiency_frontier")
        if not isinstance(frontier, list):
            continue
        variants = [
            str(item["variant_id"])
            for item in frontier
            if isinstance(item, dict) and isinstance(item.get("variant_id"), str)
        ]
        if variants:
            return variants
    return []


def _metric_gap(
    champion_summary: Mapping[str, object] | None,
    candidate_summary: Mapping[str, object] | None,
    *,
    direction: str,
) -> float | None:
    champion = _summary_number(champion_summary, "primary_metric_mean")
    candidate = _summary_number(candidate_summary, "primary_metric_mean")
    if champion is None or candidate is None:
        return None
    gap = candidate - champion if direction == "maximize" else champion - candidate
    return round(gap, 6)


def _promotion_confidence(
    champion_summary: Mapping[str, object] | None,
    candidate_summary: Mapping[str, object] | None,
    *,
    metric_gap: float | None,
) -> dict[str, object]:
    champion_stderr = _summary_number(champion_summary, "primary_metric_stderr")
    candidate_stderr = _summary_number(candidate_summary, "primary_metric_stderr")
    if metric_gap is None or champion_stderr is None or candidate_stderr is None:
        return {
            "label": "unknown",
            "combined_stderr": None,
            "gap_to_stderr": None,
        }
    combined = math.sqrt(champion_stderr**2 + candidate_stderr**2)
    ratio = abs(metric_gap) / combined if combined else None
    if ratio is None:
        label = "deterministic"
    elif ratio >= 2:
        label = "strong"
    elif ratio >= 1:
        label = "moderate"
    else:
        label = "weak"
    return {
        "label": label,
        "combined_stderr": round(combined, 6),
        "gap_to_stderr": round(ratio, 6) if ratio is not None else None,
    }


def _summary_number(summary: Mapping[str, object] | None, key: str) -> float | None:
    if summary is None:
        return None
    value = summary.get(key)
    if isinstance(value, (int, float)) and math.isfinite(float(value)):
        return float(value)
    return None


def _promotion_config(
    spec: ExperimentSpec,
    *,
    promoted_variant_id: str | None,
) -> dict[str, object]:
    config = spec.as_dict()
    if not promoted_variant_id:
        config["promotion_policy"] = "no-change"
        return config
    variants = []
    for variant in spec.variants:
        payload = variant.as_dict()
        payload["weight"] = 4.0 if variant.id == promoted_variant_id else 1.0
        variants.append(payload)
    config["variants"] = variants
    config["traffic_salt"] = f"{spec.traffic_salt}:promote:{promoted_variant_id}"
    config["promotion_policy"] = "champion-promotion"
    config["promoted_variant_id"] = promoted_variant_id
    return config


def _promotion_patch(
    spec: ExperimentSpec,
    candidate_config: Mapping[str, object],
) -> dict[str, object]:
    operations: list[dict[str, object]] = []
    if candidate_config.get("traffic_salt") != spec.traffic_salt:
        operations.append(
            {
                "op": "replace",
                "path": "/traffic_salt",
                "value": candidate_config["traffic_salt"],
            }
        )
    candidate_variants = candidate_config.get("variants")
    if isinstance(candidate_variants, list):
        for index, variant in enumerate(candidate_variants):
            if not isinstance(variant, dict):
                continue
            if index >= len(spec.variants):
                continue
            weight = variant.get("weight")
            if isinstance(weight, (int, float)) and weight != spec.variants[index].weight:
                operations.append(
                    {
                        "op": "replace",
                        "path": f"/variants/{index}/weight",
                        "value": float(weight),
                    }
                )
    return {
        "format": "json-patch",
        "operations": operations,
    }


def _promotion_recommendations(
    decision: Mapping[str, object],
    primary_metric: MetricSpec,
) -> list[str]:
    status = str(decision.get("status") or "unknown")
    reason = str(decision.get("reason") or "")
    evidence = decision.get("evidence") if isinstance(decision.get("evidence"), dict) else {}
    under_sampled = evidence.get("under_sampled_variants") if isinstance(evidence, dict) else []
    recommendations: list[str] = []
    if status == "ready":
        recommendations.append(
            "Review the proposed JSON patch, then apply it to the experiment config for the next loop."
        )
    elif status == "keep-champion":
        recommendations.append(
            "Keep the current champion allocation and continue periodic challenger sampling."
        )
    elif status == "blocked-by-gate":
        recommendations.append(
            "Run or repair agent-gate before promoting a challenger."
        )
    elif status == "blocked-by-suite-report":
        recommendations.append(
            "Run or complete agent-suite-report before promoting a challenger."
        )
    elif status == "blocked-by-pareto":
        recommendations.append(
            "Keep the candidate in exploration until it is Pareto-efficient on quality, cost, latency, and tokens."
        )
    elif status == "blocked-by-budget":
        recommendations.append(
            "Run agent-budget or lower experiment usage before promoting a challenger."
        )
    elif status == "blocked-by-balance":
        recommendations.append(
            "Run agent-balance and complete under-sampled cells before promoting a challenger."
        )
    elif status == "blocked-by-drift":
        recommendations.append(
            "Run agent-drift and resolve recent regressions before promoting a challenger."
        )
    elif status == "hold":
        recommendations.append(
            f"Keep the current allocation because the {primary_metric.name} gap is too small."
        )
    elif isinstance(under_sampled, list) and under_sampled:
        recommendations.append(
            "Collect more scored outcomes for under-sampled variants: "
            f"{', '.join(str(item) for item in under_sampled)}."
        )
    else:
        recommendations.append(
            f"Collect more outcomes with the {primary_metric.name} metric before promotion."
        )
    if reason:
        recommendations.append(reason)
    return recommendations


