def _safe_run_id(value: str) -> str:
    run_id = value.strip()
    if not _RUN_ID_RE.fullmatch(run_id) or "/" in run_id or "\\" in run_id:
        raise ValueError("run id contains unsafe characters")
    return run_id


def _safe_plan_id(value: str) -> str:
    plan_id = value.strip()
    if not _RUN_ID_RE.fullmatch(plan_id) or "/" in plan_id or "\\" in plan_id:
        raise ValueError("plan id contains unsafe characters")
    return plan_id


def _relative_vault_path(vault: Path, path: Path) -> str:
    resolved_vault = vault.expanduser().resolve()
    resolved_path = path.expanduser().resolve()
    try:
        return resolved_path.relative_to(resolved_vault).as_posix()
    except ValueError as exc:
        raise ValueError(f"agent artifact must stay inside the vault: {resolved_path}") from exc


def _single_line(value: str) -> str:
    return " ".join(str(value).splitlines()).strip()


def _table_number(value: object) -> str:
    if isinstance(value, (int, float)):
        return f"{float(value):.6g}"
    return ""


def _compact_timestamp(value: str) -> str:
    parsed = _parse_datetime(value)
    if parsed is None:
        timestamp = value.replace("-", "").replace(":", "")
        timestamp = timestamp.split(".", 1)[0]
        return timestamp.replace("+0000", "Z").replace("+00:00", "Z")
    return parsed.astimezone(timezone.utc).strftime("%Y%m%dT%H%M%SZ")


def _parse_datetime(value: str) -> datetime | None:
    try:
        parsed = datetime.fromisoformat(value)
    except ValueError:
        return None
    if parsed.tzinfo is None:
        return parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def _utc_now() -> datetime:
    return datetime.now(timezone.utc)


def _now() -> str:
    return _utc_now().isoformat()
